/*
CDXC:GPUIRemoteNewTerminal 2026-08-20:
A remote machine runs the gxserver package this app installed for it, so it can
implement fewer operations than the app that is driving it. The authenticated
`/api/health/server` probe this connection already performs carries the daemon's
own capability inventory, so record the bounded selectors remote requests have to
choose between instead of sending a newer selector and losing the whole action to
a 400. Keep this to fixed capability names: no daemon paths, ports, tokens, or
response text may be retained here.
*/
#[derive(Clone, Copy, Debug, Default)]
struct GpuiRemoteGxserverCapabilities {
    code_server_prompt_editor: bool,
}

struct GpuiRemoteGxserverConnection {
    _base_url: String,
    capabilities: GpuiRemoteGxserverCapabilities,
    code_server_component_platform: Option<String>,
    execution_target: GpuiRemoteExecutionTarget,
    local_port: u16,
    presentation_stream_cancel: Option<Arc<AtomicBool>>,
    presentation_stream_generation: Option<u64>,
    token: String,
    child: Child,
    health_check_failures: u8,
}

impl GpuiRemoteGxserverConnection {
    fn request_target(&self) -> GpuiRemoteGxserverRequestTarget {
        GpuiRemoteGxserverRequestTarget {
            capabilities: self.capabilities,
            code_server_component_platform: self.code_server_component_platform.clone(),
            execution_target: self.execution_target.clone(),
            local_port: self.local_port,
            token: self.token.clone(),
        }
    }

    fn terminate(&mut self) {
        if let Some(cancel) = self.presentation_stream_cancel.as_ref() {
            cancel.store(true, Ordering::SeqCst);
        }
        let _ = self.child.kill();
    }
}

#[derive(Clone)]
struct GpuiRemoteGxserverRequestTarget {
    capabilities: GpuiRemoteGxserverCapabilities,
    code_server_component_platform: Option<String>,
    execution_target: GpuiRemoteExecutionTarget,
    local_port: u16,
    token: String,
}

enum GpuiRemoteGxserverPresentationStreamMessage {
    Event(serde_json::Value),
    Failed,
}

#[derive(Clone)]
struct GpuiRemoteRepositoryCloneRequest {
    job_id: String,
    remote_machine_id: Option<String>,
    toast_id: String,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
enum TitlebarMode {
    Agents,
    Source,
    Browser,
    Kanban,
    Automate,
    Manage,
}

impl TitlebarMode {
    fn from_slug(value: &str) -> Option<Self> {
        match value {
            "agents" => Some(Self::Agents),
            "source" => Some(Self::Source),
            "browser" => Some(Self::Browser),
            "kanban" => Some(Self::Kanban),
            "automate" => Some(Self::Automate),
            "manage" => Some(Self::Manage),
            _ => None,
        }
    }

    fn element_slug(self) -> &'static str {
        match self {
            Self::Agents => "agents",
            Self::Source => "source",
            Self::Browser => "browser",
            Self::Kanban => "kanban",
            Self::Automate => "automate",
            Self::Manage => "manage",
        }
    }

    fn display_label(self) -> &'static str {
        match self {
            Self::Agents => "Agents",
            Self::Source => "Code",
            Self::Browser => "Browser",
            Self::Kanban => "Kanban",
            Self::Automate => "Automate",
            Self::Manage => "Docs",
        }
    }

    fn is_project_editor_mode(self) -> bool {
        matches!(
            self,
            Self::Source | Self::Browser | Self::Kanban | Self::Automate | Self::Manage
        )
    }

    fn project_editor_order(self) -> u64 {
        match self {
            Self::Source => 0,
            Self::Browser => 1,
            Self::Kanban => 2,
            Self::Automate => 3,
            Self::Manage => 4,
            Self::Agents => 5,
        }
    }

    fn switcher_index(self) -> u64 {
        match self {
            Self::Agents => 0,
            Self::Source => 1,
            Self::Browser => 2,
            Self::Kanban => 3,
            Self::Automate => 4,
            Self::Manage => 5,
        }
    }

    fn from_switcher_index(value: u64) -> Option<Self> {
        match value {
            0 => Some(Self::Agents),
            1 => Some(Self::Source),
            2 => Some(Self::Browser),
            3 => Some(Self::Kanban),
            4 => Some(Self::Automate),
            5 => Some(Self::Manage),
            _ => None,
        }
    }

    fn placeholder_message(self) -> &'static str {
        match self {
            Self::Agents => "",
            Self::Source => "Source is unavailable for the current project context.",
            Self::Browser => "",
            Self::Kanban => "Kanban is unavailable for the current project context.",
            Self::Automate => "Automate is unavailable for the current project context.",
            Self::Manage => "Docs is unavailable for the current project context.",
        }
    }
}

/*
CDXC:GPUIProjectEditorPlaceholders 2026-06-28-17:09:
Source, Kanban, Automate, and Docs neutral placeholders are unavailable/loading/error surfaces only. Real Source/Kanban/Automate/Docs replacement is owned by the direct runtime URL plus normal-layout CefSurface gate, so placeholder rendering must not create CEF views, start code-server, run file operations, synthesize fallback URLs, persist private details, or add WKWebView/WebKit paths.
*/
#[derive(Clone, PartialEq, Eq)]
struct ProjectEditorPlaceholderSignature {
    mode: TitlebarMode,
    title: Option<String>,
    message: String,
    actions: Vec<ProjectEditorPlaceholderAction>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ProjectEditorPlaceholderAction {
    HideCodeViewTab,
    InstallSourceComponent,
    RetrySourceLoad,
}

impl ProjectEditorPlaceholderSignature {
    fn for_mode(mode: TitlebarMode) -> Option<Self> {
        if matches!(mode, TitlebarMode::Agents | TitlebarMode::Browser) {
            return None;
        }

        Some(Self {
            mode,
            title: None,
            message: mode.placeholder_message().to_string(),
            actions: Vec::new(),
        })
    }

    fn for_source_code_server_launch_state(
        state: SourceCodeServerRuntimeLaunchState,
        loading_elapsed: Option<Duration>,
    ) -> Option<Self> {
        let signature = Self::for_mode(TitlebarMode::Source)?;
        let (title, message, actions) = match state {
            SourceCodeServerRuntimeLaunchState::Launching
                if loading_elapsed.is_some_and(|elapsed| {
                    elapsed < SOURCE_CODE_SERVER_LOADING_PLACEHOLDER_DELAY
                }) =>
            {
                (None, "".to_string(), Vec::new())
            }
            SourceCodeServerRuntimeLaunchState::Launching => (
                Some("Loading source...".to_string()),
                "".to_string(),
                Vec::new(),
            ),
            _ => return Some(signature),
        };

        Some(Self {
            title,
            message,
            actions,
            ..signature
        })
    }
}

/*
CDXC:GPUIProjectEditorSleepingPlaceholders 2026-06-28-17:09:
Selected sleeping/restored project-editor modes remain real layout participants with neutral text-only shell surfaces. Surface activation expresses wake intent for shell state; Browser hides existing CEF while sleeping, and Source/Kanban/Automate/Docs must not mount or replace runtime surfaces until their awake direct CEF gates permit it.
*/
#[derive(Clone, Copy, PartialEq, Eq)]
struct ProjectEditorSleepingPlaceholderSignature {
    mode: TitlebarMode,
    title: &'static str,
    message: &'static str,
}

impl ProjectEditorSleepingPlaceholderSignature {
    fn for_mode(mode: TitlebarMode) -> Option<Self> {
        /*
        CDXC:GPUIProjectEditorSleepingPlaceholder 2026-06-28-17:09:
        Sleeping/restored Source, Browser, Kanban, Automate, and Docs visible copy is private-detail-free shell state. It must not include project/session/URL details, create CEF views, mount bridges, replace placeholders, or introduce WKWebView/WebKit paths.
        */
        let (title, message) = match mode {
            TitlebarMode::Source => (
                "Source is sleeping",
                "Source shell state is retained. Activate this surface to restore it.",
            ),
            TitlebarMode::Browser => (
                "Browser is sleeping",
                "Browser shell state is retained. Activate this surface to restore it.",
            ),
            TitlebarMode::Kanban => (
                "Kanban is sleeping",
                "Kanban shell state is retained. Activate this surface to restore it.",
            ),
            TitlebarMode::Automate => (
                "Automate is sleeping",
                "Automate shell state is retained. Activate this surface to restore it.",
            ),
            TitlebarMode::Manage => (
                "Docs is sleeping",
                "Docs shell state is retained. Activate this surface to restore it.",
            ),
            TitlebarMode::Agents => return None,
        };

        Some(Self {
            mode,
            title,
            message,
        })
    }
}

