/*
CDXC:GPUIProjectSwitchCoalescing 2026-07-29:
Rapid sidebar clicking across projects used to stack one complete project
switch per click. Each switch parks the outgoing Agents model and destroys the
whole process-local runtime graph (terminal runtimes, Ghostty/engine surfaces,
command pane, browser surfaces), and every superseded switch also
throws away the attach round trip it had already started. Project switches are
therefore coalesced leading-edge + trailing-debounce: the first request runs
immediately so a single click never gets slower, and requests that arrive while
that switch is still settling collapse into one trailing replay of the latest
authoritative request per bridge kind. Requests targeting the project that is
already active are never coalesced; those are intra-project session focus
changes and stay instant.
*/
const GPUI_PROJECT_SWITCH_SETTLE_WINDOW: Duration = Duration::from_millis(350);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GpuiProjectSwitchRequestKind {
    ActiveProjectContext,
    GxserverPresentationFocusState,
    WorkspaceTerminalFocus,
}

impl GpuiProjectSwitchRequestKind {
    fn breadcrumb_id(self) -> &'static str {
        match self {
            Self::ActiveProjectContext => "activeProjectContext",
            Self::GxserverPresentationFocusState => "gxserverPresentationFocusState",
            Self::WorkspaceTerminalFocus => "workspaceTerminalFocus",
        }
    }

    /// Only the two authoritative project snapshots perform the swap itself.
    /// The imperative session-focus requests merely have to land after it, so
    /// they never open a settle window of their own.
    fn opens_settle_window(self) -> bool {
        matches!(
            self,
            Self::ActiveProjectContext | Self::GxserverPresentationFocusState
        )
    }
}

/// A sidebar request collapsed into the trailing edge of a project switch.
/// `ActiveProjectContext` carries no payload because the parsed snapshot is
/// already stored in `latest_sidebar_project_snapshot`; replaying the marker
/// applies whatever the newest stored snapshot is.
#[derive(Clone, Debug)]
enum GpuiPendingProjectSwitchPayload {
    ActiveProjectContext,
    GxserverPresentationFocusState(GpuiGxserverPresentationFocusState),
    WorkspaceTerminalFocus(GpuiSidebarWorkspaceTerminalFocusMessage),
}

impl GpuiPendingProjectSwitchPayload {
    fn kind(&self) -> GpuiProjectSwitchRequestKind {
        match self {
            Self::ActiveProjectContext => GpuiProjectSwitchRequestKind::ActiveProjectContext,
            Self::GxserverPresentationFocusState(_) => {
                GpuiProjectSwitchRequestKind::GxserverPresentationFocusState
            }
            Self::WorkspaceTerminalFocus(_) => GpuiProjectSwitchRequestKind::WorkspaceTerminalFocus,
        }
    }
}

#[derive(Clone, Debug)]
struct GpuiPendingProjectSwitchRequest {
    target_project_id: Option<String>,
    payload: GpuiPendingProjectSwitchPayload,
}

/// True for sidebar bridge events that act on per-project runtime state, so
/// they must not run ahead of a project switch that is still queued behind the
/// settle window. The listed pass-through events are project-agnostic status,
/// telemetry, and compatibility no-ops; flushing on those would defeat the
/// debounce because they arrive on every presentation publish.
fn gpui_sidebar_bridge_event_must_follow_pending_project_switch(
    event: &cef::SidebarBridgeEvent,
) -> bool {
    !matches!(
        event,
        cef::SidebarBridgeEvent::ActiveProjectContext(_)
            | cef::SidebarBridgeEvent::GxserverPresentationFocusState(_)
            | cef::SidebarBridgeEvent::WorkspaceTerminalFocus(_)
            | cef::SidebarBridgeEvent::SessionCompletionSound(_)
            | cef::SidebarBridgeEvent::SessionStatusIndicators(_)
            | cef::SidebarBridgeEvent::PetOverlayState(_)
            | cef::SidebarBridgeEvent::TitlebarGitMenuState(_)
            | cef::SidebarBridgeEvent::ProjectBoardConversationResponse(_)
            | cef::SidebarBridgeEvent::SourceWorkareaReadiness(_)
            | cef::SidebarBridgeEvent::BrowserWorkareaReadiness(_)
            | cef::SidebarBridgeEvent::ProjectWorkareaReadiness(_)
            | cef::SidebarBridgeEvent::ManageFileWorkareaOperationRequest(_)
    )
}

