    fn refresh_gpui_remote_gxserver_presentation_in_background(
        &mut self,
        remote_machine_id: String,
        mark_failed_on_error: bool,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(target) = self.gpui_remote_gxserver_request_target(&remote_machine_id) else {
            return;
        };
        let refresh_stream_generation = self
            .remote_gxserver_connections
            .get(&remote_machine_id)
            .and_then(|connection| connection.presentation_stream_generation);
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let result = background
                .spawn(async move {
                    gpui_remote_gxserver_rpc_result(
                        &target,
                        "/api/readPresentationSnapshot",
                        &serde_json::json!({}),
                        Duration::from_secs(15),
                    )
                })
                .await;
            let _ = this.update(cx, |this, cx| {
                if !refresh_stream_generation.is_some_and(|generation| {
                    !this.gpui_remote_gxserver_presentation_stream_is_current(
                        remote_machine_id.as_str(),
                        generation,
                    )
                }) {
                    match result {
                        Ok(result) => {
                            if let Some(snapshot) = result.get("snapshot").cloned() {
                                this.dispatch_gpui_sidebar_remote_event(
                                    serde_json::json!({
                                        "payload": {
                                            "snapshot": snapshot,
                                            "type": "presentationSnapshot",
                                        },
                                        "remoteMachineId": remote_machine_id.as_str(),
                                        "type": "remoteGxserverPresentation",
                                    }),
                                    cx,
                                );
                            } else if mark_failed_on_error {
                                this.dispatch_gpui_remote_machine_status(
                                    remote_machine_id.as_str(),
                                    "failed",
                                    cx,
                                );
                            }
                        }
                        Err(_) if mark_failed_on_error => {
                            this.dispatch_gpui_remote_machine_status(
                                remote_machine_id.as_str(),
                                "failed",
                                cx,
                            );
                        }
                        Err(_) => {}
                    }
                }
            });
        })
        .detach();
    }

    fn next_gpui_remote_gxserver_connect_generation(&mut self, remote_machine_id: &str) -> u64 {
        let generation = self
            .remote_gxserver_connect_generations
            .entry(remote_machine_id.to_string())
            .or_insert(0);
        *generation = generation.wrapping_add(1);
        if *generation == 0 {
            *generation = 1;
        }
        *generation
    }

    fn gpui_remote_gxserver_connect_generation_is_current(
        &self,
        remote_machine_id: &str,
        generation: u64,
    ) -> bool {
        self.remote_gxserver_connect_generations
            .get(remote_machine_id)
            .copied()
            == Some(generation)
    }

    fn next_gpui_remote_gxserver_presentation_stream_generation(&mut self) -> u64 {
        self.remote_gxserver_presentation_stream_generation = self
            .remote_gxserver_presentation_stream_generation
            .wrapping_add(1);
        if self.remote_gxserver_presentation_stream_generation == 0 {
            self.remote_gxserver_presentation_stream_generation = 1;
        }
        self.remote_gxserver_presentation_stream_generation
    }

    fn gpui_remote_gxserver_presentation_stream_is_current(
        &self,
        remote_machine_id: &str,
        generation: u64,
    ) -> bool {
        self.remote_gxserver_connections
            .get(remote_machine_id)
            .and_then(|connection| connection.presentation_stream_generation)
            == Some(generation)
    }

    fn restart_gpui_remote_gxserver_presentation_stream(
        &mut self,
        remote_machine_id: String,
        client_id: String,
        last_revision: Option<u64>,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        if !self
            .remote_gxserver_connections
            .contains_key(remote_machine_id.as_str())
        {
            return false;
        }
        let generation = self.next_gpui_remote_gxserver_presentation_stream_generation();
        let cancel = Arc::new(AtomicBool::new(false));
        let target = {
            let Some(connection) = self
                .remote_gxserver_connections
                .get_mut(remote_machine_id.as_str())
            else {
                return false;
            };
            if let Some(previous_cancel) = connection.presentation_stream_cancel.as_ref() {
                previous_cancel.store(true, Ordering::SeqCst);
            }
            let target = connection.request_target();
            connection.presentation_stream_cancel = Some(cancel.clone());
            connection.presentation_stream_generation = Some(generation);
            target
        };
        self.start_gpui_remote_gxserver_presentation_stream(
            remote_machine_id,
            target,
            generation,
            cancel,
            client_id,
            last_revision,
            cx,
        );
        true
    }

    fn start_gpui_remote_gxserver_presentation_stream(
        &mut self,
        remote_machine_id: String,
        target: GpuiRemoteGxserverRequestTarget,
        generation: u64,
        cancel: Arc<AtomicBool>,
        client_id: String,
        last_revision: Option<u64>,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUIRemotePresentationStreaming 2026-06-24-19:54:
        A connected remote machine needs the same live gxserver presentation contract as local GPUI, but CEF must not receive remote base URLs or bearer tokens. Rust opens `/api/events` through the localhost SSH tunnel, subscribes with the shared sidebar client id, and forwards only sanitized snapshot/delta payloads. A terminal stream failure enters the shared broken-status funnel, which tears down the stale tunnel before the sidebar schedules a full reconnect.
        */
        let (tx, mut rx) = mpsc::unbounded::<GpuiRemoteGxserverPresentationStreamMessage>();
        let background = cx.background_executor().clone();
        background
            .spawn(async move {
                gpui_remote_gxserver_presentation_stream_loop(
                    target,
                    cancel,
                    tx,
                    client_id,
                    last_revision,
                );
            })
            .detach();
        cx.spawn(async move |this, cx| {
            while let Some(message) = rx.next().await {
                let should_continue = this
                    .update(cx, |this, cx| {
                        if !this.gpui_remote_gxserver_presentation_stream_is_current(
                            remote_machine_id.as_str(),
                            generation,
                        ) {
                            return false;
                        }
                        match message {
                            GpuiRemoteGxserverPresentationStreamMessage::Event(payload) => {
                                this.dispatch_gpui_sidebar_remote_event(
                                    serde_json::json!({
                                        "payload": payload,
                                        "remoteMachineId": remote_machine_id.as_str(),
                                        "type": "remoteGxserverPresentation",
                                    }),
                                    cx,
                                );
                                true
                            }
                            GpuiRemoteGxserverPresentationStreamMessage::Failed => {
                                this.dispatch_gpui_remote_machine_status(
                                    remote_machine_id.as_str(),
                                    GpuiRemoteGxserverConnectState::PresentationStreamFailed
                                        .wire_status_state(),
                                    cx,
                                );
                                false
                            }
                        }
                    })
                    .unwrap_or(false);
                if !should_continue {
                    break;
                }
            }
        })
        .detach();
    }

    fn start_gpui_remote_gxserver_watchdog(&mut self, cx: &mut gpui::Context<Self>) {
        cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor()
                    .timer(GPUI_REMOTE_GXSERVER_WATCHDOG_INTERVAL)
                    .await;
                if this
                    .update(cx, |this, cx| {
                        this.validate_gpui_remote_gxserver_connections(false, cx);
                    })
                    .is_err()
                {
                    break;
                }
            }
        })
        .detach();
    }

    fn validate_gpui_remote_gxserver_connections(
        &mut self,
        wake_validation: bool,
        cx: &mut gpui::Context<Self>,
    ) {
        let exited_machine_ids = self
            .remote_gxserver_connections
            .iter_mut()
            .filter_map(|(machine_id, connection)| {
                (!matches!(connection.child.try_wait(), Ok(None))).then(|| machine_id.clone())
            })
            .collect::<Vec<_>>();
        for machine_id in exited_machine_ids {
            self.stop_gpui_remote_gxserver_connection(machine_id.as_str());
            self.dispatch_gpui_remote_machine_status_with_message(
                machine_id.as_str(),
                "disconnected",
                Some("The remote SSH tunnel disconnected."),
                cx,
            );
        }

        if !wake_validation && self.remote_gxserver_watchdog_probe_in_flight {
            return;
        }
        let probes = self
            .remote_gxserver_connections
            .iter()
            .filter_map(|(machine_id, connection)| {
                let generation = self
                    .remote_gxserver_connect_generations
                    .get(machine_id)
                    .copied()?;
                Some((machine_id.clone(), generation, connection.request_target()))
            })
            .collect::<Vec<_>>();
        if probes.is_empty() {
            return;
        }
        if !wake_validation {
            self.remote_gxserver_watchdog_probe_in_flight = true;
        }
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let results = background
                .spawn(async move {
                    probes
                        .into_iter()
                        .map(|(machine_id, generation, target)| {
                            let healthy = gpui_remote_authenticated_health(
                                target.local_port,
                                target.token.as_str(),
                            )
                            .is_some();
                            (machine_id, generation, target.local_port, healthy)
                        })
                        .collect::<Vec<_>>()
                })
                .await;
            let _ = this.update(cx, |this, cx| {
                if !wake_validation {
                    this.remote_gxserver_watchdog_probe_in_flight = false;
                }
                let mut failed_machine_ids = Vec::new();
                for (machine_id, generation, local_port, healthy) in results {
                    if !this.gpui_remote_gxserver_connect_generation_is_current(
                        machine_id.as_str(),
                        generation,
                    ) {
                        continue;
                    }
                    let Some(connection) = this
                        .remote_gxserver_connections
                        .get_mut(machine_id.as_str())
                    else {
                        continue;
                    };
                    if connection.local_port != local_port {
                        continue;
                    }
                    if healthy {
                        connection.health_check_failures = 0;
                        continue;
                    }
                    connection.health_check_failures =
                        connection.health_check_failures.saturating_add(1);
                    if wake_validation
                        || connection.health_check_failures
                            >= GPUI_REMOTE_GXSERVER_WATCHDOG_FAILURE_THRESHOLD
                    {
                        failed_machine_ids.push(machine_id);
                    }
                }
                for machine_id in failed_machine_ids {
                    this.stop_gpui_remote_gxserver_connection(machine_id.as_str());
                    this.dispatch_gpui_remote_machine_status_with_message(
                        machine_id.as_str(),
                        "disconnected",
                        Some("The remote gxserver tunnel stopped responding."),
                        cx,
                    );
                }
            });
        })
        .detach();
    }

    fn stop_gpui_remote_gxserver_connection(&mut self, remote_machine_id: &str) {
        if let Some(mut connection) = self.remote_gxserver_connections.remove(remote_machine_id) {
            connection.terminate();
        }
    }

    fn stop_all_gpui_remote_gxserver_connections(&mut self) {
        for (_, mut connection) in self.remote_gxserver_connections.drain() {
            connection.terminate();
        }
    }

    fn sync_gpui_ghostty_config_file_after_settings_save(
        &mut self,
        ghostty_config_backed_setting_keys_changed: &[&str],
        settings_snapshot: &shared_settings::SharedSidebarSettingsSnapshot,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGhosttyConfig 2026-06-24-12:24:
        Normal GPUI `updateSettings` saves should write generated Ghostty managed terminal settings only when a config-backed terminal value changed. The current GPUI GhosttyKit wrapper has load/create surface FFI but no safe live reload/update API, so this write affects Ghostty's config file, external Ghostty reloads, and future/recreated GPUI surfaces without claiming live embedded terminal reload.
        */
        if ghostty_config_backed_setting_keys_changed.is_empty() {
            return;
        }
        if shared_settings::write_ghostty_terminal_config_from_settings_object(
            settings_snapshot.object(),
            ghostty_config_backed_setting_keys_changed,
        )
        .is_ok()
        {
            return;
        }
        let message = "Settings were saved, but GPUI could not write the managed Ghostty config file. Existing embedded terminals were not live reloaded.";
        self.dispatch_gpui_settings_action_status("ghosttySettings", false, message, cx);
        self.dispatch_gpui_app_modal_toast(
            "warning",
            "Could not update Ghostty config",
            message,
            cx,
        );
    }

    fn sync_gpui_gxserver_agent_settings_after_save(
        &mut self,
        previous_agent_settings: shared_settings::SharedGxserverAgentSettings,
        next_agent_settings: shared_settings::SharedGxserverAgentSettings,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-11:39:
        GPUI matches macOS for agent launch policy: shared Settings is the local render cache, while local gxserver owns inherited Accept All and Default Prompt Agent behavior for launchers across clients. After a successful Settings save, post the current two gxserver-owned values only when either changed, and keep token/network/parser failures silent so unavailable gxserver never creates fake daemon state or rolls back the saved local cache.
        */
        if previous_agent_settings == next_agent_settings {
            return;
        }

        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let canonical_agent_settings = background
                .spawn(async move { update_gpui_gxserver_agent_settings(&next_agent_settings) })
                .await
                .ok();
            let Some(canonical_agent_settings) = canonical_agent_settings else {
                return;
            };
            let _ = this.update(cx, |this, cx| {
                this.apply_gpui_gxserver_agent_settings_to_local_settings(
                    canonical_agent_settings,
                    cx,
                );
            });
        })
        .detach();
    }

    fn reconcile_gpui_gxserver_agent_settings_in_background(
        &mut self,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-12:14:
        GPUI startup/open-time hydration must match macOS migration semantics for gxserver-owned agent policy. Read `/api/readAgentSettings`; if gxserver has no persisted row, seed it once from current shared Settings, otherwise treat daemon values as canonical and refresh the local render cache through the central settings service without logging tokens, response bodies, paths, commands, or user content.
        */
        if self.gxserver_agent_settings_reconciliation_in_flight {
            return;
        }
        self.gxserver_agent_settings_reconciliation_in_flight = true;

        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let hydration_result = background
                .spawn(async move { reconcile_gpui_gxserver_agent_settings_with_daemon() })
                .await
                .ok()
                .flatten();
            let _ = this.update(cx, |this, cx| {
                this.gxserver_agent_settings_reconciliation_in_flight = false;
                if let Some(hydration_result) = hydration_result {
                    this.apply_gpui_gxserver_agent_settings_hydration_result(hydration_result, cx);
                }
            });
        })
        .detach();
    }

    fn gpui_app_modal_sidebar_state_message_for_open(
        &mut self,
        modal: GpuiAppModalKind,
        cx: &mut gpui::Context<Self>,
    ) -> serde_json::Value {
        /*
        CDXC:GPUISettingsEntryModals 2026-06-24-12:22:
        Any shared Settings entry point can show agent-owned controls after the React host selects its initial tab. Reconcile gxserver-owned agent policy before hydrating Settings, Hotkeys, Configure Agents, Configure Actions, and Open Targets so entry-specific modal ids do not drift from the canonical Settings route.
        */
        if modal.is_settings_modal_entry() {
            self.reconcile_gpui_gxserver_agent_settings_in_background(cx);
        }
        self.gpui_app_modal_sidebar_state_message()
    }

    fn gpui_app_modal_sidebar_state_message(&self) -> serde_json::Value {
        self.with_gpui_command_pane_sidebar_indicators(gpui_app_modal_sidebar_state_message(
            self.latest_sidebar_project_snapshot.as_ref(),
        ))
    }

    fn gpui_app_modal_sidebar_state_message_from_settings_snapshot(
        &self,
        settings_snapshot: &shared_settings::SharedSidebarSettingsSnapshot,
    ) -> serde_json::Value {
        self.with_gpui_command_pane_sidebar_indicators(
            gpui_app_modal_sidebar_state_message_from_settings_snapshot(
                settings_snapshot,
                self.latest_sidebar_project_snapshot.as_ref(),
            ),
        )
    }

    fn with_gpui_command_pane_sidebar_indicators(
        &self,
        mut message: serde_json::Value,
    ) -> serde_json::Value {
        /*
        CDXC:GPUICommandPane 2026-06-25-10:50:
        App-modal sidebar hydrates must carry the same command-session indicators as the live GPUI sidebar HUD. Reuse the sanitized command-pane summary and gxserver command rows; never compute from command text, paths, status-file paths, terminal output, logs, or persisted shell-state JSON.
        */
        let commands = message
            .get("hud")
            .and_then(|hud| hud.get("commands"))
            .cloned()
            .unwrap_or_else(|| serde_json::Value::Array(Vec::new()));
        let sessions = self.command_pane.sidebar_command_session_sources(
            self.shell_focus == ShellFocusTarget::CommandPane,
            &self.command_delayed_send_timers,
            &self.command_close_after_done_timers,
            SystemTime::now(),
        );
        message["hud"]["commandSessionIndicators"] =
            gpui_sidebar_command_session_indicators_from_command_pane_sources(&commands, &sessions);
        message
    }

    fn apply_gpui_gxserver_agent_settings_hydration_result(
        &mut self,
        hydration_result: GpuiGxserverAgentSettingsHydrationResult,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-12:14:
        Startup/open hydration may finish after the user saves Settings. Apply daemon canonical values only if the shared render cache still matches the local values used for the read/seed decision; a newer save uses the existing save-time gxserver sync path instead of being overwritten by a stale startup response.
        */
        if shared_settings::shared_sidebar_settings_snapshot().gxserver_agent_settings()
            != hydration_result.expected_local_settings
        {
            return;
        }
        self.apply_gpui_gxserver_agent_settings_to_local_settings(
            hydration_result.canonical_settings,
            cx,
        );
    }

    fn apply_gpui_gxserver_agent_settings_to_local_settings(
        &mut self,
        canonical_agent_settings: shared_settings::SharedGxserverAgentSettings,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-11:39:
        gxserver read/update responses are canonical for inherited agent launch policy. If the daemon reports either agent setting differently than the current GPUI render cache, persist those canonical values through the central shared Settings service and refresh the modal/sidebar runtime state again instead of writing a separate cache or logging private daemon details.
        */
        let latest_settings_snapshot = shared_settings::shared_sidebar_settings_snapshot();
        if latest_settings_snapshot.gxserver_agent_settings() == canonical_agent_settings {
            return;
        }

        let mut settings_object = latest_settings_snapshot.object().clone();
        canonical_agent_settings.write_to_settings_object(&mut settings_object);
        let Ok(write_result) =
            shared_settings::write_shared_sidebar_settings_object(settings_object)
        else {
            return;
        };
        self.refresh_gpui_shared_settings_consumers_after_save(&write_result.snapshot, cx);
    }

    fn refresh_gpui_shared_settings_consumers_after_save(
        &mut self,
        settings_snapshot: &shared_settings::SharedSidebarSettingsSnapshot,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsPersistence 2026-06-24-11:19:
        After a successful Settings save or gxserver startup/open canonical sync, GPUI refreshes only the settings-dependent runtime state it owns today: app-modal hydrate/sidebarState, sidebar debug/beta booleans through the existing CEF runtime-settings path, project-workarea CEF visibility, project-editor auto-sleep scheduling, supported embedded Ghostty request-map settings, gxserver-owned agent-policy reconciliation, and central-service render reads such as the Browser feedback/profile toolbar controls. This is not full settings fan-out; many action bridges, code-server sync, live Ghostty config reloads, and broad future side effects remain outside this path.
        */
        self.reschedule_project_editor_auto_sleep_if_policy_changed_from_shared_settings(
            settings_snapshot,
            cx,
        );
        self.apply_gpui_sidebar_side_from_saved_settings(settings_snapshot);
        self.apply_gpui_command_pane_side_from_saved_settings(settings_snapshot);
        refresh_gpui_visual_settings(settings_snapshot);
        self.refresh_sidebar_runtime_settings_from_shared_settings(settings_snapshot, cx);
        self.coerce_active_mode_to_available_project_context(cx);
        #[cfg(target_os = "macos")]
        self.refresh_terminal_ghostty_surface_config_requests_from_shared_settings(
            settings_snapshot,
        );
        self.reload_live_gpui_engine_terminal_config(cx);
        let sidebar_state_message =
            self.gpui_app_modal_sidebar_state_message_from_settings_snapshot(settings_snapshot);
        self.refresh_open_gpui_app_modal_sidebar_state(sidebar_state_message, cx);
        let chat_theme = gpui_session_chat_theme_from_settings(settings_snapshot.object());
        let chat_theme_literal =
            serde_json::to_string(chat_theme).unwrap_or_else(|_| "\"dark\"".to_string());
        let chat_theme_script =
            format!("window.ghostexSetSessionChatTheme?.({chat_theme_literal});undefined;");
        let chat_font_family =
            gpui_session_chat_font_family_from_settings(settings_snapshot.object());
        let chat_font_family_literal =
            serde_json::to_string(&chat_font_family).unwrap_or_else(|_| "\"\"".to_string());
        let chat_font_family_script = format!(
            "window.ghostexSetSessionChatFontFamily?.({chat_font_family_literal});undefined;"
        );
        let chat_transcript_width_percent =
            gpui_session_chat_transcript_width_percent_from_settings(settings_snapshot.object());
        let chat_transcript_width_script = format!(
            "window.ghostexSetSessionChatTranscriptWidthPercent?.({chat_transcript_width_percent});undefined;"
        );
        let chat_verbose_mode =
            gpui_session_chat_verbose_mode_from_settings(settings_snapshot.object());
        let chat_verbose_mode_script =
            format!("window.ghostexSetSessionChatVerboseMode?.({chat_verbose_mode});undefined;");
        for surface in self.agents_chat_surfaces.values() {
            surface.update(cx, |surface, _| {
                surface.execute_app_owned_script(&chat_theme_script);
                surface.execute_app_owned_script(&chat_font_family_script);
                surface.execute_app_owned_script(&chat_transcript_width_script);
                surface.execute_app_owned_script(&chat_verbose_mode_script);
            });
        }
        // Newly saved hotkey chords bind immediately. The save boundary first
        // adds targeted Unbind markers for the prior Ghostex action chords, so
        // removed/remapped entries stop dispatching without clearing GPUI or
        // gpui-component's unrelated keymap entries.
        cx.bind_keys(gpui_configured_hotkey_key_bindings_from_settings());
        cx.notify();
    }

    fn reload_live_gpui_engine_terminal_config(&mut self, cx: &mut gpui::Context<Self>) {
        let shared_engine_settings =
            shared_settings::shared_sidebar_settings_snapshot().gpui_terminal_engine_settings();
        #[cfg(target_os = "macos")]
        let mut config = {
            let Ok(path) = shared_settings::selected_ghostty_config_path() else {
                return;
            };
            let Ok(config) =
                terminal_ghostty_surface::load_ghostty_terminal_engine_config_from_path(
                    &path,
                    terminal_gpui_engine::ghostty_theme_source(
                        &shared_engine_settings.ghostty_theme,
                    ),
                )
            else {
                return;
            };
            config
        };
        #[cfg(not(target_os = "macos"))]
        let mut config =
            terminal_gpui_engine::GpuiTerminalEngineConfig::from_shared(&shared_engine_settings);
        #[cfg(target_os = "macos")]
        if let Some(background) = shared_engine_settings.terminal_background_rgb {
            config.apply_terminal_background(background);
        }

        // This setting is app-owned and is not part of Ghostty's finalized
        // config string on macOS.
        config.view.scroll_to_bottom_when_typing =
            shared_engine_settings.scroll_to_bottom_when_typing;
        config.view.background_image =
            terminal_gpui_engine::terminal_background_image_from_settings(&shared_engine_settings);

        let confirm_close_behavior =
            terminal_gpui_engine::gpui_engine_confirm_close_behavior(&config);
        for record in self
            .agents_gpui_engine_terminals
            .values_mut()
            .chain(self.command_gpui_engine_terminals.values_mut())
        {
            record.confirm_close_behavior = confirm_close_behavior;
            let view = record.view.clone();
            let font = config.font.clone();
            let settings = config.view.clone();
            let colors = config.colors.clone();
            let option_as_alt = config.option_as_alt;
            view.update(cx, |view, cx| {
                view.apply_font(font);
                view.apply_settings(settings);
                view.model_mut().set_option_as_alt(option_as_alt);
                if let Some(colors) = colors {
                    let _ = view.model_mut().set_default_colors(
                        colors.foreground,
                        colors.background,
                        colors.cursor,
                        &colors.palette,
                    );
                }
                cx.notify();
            });
        }
    }

    #[cfg(target_os = "macos")]
    fn refresh_terminal_ghostty_surface_config_requests_from_shared_settings(
        &mut self,
        settings_snapshot: &shared_settings::SharedSidebarSettingsSnapshot,
    ) {
        /*
        CDXC:GPUITerminalSettings 2026-06-24-11:27:
        `updateSettings` fan-out refreshes the GPUI-owned Ghostty request maps so subsequent Agents, command, and startup surface creations use the saved supported terminal settings. Existing live Ghostty surfaces are not reloaded here because this runtime path does not yet expose a safe config-reload/apply contract; do not fake reload by dropping running terminals or logging raw settings.
        */
        let terminal_config =
            gpui_terminal_ghostty_surface_config_from_shared_settings(settings_snapshot);
        for request in self
            .agents_terminal_ghostty_surface_config_requests
            .values_mut()
        {
            request.set_terminal_config(terminal_config);
        }
        for request in self
            .command_terminal_ghostty_surface_config_requests
            .values_mut()
        {
            request.set_terminal_config(terminal_config);
        }
        for request in self
            .agents_terminal_startup_ghostty_surface_config_requests
            .values_mut()
        {
            request.set_terminal_config(terminal_config);
        }
    }

    fn refresh_open_gpui_app_modal_sidebar_state(
        &mut self,
        sidebar_state_message: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(handle) = self.app_modal_window.clone() else {
            return;
        };
        let update_result = handle.update(cx, |host, modal_window, cx| {
            host.refresh_sidebar_state_message(sidebar_state_message.clone(), cx);
            modal_window.refresh();
        });
        if update_result.is_err() {
            self.clear_lost_gpui_app_modal_window_handle();
        }
    }

    fn dispatch_open_gpui_app_modal_sidebar_state_payload(
        &mut self,
        payload: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsStatusBridge 2026-06-24-11:36:
        Settings status/action responses are transient `sidebarState` messages to the shared React modal host. They must clear modal loading states without replacing the stored full hydrate snapshot used when the app-modal host becomes ready or a Settings save rehydrates the modal.
        */
        let Some(handle) = self.app_modal_window.clone() else {
            return;
        };
        let update_result = handle.update(cx, |host, modal_window, cx| {
            host.dispatch_transient_sidebar_state_message(payload, cx);
            modal_window.refresh();
        });
        if update_result.is_err() {
            self.clear_lost_gpui_app_modal_window_handle();
        }
    }

    fn dispatch_gpui_titlebar_tips_project_state_update(
        &mut self,
        project_state_update: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(panel) = self.titlebar_tips_panel.clone() else {
            return;
        };
        panel.update(cx, |panel, cx| {
            panel.dispatch_project_state_update(project_state_update.clone(), cx);
        });
    }

    fn dispatch_gpui_titlebar_tips_sidebar_state_payload(
        &mut self,
        payload: &serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        match payload.get("type").and_then(serde_json::Value::as_str) {
            Some("ghostexCliStatus") => {
                self.titlebar_tips_cli_status = Some(payload.clone());
            }
            Some("agentHookStatus") => {
                self.titlebar_tips_agent_hook_status = Some(payload.clone());
            }
            _ => {}
        }
        if self.titlebar_popup_menu_open(GpuiTitlebarPopupKind::Tips)
            && let Some(handle) = self.titlebar_popup_window.clone()
        {
            let payload = payload.clone();
            let _ = handle.update(cx, |popup, window, cx| {
                popup.update_tips_runtime_status(payload, cx);
                window.refresh();
            });
        }
        let Some(project_state_update) =
            gpui_titlebar_project_state_update_from_sidebar_state_payload(payload)
        else {
            return;
        };
        self.dispatch_gpui_titlebar_tips_project_state_update(project_state_update, cx);
    }

    fn gpui_app_modal_current_modal(
        &mut self,
        cx: &mut gpui::Context<Self>,
    ) -> Option<GpuiAppModalKind> {
        let handle = self.app_modal_window.clone()?;
        handle
            .update(cx, |host, _modal_window, _cx| host.current_modal)
            .ok()
    }

    fn dispatch_open_gpui_app_modal_message(
        &mut self,
        message: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(handle) = self.app_modal_window.clone() else {
            return;
        };
        let update_result = handle.update(cx, |host, modal_window, cx| {
            host.dispatch_transient_message(message.clone(), cx);
            modal_window.refresh();
        });
        if update_result.is_err() {
            self.clear_lost_gpui_app_modal_window_handle();
        }
    }

    fn dispatch_gpui_app_modal_toast(
        &mut self,
        level: &str,
        title: &str,
        description: &str,
        cx: &mut gpui::Context<Self>,
    ) {
        self.dispatch_open_gpui_app_modal_message(
            serde_json::json!({
                "description": gpui_normalized_app_toast_description(title, Some(description)),
                "level": level,
                "title": title,
                "type": "toast",
            }),
            cx,
        );
    }

    /*
    CDXC:GPUIRemoteNewTerminal 2026-08-20:
    Toasts sent to the app-modal host only render while a modal window is open,
    because that host IS the modal window. Sidebar and tab-strip actions run with
    no modal up, so their failures were dropped on the floor and the click looked
    like it did nothing at all. Report those outcomes through the dedicated
    bottom-center app-toast window, which is the same modal-independent surface
    the sidebar bridge and daemon bootstrap already use.
    */
    fn dispatch_gpui_workspace_action_toast(
        &mut self,
        level: &str,
        title: &str,
        description: &str,
        cx: &mut gpui::Context<Self>,
    ) {
        self.app_toast_id_counter = self.app_toast_id_counter.wrapping_add(1);
        let id = format!("gpui-app-toast-{}", self.app_toast_id_counter);
        self.upsert_gpui_app_toast(
            GpuiAppToast {
                id,
                level: GpuiAppToastLevel::from_raw(Some(level)),
                title: title.to_string(),
                description: (!description.is_empty()).then(|| description.to_string()),
                loading: false,
                persistent: false,
                duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                epoch: 0,
            },
            cx,
        );
    }

    /// App toasts from the sidebar bridge (git/worktree/sync/clone progress)
    /// render in a dedicated bottom-center popup window, mirroring the macOS
    /// native toast panels. An in-window layer cannot work here: the workspace
    /// area is covered by native Ghostty/CEF child views that draw above all
    /// GPUI content.
    fn receive_gpui_app_toast_bridge_message(
        &mut self,
        message: &serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        self.app_toast_id_counter = self.app_toast_id_counter.wrapping_add(1);
        let generated_id = format!("gpui-app-toast-{}", self.app_toast_id_counter);
        let Some(toast) = gpui_app_toast_from_bridge_message(message, generated_id) else {
            return;
        };
        self.upsert_gpui_app_toast(toast, cx);
    }

    fn upsert_gpui_app_toast(&mut self, mut toast: GpuiAppToast, cx: &mut gpui::Context<Self>) {
        toast.description =
            gpui_normalized_app_toast_description(&toast.title, toast.description.as_deref());
        let main_window_bounds = self.main_window_bounds;
        self.app_toast_anchor = Some(point(
            main_window_bounds.origin.x + main_window_bounds.size.width / 2.0,
            main_window_bounds.origin.y + main_window_bounds.size.height,
        ));
        self.app_toast_epoch = self.app_toast_epoch.wrapping_add(1);
        toast.epoch = self.app_toast_epoch;
        let auto_dismiss =
            (!toast.persistent).then(|| (toast.id.clone(), toast.epoch, toast.duration_ms));
        if let Some(existing) = self
            .app_toasts
            .iter_mut()
            .find(|existing| existing.id == toast.id)
        {
            *existing = toast;
        } else {
            self.app_toasts.push(toast);
            while self.app_toasts.len() > GPUI_APP_TOAST_MAX_VISIBLE {
                self.app_toasts.remove(0);
            }
        }
        if let Some((toast_id, epoch, duration_ms)) = auto_dismiss {
            self.schedule_gpui_app_toast_auto_dismiss(toast_id, epoch, duration_ms, cx);
        }
        self.sync_gpui_app_toast_window(cx);
    }

    fn show_gpui_gxserver_bootstrap_toast(
        &mut self,
        level: &str,
        title: &str,
        description: &str,
        persistent: bool,
        cx: &mut gpui::Context<Self>,
    ) {
        // Every daemon-bootstrap outcome funnels through this toast, so the
        // sidebar-refresh support log records the same fixed level/title pair
        // (warning/error outcomes persist without the scenario).
        support_logs::append(
            support_logs::GpuiSupportLog::SidebarRefresh,
            if level == "info" {
                "gpui.sidebar.gxserverBootstrapStatus"
            } else {
                "gpui.sidebar.gxserverBootstrapWarning"
            },
            serde_json::json!({ "level": level, "title": title }),
        );
        self.upsert_gpui_app_toast(
            GpuiAppToast {
                id: GPUI_GXSERVER_DAEMON_TOAST_ID.to_string(),
                level: GpuiAppToastLevel::from_raw(Some(level)),
                title: title.to_string(),
                description: (!description.is_empty()).then(|| description.to_string()),
                loading: level == "info" && persistent,
                persistent,
                duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                epoch: 0,
            },
            cx,
        );
    }

    /// Will-terminate persistence flush (macOS `applicationWillTerminate`
    /// parity): persist shell state, restore lid-close sleep by stopping the
    /// Keep Awake runtime, stop the app-owned code-server, and deliberately
    /// never stop gxserver. CEF owns the durable Browser-profile store and
    /// flushes it during the existing CEF shutdown sequence; GPUI does not
    /// duplicate cookies or site storage in shell state here.
    fn flush_gpui_quit_persistence(&mut self, cx: &mut gpui::Context<Self>) {
        /*
        CDXC:GPUICommandPaneQuitPersistence 2026-07-10:
        App teardown closes the local GPUI/Ghostty renderer that is attached to
        each command zmx session. That renderer exit is not a terminal-session
        exit: command providers and their processes must remain alive so the
        next app process can reattach. Mark the quit boundary before persistence
        or runtime teardown so a final render cannot consume detach as an exit,
        delete the saved tab, and route an explicit gxserver close.
        */
        GPUI_APP_QUIT_IN_PROGRESS.store(true, Ordering::Release);
        support_logs::append(
            support_logs::GpuiSupportLog::HostLifecycle,
            "gpui.host.willTerminate",
            serde_json::json!({ "pid": std::process::id() }),
        );
        self.persist_shell_layout_state();
        self.stop_gpui_keep_awake_runtime();
        self.source_code_server_runtime.stop();
        let _ = cx;
    }

    /// Startup lifecycle breadcrumb plus the one-minute-delayed support-log
    /// retention pass (macOS `scheduleSupportLogLineRetentionAfterStartup`
    /// parity, scoped to GPUI's own `gpui-*` files).
    fn start_gpui_support_log_maintenance(&mut self, cx: &mut gpui::Context<Self>) {
        support_logs::append(
            support_logs::GpuiSupportLog::HostLifecycle,
            "gpui.host.didFinishLaunching",
            serde_json::json!({ "pid": std::process::id() }),
        );
        let executor = cx.background_executor().clone();
        let timer_executor = executor.clone();
        executor
            .spawn(async move {
                timer_executor
                    .timer(support_logs::RETENTION_STARTUP_DELAY)
                    .await;
                support_logs::prune_gpui_support_logs();
            })
            .detach();
    }

    /// Starts the packaged platform updater. Unpackaged builds simply run
    /// without an updater; packaged macOS keeps Sparkle and packaged Windows
    /// uses the Velopack manifest staged beside the executable.
    #[cfg(target_os = "macos")]
    fn start_gpui_updater(&mut self, cx: &mut gpui::Context<Self>) {
        let start_result = unsafe { GhostexGpuiSparkleUpdaterStart() };
        if start_result == 0 {
            return;
        }
        if start_result != 1 {
            cx.spawn(async move |this, cx| {
                let _ = this.update(cx, |this, cx| {
                    this.upsert_gpui_app_toast(
                        GpuiAppToast {
                            id: "gpui-sparkle-updater-start-failed".to_string(),
                            level: GpuiAppToastLevel::from_raw(Some("warning")),
                            title: "Updates unavailable".to_string(),
                            description: Some(
                                "Sparkle could not start the updater for this build.".to_string(),
                            ),
                            loading: false,
                            persistent: false,
                            duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                            epoch: 0,
                        },
                        cx,
                    );
                });
            })
            .detach();
            return;
        }
        self.updater_started = true;
        // Sparkle intentionally defers its automatic scheduler by one main-loop
        // cycle so clients can initiate their own check immediately after
        // start. Match the legacy AppKit host by using that window for the
        // quiet availability probe; deferring this call lets Sparkle's
        // scheduler win and leaves both manual and titlebar checks blocked by
        // its in-progress session.
        unsafe { GhostexGpuiSparkleProbeForUpdateInformation() };
        cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor()
                    .timer(GPUI_UPDATE_AVAILABILITY_PROBE_INTERVAL)
                    .await;
                let probed = this
                    .update(cx, |this, _cx| {
                        if !this.updater_started {
                            return false;
                        }
                        unsafe { GhostexGpuiSparkleProbeForUpdateInformation() };
                        true
                    })
                    .unwrap_or(false);
                if !probed {
                    return;
                }
            }
        })
        .detach();
    }

    #[cfg(target_os = "windows")]
    fn start_gpui_updater(&mut self, cx: &mut gpui::Context<Self>) {
        let Ok(updater) = windows_updater::WindowsUpdater::new() else {
            // Cargo/dev builds intentionally have no Velopack manifest.
            return;
        };
        self.windows_updater = Some(updater);
        self.updater_started = true;
        self.begin_windows_update_check(false, cx);
        cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor()
                    .timer(GPUI_UPDATE_AVAILABILITY_PROBE_INTERVAL)
                    .await;
                let keep_running = this
                    .update(cx, |this, cx| {
                        if !this.updater_started {
                            return false;
                        }
                        this.begin_windows_update_check(false, cx);
                        true
                    })
                    .unwrap_or(false);
                if !keep_running {
                    return;
                }
            }
        })
        .detach();
    }

    #[cfg(not(any(target_os = "macos", target_os = "windows")))]
    fn start_gpui_updater(&mut self, _cx: &mut gpui::Context<Self>) {}

    /// Titlebar update-button click and app-menu Check for Updates (macOS
    /// `showUpdateDialogFromTitlebar` / `checkForUpdates` parity): the click is
    /// the consent boundary; hand off to Sparkle's standard flow so release
    /// notes, signature validation, download, and install stay on the
    /// supported path. Ignored while a download runs, matching the disabled
    /// React titlebar button.
    // The window stays in the signature for parity with the Windows updater,
    // which opens its own update modal; Sparkle owns its own panels here.
    #[cfg(target_os = "macos")]
    fn check_for_gpui_updates(&mut self, _window: &mut Window, cx: &mut gpui::Context<Self>) {
        if self.update_downloading {
            return;
        }
        if !self.updater_started {
            self.upsert_gpui_app_toast(
                GpuiAppToast {
                    id: "gpui-sparkle-updater-unavailable".to_string(),
                    level: GpuiAppToastLevel::from_raw(Some("warning")),
                    title: "Updates unavailable".to_string(),
                    description: Some(
                        "This build was packaged without the Sparkle updater.".to_string(),
                    ),
                    loading: false,
                    persistent: false,
                    duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                    epoch: 0,
                },
                cx,
            );
            return;
        }
        unsafe { GhostexGpuiSparkleCheckForUpdates() };
    }

    #[cfg(target_os = "windows")]
    fn check_for_gpui_updates(&mut self, window: &mut Window, cx: &mut gpui::Context<Self>) {
        if self.update_downloading {
            return;
        }
        if self.windows_update.is_some() || self.windows_ready_update.is_some() {
            self.open_windows_update_modal(Some(window), cx);
            return;
        }
        if !self.updater_started {
            self.upsert_gpui_app_toast(
                GpuiAppToast {
                    id: "gpui-windows-updater-unavailable".to_string(),
                    level: GpuiAppToastLevel::from_raw(Some("warning")),
                    title: "Updates unavailable".to_string(),
                    description: Some(
                        "This build was not installed or packaged with Velopack.".to_string(),
                    ),
                    loading: false,
                    persistent: false,
                    duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                    epoch: 0,
                },
                cx,
            );
            return;
        }
        self.begin_windows_update_check(true, cx);
    }

    #[cfg(not(any(target_os = "macos", target_os = "windows")))]
    fn check_for_gpui_updates(&mut self, _window: &mut Window, _cx: &mut gpui::Context<Self>) {}

    fn set_gpui_update_available(&mut self, available: bool, cx: &mut gpui::Context<Self>) {
        if self.update_available == available {
            return;
        }
        self.update_available = available;
        cx.notify();
    }

    fn set_gpui_update_downloading(&mut self, downloading: bool, cx: &mut gpui::Context<Self>) {
        let progress_cleared = !downloading && self.update_download_progress.is_some();
        if progress_cleared {
            self.update_download_progress = None;
        }
        if self.update_downloading == downloading && !progress_cleared {
            return;
        }
        self.update_downloading = downloading;
        cx.notify();
    }

    fn set_gpui_update_download_progress(
        &mut self,
        progress: Option<f64>,
        cx: &mut gpui::Context<Self>,
    ) {
        let normalized =
            progress.and_then(|value| value.is_finite().then(|| value.clamp(0.0, 1.0)));
        if self.update_download_progress == normalized {
            return;
        }
        self.update_download_progress = normalized;
        if self.update_downloading {
            cx.notify();
        }
    }

    #[cfg(target_os = "windows")]
    fn begin_windows_update_check(&mut self, interactive: bool, cx: &mut gpui::Context<Self>) {
        if self.update_checking || self.update_downloading {
            return;
        }
        let Some(updater) = self.windows_updater.clone() else {
            return;
        };
        self.update_checking = true;
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let result = background
                .spawn(async move {
                    updater
                        .check_for_updates()
                        .map_err(|error| error.to_string())
                })
                .await;
            let _ = this.update_in(cx, |this, window, cx| {
                this.update_checking = false;
                match result {
                    Ok(windows_updater::WindowsUpdateCheck::UpdateAvailable(update)) => {
                        let ready_update = this
                            .windows_updater
                            .as_ref()
                            .and_then(windows_updater::WindowsUpdater::pending_restart)
                            .filter(|asset| asset.Version == update.version());
                        this.windows_update = Some(update);
                        this.windows_ready_update = ready_update;
                        this.set_gpui_update_available(true, cx);
                        if interactive {
                            this.open_windows_update_modal(Some(window), cx);
                        }
                    }
                    Ok(windows_updater::WindowsUpdateCheck::NoUpdateAvailable) => {
                        this.windows_update = None;
                        this.windows_ready_update = None;
                        this.set_gpui_update_available(false, cx);
                        if interactive {
                            this.upsert_gpui_app_toast(
                                GpuiAppToast {
                                    id: "gpui-windows-updater-current".to_string(),
                                    level: GpuiAppToastLevel::from_raw(Some("success")),
                                    title: "Ghostex is up to date".to_string(),
                                    description: None,
                                    loading: false,
                                    persistent: false,
                                    duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                                    epoch: 0,
                                },
                                cx,
                            );
                        }
                    }
                    Err(_) if !interactive => {}
                    Err(_) => {
                        this.upsert_gpui_app_toast(
                            GpuiAppToast {
                                id: "gpui-windows-updater-check-failed".to_string(),
                                level: GpuiAppToastLevel::from_raw(Some("warning")),
                                title: "Could not check for updates".to_string(),
                                description: Some(
                                    "Check your connection and try again.".to_string(),
                                ),
                                loading: false,
                                persistent: false,
                                duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                                epoch: 0,
                            },
                            cx,
                        );
                    }
                }
            });
        })
        .detach();
    }

    #[cfg(target_os = "windows")]
    fn open_windows_update_modal(
        &mut self,
        source_window: Option<&mut Window>,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(update) = self.windows_update.as_ref() else {
            return;
        };
        let ready = self.windows_ready_update.is_some();
        let portable = self
            .windows_updater
            .as_ref()
            .is_some_and(windows_updater::WindowsUpdater::is_portable);
        let open_message = serde_json::json!({
            "modal": GpuiAppModalKind::UpdateAvailable.modal_id(),
            "notesMarkdown": update.notes_markdown(),
            "portable": portable,
            "state": if ready { "ready" } else { "available" },
            "type": "open",
            "version": update.version(),
        });
        self.open_gpui_app_modal_window(
            GpuiAppModalKind::UpdateAvailable,
            open_message,
            serde_json::Value::Null,
            source_window,
            cx,
        );
    }

    #[cfg(target_os = "windows")]
    fn download_windows_update(&mut self, cx: &mut gpui::Context<Self>) {
        if self.update_downloading || self.windows_ready_update.is_some() {
            return;
        }
        let (Some(updater), Some(update)) =
            (self.windows_updater.clone(), self.windows_update.clone())
        else {
            return;
        };
        self.set_gpui_update_downloading(true, cx);
        self.set_gpui_update_download_progress(Some(0.0), cx);

        let (progress_sender, progress_receiver) = std::sync::mpsc::channel::<i16>();
        let (result_sender, result_receiver) = std::sync::mpsc::channel();
        cx.background_executor()
            .spawn(async move {
                let result = updater
                    .download(&update, progress_sender)
                    .map_err(|error| error.to_string());
                let _ = result_sender.send(result);
            })
            .detach();

        cx.spawn(async move |this, cx| {
            loop {
                let mut latest_progress = None;
                for progress in progress_receiver.try_iter() {
                    latest_progress = Some(f64::from(progress) / 100.0);
                }
                if let Some(progress) = latest_progress {
                    let _ = this.update(cx, |this, cx| {
                        this.set_gpui_update_download_progress(Some(progress), cx);
                    });
                }
                match result_receiver.try_recv() {
                    Ok(result) => {
                        let _ = this.update_in(cx, |this, window, cx| {
                            this.set_gpui_update_downloading(false, cx);
                            match result {
                                Ok(asset) => {
                                    this.windows_ready_update = Some(asset);
                                    this.set_gpui_update_available(true, cx);
                                    this.open_windows_update_modal(Some(window), cx);
                                }
                                Err(_) => {
                                    this.upsert_gpui_app_toast(
                                        GpuiAppToast {
                                            id: "gpui-windows-updater-download-failed".to_string(),
                                            level: GpuiAppToastLevel::from_raw(Some("warning")),
                                            title: "Update download failed".to_string(),
                                            description: Some(
                                                "The update was not installed. Try again from the titlebar."
                                                    .to_string(),
                                            ),
                                            loading: false,
                                            persistent: false,
                                            duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                                            epoch: 0,
                                        },
                                        cx,
                                    );
                                }
                            }
                        });
                        return;
                    }
                    Err(std::sync::mpsc::TryRecvError::Disconnected) => return,
                    Err(std::sync::mpsc::TryRecvError::Empty) => {}
                }
                cx.background_executor()
                    .timer(Duration::from_millis(80))
                    .await;
            }
        })
        .detach();
    }

    #[cfg(target_os = "windows")]
    fn restart_and_apply_windows_update(&mut self, cx: &mut gpui::Context<Self>) {
        let (Some(updater), Some(asset)) = (
            self.windows_updater.as_ref(),
            self.windows_ready_update.as_ref(),
        ) else {
            return;
        };
        if updater.apply_after_exit(asset).is_err() {
            self.upsert_gpui_app_toast(
                GpuiAppToast {
                    id: "gpui-windows-updater-apply-failed".to_string(),
                    level: GpuiAppToastLevel::from_raw(Some("warning")),
                    title: "Could not start the updater".to_string(),
                    description: Some("Ghostex was not changed. Try again.".to_string()),
                    loading: false,
                    persistent: false,
                    duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                    epoch: 0,
                },
                cx,
            );
            return;
        }
        GPUI_APP_QUIT_IN_PROGRESS.store(true, Ordering::Release);
        cx.quit();
    }

    /// GPUI port of the macOS sidebar-mount first-run block
    /// (`openTipsAndTricksOnFirstLaunch` + `showOSIntegrationOnboardingOnFirstLaunch`,
    /// native-sidebar.tsx): current shipped macOS consumes the legacy tips and
    /// Highlighted Features markers WITHOUT opening those surfaces (the
    /// Discover→firstLaunchSetup auto chain was superseded 2026-06-18), opens
    /// the tutorial video modal once per first-launch-setup revision, and shows
    /// a once-forever OS Integration toast.
    /// CDXC:GPUIFirstRunOnboardingOnce 2026-08-18: writes one first-run marker
    /// off the foreground thread, re-reading the file first so a concurrent
    /// writer of a different field is not clobbered by this pass's snapshot.
    fn persist_gpui_first_run_onboarding_marker(
        &self,
        marker: GpuiFirstRunOnboardingMarker,
        cx: &mut gpui::Context<Self>,
    ) {
        cx.background_executor()
            .spawn(async move {
                let mut state = load_gpui_first_run_onboarding_state();
                match marker {
                    GpuiFirstRunOnboardingMarker::FirstLaunchSetupSeen => {
                        if state.first_launch_setup_seen_revision.as_deref()
                            == Some(GPUI_FIRST_LAUNCH_SETUP_SEEN_REVISION)
                        {
                            return;
                        }
                        state.first_launch_setup_seen_revision =
                            Some(GPUI_FIRST_LAUNCH_SETUP_SEEN_REVISION.to_string());
                    }
                    GpuiFirstRunOnboardingMarker::OsIntegrationOnboardingSeen => {
                        if state.os_integration_onboarding_seen {
                            return;
                        }
                        state.os_integration_onboarding_seen = true;
                    }
                }
                persist_gpui_first_run_onboarding_state(&state);
            })
            .detach();
    }

    fn start_gpui_first_run_onboarding(&mut self, cx: &mut gpui::Context<Self>) {
        if self.sidebar.is_none() {
            return;
        }
        #[cfg(target_os = "windows")]
        if self.windows_first_run_setup_state != GpuiWindowsFirstRunSetupState::Ready {
            return;
        }
        /*
        CDXC:GPUIFirstRunOnboardingOnce 2026-08-18:
        The first-launch-setup and OS-integration markers are persisted only
        after their surface is really shown (below), so the persisted flags no
        longer dedupe the callers that start onboarding. Latch the pass in
        memory instead, after every early-return guard, so the gxserver
        bootstrap, CEF init, and daemon-respawn entry points can each try to
        start onboarding while only the first one that gets past the guards
        runs it.
        */
        if self.first_run_onboarding_started {
            return;
        }
        self.first_run_onboarding_started = true;
        let active_project_id = self.gpui_app_modal_active_project_id();
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let (show_os_integration_toast, first_launch_setup_sidebar_state) = background
                .spawn(async move {
                    let mut state = load_gpui_first_run_onboarding_state();
                    let mut changed = false;
                    if !state.tips_and_tricks_seen {
                        state.tips_and_tricks_seen = true;
                        changed = true;
                    }
                    if state.highlighted_features_seen_revision.as_deref()
                        != Some(GPUI_HIGHLIGHTED_FEATURES_SEEN_REVISION)
                    {
                        state.highlighted_features_seen_revision =
                            Some(GPUI_HIGHLIGHTED_FEATURES_SEEN_REVISION.to_string());
                        changed = true;
                    }
                    /*
                    CDXC:GPUIFirstRunOnboardingOnce 2026-08-18:
                    The first-launch-setup and OS-integration markers describe
                    surfaces the user is supposed to see, so they are persisted
                    from the foreground block below once the toast is really
                    posted and the modal window really exists. Marking them here
                    burned first-run onboarding whenever the pass reached this
                    point and the UI never appeared (no sidebar-owned window,
                    a failed modal open, or an app exit in between). The two
                    legacy markers above show nothing at all, so they stay
                    consumed on this pass.

                    CDXC:GPUIFirstLaunchTutorialVideo 2026-08-19:
                    First run raises exactly ONE modal. The tutorial video used
                    to be its own window opened before (Windows) or instead of
                    (everywhere else) the setup modal; it is the setup modal's
                    first page now. Two markers still gate it, and they mean
                    different things: the revision marker says "this revision's
                    setup was presented", written when the window exists, so a
                    future revision bump shows it again; `complete` says "the
                    user closed it", written on close, so quitting mid-setup
                    brings it back on the next launch.
                    */
                    let show_os_integration_toast = !state.os_integration_onboarding_seen;
                    if changed {
                        persist_gpui_first_run_onboarding_state(&state);
                    }
                    let needs_first_launch_setup = state.first_launch_setup_seen_revision.as_deref()
                        != Some(GPUI_FIRST_LAUNCH_SETUP_SEEN_REVISION)
                        || !state.first_launch_setup_complete;
                    let first_launch_setup_sidebar_state = needs_first_launch_setup.then(|| {
                        gpui_app_modal_sidebar_state_message_for_active_project_id(
                            active_project_id.as_deref(),
                        )
                    });
                    (show_os_integration_toast, first_launch_setup_sidebar_state)
                })
                .await;
            if !show_os_integration_toast && first_launch_setup_sidebar_state.is_none() {
                return;
            }
            let _ = this.update(cx, |this, cx| {
                if show_os_integration_toast {
                    this.upsert_gpui_app_toast(
                        GpuiAppToast {
                            id: "gpui-os-integration-onboarding".to_string(),
                            level: GpuiAppToastLevel::from_raw(Some("info")),
                            title: "OS Integration available".to_string(),
                            description: Some(
                                "Open Settings > OS Integration to set Ghostex as your editor or terminal target."
                                    .to_string(),
                            ),
                            loading: false,
                            persistent: false,
                            duration_ms: GPUI_APP_TOAST_DEFAULT_DURATION_MS,
                            epoch: 0,
                        },
                        cx,
                    );
                    this.persist_gpui_first_run_onboarding_marker(
                        GpuiFirstRunOnboardingMarker::OsIntegrationOnboardingSeen,
                        cx,
                    );
                }
                if let Some(base_sidebar_state) = first_launch_setup_sidebar_state {
                    this.open_gpui_first_launch_setup_with_sidebar_state(base_sidebar_state, cx);
                    // Only a window that actually exists counts as "this
                    // revision's setup was presented".
                    if this.app_modal_window.is_some() {
                        this.persist_gpui_first_run_onboarding_marker(
                            GpuiFirstRunOnboardingMarker::FirstLaunchSetupSeen,
                            cx,
                        );
                    }
                }
            });
        })
        .detach();
    }

    #[cfg(target_os = "windows")]
    fn retry_windows_first_run_setup(&mut self, cx: &mut gpui::Context<Self>) {
        windows_terminal_backend::reset();
        self.windows_first_run_setup_state = GpuiWindowsFirstRunSetupState::Checking;
        self.start_gpui_local_gxserver_bootstrap(cx);
        cx.notify();
    }

    #[cfg(target_os = "windows")]
    fn save_windows_first_run_distribution(
        &mut self,
        distribution: String,
        cx: &mut gpui::Context<Self>,
    ) {
        let mut settings = shared_settings::shared_sidebar_settings_snapshot()
            .object()
            .clone();
        settings.insert(
            "windowsWslDistribution".to_string(),
            serde_json::Value::String(distribution),
        );
        match shared_settings::write_shared_sidebar_settings_object(settings) {
            Ok(_) => self.retry_windows_first_run_setup(cx),
            Err(_) => {
                self.windows_first_run_setup_state = GpuiWindowsFirstRunSetupState::Failed(
                    "Ghostex could not save the selected Linux environment. Check that its settings folder is writable, then try again."
                        .to_string(),
                );
                cx.notify();
            }
        }
    }

    #[cfg(target_os = "windows")]
    fn handle_windows_first_run_setup_action(
        &mut self,
        action: GpuiWindowsFirstRunSetupAction,
        cx: &mut gpui::Context<Self>,
    ) {
        match action {
            GpuiWindowsFirstRunSetupAction::Retry => self.retry_windows_first_run_setup(cx),
            GpuiWindowsFirstRunSetupAction::OpenWslGuide => {
                let _ =
                    gpui_open_external_http_url("https://learn.microsoft.com/windows/wsl/install");
            }
            GpuiWindowsFirstRunSetupAction::ChooseDistribution(distribution) => {
                self.save_windows_first_run_distribution(distribution, cx);
            }
            GpuiWindowsFirstRunSetupAction::ClearDistribution => {
                self.save_windows_first_run_distribution(String::new(), cx);
            }
        }
    }

    #[cfg(target_os = "windows")]
    fn render_windows_first_run_setup_button(
        &self,
        label: impl Into<gpui::SharedString>,
        primary: bool,
        action: GpuiWindowsFirstRunSetupAction,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        div()
            .flex()
            .h(px(36.0))
            .px(px(16.0))
            .items_center()
            .justify_center()
            .rounded(px(7.0))
            .border_1()
            .border_color(if primary {
                rgba(0x5a9bf0ff)
            } else {
                rgba(0xffffff2b)
            })
            .bg(if primary {
                rgba(0x377bd8ff)
            } else {
                rgba(0xffffff0d)
            })
            .hover(|this| {
                this.bg(if primary {
                    rgba(0x4389e7ff)
                } else {
                    rgba(0xffffff17)
                })
            })
            .cursor_pointer()
            .text_size(px(13.0))
            .font_weight(FontWeight::SEMIBOLD)
            .text_color(rgba(0xffffffff))
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(move |this, _event: &MouseUpEvent, window, cx| {
                    window.prevent_default();
                    cx.stop_propagation();
                    this.handle_windows_first_run_setup_action(action.clone(), cx);
                }),
            )
            .child(label.into())
            .into_any_element()
    }

    #[cfg(target_os = "windows")]
    fn render_windows_first_run_setup(&self, cx: &mut gpui::Context<Self>) -> AnyElement {
        let state = self.windows_first_run_setup_state.clone();
        let (title, description, detail, progress) = match &state {
            GpuiWindowsFirstRunSetupState::Checking => (
                "Checking Windows",
                "Ghostex uses WSL2 for fast terminals, agents, and persistent sessions.",
                "Looking for an initialized Linux environment…".to_string(),
                0.12,
            ),
            GpuiWindowsFirstRunSetupState::MissingWsl => (
                "Ghostex requires WSL2",
                "Install Windows Subsystem for Linux, then return here. Ghostex will never install it or request administrator access without you choosing to do so.",
                "WSL is not available on this PC.".to_string(),
                0.0,
            ),
            GpuiWindowsFirstRunSetupState::MissingDistribution => (
                "Finish setting up Linux",
                "Install a Linux distribution such as Ubuntu and open it once to create your Linux account. Then Ghostex can finish terminal setup.",
                "No initialized WSL2 Linux environment was found.".to_string(),
                0.0,
            ),
            GpuiWindowsFirstRunSetupState::ChooseDistribution(_) => (
                "Choose your Linux environment",
                "Ghostex found more than one initialized WSL2 distribution. Choose where terminals, agents, and sessions should run.",
                "You can change this later in Settings → Terminal.".to_string(),
                0.18,
            ),
            GpuiWindowsFirstRunSetupState::ConfiguredDistributionUnavailable(distribution) => (
                "Your Linux environment is unavailable",
                "The WSL distribution saved in Ghostex was removed, renamed, or has not finished initialization.",
                format!("Saved environment: {distribution}"),
                0.0,
            ),
            GpuiWindowsFirstRunSetupState::SettingUp(phase) => {
                let (detail, progress) = match phase {
                    windows_terminal_backend::WindowsWslSetupPhase::Checking => {
                        ("Checking the bundled terminal engine…", 0.28)
                    }
                    windows_terminal_backend::WindowsWslSetupPhase::Installing => {
                        ("Installing the Ghostex terminal engine in WSL2…", 0.52)
                    }
                    windows_terminal_backend::WindowsWslSetupPhase::Starting => {
                        ("Starting the Ghostex terminal engine…", 0.74)
                    }
                    windows_terminal_backend::WindowsWslSetupPhase::Connecting => {
                        ("Connecting Ghostex to WSL2…", 0.9)
                    }
                    windows_terminal_backend::WindowsWslSetupPhase::Ready => {
                        ("Ghostex terminals are ready.", 1.0)
                    }
                };
                (
                    "Setting up Ghostex terminals",
                    "This is a one-time setup for the selected Linux environment.",
                    detail.to_string(),
                    progress,
                )
            }
            GpuiWindowsFirstRunSetupState::Failed(message) => (
                "Terminal setup didn’t finish",
                "Ghostex could not finish its WSL2 terminal setup. Nothing was removed or replaced outside Ghostex’s managed files.",
                message.clone(),
                0.0,
            ),
            GpuiWindowsFirstRunSetupState::Ready => unreachable!(),
        };

        let mut content = v_flex()
            .w(px(620.0))
            .p(px(32.0))
            .gap(px(16.0))
            .rounded(px(12.0))
            .border_1()
            .border_color(rgba(0xffffff1f))
            .bg(rgba(0x17191dff))
            .child(
                div()
                    .text_size(px(24.0))
                    .font_weight(FontWeight::SEMIBOLD)
                    .text_color(rgba(0xfffffff2))
                    .child(title),
            )
            .child(
                div()
                    .text_size(px(14.0))
                    .line_height(px(21.0))
                    .text_color(rgba(0xffffffad))
                    .child(description),
            )
            .child(
                div()
                    .w_full()
                    .h(px(7.0))
                    .rounded(px(4.0))
                    .bg(rgba(0xffffff12))
                    .child(
                        div()
                            .h_full()
                            .w(relative(progress))
                            .rounded(px(4.0))
                            .bg(rgba(0x4f8fe8ff)),
                    ),
            )
            .child(
                div()
                    .text_size(px(12.0))
                    .line_height(px(18.0))
                    .text_color(
                        if matches!(state, GpuiWindowsFirstRunSetupState::Failed(_)) {
                            rgba(0xffa2aaff)
                        } else {
                            rgba(0xffffff85)
                        },
                    )
                    .child(detail),
            );

        if let GpuiWindowsFirstRunSetupState::ChooseDistribution(distributions) = &state {
            content = content.child(v_flex().gap(px(8.0)).children(
                distributions.iter().cloned().map(|distribution| {
                    self.render_windows_first_run_setup_button(
                        distribution.clone(),
                        true,
                        GpuiWindowsFirstRunSetupAction::ChooseDistribution(distribution),
                        cx,
                    )
                }),
            ));
        }

        let actions = match state {
            GpuiWindowsFirstRunSetupState::MissingWsl
            | GpuiWindowsFirstRunSetupState::MissingDistribution => Some(
                h_flex()
                    .gap(px(10.0))
                    .child(self.render_windows_first_run_setup_button(
                        "View WSL setup guide",
                        false,
                        GpuiWindowsFirstRunSetupAction::OpenWslGuide,
                        cx,
                    ))
                    .child(self.render_windows_first_run_setup_button(
                        "Check again",
                        true,
                        GpuiWindowsFirstRunSetupAction::Retry,
                        cx,
                    )),
            ),
            GpuiWindowsFirstRunSetupState::ConfiguredDistributionUnavailable(_) => Some(
                h_flex()
                    .gap(px(10.0))
                    .child(self.render_windows_first_run_setup_button(
                        "Choose automatically",
                        false,
                        GpuiWindowsFirstRunSetupAction::ClearDistribution,
                        cx,
                    ))
                    .child(self.render_windows_first_run_setup_button(
                        "Check again",
                        true,
                        GpuiWindowsFirstRunSetupAction::Retry,
                        cx,
                    )),
            ),
            GpuiWindowsFirstRunSetupState::Failed(_) => {
                Some(h_flex().child(self.render_windows_first_run_setup_button(
                    "Try again",
                    true,
                    GpuiWindowsFirstRunSetupAction::Retry,
                    cx,
                )))
            }
            _ => None,
        };
        if let Some(actions) = actions {
            content = content.child(actions);
        }

        div()
            .size_full()
            .flex()
            .items_center()
            .justify_center()
            .bg(rgba(0x0d0f12ff))
            .child(content)
            .into_any_element()
    }

    /// Startup daemon bootstrap, mirroring the macOS GxserverClient contract:
    /// reuse a healthy protocol-matched daemon silently, surface protocol and
    /// toolchain problems honestly, and otherwise launch the bundled daemon
    /// (app-independent; quitting Ghostex never stops it) while a persistent
    /// status toast tracks progress. Unlike macOS this does not gate window
    /// creation; the shell shows its normal disconnected state until healthy.
    fn start_gpui_local_gxserver_bootstrap(&mut self, cx: &mut gpui::Context<Self>) {
        #[cfg(target_os = "windows")]
        let windows_first_run_setup_active =
            self.windows_first_run_setup_state != GpuiWindowsFirstRunSetupState::Ready;
        #[cfg(target_os = "windows")]
        let windows_setup_progress_tx = if windows_first_run_setup_active {
            let (progress_tx, mut progress_rx) = mpsc::unbounded();
            cx.spawn(async move |this, cx| {
                while let Some(phase) = progress_rx.next().await {
                    let _ = this.update(cx, |this, cx| {
                        this.windows_first_run_setup_state =
                            GpuiWindowsFirstRunSetupState::SettingUp(phase);
                        cx.notify();
                    });
                }
            })
            .detach();
            Some(progress_tx)
        } else {
            None
        };
        cx.spawn(async move |this, cx| {
            #[cfg(target_os = "windows")]
            {
                /*
                CDXC:GPUIWindowsWslPersistence 2026-07-15:
                Windows resolves an initialized WSL2 distribution before it
                probes localhost. The optional exact-name setting overrides
                automatic discovery. A missing or invalid distro surfaces setup
                guidance instead of falling back to PowerShell; Ghostex never
                invokes `wsl --install`, requests elevation, or schedules a
                reboot.
                */
                if windows_first_run_setup_active {
                    let readiness = cx
                        .background_executor()
                        .spawn(async { windows_terminal_backend::wsl_readiness() })
                        .await;
                    if readiness != windows_terminal_backend::WindowsWslReadiness::Ready {
                        let state = match readiness {
                            windows_terminal_backend::WindowsWslReadiness::MissingWsl => {
                                GpuiWindowsFirstRunSetupState::MissingWsl
                            }
                            windows_terminal_backend::WindowsWslReadiness::MissingDistribution => {
                                GpuiWindowsFirstRunSetupState::MissingDistribution
                            }
                            windows_terminal_backend::WindowsWslReadiness::ChooseDistribution(
                                distributions,
                            ) => GpuiWindowsFirstRunSetupState::ChooseDistribution(distributions),
                            windows_terminal_backend::WindowsWslReadiness::ConfiguredDistributionUnavailable(
                                distribution,
                            ) => GpuiWindowsFirstRunSetupState::ConfiguredDistributionUnavailable(
                                distribution,
                            ),
                            windows_terminal_backend::WindowsWslReadiness::Ready => unreachable!(),
                        };
                        let _ = this.update(cx, |this, cx| {
                            this.windows_first_run_setup_state = state;
                            cx.notify();
                        });
                        return;
                    }
                    let _ = this.update(cx, |this, cx| {
                        this.windows_first_run_setup_state =
                            GpuiWindowsFirstRunSetupState::SettingUp(
                                windows_terminal_backend::WindowsWslSetupPhase::Checking,
                            );
                        cx.notify();
                    });
                }
                let progress_tx = windows_setup_progress_tx.clone();
                let preparation = cx
                    .background_executor()
                    .spawn(async move {
                        if let Some(progress_tx) = progress_tx {
                            windows_terminal_backend::prepare_gxserver_for_current_settings_with_progress(
                                &mut |phase| {
                                    let _ = progress_tx.unbounded_send(phase);
                                },
                            )
                        } else {
                            windows_terminal_backend::prepare_gxserver_for_current_settings()
                        }
                    })
                    .await;
                match preparation {
                    Ok(windows_terminal_backend::ResolvedWindowsTerminalBackend::PowerShell) => {
                        let _ = this.update(cx, |this, cx| {
                            this.replay_sidebar_gxserver_bootstrap(cx);
                        });
                        return;
                    }
                    Ok(windows_terminal_backend::ResolvedWindowsTerminalBackend::Wsl { .. }) => {}
                    Err(message) => {
                        if windows_first_run_setup_active {
                            let _ = this.update(cx, |this, cx| {
                                this.windows_first_run_setup_state =
                                    GpuiWindowsFirstRunSetupState::Failed(message.clone());
                                cx.notify();
                            });
                            return;
                        }
                        let _ = this.update(cx, |this, cx| {
                            this.show_gpui_gxserver_bootstrap_toast(
                                "warning",
                                "WSL runtime setup needed",
                                &message,
                                true,
                                cx,
                            );
                            this.replay_sidebar_gxserver_bootstrap(cx);
                        });
                        return;
                    }
                }
            }
            let health = cx
                .background_executor()
                .spawn(async { gpui_probe_local_gxserver_health() })
                .await;
            match health {
                GpuiLocalGxserverHealthState::Healthy {
                    tools_available: true,
                } => {
                    let _ = this.update(cx, |this, cx| {
                        #[cfg(target_os = "windows")]
                        if windows_first_run_setup_active {
                            this.windows_first_run_setup_state =
                                GpuiWindowsFirstRunSetupState::Ready;
                            let mut state = load_gpui_first_run_onboarding_state();
                            state.windows_terminal_setup_complete = true;
                            persist_gpui_first_run_onboarding_state(&state);
                        }
                        this.replay_sidebar_gxserver_bootstrap(cx);
                        this.start_gpui_portless_setup_prompt_check(cx);
                        this.start_gpui_first_run_onboarding(cx);
                        cx.notify();
                    });
                    return;
                }
                GpuiLocalGxserverHealthState::Healthy {
                    tools_available: false,
                } => {
                    #[cfg(target_os = "windows")]
                    windows_terminal_backend::mark_package_update_required();
                    let _ = this.update(cx, |this, cx| {
                        this.show_gpui_gxserver_bootstrap_toast(
                            "info",
                            "Restarting gxserver",
                            "The running gxserver does not match the tools bundled with this Ghostex build.",
                            true,
                            cx,
                        );
                        this.stop_gpui_local_gxserver_from_titlebar(true, cx);
                    });
                    return;
                }
                GpuiLocalGxserverHealthState::BuildMismatch => {
                    #[cfg(target_os = "windows")]
                    windows_terminal_backend::mark_package_update_required();
                    let _ = this.update(cx, |this, cx| {
                        this.show_gpui_gxserver_bootstrap_toast(
                            "info",
                            "Updating gxserver",
                            "The running gxserver belongs to a different Ghostex build. Ghostex is restarting it before loading migrated storage.",
                            true,
                            cx,
                        );
                        this.stop_gpui_local_gxserver_from_titlebar(true, cx);
                    });
                    return;
                }
                GpuiLocalGxserverHealthState::ProtocolMismatch { reported } => {
                    #[cfg(target_os = "windows")]
                    {
                        windows_terminal_backend::mark_package_update_required();
                        let _ = this.update(cx, |this, cx| {
                            this.show_gpui_gxserver_bootstrap_toast(
                                "info",
                                "Updating WSL gxserver",
                                "The running WSL gxserver belongs to an older Ghostex build. Ghostex is activating the bundled runtime and restarting it.",
                                true,
                                cx,
                            );
                            this.stop_gpui_local_gxserver_from_titlebar(true, cx);
                        });
                        return;
                    }
                    #[cfg(not(target_os = "windows"))]
                    let message = gpui_gxserver_protocol_mismatch_message(reported);
                    #[cfg(not(target_os = "windows"))]
                    let _ = this.update(cx, |this, cx| {
                        this.show_gpui_gxserver_bootstrap_toast(
                            "error",
                            "gxserver protocol mismatch",
                            &message,
                            true,
                            cx,
                        );
                    });
                    #[cfg(not(target_os = "windows"))]
                    return;
                }
                GpuiLocalGxserverHealthState::Unreachable => {}
            }

            #[cfg(target_os = "windows")]
            if matches!(
                windows_terminal_backend::resolve_current(),
                Ok(windows_terminal_backend::ResolvedWindowsTerminalBackend::Wsl { .. })
            ) {
                if windows_first_run_setup_active {
                    let _ = this.update(cx, |this, cx| {
                        this.windows_first_run_setup_state = GpuiWindowsFirstRunSetupState::Failed(
                            "Ghostex started its terminal engine, but Windows could not connect to it. Check that WSL localhost forwarding is enabled, then try again."
                                .to_string(),
                        );
                        cx.notify();
                    });
                    return;
                }
                let _ = this.update(cx, |this, cx| {
                    this.show_gpui_gxserver_bootstrap_toast(
                        "error",
                        "WSL gxserver unavailable",
                        "gxserver started inside WSL2, but Windows could not reach it through localhost:58744. Check that WSL localhost forwarding is enabled, then retry.",
                        true,
                        cx,
                    );
                });
                return;
            }

            let Some(binary) = gpui_resolve_local_gxserver_binary() else {
                let _ = this.update(cx, |this, cx| {
                    this.show_gpui_gxserver_bootstrap_toast(
                        "error",
                        "gxserver unavailable",
                        "Bundled gxserver binary is missing. Run `bun run build` for development, or reinstall Ghostex so Web/gxserver is present.",
                        true,
                        cx,
                    );
                });
                return;
            };
            let _ = this.update(cx, |this, cx| {
                this.show_gpui_gxserver_bootstrap_toast(
                    "info",
                    "Loading sessions",
                    "Starting gxserver and loading projects.",
                    true,
                    cx,
                );
            });
            let spawn_result = cx
                .background_executor()
                .spawn(async move { gpui_spawn_local_gxserver_daemon(&binary) })
                .await;
            if let Err(message) = spawn_result {
                let _ = this.update(cx, |this, cx| {
                    this.show_gpui_gxserver_bootstrap_toast(
                        "error",
                        "gxserver failed",
                        &message,
                        true,
                        cx,
                    );
                });
                return;
            }
            for _ in 0..40 {
                cx.background_executor()
                    .timer(Duration::from_millis(500))
                    .await;
                let health = cx
                    .background_executor()
                    .spawn(async { gpui_probe_local_gxserver_health() })
                    .await;
                match health {
                    GpuiLocalGxserverHealthState::Healthy { tools_available } => {
                        let _ = this.update(cx, |this, cx| {
                            if !tools_available {
                                this.show_gpui_gxserver_bootstrap_toast(
                                    "error",
                                    "gxserver toolchain unavailable",
                                    "The newly started gxserver did not expose the tools bundled with this Ghostex build.",
                                    true,
                                    cx,
                                );
                            }
                            this.replay_sidebar_gxserver_bootstrap(cx);
                            this.start_gpui_portless_setup_prompt_check(cx);
                            /*
                            CDXC:GPUIFirstRunOnboardingOnce 2026-08-18:
                            A launch that had to respawn the daemon reaches
                            "gxserver healthy" here instead of through the
                            bootstrap branch, so first-run onboarding has to be
                            started from this recovery path too. The in-memory
                            latch plus the persisted markers keep it a no-op
                            when onboarding already ran.
                            */
                            this.start_gpui_first_run_onboarding(cx);
                        });
                        return;
                    }
                    GpuiLocalGxserverHealthState::ProtocolMismatch { reported } => {
                        let message = gpui_gxserver_protocol_mismatch_message(reported);
                        let _ = this.update(cx, |this, cx| {
                            this.show_gpui_gxserver_bootstrap_toast(
                                "error",
                                "gxserver protocol mismatch",
                                &message,
                                true,
                                cx,
                            );
                        });
                        return;
                    }
                    GpuiLocalGxserverHealthState::BuildMismatch => {}
                    GpuiLocalGxserverHealthState::Unreachable => {}
                }
            }
            let launch_output = cx
                .background_executor()
                .spawn(async { gpui_recent_gxserver_launch_output() })
                .await;
            let description = launch_output
                .unwrap_or_else(|| "The daemon did not become healthy in time.".to_string());
            let _ = this.update(cx, |this, cx| {
                this.show_gpui_gxserver_bootstrap_toast(
                    "error",
                    "gxserver failed to start",
                    &description,
                    true,
                    cx,
                );
            });
        })
        .detach();
    }

    fn start_gpui_workspace_open_target_availability_scan(&mut self, cx: &mut gpui::Context<Self>) {
        // macOS detects installed Open In targets once when the native sidebar
        // starts (refreshWorkspaceOpenTargetAvailabilityAtStartup) and persists
        // the result into workspaceOpenTargetAvailability; the manual titlebar
        // refresh command exists in the host protocol but has no live sender in
        // shipped macOS, so the startup scan is the whole parity surface.
        cx.spawn(async move |this, cx| {
            let detected = cx
                .background_executor()
                .spawn(async { gpui_detect_workspace_open_target_availability() })
                .await;
            let Some(detected) = detected else {
                return;
            };
            let _ = this.update(cx, |this, cx| {
                this.apply_gpui_workspace_open_target_availability_scan(detected, cx);
            });
        })
        .detach();
    }

    fn apply_gpui_workspace_open_target_availability_scan(
        &mut self,
        detected: GpuiDetectedOpenTargetAvailability,
        cx: &mut gpui::Context<Self>,
    ) {
        let mut settings_object = shared_settings::shared_sidebar_settings_snapshot()
            .object()
            .clone();
        let stored =
            gpui_open_target_availability(settings_object.get("workspaceOpenTargetAvailability"));
        if gpui_detected_open_target_availability_matches_stored(&detected, &stored) {
            return;
        }
        settings_object.insert(
            "workspaceOpenTargetAvailability".to_string(),
            gpui_workspace_open_target_availability_settings_value(&detected),
        );
        let Ok(write_result) =
            shared_settings::write_shared_sidebar_settings_object(settings_object)
        else {
            return;
        };
        self.refresh_gpui_shared_settings_consumers_after_save(&write_result.snapshot, cx);
    }

    fn schedule_gpui_app_toast_auto_dismiss(
        &mut self,
        toast_id: String,
        epoch: u64,
        duration_ms: u64,
        cx: &mut gpui::Context<Self>,
    ) {
        cx.spawn(async move |this, cx| {
            cx.background_executor()
                .timer(std::time::Duration::from_millis(duration_ms))
                .await;
            let _ = this.update(cx, |this, cx| {
                // The epoch guard keeps an update-in-place (same toastId) from
                // being dismissed by the superseded toast's timer.
                if this
                    .app_toasts
                    .iter()
                    .any(|toast| toast.id == toast_id && toast.epoch == epoch)
                {
                    this.remove_gpui_app_toast(&toast_id, cx);
                }
            });
        })
        .detach();
    }

    fn remove_gpui_app_toast(&mut self, toast_id: &str, cx: &mut gpui::Context<Self>) {
        let previous_len = self.app_toasts.len();
        self.app_toasts.retain(|toast| toast.id != toast_id);
        if self.app_toasts.len() != previous_len {
            self.sync_gpui_app_toast_window(cx);
        }
    }

    fn sync_gpui_app_toast_window(&mut self, cx: &mut gpui::Context<Self>) {
        if self.app_toasts.is_empty() {
            self.app_toast_window_height = px(0.0);
            if let Some(handle) = self.app_toast_window.take() {
                let _ = handle.update(cx, |_, toast_window, _| {
                    toast_window.remove_window();
                });
            }
            return;
        }
        let Some(anchor) = self.app_toast_anchor else {
            return;
        };
        let stack_height = px(gpui_app_toast_stack_height(&self.app_toasts));
        let toasts = self.app_toasts.clone();
        if let Some(handle) = self.app_toast_window.clone() {
            if self.app_toast_window_height == stack_height {
                let update_result = handle.update(cx, |toast_window_entity, toast_window, cx| {
                    toast_window_entity.set_toasts(toasts.clone(), cx);
                    toast_window.refresh();
                });
                if update_result.is_ok() {
                    return;
                }
                self.app_toast_window = None;
            } else {
                // The popup is exact-sized and bottom-anchored; gpui windows can
                // resize but not move, so a height change recreates the window at
                // the new bottom-anchored bounds.
                let _ = handle.update(cx, |_, toast_window, _| {
                    toast_window.remove_window();
                });
                self.app_toast_window = None;
            }
        }
        let bounds = Bounds {
            origin: point(
                anchor.x - px(GPUI_APP_TOAST_WIDTH / 2.0),
                anchor.y - stack_height - px(GPUI_APP_TOAST_BOTTOM_MARGIN),
            ),
            size: size(px(GPUI_APP_TOAST_WINDOW_WIDTH), stack_height),
        };
        let app = cx.entity().downgrade();
        let main_window_native_view = self.parent_ns_view;
        let options = WindowOptions {
            window_bounds: Some(WindowBounds::Windowed(bounds)),
            focus: false,
            show: true,
            kind: WindowKind::PopUp,
            is_movable: false,
            is_resizable: false,
            is_minimizable: false,
            titlebar: None,
            window_background: WindowBackgroundAppearance::Transparent,
            ..Default::default()
        };
        self.app_toast_window = cx
            .open_window(options, move |toast_window, cx| {
                remove_gpui_app_toast_popup_window_chrome(toast_window, main_window_native_view);
                cx.new(|_| GpuiAppToastWindow {
                    app,
                    toasts,
                    hovered_toast_id: None,
                })
            })
            .ok();
        self.app_toast_window_height = stack_height;
    }

    fn dispatch_gpui_sidebar_remote_event(
        &mut self,
        message: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUIRemoteMachines 2026-06-24-16:48:
        GPUI remote-machine status and presentation events are Rust-owned sidebar-only messages. Send only sanitized state enums, machine ids, and gxserver presentation snapshots/deltas into SidebarApp; remote auth tokens, SSH host/user/key data, paths from Settings commands, URLs, daemon response bodies, stdout/stderr, and command text must stay out of CEF globals and logs.

        CDXC:GPUIRemoteSessions 2026-06-24-17:19:
        Response-capable remote session requests may dispatch only request ids, success state, generic errors, and explicit safe metadata results such as previous-session search rows. Mutating remote session responses must be sanitized before this event boundary so renderer code never receives launch commands, tokens, SSH details, raw daemon bodies, or provider internals.
        */
        let Some(sidebar) = self.sidebar.clone() else {
            return;
        };
        let script = format!(
            "window.dispatchEvent(new CustomEvent('{GPUI_SIDEBAR_REMOTE_EVENT_NAME}', {{ detail: {} }})); undefined;",
            message
        );
        sidebar.update(cx, |surface, _| {
            surface.execute_app_owned_script(&script);
        });
    }

    fn dispatch_gpui_remote_machine_status(
        &mut self,
        remote_machine_id: &str,
        state: &str,
        cx: &mut gpui::Context<Self>,
    ) {
        self.dispatch_gpui_remote_machine_status_with_message(remote_machine_id, state, None, cx);
    }

    /*
    CDXC:GPUIRemoteConnectFeedback 2026-07-12:
    Failure states may carry the already-sanitized connect failure summary
    (the same text shown in the toast) so the sidebar can explain why the
    connect failed inline. Only Rust-authored sanitized messages may pass
    through here — never raw SSH stderr, tokens, hosts, or daemon bodies.
    */
    fn dispatch_gpui_remote_machine_status_with_message(
        &mut self,
        remote_machine_id: &str,
        state: &str,
        message: Option<&str>,
        cx: &mut gpui::Context<Self>,
    ) {
        debug_assert!(gpui_remote_gxserver_status_state_is_known(state));
        if gpui_remote_gxserver_status_state_is_broken(state) {
            self.stop_gpui_remote_gxserver_connection(remote_machine_id);
        }
        /*
        CDXC:GPUIRemoteConnectOverlay 2026-08-07:
        Every connect transition funnels through here, so this is where the
        render tree learns a machine's reachability. The terminal body draws a
        status overlay for remote sessions whose machine is not connected, and
        the workspace re-arms restored remote tabs on the connected edge. Only
        the bounded wire state slug is retained — never hosts, tokens, or the
        sanitized message text.
        */
        self.remote_machine_connect_states
            .insert(remote_machine_id.to_string(), state.to_string());
        if state == GpuiRemoteGxserverConnectState::Connected.wire_status_state() {
            self.attach_surfaced_remote_workspace_terminals(remote_machine_id, cx);
        }
        let mut payload = serde_json::json!({
            "machineId": remote_machine_id,
            "state": state,
            "type": "remoteMachineStatus",
        });
        if let Some(message) = message.map(str::trim).filter(|message| !message.is_empty()) {
            payload["message"] = serde_json::Value::String(message.to_string());
        }
        self.dispatch_gpui_sidebar_remote_event(payload, cx);
    }

    fn dispatch_gpui_settings_action_status(
        &mut self,
        action: &str,
        available: bool,
        message: &str,
        cx: &mut gpui::Context<Self>,
    ) {
        self.dispatch_open_gpui_app_modal_sidebar_state_payload(
            gpui_settings_action_status_message(action, available, message),
            cx,
        );
    }

    fn run_gpui_app_modal_sidebar_status_task<F>(&mut self, task: F, cx: &mut gpui::Context<Self>)
    where
        F: FnOnce() -> serde_json::Value + Send + 'static,
    {
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let payload = background.spawn(async move { task() }).await;
            let _ = this.update(cx, |this, cx| {
                this.dispatch_open_gpui_app_modal_sidebar_state_payload(payload, cx);
            });
        })
        .detach();
    }

    fn run_gpui_app_modal_and_titlebar_status_task<F>(
        &mut self,
        task: F,
        cx: &mut gpui::Context<Self>,
    ) where
        F: FnOnce() -> serde_json::Value + Send + 'static,
    {
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let payload = background.spawn(async move { task() }).await;
            let _ = this.update(cx, |this, cx| {
                this.dispatch_open_gpui_app_modal_sidebar_state_payload(payload.clone(), cx);
                this.dispatch_gpui_titlebar_tips_sidebar_state_payload(&payload, cx);
            });
        })
        .detach();
    }

    fn run_gpui_progressive_agent_hook_status_task(
        &mut self,
        requested_agent_ids: Option<Vec<String>>,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        macOS parity: hook-status probes run per provider in priority order
        (codex, claude, opencode, pi first) and every partial result posts
        immediately, so Settings/Tips hook warnings populate progressively
        instead of waiting behind the slowest provider probe. Install and
        uninstall stay single batched calls like macOS. One status request
        runs at a time; overlapping requests drop like the macOS in-flight
        guard, and a failed provider probe posts the error payload and stops
        the walk like the macOS catch path.
        */
        if self.agent_hook_status_request_in_flight {
            return;
        }
        self.agent_hook_status_request_in_flight = true;
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let mut merged: Option<serde_json::Value> = None;
            for agent_id in gpui_ordered_agent_hook_status_agent_ids(requested_agent_ids) {
                let payload = background
                    .spawn(async move {
                        gpui_agent_hook_status_message(
                            "/api/readAgentHookStatus",
                            Some(HashSet::from([agent_id])),
                            "Unable to inspect agent hook status.",
                        )
                    })
                    .await;
                let is_error = payload
                    .get("errorMessage")
                    .and_then(serde_json::Value::as_str)
                    .is_some();
                let next = if is_error {
                    payload
                } else {
                    match merged.as_ref() {
                        Some(previous) => gpui_merge_agent_hook_status_messages(previous, &payload),
                        None => payload,
                    }
                };
                let dispatched = this.update(cx, |this, cx| {
                    this.dispatch_open_gpui_app_modal_sidebar_state_payload(next.clone(), cx);
                    this.dispatch_gpui_titlebar_tips_sidebar_state_payload(&next, cx);
                });
                if dispatched.is_err() {
                    return;
                }
                if is_error {
                    break;
                }
                merged = Some(next);
            }
            let _ = this.update(cx, |this, _| {
                this.agent_hook_status_request_in_flight = false;
            });
        })
        .detach();
    }

    fn run_gpui_ghostex_cli_settings_action(
        &mut self,
        action: GpuiGhostexCliSettingsAction,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsCliInstall 2026-06-24-12:56:
        Settings integration actions in GPUI must mutate only bounded local install targets and then refresh the shared `ghostexCliStatus` contract. CLI repair uses packaged app resources only; skill install/uninstall actions use fixed Ghostex-owned command or directory targets and never accept React-provided shell text, paths, stdout, stderr, URLs, tokens, or environment data.
        */
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            // The status message probe runs `cua-driver check_permissions`
            // (5s timeout plus an unbounded pipe-reader join) — it must run
            // in the same background task as the action, never inside the
            // main-thread completion update (CDXC:GPUISettingsCliInstall
            // 2026-07-11: previously stalled the UI up to 5s per action).
            let (result, status_message) = background
                .spawn(async move {
                    let result = gpui_run_ghostex_cli_settings_action(action);
                    let status_message =
                        gpui_ghostex_cli_status_message(Some(result.message.as_str()));
                    (result, status_message)
                })
                .await;
            let _ = this.update(cx, |this, cx| {
                this.dispatch_open_gpui_app_modal_sidebar_state_payload(status_message, cx);
                this.dispatch_gpui_settings_action_status(
                    result.action_id,
                    result.available,
                    result.message.as_str(),
                    cx,
                );
                this.dispatch_gpui_app_modal_toast(
                    result.toast_level,
                    result.toast_title,
                    result.message.as_str(),
                    cx,
                );
            });
        })
        .detach();
    }

    fn handle_gpui_cua_driver_install_or_update(
        &mut self,
        window: &Window,
        cx: &mut gpui::Context<Self>,
    ) {
        #[cfg(target_os = "macos")]
        {
            self.start_gpui_cua_driver_install_or_update_terminal(window, cx);
        }
        #[cfg(not(target_os = "macos"))]
        {
            let result = gpui_open_url(GPUI_CUA_DRIVER_RELEASES_URL);
            let (toast_level, toast_title, detail) = if result.is_ok() {
                (
                    "info",
                    "Cua Driver downloads opened",
                    "Cua Driver installation and updates are available from the Cua GitHub releases page on this platform.",
                )
            } else {
                (
                    "warning",
                    "Unable to open Cua downloads",
                    "Ghostex could not open the Cua GitHub releases page.",
                )
            };
            self.run_gpui_app_modal_and_titlebar_status_task(
                move || gpui_ghostex_cli_status_message(Some(detail)),
                cx,
            );
            self.dispatch_gpui_app_modal_toast(toast_level, toast_title, detail, cx);
        }
    }

    #[cfg(target_os = "macos")]
    fn start_gpui_cua_driver_install_or_update_terminal(
        &mut self,
        window: &Window,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUIDesktopControlSettings 2026-08-09:
        Installing or updating Cua Driver can take minutes and prints useful
        progress. Run it in a real command-pane terminal tab so the user can
        watch the official installer/updater instead of staring at a silent
        Settings spinner. The tab opens without stealing typing focus like
        every other command Action.
        */
        let GpuiCuaDriverCommandAction {
            command,
            command_id,
            running_message,
            tab_title,
            toast_title,
        } = gpui_cua_driver_command_action();
        self.open_gpui_command_action_terminal(
            command_id.to_string(),
            tab_title.to_string(),
            command,
            false,
            false,
            window,
            cx,
        );
        self.run_gpui_app_modal_and_titlebar_status_task(
            move || gpui_ghostex_cli_status_message(Some(running_message)),
            cx,
        );
        self.dispatch_gpui_app_modal_toast("info", toast_title, running_message, cx);
    }

    fn install_gpui_gte_from_homebrew(&mut self, cx: &mut gpui::Context<Self>) {
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let result = background
                .spawn(async move { gpui_install_gte_from_homebrew() })
                .await;
            let _ = this.update(cx, |this, cx| {
                this.dispatch_gpui_settings_action_status(
                    GPUI_GTE_INSTALL_ACTION_ID,
                    result.available,
                    result.message,
                    cx,
                );
                this.dispatch_gpui_app_modal_toast(
                    result.toast_level,
                    result.toast_title,
                    result.message,
                    cx,
                );
            });
        })
        .detach();
    }

    fn refresh_gpui_daemon_sessions_state_in_background(
        &mut self,
        error_message: Option<String>,
        cx: &mut gpui::Context<Self>,
    ) {
        let active_project_id = self.gpui_daemon_sessions_active_project_id();
        let focused_session_id = self.gpui_daemon_sessions_focused_session_id();
        self.run_gpui_app_modal_sidebar_status_task(
            move || {
                gpui_daemon_sessions_state_message(
                    error_message,
                    active_project_id.as_deref(),
                    focused_session_id.as_deref(),
                )
            },
            cx,
        );
    }

    fn refresh_gpui_quick_access_sessions_state_in_background(
        &mut self,
        mut sidebar_state_message: serde_json::Value,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUIQuickAccessSessions 2026-08-08:
        The reusable app-modal hydrate is settings-oriented and intentionally
        carries no session groups. Read the authoritative gxserver presentation
        off the UI thread when the Sessions page opens, project it into the
        existing SidebarSessionGroup contract, and apply it as a normal
        sessionState message. Closed-session paging remains independent, so the
        modal can display whichever real dataset arrives first without a fake
        loading row or a second list area.
        */
        let active_project_id = self.gpui_daemon_sessions_active_project_id();
        self.run_gpui_app_modal_sidebar_status_task(
            move || {
                let groups = gpui_read_gxserver_presentation_snapshot()
                    .map(|snapshot| {
                        gpui_quick_access_sidebar_groups_from_presentation_snapshot(
                            &snapshot,
                            active_project_id.as_deref(),
                        )
                    })
                    .unwrap_or_default();
                sidebar_state_message["groups"] = serde_json::Value::Array(groups);
                sidebar_state_message["type"] =
                    serde_json::Value::String("sessionState".to_string());
                sidebar_state_message
            },
            cx,
        );
    }

    fn gpui_daemon_sessions_active_project_id(&self) -> Option<String> {
        self.latest_sidebar_project_snapshot
            .as_ref()
            .and_then(|snapshot| snapshot.active_project_id.as_ref())
            .map(|project_id| project_id.0.clone())
    }

    fn gpui_daemon_sessions_focused_session_id(&self) -> Option<String> {
        self.sidebar_gxserver_presentation_focus_state
            .focused_session_id
            .clone()
    }

    fn gpui_app_modal_active_project_id(&self) -> Option<String> {
        gpui_active_project_id_from_snapshot(self.latest_sidebar_project_snapshot.as_ref())
            .map(str::to_string)
    }

    fn gpui_titlebar_browser_url_allowed(&self, url: &str) -> bool {
        if self.titlebar_tips_panel_open && gpui_titlebar_tips_browser_url_allowed(url) {
            return true;
        }
        self.titlebar_resources_panel_open && gpui_titlebar_resources_browser_url_allowed(url)
    }

    fn update_gpui_ghostty_visible_settings(
        &mut self,
        mutate_settings: fn(&mut serde_json::Map<String, serde_json::Value>),
        write_ghostty_config: fn() -> Result<
            shared_settings::SharedGhosttyConfigFileWriteStatus,
            shared_settings::SharedGhosttyConfigFileError,
        >,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUISettingsGhosttyConfig 2026-06-24-12:24:
        Apply/reset Ghostty actions must mirror macOS by updating the visible shared Settings keys and merging the bounded managed Ghostty config file. They may not accept a React-provided config path, create a fallback file after failure, or claim live embedded reload because GPUI has no safe Ghostty app config reload/update FFI yet.
        */
        let mut settings_object = shared_settings::shared_sidebar_settings_snapshot()
            .object()
            .clone();
        mutate_settings(&mut settings_object);
        let Ok(write_result) =
            shared_settings::write_shared_sidebar_settings_object(settings_object)
        else {
            self.dispatch_gpui_settings_action_status(
                "ghosttySettings",
                false,
                "GPUI could not update shared Ghostty Settings.",
                cx,
            );
            return;
        };
        self.refresh_gpui_shared_settings_consumers_after_save(&write_result.snapshot, cx);
        match write_ghostty_config() {
            Ok(_) => {
                self.dispatch_gpui_settings_action_status(
                    "ghosttySettings",
                    true,
                    "Shared Ghostty Settings and the managed Ghostty config file were saved. Existing GPUI terminals are not live reloaded; changes affect external Ghostty reloads and future/recreated GPUI surfaces.",
                    cx,
                );
            }
            Err(_) => {
                let message = "Shared Ghostty Settings were saved, but GPUI could not write the managed Ghostty config file. Existing embedded terminals were not live reloaded.";
                self.dispatch_gpui_settings_action_status("ghosttySettings", false, message, cx);
                self.dispatch_gpui_app_modal_toast(
                    "warning",
                    "Could not update Ghostty config",
                    message,
                    cx,
                );
            }
        }
    }

    fn open_gpui_ghostex_folder(&mut self, cx: &mut gpui::Context<Self>) {
        let folder_path = shared_settings::ghostex_storage_paths().data_dir.clone();
        let open_result = fs::create_dir_all(&folder_path)
            .map_err(|_| "GPUI could not prepare the Ghostex support folder.".to_string())
            .and_then(|_| gpui_open_path(&folder_path));
        if let Err(message) = open_result {
            self.dispatch_open_gpui_app_modal_sidebar_state_payload(
                gpui_ghostex_folder_stats_error_message(&message),
                cx,
            );
            self.dispatch_gpui_app_modal_toast(
                "warning",
                "Could not open Ghostex folder",
                &message,
                cx,
            );
        }
    }

    fn open_gpui_ghostty_config_file(&mut self, cx: &mut gpui::Context<Self>) {
        /*
        CDXC:GPUISettingsGhosttyConfig 2026-06-24-12:24:
        The Settings config-file button should open the bounded selected Ghostty config path. Prepare only that path, create an empty file if it is missing, avoid surfacing raw paths in status/toast copy, and report failure honestly instead of opening a parent folder or a second fallback config file.
        */
        let path = match shared_settings::prepare_ghostty_config_file_for_open() {
            Ok(path) => path,
            Err(_) => {
                let message = "GPUI could not prepare the selected Ghostty config file.";
                self.dispatch_gpui_settings_action_status(
                    "openGhosttyConfigFile",
                    false,
                    message,
                    cx,
                );
                self.dispatch_gpui_app_modal_toast(
                    "warning",
                    "Could not open Ghostty config",
                    message,
                    cx,
                );
                return;
            }
        };
        if let Err(message) = gpui_open_path(&path) {
            self.dispatch_gpui_settings_action_status("openGhosttyConfigFile", false, &message, cx);
            self.dispatch_gpui_app_modal_toast(
                "warning",
                "Could not open Ghostty config",
                &message,
                cx,
            );
            return;
        }
        self.dispatch_gpui_settings_action_status(
            "openGhosttyConfigFile",
            true,
            "Ghostty config file opened with the OS file handler.",
            cx,
        );
    }

    fn open_gpui_agents_hub_path_in_finder(
        &mut self,
        command: &serde_json::Map<String, serde_json::Value>,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(path) = command
            .get("path")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
        else {
            return;
        };
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let result = background
                .spawn(async move { gpui_agents_hub_open_path_in_finder(path) })
                .await;
            let _ = this.update(cx, |this, cx| {
                if let Err(message) = result {
                    this.dispatch_gpui_app_modal_toast(
                        "warning",
                        "Could not open Agents Hub path",
                        &message,
                        cx,
                    );
                }
            });
        })
        .detach();
    }

    fn open_gpui_agents_hub_file_in_built_in_editor(
        &mut self,
        command: &serde_json::Map<String, serde_json::Value>,
        _window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(file_path) = command
            .get("filePath")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
        else {
            return;
        };
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let result = background
                .spawn(async move { gpui_agents_hub_source_open_target(file_path) })
                .await;
            let _ = this.update_in(cx, |this, window, cx| match result {
                Ok(pending) => {
                    let project_path = pending.project_path.clone();
                    this.pending_source_file_open = Some(pending);
                    this.close_gpui_app_modal_window_and_restore_command_focus(cx);
                    this.dispatch_gpui_os_integration_command_message(
                        serde_json::json!({
                            "action": "openProjectPaths",
                            "projects": [{
                                "path": project_path.to_string_lossy(),
                            }],
                        }),
                        cx,
                    );
                    this.switch_workarea_from_hotkey(TitlebarMode::Source, window, cx);
                    this.focus_project_editor_surface(TitlebarMode::Source, window, cx);
                }
                Err(message) => {
                    this.dispatch_gpui_app_modal_toast(
                        "warning",
                        "Could not open Agents Hub file",
                        &message,
                        cx,
                    );
                }
            });
        })
        .detach();
    }

    fn handle_gpui_save_agents_hub_file_command(
        &mut self,
        command: &serde_json::Map<String, serde_json::Value>,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUIAgentsHubBridge 2026-06-24-12:26:
        Agents Hub saves are real file writes, but the writer boundary must validate the selected file against the current catalog-derived allowlist before touching disk. Do not trust React-provided paths, log file content, create fallback draft stores, or claim success without refreshing the shared modal state.
        */
        let Some(file_path) = command
            .get("filePath")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
        else {
            return;
        };
        let Some(content) = command
            .get("content")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
        else {
            return;
        };
        let background = cx.background_executor().clone();
        cx.spawn(async move |this, cx| {
            let result = background
                .spawn(async move { gpui_save_agents_hub_file(file_path, content) })
                .await;
            let _ = this.update(cx, |this, cx| match result {
                Ok(catalog_message) => {
                    this.dispatch_open_gpui_app_modal_sidebar_state_payload(catalog_message, cx);
                    this.dispatch_gpui_app_modal_toast(
                        "success",
                        "File saved",
                        "Agents Hub refreshed the saved file metadata.",
                        cx,
                    );
                }
                Err(message) => {
                    this.dispatch_gpui_app_modal_toast(
                        "warning",
                        "Could not save Agents Hub file",
                        &message,
                        cx,
                    );
                }
            });
        })
        .detach();
    }

