fn browser_agentation_feedback_injection_script() -> String {
    /*
    CDXC:GPUIBrowserFeedback 2026-06-23-11:04:
    Browser feedback toolbar parity now injects the Settings-selected Agentation tool into the active GPUI CEF main frame instead of showing a placeholder notification. Keep the script bounded to pinned module URLs, auto-start feedback mode, and avoid persistent logs, console page metadata, raw URLs, titles, page content, cookies, tokens, paths, command text, terminal content, or JS error payloads.
    */
    const TEMPLATE: &str = r##"
(function() {
  const packageModuleUrl = __AGENTATION_PACKAGE_MODULE_URL__;
  const reactModuleUrl = __AGENTATION_REACT_MODULE_URL__;
  const reactDOMClientModuleUrl = __AGENTATION_REACT_DOM_CLIENT_MODULE_URL__;
  const stateKey = '__GHOSTEX_AGENTATION__';
  const rootId = 'ghostex-agentation-root';
  const directionStyleId = 'ghostex-agentation-direction-style';
  const existing = window[stateKey];
  if (existing && typeof existing.unmount === 'function') {
    existing.unmount();
    return;
  }

  const state = {
    canceled: false,
    container: null,
    directionStyle: null,
    root: null,
    activated: false,
    failed: false,
    unmount: function() {
      this.canceled = true;
      if (this.root && typeof this.root.unmount === 'function') {
        try {
          this.root.unmount();
        } catch (_) {}
      }
      if (this.container && this.container.parentNode) {
        this.container.parentNode.removeChild(this.container);
      }
      if (this.directionStyle && this.directionStyle.parentNode) {
        this.directionStyle.parentNode.removeChild(this.directionStyle);
      }
      if (window[stateKey] === this) {
        delete window[stateKey];
      }
    }
  };
  window[stateKey] = state;

  const findStartButton = function() {
    const root = state.container || document.getElementById(rootId);
    return document.querySelector('[data-agentation-toolbar] [title="Start feedback mode"][role="button"]')
      || document.querySelector('[data-agentation-toolbar][title="Start feedback mode"][role="button"]')
      || document.querySelector('[title="Start feedback mode"][role="button"]')
      || (root && root.querySelector('[title="Start feedback mode"][role="button"]'))
      || document.querySelector('[data-agentation-toolbar][title="Start feedback mode"]')
      || document.querySelector('[title="Start feedback mode"]')
      || (root && root.querySelector('[title="Start feedback mode"]'));
  };

  const autoActivate = function(attempt) {
    if (state.canceled) {
      return;
    }
    const startButton = findStartButton();
    if (startButton && typeof startButton.click === 'function') {
      startButton.click();
      state.activated = true;
      return;
    }
    if (attempt < 20) {
      window.setTimeout(function() {
        autoActivate(attempt + 1);
      }, 50);
    }
  };

  const scheduleAutoActivate = function() {
    const run = function() {
      autoActivate(0);
    };
    if (typeof window.requestAnimationFrame === 'function') {
      window.requestAnimationFrame(function() {
        window.requestAnimationFrame(run);
      });
    } else {
      window.setTimeout(run, 0);
    }
  };

  const mount = async function() {
    const modules = await Promise.all([
      import(reactModuleUrl),
      import(reactDOMClientModuleUrl),
      import(packageModuleUrl)
    ]);
    if (state.canceled) {
      return;
    }
    const React = modules[0].default || modules[0];
    const ReactDOMClient = modules[1];
    const Agentation = modules[2].Agentation;
    if (!React || typeof React.createElement !== 'function' || !ReactDOMClient.createRoot || !Agentation) {
      state.failed = true;
      state.unmount();
      return;
    }

    const staleContainer = document.getElementById(rootId);
    if (staleContainer && staleContainer.parentNode) {
      staleContainer.parentNode.removeChild(staleContainer);
    }
    const staleDirectionStyle = document.getElementById(directionStyleId);
    if (staleDirectionStyle && staleDirectionStyle.parentNode) {
      staleDirectionStyle.parentNode.removeChild(staleDirectionStyle);
    }
    // Agentation portals its visible UI into document.body, outside this
    // mount container. Give that portal an explicit writing-mode boundary so
    // RTL page content cannot reverse Agentation's own controls.
    const directionStyle = document.createElement('style');
    directionStyle.id = directionStyleId;
    directionStyle.textContent = '[data-agentation-root][data-agentation-theme] { direction: ltr !important; text-align: left !important; }';
    (document.head || document.documentElement).appendChild(directionStyle);
    const container = document.createElement('div');
    container.id = rootId;
    container.setAttribute('data-agentation-root', 'true');
    (document.body || document.documentElement).appendChild(container);

    state.container = container;
    state.directionStyle = directionStyle;
    state.root = ReactDOMClient.createRoot(container);
    state.root.render(React.createElement(Agentation));
    scheduleAutoActivate();
  };

  const start = function() {
    mount().catch(function() {
      state.failed = true;
      state.unmount();
    });
  };

  if (document.body || document.readyState !== 'loading') {
    start();
  } else {
    window.addEventListener('DOMContentLoaded', start, { once: true });
  }
})();
"##;

    TEMPLATE
        .replace(
            "__AGENTATION_PACKAGE_MODULE_URL__",
            &browser_feedback_js_string_literal(BROWSER_FEEDBACK_AGENTATION_PACKAGE_MODULE_URL),
        )
        .replace(
            "__AGENTATION_REACT_MODULE_URL__",
            &browser_feedback_js_string_literal(BROWSER_FEEDBACK_AGENTATION_REACT_MODULE_URL),
        )
        .replace(
            "__AGENTATION_REACT_DOM_CLIENT_MODULE_URL__",
            &browser_feedback_js_string_literal(
                BROWSER_FEEDBACK_AGENTATION_REACT_DOM_CLIENT_MODULE_URL,
            ),
        )
}

fn browser_url_host(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let after_scheme = trimmed
        .split_once("://")
        .map(|(_, rest)| rest)
        .unwrap_or(trimmed);
    let without_userinfo = after_scheme.rsplit('@').next().unwrap_or(after_scheme);
    let authority_end = without_userinfo
        .find(['/', '?', '#'])
        .unwrap_or(without_userinfo.len());
    let authority = &without_userinfo[..authority_end];
    if authority.is_empty() {
        return None;
    }
    let host = if let Some(rest) = authority.strip_prefix('[') {
        rest.split_once(']').map(|(host, _)| host).unwrap_or("")
    } else {
        authority
            .split_once(':')
            .map(|(host, _)| host)
            .unwrap_or(authority)
    };
    let normalized = host.trim_end_matches('.').to_ascii_lowercase();
    (!normalized.is_empty()).then_some(normalized)
}

fn browser_tab_title_for_url(url: &str) -> String {
    if let Some(host) = browser_url_host(url) {
        return host;
    }

    let trimmed = url.trim();
    if trimmed.is_empty() || trimmed == BROWSER_ADDRESS_ONLY_CEF_URL {
        "New Tab".to_string()
    } else {
        trimmed.to_string()
    }
}

/*
CDXC:GPUIBrowserTabTitleCache 2026-07-12:
The cached title persisted into browser shell state is the user-visible tab
label only: trimmed, bounded, and never a URL/query/credential field. It exists
so restart keeps showing the last displayed title instead of the URL-host
fallback.
*/
const BROWSER_TAB_CACHED_TITLE_MAX_CHARS: usize = 256;

fn sanitize_browser_tab_cached_title(title: &str) -> Option<String> {
    let trimmed = title.trim();
    if trimmed.is_empty() {
        return None;
    }
    Some(
        trimmed
            .chars()
            .take(BROWSER_TAB_CACHED_TITLE_MAX_CHARS)
            .collect(),
    )
}

fn browser_repository_remote_web_url(project_path: &Path) -> Option<String> {
    let output = std::process::Command::new("/usr/bin/git")
        .args(["remote", "get-url", "origin"])
        .current_dir(project_path)
        .stdin(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }

    let remote = String::from_utf8(output.stdout).ok()?;
    let remote = remote.trim().trim_end_matches('/').trim_end_matches(".git");
    let web_url = if let Some(path) = remote.strip_prefix("git@") {
        let (host, repository) = path.split_once(':')?;
        format!("https://{host}/{repository}")
    } else if let Some(path) = remote.strip_prefix("ssh://git@") {
        let (host, repository) = path.split_once('/')?;
        format!("https://{host}/{repository}")
    } else if remote.starts_with("https://") || remote.starts_with("http://") {
        remote.to_string()
    } else {
        return None;
    };

    sanitize_browser_tab_url_for_state(&web_url)
}

fn browser_shell_default_url(project_path: Option<&Path>) -> String {
    project_path
        .and_then(browser_repository_remote_web_url)
        .unwrap_or_else(|| DEFAULT_BROWSER_URL.to_string())
}

fn titlebar_project_label_from_latest_sidebar_snapshot(
    latest_snapshot: Option<&GpuiProjectSnapshot>,
) -> String {
    /*
    CDXC:GPUITitlebarProjectLabel 2026-06-22-19:57:
    The titlebar label is runtime-only sidebar state: use the latest valid snapshot display name and show the static Ghostex label before any valid sidebar payload arrives. Do not read env vars, repo folders, .git metadata, workspace names, fixture names, paths, URLs, sidebar titles, persisted state, or logs to infer the label.
    */
    latest_snapshot
        .map(|snapshot| snapshot.display_name.clone())
        .unwrap_or_else(|| TITLEBAR_PROJECT_LABEL_FALLBACK.to_string())
}

fn cef_parent_native_view(window: &mut Window) -> Result<*mut std::ffi::c_void> {
    /*
    CDXC:GPUICefPlatformSeam 2026-07-04:
    Windowed CEF parents its child views on the GPUI window's native handle:
    the root NSView on macOS, the top-level HWND on Windows, and the X11
    window id on Linux (gpui's X11 backend hands out an Xcb handle; the Xlib
    arm covers the same id space for completeness). The pointer stays opaque
    past this point; only the cef platform adapters interpret it.
    */
    let handle = window
        .window_handle()
        .map_err(|error| anyhow::anyhow!("failed to read GPUI raw window handle: {error:?}"))?;
    match handle.as_raw() {
        RawWindowHandle::AppKit(handle) => Ok(handle.ns_view.as_ptr()),
        RawWindowHandle::Win32(handle) => Ok(handle.hwnd.get() as *mut std::ffi::c_void),
        RawWindowHandle::Xcb(handle) => Ok(handle.window.get() as usize as *mut std::ffi::c_void),
        RawWindowHandle::Xlib(handle) => Ok(handle.window as usize as *mut std::ffi::c_void),
        other => {
            anyhow::bail!("windowed CEF requires an AppKit, Win32, or X11 parent, got {other:?}")
        }
    }
}

fn normalize_address(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return None;
    }
    if trimmed.contains("://") {
        return Some(trimmed.to_string());
    }
    if trimmed == "localhost"
        || trimmed.starts_with("localhost:")
        || trimmed.starts_with("127.0.0.1")
    {
        return Some(format!("http://{trimmed}"));
    }
    if trimmed.contains('.') && !trimmed.contains(' ') {
        return Some(format!("https://{trimmed}"));
    }
    /*
    CDXC:GPUIBrowserToolbar 2026-06-14-17:42:
    The GPUI address field should resolve committed non-empty text the same way as the macOS browser toolbar: explicit schemes are kept, local hosts use http, domain-like text uses https, and free text becomes an in-pane Google search. Empty commits are not normalized; the toolbar restores the current tab URL and returns focus to page content.
    */
    Some(format!(
        "https://www.google.com/search?q={}",
        encode_search_query(trimmed)
    ))
}

fn browser_url_origin_key(url: &str) -> Option<String> {
    // Mirrors the macOS sidebar's `browserUrlOriginKey`: a lowercased
    // scheme+host (host keeps its port, drops userinfo) or None for
    // unparseable/hostless URLs so they can never match each other.
    let (scheme, rest) = url.split_once("://")?;
    let authority = rest.split(['/', '?', '#']).next().unwrap_or_default();
    let host = authority
        .rsplit_once('@')
        .map(|(_, host)| host)
        .unwrap_or(authority);
    if scheme.is_empty() || host.is_empty() {
        return None;
    }
    Some(format!("{scheme}://{host}").to_ascii_lowercase())
}

fn encode_search_query(value: &str) -> String {
    let mut encoded = String::with_capacity(value.len());
    const HEX: &[u8; 16] = b"0123456789ABCDEF";

    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                encoded.push(byte as char);
            }
            b' ' => encoded.push('+'),
            _ => {
                encoded.push('%');
                encoded.push(HEX[(byte >> 4) as usize] as char);
                encoded.push(HEX[(byte & 0x0f) as usize] as char);
            }
        }
    }

    encoded
}

fn sidebar_url() -> Result<String> {
    if let Ok(value) = env::var("GHOSTEX_GPUI_SIDEBAR_URL") {
        if !value.trim().is_empty() {
            return Ok(value);
        }
    }

    let executable = env::current_exe().context("failed to resolve current executable")?;
    if let Some(bundle_root) = find_app_bundle_root(&executable) {
        let bundled = bundle_root.join("Contents/Resources/sidebar/index.html");
        if bundled.exists() {
            return Ok(file_url(&bundled));
        }
    }

    /*
    CDXC:GPUIWindowsBringup 2026-07-04:
    Packaged Windows and Linux layouts have no .app bundle: the packaging
    scripts (build-windows-app.ps1 / build-linux-app.sh) stage the sidebar at
    dist/sidebar beside the executable. That directory name is load-bearing —
    the CEF helper's first-party entry-URL check accepts only
    /Contents/Resources/sidebar/ or /dist/sidebar/ file URLs.
    */
    #[cfg(any(target_os = "windows", target_os = "linux"))]
    if let Some(exe_dir) = executable.parent() {
        let packaged = exe_dir.join("dist/sidebar/index.html");
        if packaged.exists() {
            return Ok(file_url(&packaged));
        }
    }

    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let local = manifest_dir.join("dist/sidebar/index.html");
    if local.exists() {
        return Ok(file_url(&local));
    }

    anyhow::bail!(
        "sidebar bundle was not found; run gpui/scripts/build-macos-app.sh or bunx vite build --config gpui/vite.config.ts"
    );
}

fn find_app_bundle_root(path: &std::path::Path) -> Option<PathBuf> {
    for ancestor in path.ancestors() {
        if ancestor
            .extension()
            .is_some_and(|extension| extension == "app")
        {
            return Some(ancestor.to_path_buf());
        }
    }
    None
}

#[cfg(not(target_os = "windows"))]
fn file_url(path: &std::path::Path) -> String {
    format!("file://{}", path.to_string_lossy())
}

#[cfg(target_os = "windows")]
fn file_url(path: &std::path::Path) -> String {
    let normalized = path.to_string_lossy().replace('\\', "/");
    format!("file:///{}", normalized.trim_start_matches('/'))
}

