fn gpui_open_url(url: &'static str) -> Result<(), String> {
    /*
    CDXC:GPUISettingsActionBridge 2026-06-24-11:59:
    Settings URL actions in GPUI are bounded to hardcoded product URLs from Rust. Do not accept React-provided URLs, shell commands, environment values, or user paths for docs/System Settings opens.
    */
    gpui_spawn_os_open(std::ffi::OsStr::new(url))
}

/// Terminal link clicks (Ghostty OPEN_URL actions) carry runtime-provided
/// text and only fire on an explicit cmd+click, so this mirrors the macOS
/// host's open-url handling: text with a URL scheme opens with its default
/// handler, and anything else is treated as a file path (`~` expanded) so
/// the ghostty link regex's absolute/relative path matches open too.
fn gpui_open_terminal_action_url(url: &str) -> Result<(), String> {
    let trimmed = url.trim();
    if trimmed.is_empty() {
        return Err("Terminal link is empty.".to_string());
    }
    if trimmed.len() > 2048 {
        return Err("Terminal link is too long.".to_string());
    }
    let open_value = gpui_terminal_markdown_image_reference_path(trimmed).unwrap_or(trimmed);
    if gpui_terminal_link_has_scheme(open_value) {
        return gpui_spawn_os_open(std::ffi::OsStr::new(open_value));
    }
    gpui_spawn_os_open(gpui_expand_terminal_link_path(open_value).as_os_str())
}

fn gpui_terminal_link_is_web_url(link: &str) -> bool {
    link.get(..7)
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("http://"))
        || link
            .get(..8)
            .is_some_and(|prefix| prefix.eq_ignore_ascii_case("https://"))
}

fn gpui_terminal_markdown_image_reference_path(value: &str) -> Option<&str> {
    if !value.starts_with("[Image #") || !value.ends_with(')') {
        return None;
    }
    let open_paren = value.find('(')?;
    let path = value.get(open_paren + 1..value.len() - 1)?.trim();
    let path = path
        .strip_prefix('<')
        .and_then(|path| path.strip_suffix('>'))
        .unwrap_or(path)
        .trim();
    (!path.is_empty()).then_some(path)
}

fn gpui_terminal_file_link_path(link: &str) -> Option<PathBuf> {
    let decoded_file_url;
    let path = if let Some(file_url_path) = link
        .get(..7)
        .filter(|prefix| prefix.eq_ignore_ascii_case("file://"))
        .and_then(|_| link.get(7..))
    {
        decoded_file_url = browser_favicon_percent_decode(file_url_path, 2048)
            .and_then(|bytes| String::from_utf8(bytes).ok())
            .unwrap_or_else(|| file_url_path.to_string());
        decoded_file_url.as_str()
    } else {
        if gpui_terminal_link_has_scheme(link) && !gpui_terminal_link_is_windows_drive_path(link) {
            return None;
        }
        link
    };
    let path = gpui_terminal_file_link_path_without_coordinates(path);
    #[cfg(target_os = "windows")]
    let path = path
        .strip_prefix('/')
        .filter(|candidate| gpui_terminal_link_is_windows_drive_path(candidate))
        .unwrap_or(path);
    (!path.is_empty()).then(|| gpui_expand_terminal_link_path(path))
}

fn gpui_terminal_file_link_path_without_coordinates(path: &str) -> &str {
    let mut path = path;
    for _ in 0..2 {
        let Some((candidate, coordinate)) = path.rsplit_once(':') else {
            break;
        };
        if coordinate.is_empty() || !coordinate.bytes().all(|byte| byte.is_ascii_digit()) {
            break;
        }
        path = candidate;
    }
    path
}

/// RFC 3986 scheme prefix (alpha, then alphanumeric/`+`/`-`/`.`, then `:`)
/// splits URLs from file paths the way the macOS host does; path matches
/// like `src/file.rs:12` fail it because `/` appears before the colon.
fn gpui_terminal_link_has_scheme(link: &str) -> bool {
    let Some(colon) = link.find(':') else {
        return false;
    };
    let mut chars = link[..colon].chars();
    chars.next().is_some_and(|c| c.is_ascii_alphabetic())
        && chars.all(|c| c.is_ascii_alphanumeric() || matches!(c, '+' | '-' | '.'))
}

fn gpui_terminal_link_is_windows_drive_path(link: &str) -> bool {
    let bytes = link.as_bytes();
    bytes.len() >= 3
        && bytes[0].is_ascii_alphabetic()
        && bytes[1] == b':'
        && matches!(bytes[2], b'/' | b'\\')
}

/// Expand a leading `~/` to the user's home directory so home-relative
/// path links resolve like the macOS host's standardizing conversion.
fn gpui_expand_terminal_link_path(link: &str) -> PathBuf {
    if let Some(rest) = link.strip_prefix("~/")
        && let Some(home) = std::env::var_os("HOME")
    {
        return PathBuf::from(home).join(rest);
    }
    PathBuf::from(link)
}

/// Per-terminal runtime state reported by Ghostty OSC sequences and runtime
/// actions (window title, working directory, bell, hovered link, search).
/// Runtime-only: keyed by runtime session identity and never persisted into
/// shell-layout state.
#[derive(Clone, Debug, Default)]
struct GpuiTerminalRuntimeOscState {
    title: Option<String>,
    pwd: Option<String>,
    bell_count: u64,
    hovered_link_url: Option<String>,
    search: Option<GpuiTerminalSearchState>,
}

struct PendingGpuiTerminalPasteConfirmation {
    text: String,
    view: Entity<terminal_element::TerminalView>,
}

/// Mirrors the macOS host's per-surface `GhostexGhosttySearchState`: created by
/// START_SEARCH, updated by SEARCH_TOTAL/SEARCH_SELECTED, cleared by
/// END_SEARCH. Negative totals/selections from Ghostty mean "unknown".
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct GpuiTerminalSearchState {
    needle: String,
    total: Option<u64>,
    selected: Option<u64>,
}

/// Which pane family a GPUI-engine terminal view reports events for.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GpuiEngineTerminalEventTarget {
    Agents(TerminalSessionId),
    Command(CommandSessionId),
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum GpuiTerminalAttachmentTarget {
    Terminal(GpuiEngineTerminalEventTarget),
    // Companion can display a shell id borrowed from a project-local remote
    // namespace. Retain the full shared workspace identity across the native
    // picker and upload so parked projects with the same numeric id cannot
    // redirect either the upload or its eventual paste.
    ProjectEditorCompanion {
        slot_id: ProjectEditorCompanionTerminalBodyMountSlotId,
        session_key: GpuiWorkspaceTerminalSessionKey,
    },
}

impl GpuiTerminalAttachmentTarget {
    fn engine_target(&self) -> GpuiEngineTerminalEventTarget {
        match self {
            Self::Terminal(target) => *target,
            Self::ProjectEditorCompanion { slot_id, .. } => {
                GpuiEngineTerminalEventTarget::Agents(slot_id.session_id)
            }
        }
    }
}

/// Where a command tab dropped into the Agents workspace should land.
#[derive(Clone, Copy, PartialEq, Eq)]
enum CommandToAgentsDropPlacement {
    PaneBody(WorkspaceDropZone),
    TabStrip(usize),
}

fn apply_gpui_terminal_runtime_action_events(
    osc_states: &mut HashMap<AgentsTerminalRuntimeSessionId, GpuiTerminalRuntimeOscState>,
    runtime_session_id: AgentsTerminalRuntimeSessionId,
    events: Vec<terminal_ghostty_surface::GhosttyRuntimeActionEvent>,
) -> bool {
    use terminal_ghostty_surface::GhosttyRuntimeActionEvent;

    let mut runtime_state_changed = false;
    for event in events {
        match event {
            GhosttyRuntimeActionEvent::OpenUrl { .. } => {}
            GhosttyRuntimeActionEvent::RingBell => {
                let state = osc_states.entry(runtime_session_id).or_default();
                state.bell_count = state.bell_count.wrapping_add(1);
                runtime_state_changed = true;
            }
            GhosttyRuntimeActionEvent::SetTitle { title } => {
                if title == TEMP_REMOTE_LOCAL_READY_TITLE || title == TEMP_REMOTE_SSH_READY_TITLE {
                    support_logs::append_temporary(
                        support_logs::GpuiSupportLog::TerminalFocus,
                        if title == TEMP_REMOTE_LOCAL_READY_TITLE {
                            "TEMP.remoteNewTerminal.localWrapperReady"
                        } else {
                            "TEMP.remoteNewTerminal.remoteCommandReady"
                        },
                        serde_json::json!({ "engine": "ghostty" }),
                    );
                }
                osc_states.entry(runtime_session_id).or_default().title = Some(title);
                runtime_state_changed = true;
            }
            GhosttyRuntimeActionEvent::Pwd { pwd } => {
                osc_states.entry(runtime_session_id).or_default().pwd = Some(pwd);
                runtime_state_changed = true;
            }
            GhosttyRuntimeActionEvent::MouseOverLink { url } => {
                let state = osc_states.entry(runtime_session_id).or_default();
                if state.hovered_link_url != url {
                    state.hovered_link_url = url;
                    runtime_state_changed = true;
                }
            }
            GhosttyRuntimeActionEvent::StartSearch { needle } => {
                let state = osc_states.entry(runtime_session_id).or_default();
                match (&mut state.search, needle) {
                    (Some(search), Some(needle)) => search.needle = needle,
                    (Some(_), None) => {}
                    (search @ None, needle) => {
                        *search = Some(GpuiTerminalSearchState {
                            needle: needle.unwrap_or_default(),
                            ..GpuiTerminalSearchState::default()
                        });
                    }
                }
                runtime_state_changed = true;
            }
            GhosttyRuntimeActionEvent::EndSearch => {
                let state = osc_states.entry(runtime_session_id).or_default();
                if state.search.take().is_some() {
                    runtime_state_changed = true;
                }
            }
            GhosttyRuntimeActionEvent::SearchTotal { total } => {
                let state = osc_states.entry(runtime_session_id).or_default();
                if let Some(search) = &mut state.search {
                    if search.total != total {
                        search.total = total;
                        runtime_state_changed = true;
                    }
                }
            }
            GhosttyRuntimeActionEvent::SearchSelected { selected } => {
                let state = osc_states.entry(runtime_session_id).or_default();
                if let Some(search) = &mut state.search {
                    if search.selected != selected {
                        search.selected = selected;
                        runtime_state_changed = true;
                    }
                }
            }
        }
    }
    runtime_state_changed
}

fn gpui_open_path(path: &Path) -> Result<(), String> {
    gpui_spawn_os_open(path.as_os_str())
}

