fn gpui_agents_hub_profiles_for(
    candidate_path: &Path,
    home: &Path,
    profiles: &[GpuiAgentsHubProfileItem],
    linked_profiles: &[GpuiAgentsHubProfileItem],
    open_code: &GpuiAgentsHubProfileItem,
    pi_agent: &GpuiAgentsHubProfileItem,
) -> Vec<GpuiAgentsHubProfileItem> {
    let shared_agents_root = home.join(".agents");
    let shared_skills_root = home.join("agents");
    if gpui_path_is_relative_to(candidate_path, &shared_agents_root)
        || gpui_path_is_relative_to(candidate_path, &shared_skills_root)
    {
        let mut result = linked_profiles.to_vec();
        if gpui_path_is_relative_to(candidate_path, &home.join("agents").join("hooks")) {
            result.push(pi_agent.clone());
        }
        return result;
    }
    for profile in profiles {
        if gpui_path_is_relative_to(candidate_path, &profile.profile_path) {
            return vec![profile.clone()];
        }
    }
    if gpui_path_is_relative_to(candidate_path, &open_code.profile_path) {
        return vec![open_code.clone()];
    }
    if gpui_path_is_relative_to(candidate_path, &pi_agent.profile_path) {
        return vec![pi_agent.clone()];
    }
    Vec::new()
}

fn gpui_agents_hub_existing_files(paths: Vec<PathBuf>) -> Vec<PathBuf> {
    paths
        .into_iter()
        .filter(|path| gpui_is_file(path))
        .collect()
}

fn gpui_agents_hub_list_directories(root: &Path) -> Vec<PathBuf> {
    let mut directories = fs::read_dir(root)
        .ok()
        .into_iter()
        .flat_map(|entries| entries.filter_map(Result::ok))
        .map(|entry| entry.path())
        .filter(|path| {
            fs::metadata(path)
                .map(|metadata| metadata.is_dir())
                .unwrap_or(false)
        })
        .collect::<Vec<_>>();
    directories.sort();
    directories
}

fn gpui_agents_hub_walk_files<F>(root: &Path, max_depth: usize, predicate: F) -> Vec<PathBuf>
where
    F: Fn(&Path) -> bool,
{
    let mut files = Vec::new();
    gpui_agents_hub_walk_files_inner(root, 0, max_depth, &predicate, &mut files);
    files.sort();
    files
}

fn gpui_agents_hub_walk_files_inner<F>(
    current: &Path,
    depth: usize,
    max_depth: usize,
    predicate: &F,
    files: &mut Vec<PathBuf>,
) where
    F: Fn(&Path) -> bool,
{
    let mut entries = fs::read_dir(current)
        .ok()
        .into_iter()
        .flat_map(|entries| entries.filter_map(Result::ok))
        .collect::<Vec<_>>();
    entries.sort_by_key(|entry| entry.path());
    for entry in &entries {
        let path = entry.path();
        if fs::metadata(&path)
            .map(|metadata| metadata.is_file())
            .unwrap_or(false)
            && predicate(&path)
        {
            files.push(path);
        }
    }
    if depth >= max_depth {
        return;
    }
    for entry in entries {
        let path = entry.path();
        let name = gpui_file_name_string(&path);
        if gpui_agents_hub_ignored_directory_name(&name) {
            continue;
        }
        if fs::metadata(&path)
            .map(|metadata| metadata.is_dir())
            .unwrap_or(false)
        {
            gpui_agents_hub_walk_files_inner(&path, depth + 1, max_depth, predicate, files);
        }
    }
}

fn gpui_agents_hub_ignored_directory_name(name: &str) -> bool {
    matches!(
        name,
        ".git"
            | "node_modules"
            | "dist"
            | "build"
            | "out"
            | "coverage"
            | ".cache"
            | "cache"
            | "__pycache__"
            | "sessions"
            | "projects"
            | "todos"
            | "telemetry"
            | "usage-data"
            | "ambient-suggestions"
            | "memories_2026-04-24"
            | "logs"
            | "tmp"
            | ".tmp"
    )
}

fn gpui_agents_hub_is_skill_file(candidate: &Path) -> bool {
    gpui_file_name_string(candidate) == "SKILL.md"
        || matches!(
            gpui_agents_hub_extension(candidate).as_str(),
            ".json" | ".yaml" | ".yml" | ".sh" | ".py" | ".js" | ".ts"
        )
}

fn gpui_agents_hub_is_text_file(candidate: &Path) -> bool {
    matches!(
        gpui_agents_hub_extension(candidate).as_str(),
        ".md"
            | ".json"
            | ".jsonl"
            | ".toml"
            | ".yaml"
            | ".yml"
            | ".sh"
            | ".ts"
            | ".js"
            | ".mjs"
            | ".py"
            | ".txt"
    )
}

fn gpui_agents_hub_plugin_root(plugin_file: &Path) -> Option<PathBuf> {
    let components = plugin_file.components().collect::<Vec<_>>();
    let file_name = gpui_file_name_string(plugin_file);
    if file_name == "SKILL.md" {
        for (index, component) in components.iter().enumerate() {
            if component.as_os_str() == std::ffi::OsStr::new("skills")
                && index + 1 < components.len()
            {
                return Some(gpui_path_from_components(&components[..=index + 1]));
            }
        }
    }
    for (index, component) in components.iter().enumerate() {
        if component.as_os_str() == std::ffi::OsStr::new(".codex-plugin")
            || component.as_os_str() == std::ffi::OsStr::new(".claude-plugin")
        {
            return Some(gpui_path_from_components(&components[..index]));
        }
    }
    None
}

fn gpui_path_from_components(components: &[std::path::Component<'_>]) -> PathBuf {
    let mut path = PathBuf::new();
    for component in components {
        path.push(component.as_os_str());
    }
    path
}

fn gpui_agents_hub_language_for(file_path: &Path) -> &'static str {
    let name = gpui_file_name_string(file_path);
    let extension = gpui_agents_hub_extension(file_path);
    if name.ends_with(".yaml") || name.ends_with(".yml") {
        "yaml"
    } else {
        match extension.as_str() {
            ".json" | ".jsonl" => "json",
            ".toml" => "toml",
            ".sh" => "shell",
            ".py" => "python",
            ".ts" | ".tsx" => "typescript",
            ".js" | ".mjs" | ".cjs" => "javascript",
            ".md" => "markdown",
            _ => "plaintext",
        }
    }
}

fn gpui_agents_hub_file_id(path: &Path) -> String {
    let mut id = String::new();
    let mut previous_dash = false;
    for character in gpui_path_string(path).to_lowercase().chars() {
        if character.is_ascii_alphanumeric() {
            id.push(character);
            previous_dash = false;
        } else if !previous_dash && !id.is_empty() {
            id.push('-');
            previous_dash = true;
        }
        if id.len() >= 180 {
            break;
        }
    }
    while id.ends_with('-') {
        id.pop();
    }
    id
}

fn gpui_agents_hub_extension(path: &Path) -> String {
    path.extension()
        .and_then(|value| value.to_str())
        .map(|value| format!(".{}", value.to_lowercase()))
        .unwrap_or_default()
}

fn gpui_file_name_string(path: &Path) -> String {
    path.file_name()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_string()
}

fn gpui_path_string(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

fn gpui_relative_path_name(path: &Path, root: &Path) -> Option<String> {
    path.strip_prefix(root)
        .ok()
        .map(gpui_path_string)
        .filter(|value| !value.is_empty())
}

fn gpui_path_is_relative_to(candidate: &Path, root: &Path) -> bool {
    candidate == root || candidate.strip_prefix(root).is_ok()
}

