#[cfg(target_os = "macos")]
fn gpui_deliver_macos_session_attention_notification(
    candidate: GpuiSessionAttentionNotificationCandidate,
) -> GpuiMacOSNotificationDeliveryResult {
    let Ok(session_id) = std::ffi::CString::new(candidate.session_id.as_str()) else {
        return GpuiMacOSNotificationDeliveryResult::Failed;
    };
    let Ok(title) = std::ffi::CString::new(candidate.title.as_str()) else {
        return GpuiMacOSNotificationDeliveryResult::Failed;
    };
    let Ok(body) = std::ffi::CString::new(candidate.body.as_str()) else {
        return GpuiMacOSNotificationDeliveryResult::Failed;
    };
    let icon_data_url = match candidate.icon_data_url.as_deref() {
        Some(value) => match std::ffi::CString::new(value) {
            Ok(value) => Some(value),
            Err(_) => return GpuiMacOSNotificationDeliveryResult::Failed,
        },
        None => None,
    };
    GpuiMacOSNotificationDeliveryResult::from_native_code(unsafe {
        GhostexGpuiDeliverSessionAttentionNotification(
            session_id.as_ptr(),
            title.as_ptr(),
            body.as_ptr(),
            icon_data_url
                .as_ref()
                .map_or(std::ptr::null(), |value| value.as_ptr()),
        )
    })
}

#[cfg(not(target_os = "macos"))]
fn gpui_deliver_macos_session_attention_notification(
    _candidate: GpuiSessionAttentionNotificationCandidate,
) -> GpuiMacOSNotificationDeliveryResult {
    GpuiMacOSNotificationDeliveryResult::Unsupported
}

#[cfg(target_os = "macos")]
fn apply_gpui_menu_bar_status_item(state: &GpuiSidebarSessionStatusIndicatorsState) {
    if let Some(visible_state) = gpui_menu_bar_status_item_visible_state(state) {
        let (_project_owners, project_entries) = gpui_menu_bar_status_native_projects(state);
        unsafe {
            GhostexGpuiApplyMenuBarStatusItemWithProjects(
                visible_state.attention_count,
                visible_state.working_count,
                visible_state.available_count,
                project_entries.as_ptr(),
                project_entries.len(),
            );
        }
    } else {
        hide_gpui_menu_bar_status_item();
    }
}

#[cfg(not(target_os = "macos"))]
fn apply_gpui_menu_bar_status_item(_state: &GpuiSidebarSessionStatusIndicatorsState) {}

#[cfg(target_os = "macos")]
fn gpui_menu_bar_status_native_projects(
    state: &GpuiSidebarSessionStatusIndicatorsState,
) -> (
    Vec<GpuiMenuBarStatusNativeProjectOwner>,
    Vec<GpuiMenuBarStatusNativeProjectEntry>,
) {
    let project_owners = state
        .projects
        .iter()
        .filter_map(gpui_menu_bar_status_native_project_owner)
        .collect::<Vec<_>>();
    let project_entries = project_owners
        .iter()
        .map(|project| GpuiMenuBarStatusNativeProjectEntry {
            project_id: project.project_id.as_ptr(),
            title: project.title.as_ptr(),
            sessions: project.entries.as_ptr(),
            session_count: project.entries.len(),
        })
        .collect::<Vec<_>>();
    (project_owners, project_entries)
}

#[cfg(target_os = "macos")]
fn gpui_menu_bar_status_native_project_owner(
    project: &GpuiStatusIndicatorProjectState,
) -> Option<GpuiMenuBarStatusNativeProjectOwner> {
    let project_id = std::ffi::CString::new(project.project_id.as_str()).ok()?;
    let title = std::ffi::CString::new(project.title.as_str()).ok()?;
    let sessions = project
        .sessions
        .iter()
        .filter_map(gpui_menu_bar_status_native_session_owner)
        .collect::<Vec<_>>();
    let entries = sessions
        .iter()
        .map(|session| session.entry)
        .collect::<Vec<_>>();
    Some(GpuiMenuBarStatusNativeProjectOwner {
        project_id,
        title,
        sessions,
        entries,
    })
}

#[cfg(target_os = "macos")]
fn gpui_menu_bar_status_native_session_owner(
    session: &GpuiStatusIndicatorSessionState,
) -> Option<GpuiMenuBarStatusNativeSessionOwner> {
    let session_id = std::ffi::CString::new(session.session_id.as_str()).ok()?;
    let title = std::ffi::CString::new(session.title.as_str()).ok()?;
    let last_active_at = session
        .last_active_at
        .as_ref()
        .and_then(|timestamp| std::ffi::CString::new(timestamp.as_str()).ok());
    let entry = GpuiMenuBarStatusNativeSessionEntry {
        session_id: session_id.as_ptr(),
        title: title.as_ptr(),
        last_active_at: last_active_at
            .as_ref()
            .map_or(std::ptr::null(), |timestamp| timestamp.as_ptr()),
        status: gpui_menu_bar_status_native_kind(session.status),
        order: session.order,
    };
    Some(GpuiMenuBarStatusNativeSessionOwner {
        session_id,
        title,
        last_active_at,
        entry,
    })
}

#[cfg(target_os = "macos")]
fn gpui_menu_bar_status_native_kind(status: GpuiStatusIndicatorStatus) -> i32 {
    match status {
        GpuiStatusIndicatorStatus::Attention => 0,
        GpuiStatusIndicatorStatus::Working => 1,
        GpuiStatusIndicatorStatus::Available => 2,
    }
}

