/// Mirrors macOS `resolvePortlessSetupPrompt` (native-sidebar.tsx): the guided
/// setup prompt appears only when the global setting and gxserver status say
/// Portless is enabled, this app can run the privileged admin helper, a live
/// listener exists, and setup is missing or needs reconfigure/takeover.
fn gpui_resolve_portless_setup_prompt(
    settings_portless_enabled: bool,
    portless_state: &serde_json::Value,
) -> Option<(GpuiPortlessSetupPromptMode, GpuiPortlessProtocol)> {
    let health = portless_state.get("health")?;
    if !settings_portless_enabled
        || health.get("enabled").and_then(serde_json::Value::as_bool) != Some(true)
    {
        return None;
    }
    if portless_state
        .get("nativeAdmin")
        .and_then(|admin| admin.get("available"))
        .and_then(serde_json::Value::as_bool)
        != Some(true)
    {
        return None;
    }
    if portless_state
        .get("presentation")
        .and_then(|presentation| presentation.get("liveListenerCount"))
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0)
        == 0
    {
        return None;
    }
    if health
        .get("setupStatus")
        .and_then(serde_json::Value::as_str)
        != Some("needed")
    {
        return None;
    }
    let protocol = health
        .get("protocol")
        .and_then(serde_json::Value::as_str)
        .and_then(gpui_portless_protocol)?;
    match health
        .get("setupOwnership")
        .and_then(serde_json::Value::as_str)
    {
        Some("missing") => Some((GpuiPortlessSetupPromptMode::FirstSetup, protocol)),
        Some("standalone") | Some("ghostex") => {
            Some((GpuiPortlessSetupPromptMode::StandaloneReconfigure, protocol))
        }
        _ => None,
    }
}

impl GpuiPortlessStateUpdate {
    fn to_rpc_params(self) -> serde_json::Value {
        /*
        CDXC:GPUISettingsPortlessBridge 2026-06-24-11:48:
        `/api/updatePortlessState` accepts only the shared Portless state-update contract: `setEnabled`, `setProtocol`, or `recordAdminResult` with booleans and bounded action/protocol enums. Keep request construction centralized here so GPUI never forwards request ids, paths, URLs, commands, output, environment, tokens, or arbitrary React payload fields to gxserver.
        */
        match self {
            Self::SetEnabled { enabled } => serde_json::json!({
                "enabled": enabled,
                "kind": "setEnabled",
            }),
            Self::SetProtocol { protocol } => serde_json::json!({
                "kind": "setProtocol",
                "protocol": protocol.as_str(),
            }),
            Self::RecordAdminResult {
                action,
                ok,
                protocol,
            } => {
                let mut params = serde_json::Map::new();
                params.insert(
                    "action".to_string(),
                    serde_json::Value::String(action.as_str().to_string()),
                );
                params.insert(
                    "kind".to_string(),
                    serde_json::Value::String("recordAdminResult".to_string()),
                );
                params.insert("ok".to_string(), serde_json::Value::Bool(ok));
                if let Some(protocol) = protocol {
                    params.insert(
                        "protocol".to_string(),
                        serde_json::Value::String(protocol.as_str().to_string()),
                    );
                }
                serde_json::Value::Object(params)
            }
        }
    }
}

#[derive(Clone, Debug)]
struct GpuiPortlessAdminResult {
    request_id: String,
    action: GpuiPortlessAdminAction,
    protocol: Option<GpuiPortlessProtocol>,
    ok: bool,
    exit_code: Option<i32>,
    status: &'static str,
    error_code: Option<&'static str>,
}

impl GpuiPortlessAdminResult {
    fn message(&self) -> serde_json::Value {
        let mut result = serde_json::Map::new();
        result.insert(
            "action".to_string(),
            serde_json::Value::String(self.action.as_str().to_string()),
        );
        if let Some(error_code) = self.error_code {
            result.insert(
                "errorCode".to_string(),
                serde_json::Value::String(error_code.to_string()),
            );
        }
        if let Some(exit_code) = self.exit_code {
            result.insert(
                "exitCode".to_string(),
                serde_json::Value::Number(serde_json::Number::from(i64::from(exit_code))),
            );
        }
        result.insert("ok".to_string(), serde_json::Value::Bool(self.ok));
        if let Some(protocol) = self.protocol {
            result.insert(
                "protocol".to_string(),
                serde_json::Value::String(protocol.as_str().to_string()),
            );
        }
        result.insert(
            "requestId".to_string(),
            serde_json::Value::String(self.request_id.clone()),
        );
        result.insert(
            "status".to_string(),
            serde_json::Value::String(self.status.to_string()),
        );
        result.insert(
            "type".to_string(),
            serde_json::Value::String("portlessAdminResult".to_string()),
        );
        serde_json::Value::Object(result)
    }
}

#[derive(Clone, Debug)]
struct GpuiPortlessAdminRuntime {
    node_path: PathBuf,
    portless_cli_path: PathBuf,
}

fn gpui_portless_admin_request_id(
    command: &serde_json::Map<String, serde_json::Value>,
) -> Option<String> {
    command
        .get("requestId")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| {
            !value.is_empty() && value.chars().count() <= GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS
        })
        .map(ToOwned::to_owned)
}

fn gpui_run_portless_admin_action(
    action: GpuiPortlessAdminAction,
    protocol: Option<GpuiPortlessProtocol>,
    request_id: String,
) -> GpuiPortlessAdminResult {
    let service_protocol = match action {
        GpuiPortlessAdminAction::Install
        | GpuiPortlessAdminAction::Reconfigure
        | GpuiPortlessAdminAction::Retry => protocol,
        GpuiPortlessAdminAction::Remove => Some(protocol.unwrap_or(GpuiPortlessProtocol::Https)),
    };
    let result_protocol = if action == GpuiPortlessAdminAction::Remove {
        None
    } else {
        service_protocol
    };
    let Some(service_protocol) = service_protocol else {
        return gpui_portless_admin_result(
            request_id,
            action,
            None,
            false,
            None,
            "missing-protocol",
            Some("missing-protocol"),
        );
    };
    let Some(runtime) = gpui_resolve_portless_admin_runtime() else {
        return gpui_portless_admin_result(
            request_id,
            action,
            result_protocol,
            false,
            None,
            "missing-bundled-portless-runtime",
            Some("missing-bundled-portless-runtime"),
        );
    };
    gpui_run_portless_admin_action_with_runtime(
        action,
        service_protocol,
        result_protocol,
        request_id,
        runtime,
    )
}

#[cfg(target_os = "macos")]
fn gpui_run_portless_admin_action_with_runtime(
    action: GpuiPortlessAdminAction,
    service_protocol: GpuiPortlessProtocol,
    result_protocol: Option<GpuiPortlessProtocol>,
    request_id: String,
    runtime: GpuiPortlessAdminRuntime,
) -> GpuiPortlessAdminResult {
    let Some(script_path) = gpui_write_portless_admin_script(action, service_protocol, &runtime)
    else {
        return gpui_portless_admin_result(
            request_id,
            action,
            result_protocol,
            false,
            None,
            "admin-script-unavailable",
            Some("admin-script-unavailable"),
        );
    };
    let script_result = gpui_run_privileged_portless_admin_script(&script_path);
    let _ = fs::remove_file(&script_path);
    gpui_portless_admin_result(
        request_id,
        action,
        result_protocol,
        script_result.ok,
        Some(script_result.exit_code),
        script_result.status,
        (!script_result.ok).then_some(script_result.status),
    )
}

#[cfg(not(target_os = "macos"))]
fn gpui_run_portless_admin_action_with_runtime(
    action: GpuiPortlessAdminAction,
    _service_protocol: GpuiPortlessProtocol,
    result_protocol: Option<GpuiPortlessProtocol>,
    request_id: String,
    _runtime: GpuiPortlessAdminRuntime,
) -> GpuiPortlessAdminResult {
    gpui_portless_admin_result(
        request_id,
        action,
        result_protocol,
        false,
        None,
        "missing-bundled-portless-runtime",
        Some("missing-bundled-portless-runtime"),
    )
}

fn gpui_portless_admin_result(
    request_id: String,
    action: GpuiPortlessAdminAction,
    protocol: Option<GpuiPortlessProtocol>,
    ok: bool,
    exit_code: Option<i32>,
    status: &'static str,
    error_code: Option<&'static str>,
) -> GpuiPortlessAdminResult {
    GpuiPortlessAdminResult {
        request_id,
        action,
        protocol,
        ok,
        exit_code,
        status,
        error_code,
    }
}

#[cfg(target_os = "macos")]
fn gpui_resolve_portless_admin_runtime() -> Option<GpuiPortlessAdminRuntime> {
    /*
    CDXC:GPUIPortlessAdminBridge 2026-06-24-14:28:
    The GPUI privileged Portless helper is production-capable only from a packaged macOS app with Contents/Resources/Web/code-server/lib/node and Contents/Resources/Web/portless/dist/cli.js. Development binaries and incomplete bundles must report `missing-bundled-portless-runtime` rather than using PATH, global npm, gxserver-rs, or repository-local commands.

    Portless integration is currently disabled. If it returns, its Node runtime must resolve from the installed code-server component instead of restoring a Node binary to the base app bundle.
    */
    let executable = env::current_exe().ok()?;
    let bundle_root = find_app_bundle_root(&executable)?;
    let web_root = bundle_root.join("Contents/Resources/Web");
    let node_path = web_root.join("code-server/lib/node");
    let portless_cli_path = web_root.join("portless/dist/cli.js");
    if !gpui_is_executable_file(&node_path) || !gpui_is_file(&portless_cli_path) {
        return None;
    }
    Some(GpuiPortlessAdminRuntime {
        node_path,
        portless_cli_path,
    })
}

#[cfg(not(target_os = "macos"))]
fn gpui_resolve_portless_admin_runtime() -> Option<GpuiPortlessAdminRuntime> {
    None
}

#[cfg(target_os = "macos")]
fn gpui_write_portless_admin_script(
    action: GpuiPortlessAdminAction,
    service_protocol: GpuiPortlessProtocol,
    runtime: &GpuiPortlessAdminRuntime,
) -> Option<PathBuf> {
    let home_directory = env::var("HOME").ok().filter(|value| !value.is_empty())?;
    let user_name = gpui_portless_current_user_field("-un")?;
    let user_id = gpui_portless_current_user_field("-u")?;
    let group_id = gpui_portless_current_user_field("-g")?;
    let storage_paths = shared_settings::ghostex_storage_paths();
    let ghostex_state_directory = gpui_path_string(&storage_paths.state_dir);
    let gxserver_directory = gpui_path_string(&storage_paths.gxserver_state_dir());
    let portless_state_directory =
        gpui_path_string(&storage_paths.gxserver_state_dir().join("portless"));
    let admin_commands = gpui_portless_admin_commands(
        action,
        service_protocol,
        runtime,
        &home_directory,
        &portless_state_directory,
        &user_id,
        &group_id,
    );
    let script = format!(
        r#"#!/bin/sh
set -eu

USER_HOME={home}
USER_NAME={user_name}
USER_UID={user_id}
USER_GID={group_id}
HOME="$USER_HOME"
GHOSTEX_STATE_DIR={ghostex_state_directory}
GXSERVER_DIR={gxserver_directory}
PORTLESS_STATE_DIR={portless_state_directory}
NODE_PATH={node_path}
PORTLESS_CLI_PATH={portless_cli_path}
SERVICE_LABEL="sh.portless.proxy"
PLIST_PATH="/Library/LaunchDaemons/$SERVICE_LABEL.plist"

if [ "$(/usr/bin/id -u)" -ne 0 ]; then
  exit 91
fi

/bin/mkdir -p "$PORTLESS_STATE_DIR"
/usr/sbin/chown "$USER_UID:$USER_GID" "$GHOSTEX_STATE_DIR" "$GXSERVER_DIR" "$PORTLESS_STATE_DIR" 2>/dev/null || true
/usr/sbin/chown -R "$USER_UID:$USER_GID" "$PORTLESS_STATE_DIR" 2>/dev/null || true

run_portless_cli() {{
  /usr/bin/env -i \
    HOME="$HOME" \
    USER="$USER_NAME" \
    LOGNAME="$USER_NAME" \
    SUDO_USER="$USER_NAME" \
    SUDO_UID="$USER_UID" \
    SUDO_GID="$USER_GID" \
    PATH="/usr/bin:/bin:/usr/sbin:/sbin" \
    PORTLESS_STATE_DIR="$PORTLESS_STATE_DIR" \
    PORTLESS_SYNC_HOSTS=0 \
    "$NODE_PATH" "$PORTLESS_CLI_PATH" "$@"
}}

{admin_commands}
"#,
        home = gpui_shell_quote(&home_directory),
        user_name = gpui_shell_quote(&user_name),
        user_id = gpui_shell_quote(&user_id),
        group_id = gpui_shell_quote(&group_id),
        ghostex_state_directory = gpui_shell_quote(&ghostex_state_directory),
        gxserver_directory = gpui_shell_quote(&gxserver_directory),
        portless_state_directory = gpui_shell_quote(&portless_state_directory),
        node_path = gpui_shell_quote(&gpui_path_string(&runtime.node_path)),
        portless_cli_path = gpui_shell_quote(&gpui_path_string(&runtime.portless_cli_path)),
    );
    let unique_suffix = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default();
    let script_path = env::temp_dir().join(format!(
        "ghostex-portless-admin-{}-{unique_suffix}.sh",
        std::process::id()
    ));
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&script_path)
        .ok()?;
    if file.write_all(script.as_bytes()).is_err() {
        let _ = fs::remove_file(&script_path);
        return None;
    }
    if fs::set_permissions(&script_path, fs::Permissions::from_mode(0o700)).is_err() {
        let _ = fs::remove_file(&script_path);
        return None;
    }
    Some(script_path)
}

#[cfg(target_os = "macos")]
fn gpui_portless_admin_commands(
    action: GpuiPortlessAdminAction,
    service_protocol: GpuiPortlessProtocol,
    runtime: &GpuiPortlessAdminRuntime,
    home_directory: &str,
    portless_state_directory: &str,
    user_id: &str,
    group_id: &str,
) -> String {
    match action {
        GpuiPortlessAdminAction::Install
        | GpuiPortlessAdminAction::Reconfigure
        | GpuiPortlessAdminAction::Retry => {
            let plist = gpui_portless_launchd_plist(
                service_protocol,
                runtime,
                home_directory,
                portless_state_directory,
                user_id,
                group_id,
            );
            let (proxy_port, trust_command) = match service_protocol {
                GpuiPortlessProtocol::Https => {
                    ("443", "run_portless_cli trust >/dev/null 2>&1 || true\n")
                }
                GpuiPortlessProtocol::Http => ("80", ""),
            };
            format!(
                r#"# CDXC:GPUIPortlessServiceInstall 2026-06-24-14:28:
# GPUI installs the Portless macOS LaunchDaemon with the same fixed root commands as the reviewed Swift helper. The daemon writes stdout/stderr to /dev/null and runs with PORTLESS_SYNC_HOSTS=0 so support bundles do not persist paths, hostnames, command/env values, or proxy output.
{trust_command}/bin/launchctl bootout system "$PLIST_PATH" >/dev/null 2>&1 || true
run_portless_cli proxy stop --port {proxy_port} >/dev/null 2>&1 || true
/bin/cat > "$PLIST_PATH" <<'EOF_PLIST'
{plist}
EOF_PLIST
/usr/sbin/chown root:wheel "$PLIST_PATH"
/bin/chmod 644 "$PLIST_PATH"
/bin/launchctl bootstrap system "$PLIST_PATH"
/bin/launchctl enable "system/$SERVICE_LABEL"
/bin/launchctl kickstart -k "system/$SERVICE_LABEL"
"#
            )
        }
        GpuiPortlessAdminAction::Remove => {
            r#"/bin/launchctl bootout system "$PLIST_PATH" >/dev/null 2>&1 || true
/bin/rm -f "$PLIST_PATH"
"#
            .to_string()
        }
    }
}

#[cfg(target_os = "macos")]
fn gpui_portless_launchd_plist(
    service_protocol: GpuiPortlessProtocol,
    runtime: &GpuiPortlessAdminRuntime,
    home_directory: &str,
    portless_state_directory: &str,
    user_id: &str,
    group_id: &str,
) -> String {
    let (port, https, protocol_flag) = match service_protocol {
        GpuiPortlessProtocol::Https => ("443", "1", "--https"),
        GpuiPortlessProtocol::Http => ("80", "0", "--no-tls"),
    };
    format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>sh.portless.proxy</string>
  <key>ProgramArguments</key>
  <array>
    <string>{node_path}</string>
    <string>{portless_cli_path}</string>
    <string>proxy</string>
    <string>start</string>
    <string>--foreground</string>
    <string>--port</string>
    <string>{port}</string>
    <string>{protocol_flag}</string>
    <string>--tld</string>
    <string>localhost</string>
    <string>--skip-trust</string>
  </array>
  <key>EnvironmentVariables</key>
  <dict>
    <key>HOME</key>
    <string>{home}</string>
    <key>SUDO_UID</key>
    <string>{user_id}</string>
    <key>SUDO_GID</key>
    <string>{group_id}</string>
    <key>PORTLESS_STATE_DIR</key>
    <string>{state_dir}</string>
    <key>PORTLESS_PORT</key>
    <string>{port}</string>
    <key>PORTLESS_HTTPS</key>
    <string>{https}</string>
    <key>PORTLESS_TLD</key>
    <string>localhost</string>
    <key>PORTLESS_LAN</key>
    <string>0</string>
    <key>PORTLESS_WILDCARD</key>
    <string>0</string>
    <key>PORTLESS_SYNC_HOSTS</key>
    <string>0</string>
  </dict>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <true/>
  <key>StandardOutPath</key>
  <string>/dev/null</string>
  <key>StandardErrorPath</key>
  <string>/dev/null</string>
</dict>
</plist>"#,
        node_path = gpui_xml_escape(&gpui_path_string(&runtime.node_path)),
        portless_cli_path = gpui_xml_escape(&gpui_path_string(&runtime.portless_cli_path)),
        home = gpui_xml_escape(home_directory),
        user_id = gpui_xml_escape(user_id),
        group_id = gpui_xml_escape(group_id),
        state_dir = gpui_xml_escape(portless_state_directory),
    )
}

#[cfg(target_os = "macos")]
fn gpui_run_privileged_portless_admin_script(script_path: &Path) -> GpuiPrivilegedScriptResult {
    let command = format!(
        "/bin/sh {}",
        gpui_shell_quote(&gpui_path_string(script_path))
    );
    let apple_script = format!(
        "do shell script {} with administrator privileges",
        gpui_applescript_string(&command)
    );
    let output = std::process::Command::new("/usr/bin/osascript")
        .arg("-e")
        .arg(apple_script)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .output();
    let Ok(output) = output else {
        return GpuiPrivilegedScriptResult {
            ok: false,
            exit_code: 127,
            status: "admin-launch-failed",
        };
    };
    let exit_code = output.status.code().unwrap_or(127);
    if output.status.success() {
        return GpuiPrivilegedScriptResult {
            ok: true,
            exit_code,
            status: "completed",
        };
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);
    let combined_output = stdout
        .chars()
        .chain(stderr.chars())
        .take(4096)
        .collect::<String>();
    GpuiPrivilegedScriptResult {
        ok: false,
        exit_code,
        status: gpui_portless_admin_failure_status(exit_code, &combined_output),
    }
}

struct GpuiPrivilegedScriptResult {
    ok: bool,
    exit_code: i32,
    status: &'static str,
}

#[cfg(target_os = "macos")]
fn gpui_portless_admin_failure_status(exit_code: i32, output: &str) -> &'static str {
    let normalized_output = output.to_lowercase();
    if normalized_output.contains("user canceled") || normalized_output.contains("user cancelled") {
        return "authorization-cancelled";
    }
    if exit_code == 91 {
        return "admin-required";
    }
    "portless-cli-failed"
}

#[cfg(target_os = "macos")]
fn gpui_portless_current_user_field(argument: &str) -> Option<String> {
    let output = std::process::Command::new("/usr/bin/id")
        .arg(argument)
        .stdin(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    String::from_utf8(output.stdout)
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

#[cfg(target_os = "macos")]
fn gpui_shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}

#[cfg(target_os = "macos")]
fn gpui_applescript_string(value: &str) -> String {
    format!("\"{}\"", value.replace('\\', "\\\\").replace('"', "\\\""))
}

#[cfg(target_os = "macos")]
fn gpui_xml_escape(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

fn gpui_update_portless_gxserver_state(
    update: GpuiPortlessStateUpdate,
) -> Result<serde_json::Value, String> {
    /*
    CDXC:GPUISettingsPortlessBridge 2026-06-24-11:48:
    Successful Portless state updates return canonical gxserver status and presentation metadata. Parse just enough of that response to refresh the shared app-modal `hud.portless` payload immediately, while transport/parser failures remain silent local `Result` values so unavailable gxserver cannot create fake success or roll back saved Settings.
    */
    let result = gpui_gxserver_rpc_result(
        "/api/updatePortlessState",
        &update.to_rpc_params(),
        Duration::from_secs(10),
    )?;
    gpui_sidebar_portless_state_from_update_result(&result)
        .ok_or_else(|| "gxserver returned invalid Portless state.".to_string())
}

fn gpui_sidebar_portless_state_from_update_result(
    result: &serde_json::Value,
) -> Option<serde_json::Value> {
    let status = result.get("status")?.as_object().cloned()?;
    let presentation = result.get("presentation")?.as_object().cloned()?;
    let health = serde_json::Value::Object(status.clone());
    Some(serde_json::json!({
        "health": health.clone(),
        "nativeAdmin": {
            "actions": gpui_portless_native_admin_actions(&health),
            "available": gpui_portless_native_admin_available(),
        },
        "presentation": serde_json::Value::Object(presentation),
    }))
}

fn gpui_sidebar_portless_state() -> Option<serde_json::Value> {
    /*
    CDXC:GPUIPortlessAdminBridge 2026-06-24-14:28:
    GPUI Settings hydration exposes privileged Portless admin actions only when this local macOS app bundle has the reviewed Web/code-server Node and Web/portless CLI runtime. Non-macOS, development binaries, incomplete bundles, and non-recommended actions stay unavailable rather than presenting fake setup capability.
    */
    let health = gpui_gxserver_server_health(Duration::from_millis(500)).ok()?;
    let portless = health.get("portless")?.clone();
    Some(serde_json::json!({
        "health": portless.clone(),
        "nativeAdmin": {
            "actions": gpui_portless_native_admin_actions(&portless),
            "available": gpui_portless_native_admin_available(),
        },
    }))
}

/// The setup-prompt gate needs `presentation.liveListenerCount`, which the
/// short health probe does not carry; macOS reads it from the startup
/// presentation snapshot (`createSidebarPortlessState`), so GPUI reads the
/// daemon's presentation snapshot the same way.
fn gpui_sidebar_portless_state_with_presentation() -> Option<serde_json::Value> {
    let mut state = gpui_sidebar_portless_state()?;
    let snapshot = gpui_read_gxserver_presentation_snapshot().ok()?;
    let presentation = snapshot.get("portless")?.clone();
    state["presentation"] = presentation;
    Some(state)
}

fn gpui_gxserver_server_health(timeout: Duration) -> Result<serde_json::Value, String> {
    let (status_code, body) = gxserver_get_typed_operation("/api/health/server", timeout)?;
    if !(200..300).contains(&status_code) {
        return Err(format!("gxserver health failed with HTTP {status_code}."));
    }
    serde_json::from_str::<serde_json::Value>(&body)
        .map_err(|_| "gxserver health returned invalid JSON.".to_string())
}

const GPUI_GXSERVER_DAEMON_TOAST_ID: &str = "toast-gxserver-daemon";
const GPUI_MISSING_MONACO_PROMPT_EDITOR_TOAST_ID: &str = "toast-monaco-prompt-editor-missing";
const GPUI_GXSERVER_EXPECTED_PRODUCT: &str = "gxserver";

enum GpuiLocalGxserverHealthState {
    Healthy { tools_available: bool },
    BuildMismatch,
    ProtocolMismatch { reported: Option<u64> },
    Unreachable,
}

/// Mirrors the macOS GxserverClient handshake: authenticated health, product
/// check, hard protocol-version and build-identity matches, and availability
/// of the tools shipped beside this GPUI build's gxserver binary.
fn gpui_probe_local_gxserver_health() -> GpuiLocalGxserverHealthState {
    let Ok(health) = gpui_gxserver_server_health(Duration::from_millis(1000)) else {
        return GpuiLocalGxserverHealthState::Unreachable;
    };
    if health.get("product").and_then(serde_json::Value::as_str)
        != Some(GPUI_GXSERVER_EXPECTED_PRODUCT)
    {
        return GpuiLocalGxserverHealthState::Unreachable;
    }
    let reported_protocol = health
        .get("protocolVersion")
        .and_then(serde_json::Value::as_u64);
    if reported_protocol != Some(GPUI_GXSERVER_PROTOCOL_VERSION) {
        return GpuiLocalGxserverHealthState::ProtocolMismatch {
            reported: reported_protocol,
        };
    }
    #[cfg(not(target_os = "windows"))]
    if let Some(expected_build_identity) = gpui_expected_local_gxserver_build_identity() {
        let reported_build_identity = health
            .get("buildIdentity")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty());
        if reported_build_identity != Some(expected_build_identity.as_str()) {
            return GpuiLocalGxserverHealthState::BuildMismatch;
        }
    }
    GpuiLocalGxserverHealthState::Healthy {
        tools_available: gpui_gxserver_required_tools_available(&health),
    }
}

#[cfg(not(target_os = "windows"))]
fn gpui_expected_local_gxserver_build_identity() -> Option<String> {
    let binary = gpui_resolve_local_gxserver_binary()?;
    let package_root = binary.parent()?.parent()?;
    let value: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(package_root.join("build-identity.json")).ok()?)
            .ok()?;
    value
        .get("buildIdentity")?
        .as_str()
        .map(str::trim)
        .filter(|identity| !identity.is_empty())
        .map(str::to_string)
}

/// A running app can outlive replacement of its app bundle during an update.
/// Reconcile that version skew at the durable Delayed Send command boundary so
/// the user's submission is persisted by the daemon that implements the
/// bundled contract instead of being accepted by the modal and rejected by an
/// obsolete control plane.
fn gpui_schedule_agents_delayed_send_with_current_gxserver_build(
    params: &serde_json::Value,
) -> Result<serde_json::Value, String> {
    if matches!(
        gpui_probe_local_gxserver_health(),
        GpuiLocalGxserverHealthState::BuildMismatch
    ) {
        gpui_restart_local_gxserver_for_current_build()?;
    }
    gpui_gxserver_rpc_result("/api/scheduleDelayedSend", params, Duration::from_secs(5))
}

fn gpui_restart_local_gxserver_for_current_build() -> Result<(), String> {
    let (status_code, _) = gxserver_post_typed_operation(
        "/api/control/stop",
        &serde_json::json!({}),
        Duration::from_secs(5),
    )?;
    if !(200..300).contains(&status_code) {
        return Err(format!("gxserver stop failed with HTTP {status_code}."));
    }

    let mut stopped = false;
    for _ in 0..20 {
        std::thread::sleep(Duration::from_millis(250));
        if matches!(
            gpui_probe_local_gxserver_health(),
            GpuiLocalGxserverHealthState::Unreachable
        ) {
            stopped = true;
            break;
        }
    }
    if !stopped {
        return Err("gxserver did not stop before its build update.".to_string());
    }

    let binary = gpui_resolve_local_gxserver_binary()
        .ok_or_else(|| "Bundled gxserver binary is missing.".to_string())?;
    gpui_spawn_local_gxserver_daemon(&binary)?;
    for _ in 0..40 {
        std::thread::sleep(Duration::from_millis(500));
        match gpui_probe_local_gxserver_health() {
            GpuiLocalGxserverHealthState::Healthy {
                tools_available: true,
            } => return Ok(()),
            GpuiLocalGxserverHealthState::Healthy {
                tools_available: false,
            } => {
                return Err(
                    "The current gxserver build is missing its required toolchain.".to_string(),
                );
            }
            GpuiLocalGxserverHealthState::ProtocolMismatch { .. } => {
                return Err("The current gxserver build has an incompatible protocol.".to_string());
            }
            GpuiLocalGxserverHealthState::BuildMismatch
            | GpuiLocalGxserverHealthState::Unreachable => {}
        }
    }
    Err("The current gxserver build did not become healthy in time.".to_string())
}

fn gpui_gxserver_required_tools_available(health: &serde_json::Value) -> bool {
    let Some(tools) = health.get("tools").and_then(serde_json::Value::as_array) else {
        return true;
    };
    // zmx is the one mandatory GPUI daemon companion.
    //
    // CDXC:AgentHistorySearch 2026-08-20: Zehn used to be gated here too,
    // because it was a separate bundled binary a build might not carry. It is
    // now a Rust crate compiled into gxserver, so every daemon that exists can
    // serve prompt-history search and there is nothing left to probe for.
    //
    // Beads is deliberately excluded. gxserver resolves `bd` from the user's
    // machine-installed Beads release (see `system_bd_tool_candidates`) and
    // never from the app bundle, so a missing `bd` reports the operator's
    // environment, not a stale daemon. Gating on it made a first launch on a
    // machine without Beads report "gxserver toolchain unavailable" and then
    // restart a perfectly healthy daemon on every later launch. Project board
    // surfaces already carry their own install guidance for that case.
    let required_tools = vec!["zmx"];
    #[cfg(target_os = "windows")]
    if matches!(
        windows_terminal_backend::resolve_current(),
        Ok(windows_terminal_backend::ResolvedWindowsTerminalBackend::Wsl { .. })
    ) {
        return required_tools.iter().all(|required| {
            tools.iter().any(|tool| {
                tool.get("tool").and_then(serde_json::Value::as_str) == Some(*required)
                    && tool.get("availability").and_then(serde_json::Value::as_str)
                        == Some("available")
            })
        });
    }
    required_tools.iter().all(|required| {
        tools.iter().any(|tool| {
            tool.get("tool").and_then(serde_json::Value::as_str) == Some(*required)
                && tool.get("availability").and_then(serde_json::Value::as_str) == Some("available")
        })
    })
}

/// Resolution order is explicit env selection, this app bundle's Resources,
/// then the GPUI-owned development runtime next to this crate. Only native
/// gxserver executables are launched.
fn gpui_resolve_local_gxserver_binary() -> Option<PathBuf> {
    for key in ["GHOSTEX_GXSERVER_CLI", "GHOSTEX_GXSERVER_BIN"] {
        if let Ok(value) = std::env::var(key) {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                let path = PathBuf::from(trimmed);
                if path.is_absolute() && gpui_is_executable_file(&path) {
                    return Some(path);
                }
                return None;
            }
        }
    }
    let mut candidates: Vec<PathBuf> = Vec::new();
    if let Ok(current_exe) = std::env::current_exe() {
        if let Some(contents_dir) = current_exe.parent().and_then(Path::parent) {
            candidates.push(contents_dir.join("Resources/Web/gxserver/bin/gxserver"));
        }
        // CDXC:GPUILinuxX11Backend 2026-07-05: the Linux app is a flat
        // CEF-conventional directory (scripts/build-linux-app.sh), so the
        // bundled gxserver package sits beside the executable instead of
        // under a macOS Contents/Resources tree.
        #[cfg(target_os = "linux")]
        if let Some(exe_dir) = current_exe.parent() {
            candidates.push(exe_dir.join("gxserver/bin/gxserver"));
        }
    }
    if let Some(repo_root) = Path::new(env!("CARGO_MANIFEST_DIR")).parent() {
        candidates.push(repo_root.join("gpui/runtime/macos/Web/gxserver/bin/gxserver"));
        // Linux dev runs resolve the package produced by
        // `bun gxserver-rs/package-remote-linux.mjs` before any packaging step.
        #[cfg(target_os = "linux")]
        {
            #[cfg(target_arch = "x86_64")]
            const GPUI_LINUX_GXSERVER_PACKAGE_ARCH: &str = "x64";
            #[cfg(target_arch = "aarch64")]
            const GPUI_LINUX_GXSERVER_PACKAGE_ARCH: &str = "arm64";
            candidates.push(repo_root.join(format!(
                "build/remote-gxserver-linux/{GPUI_LINUX_GXSERVER_PACKAGE_ARCH}/package/bin/gxserver"
            )));
        }
    }
    candidates
        .into_iter()
        .find(|candidate| gpui_is_executable_file(candidate))
}

/// The bundled zmx binary ships beside the bundled gxserver binary in every
/// GPUI package layout (`Resources/Web/gxserver/bin`, the Linux flat app
/// directory, and the development tree), so it resolves as a sibling of the
/// resolved gxserver executable. Mirrors macOS `nativeBundledZmxExecutablePath`.
fn gpui_resolve_local_zmx_binary() -> Option<PathBuf> {
    let gxserver = gpui_resolve_local_gxserver_binary()?;
    let candidate = gxserver.parent()?.join("zmx");
    gpui_is_executable_file(&candidate).then_some(candidate)
}

/*
CDXC:GPUIZmxPersistenceRefresh 2026-07-06:
Terminal-content clicks should repair a zmx session that another client
resized, but a click inside an already-correct pane must not repaint the
terminal because a repaint scrolls the view to the visible bottom. Mirror
macOS `nativeRunZmxRefreshIfStaleProcess`: run bundled
`zmx refresh-if-stale <name> <rows> <cols>` through zmx IPC outside the
terminal input/output path, on a background thread, with a one-second
deadline, discarding output.
*/
fn gpui_spawn_zmx_refresh_if_stale_process(
    session_name: Option<String>,
    grid_size: Option<(u16, u16)>,
    reason: &'static str,
) {
    let Some(session_name) = session_name.filter(|name| !name.trim().is_empty()) else {
        support_logs::append(
            support_logs::GpuiSupportLog::TerminalFocus,
            "gpui.zmxPersistenceViewportRefresh.ifStale",
            serde_json::json!({
                "didRequest": false,
                "reason": reason,
                "skipReason": "missingSessionName",
            }),
        );
        return;
    };
    let Some((rows, columns)) = grid_size.filter(|(rows, columns)| *rows > 0 && *columns > 0)
    else {
        support_logs::append(
            support_logs::GpuiSupportLog::TerminalFocus,
            "gpui.zmxPersistenceViewportRefresh.ifStale",
            serde_json::json!({
                "didRequest": false,
                "reason": reason,
                "skipReason": "invalidSurfaceSize",
            }),
        );
        return;
    };
    #[cfg(target_os = "windows")]
    {
        let Ok(windows_terminal_backend::ResolvedWindowsTerminalBackend::Wsl { distribution }) =
            windows_terminal_backend::resolve_current()
        else {
            support_logs::append(
                support_logs::GpuiSupportLog::TerminalFocus,
                "gpui.zmxPersistenceViewportRefresh.ifStale",
                serde_json::json!({
                    "didRequest": false,
                    "reason": reason,
                    "skipReason": "windowsPowerShellBackend",
                }),
            );
            return;
        };
        std::thread::spawn(move || {
            let spawned = windows_terminal_backend::spawn_zmx_refresh(
                distribution.as_str(),
                session_name.as_str(),
                rows,
                columns,
            );
            let Ok(child) = spawned else {
                gpui_record_zmx_refresh_launch_failure(rows, columns, reason);
                return;
            };
            gpui_monitor_zmx_refresh_process(child, rows, columns, reason);
        });
        return;
    }
    #[cfg(not(target_os = "windows"))]
    let Some(zmx_path) = gpui_resolve_local_zmx_binary() else {
        support_logs::append(
            support_logs::GpuiSupportLog::TerminalFocus,
            "gpui.zmxPersistenceViewportRefresh.ifStale",
            serde_json::json!({
                "didRequest": false,
                "reason": reason,
                "skipReason": "missingBundledZmx",
            }),
        );
        return;
    };
    #[cfg(not(target_os = "windows"))]
    std::thread::spawn(move || {
        let spawned = Command::new(&zmx_path)
            .args([
                "refresh-if-stale",
                session_name.as_str(),
                rows.to_string().as_str(),
                columns.to_string().as_str(),
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn();
        let Ok(child) = spawned else {
            gpui_record_zmx_refresh_launch_failure(rows, columns, reason);
            return;
        };
        gpui_monitor_zmx_refresh_process(child, rows, columns, reason);
    });
}

fn gpui_record_zmx_refresh_launch_failure(rows: u16, columns: u16, reason: &'static str) {
    support_logs::append(
        support_logs::GpuiSupportLog::TerminalFocus,
        "gpui.zmxPersistenceViewportRefresh.ifStale",
        serde_json::json!({
            "columns": columns,
            "didLaunch": false,
            "didRequest": true,
            "reason": reason,
            "rows": rows,
        }),
    );
}

fn gpui_monitor_zmx_refresh_process(
    mut child: std::process::Child,
    rows: u16,
    columns: u16,
    reason: &'static str,
) {
    let deadline = Instant::now() + Duration::from_secs(1);
    let mut timed_out = false;
    let mut exit_code: i32 = -1;
    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                exit_code = status.code().unwrap_or(-1);
                break;
            }
            Ok(None) => {
                if Instant::now() >= deadline {
                    timed_out = true;
                    let _ = child.kill();
                    let _ = child.wait();
                    break;
                }
                std::thread::sleep(Duration::from_millis(20));
            }
            Err(_) => break,
        }
    }
    support_logs::append(
        support_logs::GpuiSupportLog::TerminalFocus,
        "gpui.zmxPersistenceViewportRefresh.ifStale",
        serde_json::json!({
            "columns": columns,
            "didLaunch": true,
            "didRequest": true,
            "exitCode": exit_code,
            "reason": reason,
            "rows": rows,
            "timedOut": timed_out,
        }),
    );
}

fn gpui_gxserver_launch_log_path() -> PathBuf {
    shared_settings::ghostex_storage_paths()
        .logs_dir
        .join("gxserver")
        .join("macos-launch.log")
}

fn gpui_normalized_user_tool_path(current_path: Option<&str>) -> String {
    /*
    CDXC:GPUIUserToolPathEntries 2026-07-24:
    Keep the normal user tool locations used by the GPUI process and its local
    daemon bootstrap in one place. Packaged macOS apps otherwise inherit a
    sparse LaunchServices PATH that cannot see Homebrew-installed Ghostex tools.
    */
    let home = env::var("HOME")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let mut entries = vec![
        "/opt/homebrew/bin".to_string(),
        "/opt/homebrew/sbin".to_string(),
        "/usr/local/bin".to_string(),
        "/usr/local/sbin".to_string(),
    ];
    if let Some(home) = home.as_deref() {
        entries.extend([
            format!("{home}/.volta/bin"),
            format!("{home}/.local/share/mise/shims"),
            format!("{home}/.local/bin"),
            format!("{home}/.asdf/shims"),
            format!("{home}/.nodenv/shims"),
        ]);
    }
    entries.extend([
        "/usr/bin".to_string(),
        "/bin".to_string(),
        "/usr/sbin".to_string(),
        "/sbin".to_string(),
    ]);
    if let Some(current_path) = current_path {
        entries.extend(current_path.split(':').map(str::to_string));
    }

    let mut seen = HashSet::new();
    entries
        .into_iter()
        .map(|entry| entry.trim().to_string())
        .filter(|entry| !entry.is_empty() && seen.insert(entry.clone()))
        .collect::<Vec<_>>()
        .join(":")
}

/// The gxserver launchd agent label is client-agnostic on purpose: one
/// per-user gxserver serves the Swift app, GPUI, and the CLI, so whichever
/// client bootstraps it owns the same job definition.
#[cfg(target_os = "macos")]
const GPUI_GXSERVER_LAUNCH_AGENT_LABEL: &str = "com.madda.ghostex.gxserver";

#[cfg(target_os = "macos")]
fn gpui_launchd_plist_xml_escape(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

/*
CDXC:GPUIGxserverLaunchdJob 2026-07-10:
macOS 27 attributes app-spawned processes that outlive the app to the app's
Background Task Management identity, and the Dock then renders the dim
"Running in Background" indicator instead of the normal running dot even
while the app is open. Registered launchd jobs carry their own BTM identity
(the TeamViewer_Service and sh.portless.proxy precedents), so the persistent
gxserver daemon -- and every zmx/node process it goes on to spawn -- must
enter the user session as a launchd agent instead of a detached nohup child
of the GPUI process. launchd starts the job with a clean environment, which
also covers the color-blocker and session-identity stripping the nohup path
performed; CLICOLOR mirrors terminal_environment's color opt-in.
*/
#[cfg(target_os = "macos")]
fn gpui_spawn_local_gxserver_daemon(binary: &Path) -> Result<(), String> {
    const LAUNCH_FAILURE: &str = "gxserver failed to launch.";
    let Some(binary_path) = binary.to_str() else {
        return Err(LAUNCH_FAILURE.to_string());
    };
    let launch_log = gpui_gxserver_launch_log_path();
    if let Some(parent) = launch_log.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let Some(launch_log_path) = launch_log.to_str() else {
        return Err(LAUNCH_FAILURE.to_string());
    };
    let home = env::var("HOME")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| LAUNCH_FAILURE.to_string())?;
    let agents_dir = PathBuf::from(&home).join("Library/LaunchAgents");
    std::fs::create_dir_all(&agents_dir).map_err(|_| LAUNCH_FAILURE.to_string())?;
    let plist_path = agents_dir.join(format!("{GPUI_GXSERVER_LAUNCH_AGENT_LABEL}.plist"));

    let current_path = env::var("PATH").ok();
    let mut environment_entries = vec![
        (
            "PATH".to_string(),
            gpui_normalized_user_tool_path(current_path.as_deref()),
        ),
        ("CLICOLOR".to_string(), "1".to_string()),
    ];
    for variable in [
        "GHOSTEX_HOME",
        "XDG_CONFIG_HOME",
        "XDG_DATA_HOME",
        "XDG_STATE_HOME",
        "XDG_CACHE_HOME",
        "XDG_RUNTIME_DIR",
    ] {
        if let Some(value) = env::var(variable)
            .ok()
            .map(|value| value.trim().to_string())
            .filter(|value| Path::new(value).is_absolute())
        {
            environment_entries.push((variable.to_string(), value));
        }
    }
    let environment_xml = environment_entries
        .iter()
        .map(|(key, value)| {
            format!(
                "\t\t<key>{}</key>\n\t\t<string>{}</string>\n",
                gpui_launchd_plist_xml_escape(key),
                gpui_launchd_plist_xml_escape(value),
            )
        })
        .collect::<String>();
    // RunAtLoad stays false so the daemon keeps its on-demand lifecycle:
    // loading the job at login must not start gxserver; only an explicit
    // kickstart from a client that found it unreachable does.
    let plist = format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
	<key>Label</key>
	<string>{label}</string>
	<key>ProgramArguments</key>
	<array>
		<string>{binary}</string>
		<string>--foreground</string>
	</array>
	<key>EnvironmentVariables</key>
	<dict>
{environment_xml}	</dict>
	<key>RunAtLoad</key>
	<false/>
	<key>KeepAlive</key>
	<false/>
	<key>ProcessType</key>
	<string>Interactive</string>
	<key>StandardOutPath</key>
	<string>{launch_log}</string>
	<key>StandardErrorPath</key>
	<string>{launch_log}</string>
</dict>
</plist>
"#,
        label = gpui_launchd_plist_xml_escape(GPUI_GXSERVER_LAUNCH_AGENT_LABEL),
        binary = gpui_launchd_plist_xml_escape(binary_path),
        environment_xml = environment_xml,
        launch_log = gpui_launchd_plist_xml_escape(launch_log_path),
    );
    std::fs::write(&plist_path, plist).map_err(|_| LAUNCH_FAILURE.to_string())?;

    let uid_output = std::process::Command::new("/usr/bin/id")
        .arg("-u")
        .output()
        .map_err(|_| LAUNCH_FAILURE.to_string())?;
    let uid = String::from_utf8_lossy(&uid_output.stdout)
        .trim()
        .to_string();
    if uid.is_empty() {
        return Err(LAUNCH_FAILURE.to_string());
    }
    let job_target = format!("gui/{uid}/{GPUI_GXSERVER_LAUNCH_AGENT_LABEL}");
    let domain_target = format!("gui/{uid}");

    let run_launchctl = |arguments: &[&str]| -> bool {
        std::process::Command::new("/bin/launchctl")
            .args(arguments)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .map(|status| status.success())
            .unwrap_or(false)
    };
    // This path only runs when the daemon health probe reported unreachable,
    // so removing a stale or hung job definition before loading the fresh
    // plist (whose binary path changes across app versions) is safe.
    let _ = run_launchctl(&["bootout", &job_target]);
    let bootstrapped = run_launchctl(&["bootstrap", &domain_target, &plist_path.to_string_lossy()]);
    // A concurrent client may have loaded the same label between the bootout
    // and bootstrap (making bootstrap fail) or already started the job
    // (making kickstart report already-active), so either success signal
    // means the job is loaded; the caller's health-probe loop owns the
    // final running/not-running verdict.
    let kickstarted = run_launchctl(&["kickstart", &job_target]);
    support_logs::append(
        support_logs::GpuiSupportLog::HostLifecycle,
        "gpui.gxserverBootstrap.launchdAgent",
        serde_json::json!({
            "bootstrapped": bootstrapped,
            "kickstarted": kickstarted,
        }),
    );
    if !bootstrapped && !kickstarted {
        return Err(LAUNCH_FAILURE.to_string());
    }
    Ok(())
}

/// Launches the daemon exactly like the macOS client used to: a
/// shell-detached `nohup <gxserver> --foreground` so the process is
/// app-independent and survives quitting Ghostex. The app never retains the
/// child as ownership. (Linux has no Dock background-attribution concern, so
/// the detached-child launch remains correct there.)
#[cfg(target_os = "linux")]
fn gpui_spawn_local_gxserver_daemon(binary: &Path) -> Result<(), String> {
    let Some(binary_path) = binary.to_str() else {
        return Err("gxserver failed to launch.".to_string());
    };
    let launch_log = gpui_gxserver_launch_log_path();
    if let Some(parent) = launch_log.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let Some(launch_log_path) = launch_log.to_str() else {
        return Err("gxserver failed to launch.".to_string());
    };
    let command = format!(
        "nohup {} --foreground >>{} 2>&1 </dev/null &",
        gpui_shell_single_quote(binary_path),
        gpui_shell_single_quote(launch_log_path),
    );
    let mut shell = std::process::Command::new("/bin/sh");
    terminal_environment::apply_color_capable_process_command(&mut shell);
    terminal_environment::remove_session_identity_from_process_command(&mut shell);
    let current_path = env::var("PATH").ok();
    shell.env(
        "PATH",
        gpui_normalized_user_tool_path(current_path.as_deref()),
    );
    let status = shell
        .arg("-c")
        .arg(&command)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .map_err(|_| "gxserver failed to launch.".to_string())?;
    if !status.success() {
        return Err("gxserver failed to launch.".to_string());
    }
    Ok(())
}

#[cfg(target_os = "windows")]
fn gpui_spawn_local_gxserver_daemon(binary: &Path) -> Result<(), String> {
    use std::os::windows::process::CommandExt;

    const CREATE_NEW_PROCESS_GROUP: u32 = 0x0000_0200;
    const DETACHED_PROCESS: u32 = 0x0000_0008;
    const CREATE_NO_WINDOW: u32 = 0x0800_0000;
    let launch_log = gpui_gxserver_launch_log_path();
    if let Some(parent) = launch_log.parent() {
        std::fs::create_dir_all(parent).map_err(|_| "gxserver failed to launch.".to_string())?;
    }
    let stdout = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&launch_log)
        .map_err(|_| "gxserver failed to launch.".to_string())?;
    let stderr = stdout
        .try_clone()
        .map_err(|_| "gxserver failed to launch.".to_string())?;
    let mut command = std::process::Command::new(binary);
    terminal_environment::apply_color_capable_process_command(&mut command);
    terminal_environment::remove_session_identity_from_process_command(&mut command);
    command
        .arg("--foreground")
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::from(stdout))
        .stderr(std::process::Stdio::from(stderr))
        .creation_flags(CREATE_NEW_PROCESS_GROUP | DETACHED_PROCESS | CREATE_NO_WINDOW)
        .spawn()
        .map_err(|_| "gxserver failed to launch.".to_string())?;
    Ok(())
}

/// Last few launch-log lines so a startup-timeout toast can say why, matching
/// the macOS client's recentGxserverLaunchOutput.
fn gpui_recent_gxserver_launch_output() -> Option<String> {
    let text = std::fs::read_to_string(gpui_gxserver_launch_log_path()).ok()?;
    let lines = text
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>();
    if lines.is_empty() {
        return None;
    }
    let start = lines.len().saturating_sub(6);
    Some(lines[start..].join(" "))
}

fn gpui_gxserver_protocol_mismatch_message(reported: Option<u64>) -> String {
    format!(
        "gxserver protocol mismatch. Expected protocol {GPUI_GXSERVER_PROTOCOL_VERSION}, got {}. Update Ghostex and gxserver so their protocol versions match.",
        reported.map_or_else(|| "none".to_string(), |version| version.to_string()),
    )
}

fn gpui_portless_state_with_admin_result(
    mut portless_state: serde_json::Value,
    result: &GpuiPortlessAdminResult,
) -> serde_json::Value {
    if let Some(native_admin) = portless_state
        .get_mut("nativeAdmin")
        .and_then(serde_json::Value::as_object_mut)
    {
        native_admin.insert("lastResult".to_string(), result.message());
    }
    portless_state
}

fn gpui_portless_native_admin_available() -> bool {
    gpui_resolve_portless_admin_runtime().is_some()
}

fn gpui_portless_native_admin_actions(health: &serde_json::Value) -> serde_json::Value {
    let is_local_mac = gpui_portless_native_admin_available();
    let recommended_action = gpui_recommended_portless_native_admin_action(health);
    let setup_ownership = health
        .get("setupOwnership")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("unknown");
    let mut actions = serde_json::Map::new();
    for action in [
        GpuiPortlessAdminAction::Install,
        GpuiPortlessAdminAction::Reconfigure,
        GpuiPortlessAdminAction::Retry,
        GpuiPortlessAdminAction::Remove,
    ] {
        let available = is_local_mac
            && (Some(action) == recommended_action
                || (action == GpuiPortlessAdminAction::Remove && setup_ownership == "ghostex"));
        let unavailable_reason = if available {
            None
        } else if !is_local_mac {
            Some("localMacOnly")
        } else if action == GpuiPortlessAdminAction::Remove && setup_ownership != "ghostex" {
            Some("setupNotGhostexOwned")
        } else {
            Some("notRecommended")
        };
        let mut action_state = serde_json::Map::new();
        action_state.insert(
            "action".to_string(),
            serde_json::Value::String(action.as_str().to_string()),
        );
        action_state.insert("available".to_string(), serde_json::Value::Bool(available));
        if let Some(unavailable_reason) = unavailable_reason {
            action_state.insert(
                "unavailableReason".to_string(),
                serde_json::Value::String(unavailable_reason.to_string()),
            );
        }
        actions.insert(
            action.as_str().to_string(),
            serde_json::Value::Object(action_state),
        );
    }
    serde_json::Value::Object(actions)
}

fn gpui_recommended_portless_native_admin_action(
    health: &serde_json::Value,
) -> Option<GpuiPortlessAdminAction> {
    let enabled = health
        .get("enabled")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let setup_status = health
        .get("setupStatus")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("unknown");
    let setup_ownership = health
        .get("setupOwnership")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("unknown");
    if !enabled || setup_status == "disabled" {
        return None;
    }
    if setup_ownership == "missing" && setup_status == "needed" {
        return Some(GpuiPortlessAdminAction::Install);
    }
    if (setup_ownership == "ghostex" || setup_ownership == "standalone") && setup_status == "needed"
    {
        return Some(GpuiPortlessAdminAction::Reconfigure);
    }
    if setup_ownership == "ghostex" && setup_status == "failed" {
        return Some(GpuiPortlessAdminAction::Retry);
    }
    None
}

fn gpui_settings_portless_enabled(settings: &serde_json::Map<String, serde_json::Value>) -> bool {
    GPUI_PORTLESS_APP_INTEGRATION_ENABLED
        && settings
            .get("portlessEnabled")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true)
}

fn gpui_settings_portless_protocol(
    settings: &serde_json::Map<String, serde_json::Value>,
) -> GpuiPortlessProtocol {
    settings
        .get("portlessProtocol")
        .and_then(serde_json::Value::as_str)
        .and_then(gpui_portless_protocol)
        .unwrap_or(GpuiPortlessProtocol::Https)
}

fn gpui_portless_protocol(value: &str) -> Option<GpuiPortlessProtocol> {
    match value {
        "http" => Some(GpuiPortlessProtocol::Http),
        "https" => Some(GpuiPortlessProtocol::Https),
        _ => None,
    }
}

fn gpui_portless_admin_action(value: &str) -> Option<GpuiPortlessAdminAction> {
    match value {
        "install" => Some(GpuiPortlessAdminAction::Install),
        "reconfigure" => Some(GpuiPortlessAdminAction::Reconfigure),
        "retry" => Some(GpuiPortlessAdminAction::Retry),
        "remove" => Some(GpuiPortlessAdminAction::Remove),
        _ => None,
    }
}

/*
CDXC:GPUISettingsMetadata 2026-06-24-12:19:
The GPUI app-modal write bridge validates bounded Settings agent/action messages from CEF, while read hydration comes from gxserver's `/api/readSidebarHud` contract instead of app-modal Rust reimplementing the custom launcher/action projection.

CDXC:SidebarHudSettingsMutation 2026-06-24-20:54:
Agent/action Settings writes now persist through gxserver's `/api/mutateSidebarHudSettings` contract. Keep this parser as a shape/type boundary only; do not mutate custom agent/action project metadata locally or log launcher commands, URLs, project names, paths, prompts, tokens, stdout/stderr, daemon bodies, or renderer payload contents.
*/
#[derive(Clone, Copy)]
struct GpuiDefaultSidebarAgent {
    agent_id: &'static str,
    command: &'static str,
    hidden_by_default: bool,
    icon: &'static str,
    name: &'static str,
}

#[derive(Clone, Debug)]
struct GpuiStoredSidebarAgent {
    accept_all_mode: Option<String>,
    agent_id: String,
    command: String,
    hidden: bool,
    icon: Option<String>,
    name: String,
}

#[derive(Clone, Copy)]
struct GpuiDefaultSidebarCommand {
    command_id: &'static str,
    name: &'static str,
}

#[derive(Clone, Debug)]
struct GpuiStoredSidebarCommand {
    action_type: &'static str,
    close_terminal_on_exit: bool,
    command: Option<String>,
    command_id: String,
    icon: Option<String>,
    is_default: bool,
    name: String,
    play_completion_sound: bool,
    show_on_project_row: bool,
    url: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GpuiTitlebarActionType {
    Browser,
    Terminal,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GpuiTitlebarActionRunMode {
    Default,
    Debug,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GpuiTitlebarActionLinkTarget {
    External,
    Integrated,
}

/*
CDXC:ProjectActions 2026-07-31-12:00:
Terminal Actions can carry saved links that open alongside the command run, so a
dev-server Action starts the server and surfaces its localhost URL in one click.
Each link targets the project's integrated Browser tab or the OS default browser.
*/
#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiTitlebarActionLink {
    target: GpuiTitlebarActionLinkTarget,
    url: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiTitlebarAction {
    action_type: GpuiTitlebarActionType,
    close_terminal_on_exit: bool,
    command: Option<String>,
    command_id: String,
    icon: Option<String>,
    links: Vec<GpuiTitlebarActionLink>,
    name: String,
    play_completion_sound: bool,
    run_mode: GpuiTitlebarActionRunMode,
    url: Option<String>,
}

impl GpuiTitlebarAction {
    fn is_configured(&self) -> bool {
        match self.action_type {
            GpuiTitlebarActionType::Browser => self
                .url
                .as_deref()
                .and_then(|url| gpui_trimmed_nonempty_str(Some(url)))
                .is_some(),
            GpuiTitlebarActionType::Terminal => self
                .command
                .as_deref()
                .and_then(|command| gpui_trimmed_nonempty_str(Some(command)))
                .is_some(),
        }
    }

    fn menu_label(&self) -> String {
        self.action_title()
            .unwrap_or_else(|| self.command_id.clone())
    }

    fn titlebar_menu_name(&self) -> String {
        gpui_normalized_sidebar_command_title(Some(&self.name))
            .unwrap_or_else(|| self.command_id.clone())
    }

    fn titlebar_menu_preview(&self) -> (String, bool) {
        let preview = match self.action_type {
            GpuiTitlebarActionType::Browser => self
                .url
                .as_deref()
                .and_then(|url| gpui_trimmed_nonempty_str(Some(url))),
            GpuiTitlebarActionType::Terminal => self
                .command
                .as_deref()
                .and_then(|command| gpui_trimmed_nonempty_str(Some(command))),
        };
        preview
            .map(|preview| (preview.to_string(), false))
            .unwrap_or_else(|| (TITLEBAR_ACTION_UNCONFIGURED_PREVIEW.to_string(), true))
    }

    fn command_title(&self) -> String {
        /*
        CDXC:GPUICommandPane 2026-06-25-11:42:
        Command-pane Action tabs must use the same visible title rule as macOS: normalized Action name first, otherwise the normalized command text truncated to 20 characters. Do not substitute command ids for unnamed terminal Actions because title-owned reuse and duplicate-title checks depend on this user-facing Action title.
        */
        gpui_normalized_sidebar_command_title(Some(&self.name))
            .or_else(|| {
                gpui_normalized_sidebar_command_title(self.command.as_deref())
                    .map(gpui_sidebar_command_short_title)
            })
            .unwrap_or_else(|| self.command_id.clone())
    }

    fn action_title(&self) -> Option<String> {
        gpui_normalized_sidebar_command_title(Some(&self.name)).or_else(|| {
            match self.action_type {
                GpuiTitlebarActionType::Browser => self.url.as_deref(),
                GpuiTitlebarActionType::Terminal => self.command.as_deref(),
            }
            .and_then(|target| {
                gpui_normalized_sidebar_command_title(Some(target))
                    .map(gpui_sidebar_command_short_title)
            })
        })
    }
}

const GPUI_SIDEBAR_METADATA_GENERIC_ERROR: &str = "sidebar metadata write failed";
const GPUI_SIDEBAR_DUPLICATE_ACTION_TITLE_ERROR: &str = "duplicate action title";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GpuiSidebarMetadataWriteKind {
    Agents,
    Commands,
}

impl GpuiSidebarMetadataWriteKind {
    fn failure_message(self) -> &'static str {
        match self {
            Self::Agents => "GPUI could not save the Agents settings.",
            Self::Commands => "GPUI could not save the Actions settings.",
        }
    }
}

#[derive(Clone, Debug)]
enum GpuiAgentAcceptAllModeUpdate {
    Preserve,
    Set(Option<String>),
}

#[derive(Clone, Debug)]
enum GpuiSidebarAgentMetadataWrite {
    Save {
        accept_all_mode: GpuiAgentAcceptAllModeUpdate,
        agent_id: Option<String>,
        command: String,
        icon: Option<String>,
        name: String,
    },
    Delete {
        agent_id: String,
    },
    SyncOrder {
        agent_ids: Vec<String>,
        request_id: String,
    },
}

impl GpuiSidebarAgentMetadataWrite {
    fn order_sync_result(
        &self,
        status: &'static str,
        item_ids: Vec<String>,
    ) -> Option<serde_json::Value> {
        match self {
            Self::SyncOrder { request_id, .. } => Some(gpui_sidebar_order_sync_result_message(
                "agent", request_id, status, item_ids,
            )),
            _ => None,
        }
    }
}

/*
CDXC:GlobalActions 2026-08-01-19:00:
Settings > Actions writes reach gxserver through this Rust path, not through the
sidebar TypeScript runtime, so Global Actions need their own scope here or the
message is parsed as a project write. Scope only selects the mutation target;
the payload and every validation rule stay identical between the two lists.
*/
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GpuiSidebarCommandScope {
    Global,
    Project,
}

impl GpuiSidebarCommandScope {
    fn mutation_target(self) -> &'static str {
        match self {
            Self::Global => "globalCommand",
            Self::Project => "command",
        }
    }
}

#[derive(Clone, Debug)]
enum GpuiSidebarCommandMetadataWrite {
    Save {
        action_type: &'static str,
        active_project_id: String,
        close_terminal_on_exit: bool,
        command: Option<String>,
        command_id: Option<String>,
        icon: Option<String>,
        name: String,
        play_completion_sound: bool,
        scope: GpuiSidebarCommandScope,
        show_on_project_row: bool,
        url: Option<String>,
    },
    Delete {
        active_project_id: String,
        command_id: String,
        scope: GpuiSidebarCommandScope,
    },
    SyncOrder {
        active_project_id: String,
        command_ids: Vec<String>,
        request_id: String,
        scope: GpuiSidebarCommandScope,
    },
}

impl GpuiSidebarCommandMetadataWrite {
    fn scope(&self) -> GpuiSidebarCommandScope {
        match self {
            Self::Save { scope, .. }
            | Self::Delete { scope, .. }
            | Self::SyncOrder { scope, .. } => *scope,
        }
    }
}

impl GpuiSidebarCommandMetadataWrite {
    fn order_sync_result(
        &self,
        status: &'static str,
        item_ids: Vec<String>,
    ) -> Option<serde_json::Value> {
        match self {
            Self::SyncOrder { request_id, .. } => Some(gpui_sidebar_order_sync_result_message(
                "command", request_id, status, item_ids,
            )),
            _ => None,
        }
    }

    fn deleted_command_id(&self) -> Option<&str> {
        match self {
            Self::Delete { command_id, .. } => Some(command_id.as_str()),
            _ => None,
        }
    }
}

