fn append_url_query_params(mut url: String, params: &[(&str, String)]) -> String {
    if params.is_empty() {
        return url;
    }
    url.push(if url.contains('?') { '&' } else { '?' });
    for (index, (key, value)) in params.iter().enumerate() {
        if index > 0 {
            url.push('&');
        }
        url.push_str(&encode_search_query(key));
        url.push('=');
        url.push_str(&encode_search_query(value));
    }
    url
}

fn append_url_query_params_with_percent_encoded_spaces(
    mut url: String,
    params: &[(&str, String)],
) -> String {
    if params.is_empty() {
        return url;
    }
    url.push(if url.contains('?') { '&' } else { '?' });
    for (index, (key, value)) in params.iter().enumerate() {
        if index > 0 {
            url.push('&');
        }
        url.push_str(&encode_search_query(key).replace('+', "%20"));
        url.push('=');
        url.push_str(&encode_search_query(value).replace('+', "%20"));
    }
    url
}

fn source_code_server_runtime_target_from_project_snapshot(
    snapshot: &GpuiProjectSnapshot,
    endpoint: SourceCodeServerRuntimeEndpoint,
) -> Option<SourceCodeServerRuntimeTarget> {
    /*
    CDXC:GPUISourceRuntime 2026-06-24-23:17:
    Source folder URLs are authorized only from the strict in-memory sidebar project snapshot: explicit project id, Source workarea id, project path, and Source availability. This mirrors the macOS sidebar's `createCodeServerProjectEditorUrl(project.path)` contract without accepting renderer URLs, filesystem probes, fallback localhost strings, or persisted project facts.
    */
    if !snapshot.feature_availability.source || snapshot.is_quick_projectless {
        return None;
    }
    let active_project_id = snapshot.active_project_id.as_ref()?.clone();
    let source_workarea_id = snapshot.surface_ids.source_workarea_id.as_ref()?.clone();
    let project_path = snapshot.in_memory_project_path.as_ref()?.clone();
    Some(SourceCodeServerRuntimeTarget {
        active_project_id,
        source_workarea_id,
        project_path,
        endpoint,
    })
}

fn source_code_server_runtime_url(
    runtime_origin: &str,
    project_path: &Path,
) -> Option<ProjectWorkareaRealRuntimeUrl> {
    ProjectWorkareaRealRuntimeUrl::from_authorized_runtime_url(append_url_query_params(
        format!("{}/", runtime_origin.trim_end_matches('/')),
        &[("folder", gpui_path_string(project_path))],
    ))
}

fn source_code_server_start_runtime_for_target(
    target: SourceCodeServerRuntimeTarget,
    settings: SourceCodeServerRuntimeSettings,
    startup_deadline: Instant,
) -> Result<
    (
        SourceCodeServerRuntimeTarget,
        SourceCodeServerRuntimeSettings,
        SourceCodeServerRuntimeStartOutput,
    ),
    (
        SourceCodeServerRuntimeTarget,
        SourceCodeServerRuntimeSettings,
        String,
    ),
> {
    let result = source_code_server_spawn_runtime(&target, &settings, startup_deadline);
    match result {
        Ok(output) => Ok((target, settings, output)),
        Err(message) => Err((target, settings, message)),
    }
}

#[cfg(not(target_os = "windows"))]
fn source_code_server_spawn_runtime(
    target: &SourceCodeServerRuntimeTarget,
    settings: &SourceCodeServerRuntimeSettings,
    startup_deadline: Instant,
) -> Result<SourceCodeServerRuntimeStartOutput, String> {
    if matches!(
        target.endpoint,
        SourceCodeServerRuntimeEndpoint::Remote { .. }
    ) {
        #[cfg(target_os = "macos")]
        return source_code_server_spawn_remote_runtime(target, startup_deadline);
        #[cfg(not(target_os = "macos"))]
        return Err(
            "Remote Source runtime is available only from the macOS SSH owner.".to_string(),
        );
    }
    if source_code_server_health_check() {
        let remaining = startup_deadline.saturating_duration_since(Instant::now());
        let _ = source_code_server_wait_until_not_responsive(
            SOURCE_CODE_SERVER_PORT_BUSY_WAIT_INTERVAL.min(remaining),
        );
    }

    let repo_root = source_code_server_resolve_repo_root()?;
    let entrypoint = repo_root.join("out/node/entry.js");
    let node_path = source_code_server_resolve_node_path(&repo_root)?;
    let (user_data_dir, extensions_dir) = source_code_server_runtime_storage()?;
    if source_code_server_should_seed_default_theme(settings) {
        source_code_server_ensure_default_theme(&user_data_dir)?;
    }
    if Instant::now() >= startup_deadline {
        return Err("Source runtime startup timed out".to_string());
    }

    let mut command = Command::new(&node_path);
    command
        .arg(&entrypoint)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .current_dir(&target.project_path)
        .envs(source_code_server_runtime_environment(&repo_root));
    if let Some(vscode_user_config_dir) = settings.linked_vscode_user_config_dir() {
        command
            .arg("--link-vscode-user-config")
            .arg("--vscode-user-config-dir")
            .arg(vscode_user_config_dir);
    }
    command
        .arg("--auth")
        .arg("none")
        .arg("--bind-addr")
        .arg(format!(
            "{}:{}",
            SOURCE_CODE_SERVER_EDITOR_HOST, SOURCE_CODE_SERVER_EDITOR_PORT
        ))
        .arg("--disable-telemetry")
        .arg("--disable-update-check")
        .arg("--disable-workspace-trust")
        .arg("--disable-getting-started-override")
        .arg("--ignore-last-opened")
        .arg("--app-name")
        .arg("ghostex Code")
        .arg("--user-data-dir")
        .arg(&user_data_dir)
        .arg("--extensions-dir")
        .arg(&extensions_dir);

    let started_at = Instant::now();
    let child = command
        .spawn()
        .map_err(|_| "failed to start Source runtime".to_string())?;
    let readiness = source_code_server_wait_until_responsive(
        startup_deadline.saturating_duration_since(Instant::now()),
    );
    Ok(SourceCodeServerRuntimeStartOutput {
        child,
        runtime_origin: SOURCE_CODE_SERVER_EDITOR_ORIGIN.to_string(),
        prompt_editor_ipc_ready: readiness.prompt_editor_ipc_ready,
        started_at,
        http_runtime_ready: readiness.http_runtime_ready,
    })
}

#[cfg(target_os = "windows")]
fn source_code_server_spawn_runtime(
    target: &SourceCodeServerRuntimeTarget,
    settings: &SourceCodeServerRuntimeSettings,
    startup_deadline: Instant,
) -> Result<SourceCodeServerRuntimeStartOutput, String> {
    /*
    CDXC:GPUISourceWindowsWsl 2026-07-26:
    Windows projects and their authoritative paths live inside the selected
    WSL2 distribution. Launch code-server there as well; a native Windows
    Node child cannot use the WSL project path or the Linux runtime payload.
    The packaged Linux runtime is activated in WSL during startup; project and
    launch parameters cross the boundary as argv values, while the fixed WSL
    script owns Linux storage, environment, and working-directory setup.
    */
    if source_code_server_health_check() {
        let remaining = startup_deadline.saturating_duration_since(Instant::now());
        let _ = source_code_server_wait_until_not_responsive(
            SOURCE_CODE_SERVER_PORT_BUSY_WAIT_INTERVAL.min(remaining),
        );
    }

    if Instant::now() >= startup_deadline {
        return Err("Source runtime startup timed out".to_string());
    }
    let bind_address = format!(
        "{}:{}",
        SOURCE_CODE_SERVER_EDITOR_HOST, SOURCE_CODE_SERVER_EDITOR_PORT
    );
    let mut command = windows_terminal_backend::source_code_server_command(
        &target.project_path,
        SOURCE_CODE_SERVER_DEFAULT_NODE_MAJOR,
        &bind_address,
        settings.link_vscode_user_config,
        settings.use_vscode_insiders_user_config,
    )?;
    command
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());

    let started_at = Instant::now();
    let child = command
        .spawn()
        .map_err(|_| "failed to start Source runtime in WSL".to_string())?;
    let readiness = source_code_server_wait_until_responsive(
        startup_deadline.saturating_duration_since(Instant::now()),
    );
    Ok(SourceCodeServerRuntimeStartOutput {
        child,
        runtime_origin: SOURCE_CODE_SERVER_EDITOR_ORIGIN.to_string(),
        prompt_editor_ipc_ready: readiness.prompt_editor_ipc_ready,
        started_at,
        http_runtime_ready: readiness.http_runtime_ready,
    })
}

#[cfg(target_os = "macos")]
fn source_code_server_spawn_remote_runtime(
    target: &SourceCodeServerRuntimeTarget,
    startup_deadline: Instant,
) -> Result<SourceCodeServerRuntimeStartOutput, String> {
    let SourceCodeServerRuntimeEndpoint::Remote {
        component_platform,
        execution_target,
        machine_config,
        ..
    } = &target.endpoint
    else {
        return Err("Remote Source runtime target is invalid.".to_string());
    };
    let store = on_demand_component_store()?
        .ok_or_else(|| "The sealed code-server component manifest is unavailable.".to_string())?;
    let installed =
        store.query_current_for_platform(SOURCE_CODE_SERVER_COMPONENT_NAME, component_platform)?;
    if !installed.installed {
        return Err("The Linux code-server component is not installed.".to_string());
    }
    source_code_server_validate_remote_linux_payload(&installed.path)?;
    source_code_server_ensure_remote_payload(machine_config, execution_target, &installed)?;

    for local_port in source_code_server_remote_candidate_ports() {
        if Instant::now() >= startup_deadline {
            break;
        }
        let askpass = gpui_remote_ssh_askpass_script(machine_config)?;
        let mut arguments = gpui_remote_ssh_client_options(machine_config.has_saved_password);
        arguments.extend([
            "-o".to_string(),
            "ExitOnForwardFailure=yes".to_string(),
            "-L".to_string(),
            format!("127.0.0.1:{local_port}:127.0.0.1:{SOURCE_CODE_SERVER_REMOTE_PORT}"),
        ]);
        arguments.extend(gpui_remote_ssh_target_arguments(machine_config));
        arguments.push(gpui_remote_command_for_execution_target(
            execution_target,
            source_code_server_remote_launch_command(target.project_path.as_path()).as_str(),
        ));
        let mut command = Command::new("/usr/bin/ssh");
        command
            .args(arguments)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        if let Some(environment) = gpui_remote_ssh_askpass_environment(askpass.as_ref()) {
            command.envs(environment);
        }
        let started_at = Instant::now();
        let mut child = match command.spawn() {
            Ok(child) => child,
            Err(_) => continue,
        };
        let readiness = source_code_server_wait_until_responsive_at(
            local_port,
            startup_deadline.saturating_duration_since(Instant::now()),
        );
        let child_running = child.try_wait().ok().flatten().is_none();
        if readiness.is_ready() && child_running {
            return Ok(SourceCodeServerRuntimeStartOutput {
                child,
                runtime_origin: format!("http://127.0.0.1:{local_port}"),
                prompt_editor_ipc_ready: readiness.prompt_editor_ipc_ready,
                started_at,
                http_runtime_ready: readiness.http_runtime_ready,
            });
        }
        let _ = child.kill();
        let _ = child.wait();
    }
    Err("Remote Source runtime did not become reachable through SSH.".to_string())
}

#[cfg(target_os = "macos")]
fn source_code_server_ensure_remote_payload(
    config: &GpuiRemoteMachineConfig,
    execution_target: &GpuiRemoteExecutionTarget,
    installed: &component_store::InstalledComponent,
) -> Result<(), String> {
    let component_key = format!("{}:{}", installed.version, installed.platform);
    let ready_command = source_code_server_remote_payload_ready_command(component_key.as_str());
    let ready = gpui_run_remote_ssh_in_execution_target(
        config,
        execution_target,
        ready_command.as_str(),
        Duration::from_secs(15),
    );
    if ready.exit_code == 0 {
        return Ok(());
    }

    let unique = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let archive_path = env::temp_dir().join(format!(
        "ghostex-code-server-{}-{unique:x}.tar.gz",
        std::process::id()
    ));
    let archive_result = Command::new("/usr/bin/tar")
        .args(["-czf"])
        .arg(&archive_path)
        .arg("-C")
        .arg(&installed.path)
        .arg(".")
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map_err(|_| "Could not package the Linux code-server component.".to_string())?;
    if !archive_result.success() {
        let _ = fs::remove_file(&archive_path);
        return Err("Could not package the Linux code-server component.".to_string());
    }
    let upload_command = source_code_server_remote_payload_upload_command(component_key.as_str());
    let upload = gpui_run_remote_ssh_with_stdin_file_in_execution_target(
        config,
        execution_target,
        upload_command.as_str(),
        archive_path.as_path(),
        Duration::from_secs(180),
    );
    let _ = fs::remove_file(&archive_path);
    if upload.exit_code != 0 {
        return Err("Could not upload the Linux code-server component over SSH.".to_string());
    }
    Ok(())
}

#[cfg(target_os = "macos")]
fn source_code_server_remote_data_root_script() -> &'static str {
    r#"if [ -n "${GHOSTEX_HOME:-}" ] && [ "${GHOSTEX_HOME#/}" != "$GHOSTEX_HOME" ]; then ghostex_data="$GHOSTEX_HOME"; elif [ -n "${XDG_DATA_HOME:-}" ]; then ghostex_data="$XDG_DATA_HOME/ghostex"; else ghostex_data="$HOME/.local/share/ghostex"; fi
code_root="$ghostex_data/code-server""#
}

#[cfg(target_os = "macos")]
fn source_code_server_remote_payload_ready_command(component_key: &str) -> String {
    format!(
        "set -eu\n{}\ntest -f \"$code_root/package/.ghostex-component-key\"\ntest \"$(cat \"$code_root/package/.ghostex-component-key\")\" = {}\ntest -x \"$code_root/package/lib/node\"\ntest -f \"$code_root/package/out/node/entry.js\"\ntest -f \"$code_root/package/lib/vscode/out/server-main.js\"",
        source_code_server_remote_data_root_script(),
        gpui_shell_quote(component_key),
    )
}

#[cfg(target_os = "macos")]
fn source_code_server_remote_payload_upload_command(component_key: &str) -> String {
    format!(
        "set -eu\n{}\numask 077\nreleases=\"$code_root/releases\"\nmkdir -p \"$releases\"\nstage=\"$releases/.install-$$\"\nrelease=\"$releases/{}\"\npointer_stage=\"$code_root/.package-$$\"\ncleanup() {{ rm -rf -- \"$stage\"; rm -f -- \"$pointer_stage\"; }}\ntrap cleanup EXIT HUP INT TERM\nfor abandoned in \"$releases\"/.install-* \"$code_root\"/.package-*; do\n  if [ ! -e \"$abandoned\" ] && [ ! -L \"$abandoned\" ]; then continue; fi\n  abandoned_pid=${{abandoned##*-}}\n  case \"$abandoned_pid\" in ''|*[!0-9]*) continue ;; esac\n  if [ ! -d \"/proc/$abandoned_pid\" ]; then rm -rf -- \"$abandoned\"; fi\ndone\nrm -rf -- \"$stage\"\nrm -f -- \"$pointer_stage\"\nmkdir \"$stage\"\ntar -xzf - -C \"$stage\"\ntest -x \"$stage/lib/node\"\ntest -f \"$stage/out/node/entry.js\"\ntest -f \"$stage/lib/vscode/out/server-main.js\"\nprintf '%s' {} >\"$stage/.ghostex-component-key\"\nif [ -e \"$release\" ]; then\n  test -f \"$release/.ghostex-component-key\"\n  test \"$(cat \"$release/.ghostex-component-key\")\" = {}\n  test -x \"$release/lib/node\"\n  test -f \"$release/out/node/entry.js\"\n  test -f \"$release/lib/vscode/out/server-main.js\"\n  rm -rf -- \"$stage\"\nelif ! mv -T \"$stage\" \"$release\"; then\n  test -f \"$release/.ghostex-component-key\"\n  test \"$(cat \"$release/.ghostex-component-key\")\" = {}\n  test -x \"$release/lib/node\"\n  test -f \"$release/out/node/entry.js\"\n  test -f \"$release/lib/vscode/out/server-main.js\"\n  rm -rf -- \"$stage\"\nfi\nprevious_release=$(readlink -f \"$code_root/package\" 2>/dev/null || true)\nln -s \"releases/{}\" \"$pointer_stage\"\nmv -Tf \"$pointer_stage\" \"$code_root/package\"\nfor candidate in \"$releases\"/*; do\n  [ -d \"$candidate\" ] || continue\n  if [ \"$candidate\" = \"$release\" ] || [ \"$candidate\" = \"$previous_release\" ]; then continue; fi\n  if find \"$candidate\" -maxdepth 0 -mmin +10 -print -quit | grep -q .; then rm -rf -- \"$candidate\"; fi\ndone\ntrap - EXIT HUP INT TERM",
        source_code_server_remote_data_root_script(),
        installed_key_path_fragment(component_key),
        gpui_shell_quote(component_key),
        gpui_shell_quote(component_key),
        gpui_shell_quote(component_key),
        installed_key_path_fragment(component_key),
    )
}

#[cfg(target_os = "macos")]
fn installed_key_path_fragment(component_key: &str) -> String {
    component_key
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '.' | '-' | '_') {
                character
            } else {
                '-'
            }
        })
        .collect()
}

#[cfg(target_os = "macos")]
fn source_code_server_remote_launch_command(project_path: &Path) -> String {
    format!(
        "set -eu\n{}\npackage=\"$code_root/package\"\nruntime=\"$code_root/runtime\"\nmkdir -p \"$runtime/user-data\" \"$runtime/extensions\"\ncd {}\nchild=\ncleanup() {{ if [ -n \"$child\" ]; then kill \"$child\" 2>/dev/null || true; wait \"$child\" 2>/dev/null || true; fi; }}\ntrap cleanup EXIT HUP INT TERM\n\"$package/lib/node\" \"$package/out/node/entry.js\" --auth none --bind-addr 127.0.0.1:{} --disable-telemetry --disable-update-check --disable-workspace-trust --disable-getting-started-override --ignore-last-opened --app-name 'ghostex Code' --user-data-dir \"$runtime/user-data\" --extensions-dir \"$runtime/extensions\" &\nchild=$!\nwait \"$child\"",
        source_code_server_remote_data_root_script(),
        gpui_shell_quote(gpui_path_string(project_path).as_str()),
        SOURCE_CODE_SERVER_REMOTE_PORT,
    )
}

#[cfg(target_os = "macos")]
fn source_code_server_remote_candidate_ports() -> Vec<u16> {
    let range =
        u64::from(SOURCE_CODE_SERVER_TUNNEL_PORT_MAX - SOURCE_CODE_SERVER_TUNNEL_PORT_MIN + 1);
    let seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64
        ^ u64::from(std::process::id());
    (0..SOURCE_CODE_SERVER_TUNNEL_ATTEMPTS)
        .map(|offset| SOURCE_CODE_SERVER_TUNNEL_PORT_MIN + ((seed + offset as u64) % range) as u16)
        .collect()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SourceCodeServerRuntimeAvailability {
    Available,
    InstallRequired,
    Failed(SourceCodeServerRuntimeFailure),
}

fn on_demand_component_manifest_path() -> Option<PathBuf> {
    if let Some(path) = env::var_os("GHOSTEX_ON_DEMAND_MANIFEST") {
        let path = PathBuf::from(path);
        return path.is_file().then_some(path);
    }
    #[cfg(target_os = "macos")]
    if let Some(resources_dir) = gpui_app_bundle_resources_dir() {
        let path = resources_dir.join("Web/on-demand-resources.json");
        if path.is_file() {
            return Some(path);
        }
    }
    if let Ok(executable) = env::current_exe()
        && let Some(executable_dir) = executable.parent()
    {
        for path in [
            executable_dir.join("resources/on-demand-resources.json"),
            executable_dir.join("resources/Web/on-demand-resources.json"),
            executable_dir.join("on-demand-resources.json"),
        ] {
            if path.is_file() {
                return Some(path);
            }
        }
    }
    None
}

fn on_demand_component_store() -> Result<Option<component_store::ComponentStore>, String> {
    let Some(manifest_path) = on_demand_component_manifest_path() else {
        return Ok(None);
    };
    let manifest = component_store::OnDemandManifest::load(&manifest_path)?;
    component_store::ComponentStore::from_manifest(manifest).map(Some)
}

fn source_code_server_runtime_availability(
    target: &SourceCodeServerRuntimeTarget,
) -> SourceCodeServerRuntimeAvailability {
    #[cfg(not(target_os = "windows"))]
    if target.component_platform().is_none() && source_code_server_resolve_repo_root().is_ok() {
        return SourceCodeServerRuntimeAvailability::Available;
    }
    let store = match on_demand_component_store() {
        Ok(Some(store)) => store,
        Ok(None) => {
            return SourceCodeServerRuntimeAvailability::Failed(
                SourceCodeServerRuntimeFailure::Launch,
            );
        }
        Err(_) => {
            return SourceCodeServerRuntimeAvailability::Failed(
                SourceCodeServerRuntimeFailure::InstallOther,
            );
        }
    };
    let installed = match target.component_platform() {
        Some(platform) => {
            store.query_current_for_platform(SOURCE_CODE_SERVER_COMPONENT_NAME, platform)
        }
        None => store.query_current(SOURCE_CODE_SERVER_COMPONENT_NAME),
    };
    match installed {
        Ok(installed) if installed.installed => SourceCodeServerRuntimeAvailability::Available,
        Ok(_) => SourceCodeServerRuntimeAvailability::InstallRequired,
        Err(_) => SourceCodeServerRuntimeAvailability::Failed(
            SourceCodeServerRuntimeFailure::InstallOther,
        ),
    }
}

fn source_code_server_install_component(
    target: Option<&SourceCodeServerRuntimeTarget>,
    progress_tx: mpsc::UnboundedSender<component_store::ComponentStoreProgressPhase>,
) -> Result<component_store::InstalledComponent, String> {
    let store = on_demand_component_store()?
        .ok_or_else(|| "The sealed code-server component manifest is unavailable.".to_string())?;
    let mut report_progress = |progress: component_store::ComponentStoreProgress| {
        let _ = progress_tx.unbounded_send(progress.phase);
    };
    let component_platform = target.and_then(SourceCodeServerRuntimeTarget::component_platform);
    let installed = match component_platform {
        Some(platform) => store.install_for_platform(
            SOURCE_CODE_SERVER_COMPONENT_NAME,
            platform,
            &mut report_progress,
        )?,
        None => store.install(SOURCE_CODE_SERVER_COMPONENT_NAME, &mut report_progress)?,
    };
    #[cfg(not(target_os = "windows"))]
    {
        if component_platform.is_some() {
            source_code_server_validate_remote_linux_payload(&installed.path)?;
        } else {
            source_code_server_validate_development_payload(&installed.path)?;
            let node_path = installed.path.join("lib/node");
            if source_code_server_node_major(&node_path)
                != Some(SOURCE_CODE_SERVER_DEFAULT_NODE_MAJOR)
            {
                return Err(
                    "The installed code-server component has an invalid Node runtime.".to_string(),
                );
            }
        }
    }
    #[cfg(target_os = "windows")]
    {
        component_store::verify_installed_windows_code_server_component(
            &installed.path,
            &installed.version,
            &installed.platform,
        )?;
    }
    Ok(installed)
}

fn source_code_server_validate_remote_linux_payload(repo_root: &Path) -> Result<(), String> {
    for relative_path in [
        "lib/node",
        "out/node/entry.js",
        "lib/vscode/out/server-main.js",
    ] {
        if !repo_root.join(relative_path).is_file() {
            return Err("The Linux code-server component is incomplete.".to_string());
        }
    }
    Ok(())
}

fn source_code_server_install_failure(message: &str) -> SourceCodeServerRuntimeFailure {
    let message = message.to_ascii_lowercase();
    if message.contains("sha-256")
        || message.contains("checksum")
        || message.contains("size mismatch")
        || message.contains("verification")
    {
        SourceCodeServerRuntimeFailure::InstallIntegrity
    } else if message.contains("download") || message.contains("invoke-webrequest") {
        SourceCodeServerRuntimeFailure::InstallDownload
    } else {
        SourceCodeServerRuntimeFailure::InstallOther
    }
}

fn source_code_server_resolve_repo_root() -> Result<PathBuf, String> {
    let configured_root = env::var("GHOSTEX_CODE_SERVER_ROOT")
        .ok()
        .or_else(|| env::var("ghostex_CODE_SERVER_ROOT").ok())
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let configured_root_is_set = configured_root.is_some();
    let candidates = if let Some(configured_root) = configured_root {
        vec![PathBuf::from(configured_root)]
    } else {
        source_code_server_repo_root_candidates()
    };
    for candidate in candidates {
        if candidate.join("out/node/entry.js").exists()
            && source_code_server_validate_development_payload(&candidate).is_ok()
        {
            return Ok(candidate);
        }
    }
    if !configured_root_is_set && let Some(store) = on_demand_component_store()? {
        let installed = store.query_current(SOURCE_CODE_SERVER_COMPONENT_NAME)?;
        if installed.installed
            && installed.path.join("out/node/entry.js").is_file()
            && source_code_server_validate_development_payload(&installed.path).is_ok()
        {
            return Ok(installed.path);
        }
    }
    Err("code-server runtime is unavailable".to_string())
}

fn source_code_server_repo_root_candidates() -> Vec<PathBuf> {
    let mut candidates = Vec::new();
    let mut append = |candidate: PathBuf| {
        if !candidates.iter().any(|existing| existing == &candidate) {
            candidates.push(candidate);
        }
    };
    if let Ok(executable) = env::current_exe() {
        #[cfg(target_os = "macos")]
        if let Some(bundle_root) = find_app_bundle_root(&executable) {
            let resources_dir = bundle_root.join("Contents/Resources");
            append(resources_dir.join("Web/code-server"));
            append(resources_dir.join("code-server"));
        }
        // Non-macOS staged layouts are flat: bundled payloads sit beside the
        // executable (same contract as the staged gxserver package).
        #[cfg(not(target_os = "macos"))]
        if let Some(exe_dir) = executable.parent() {
            append(exe_dir.join("code-server"));
        }
    }
    if let Ok(repo_root) = env::var("ghostex_REPO_ROOT") {
        let repo_root = repo_root.trim();
        if !repo_root.is_empty() {
            append(PathBuf::from(repo_root).join("code-server"));
        }
    }
    if let Ok(cwd) = env::current_dir() {
        append(cwd.join("code-server"));
    }
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    if let Some(repo_root) = manifest_dir.parent() {
        append(repo_root.join("code-server"));
        #[cfg(target_os = "macos")]
        append(repo_root.join("gpui/runtime/macos/Web/code-server"));
    }
    candidates
}

fn source_code_server_validate_development_payload(repo_root: &Path) -> Result<(), String> {
    if !repo_root.join("lib/vscode/package.json").exists() {
        return Err("code-server VS Code payload is unavailable".to_string());
    }
    if !repo_root.join("lib/vscode/out/server-main.js").exists() {
        return Err("code-server VS Code server output is unavailable".to_string());
    }
    // fs-copyfile only compiles a native binding on macOS (binding.gyp is
    // `type: none` elsewhere and the JS falls back to node:fs), so the
    // installed-package check is the platform-correct git-extension probe
    // off macOS.
    #[cfg(target_os = "macos")]
    let git_extension_probe =
        "lib/vscode/extensions/git/node_modules/@vscode/fs-copyfile/build/Release/vscode_fs.node";
    #[cfg(not(target_os = "macos"))]
    let git_extension_probe =
        "lib/vscode/extensions/git/node_modules/@vscode/fs-copyfile/package.json";
    if !repo_root.join(git_extension_probe).exists() {
        return Err("code-server Git extension native module is unavailable".to_string());
    }
    Ok(())
}

fn source_code_server_runtime_storage() -> Result<(PathBuf, PathBuf), String> {
    let storage = shared_settings::ghostex_storage_paths().code_server_runtime_dir();
    let user_data_dir = storage.join("user-data");
    let extensions_dir = storage.join("extensions");
    fs::create_dir_all(&user_data_dir)
        .map_err(|_| "failed to prepare Source runtime storage".to_string())?;
    fs::create_dir_all(&extensions_dir)
        .map_err(|_| "failed to prepare Source runtime storage".to_string())?;
    Ok((user_data_dir, extensions_dir))
}

fn source_code_server_should_seed_default_theme(
    settings: &SourceCodeServerRuntimeSettings,
) -> bool {
    let Some(linked_dir) = settings.linked_vscode_user_config_dir() else {
        return true;
    };
    !PathBuf::from(linked_dir).join("settings.json").exists()
}

fn source_code_server_ensure_default_theme(user_data_dir: &Path) -> Result<(), String> {
    /*
    CDXC:GPUISourceRuntime 2026-06-24-23:17:
    When GPUI owns the code-server user-data profile, seed the same Dark 2026 default theme as macOS only if the profile has no settings file. Do not overwrite user-edited runtime settings or linked local VS Code settings.
    */
    let user_dir = user_data_dir.join("User");
    let settings_path = user_dir.join("settings.json");
    fs::create_dir_all(&user_dir)
        .map_err(|_| "failed to prepare Source runtime settings".to_string())?;
    if settings_path.exists() {
        return Ok(());
    }
    fs::write(
        settings_path,
        "{\n  \"workbench.colorTheme\": \"Dark 2026\"\n}\n",
    )
    .map_err(|_| "failed to prepare Source runtime settings".to_string())
}

fn source_code_server_resolve_node_path(repo_root: &Path) -> Result<PathBuf, String> {
    let required_major = source_code_server_required_node_major(repo_root)
        .unwrap_or(SOURCE_CODE_SERVER_DEFAULT_NODE_MAJOR);
    if let Some(configured) = env::var("GHOSTEX_CODE_SERVER_NODE_PATH")
        .ok()
        .or_else(|| env::var("ghostex_CODE_SERVER_NODE_PATH").ok())
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
    {
        let configured = PathBuf::from(configured);
        if source_code_server_node_major(&configured) == Some(required_major) {
            return Ok(configured);
        }
        return Err("configured Source Node runtime is incompatible".to_string());
    }

    for candidate in source_code_server_bundled_node_candidates(repo_root) {
        if source_code_server_node_major(&candidate) == Some(required_major) {
            return Ok(candidate);
        }
    }
    if source_code_server_is_bundled_repo_root(repo_root) {
        return Err("bundled Source Node runtime is unavailable".to_string());
    }
    for candidate in source_code_server_system_node_candidates(required_major) {
        if source_code_server_node_major(&candidate) == Some(required_major) {
            return Ok(candidate);
        }
    }
    Err("Source Node runtime is unavailable".to_string())
}

fn source_code_server_required_node_major(repo_root: &Path) -> Option<u64> {
    let package_json = fs::read_to_string(repo_root.join("package.json")).ok()?;
    let value = serde_json::from_str::<serde_json::Value>(&package_json).ok()?;
    let node_engine = value.get("engines")?.get("node")?.as_str()?;
    source_code_server_first_integer(node_engine)
}

fn source_code_server_bundled_node_candidates(repo_root: &Path) -> Vec<PathBuf> {
    let mut candidates = Vec::new();
    let mut append = |candidate: PathBuf| {
        if !candidates.iter().any(|existing| existing == &candidate) {
            candidates.push(candidate);
        }
    };
    append(repo_root.join("lib/node"));
    #[cfg(target_os = "macos")]
    {
        if let Ok(executable) = env::current_exe() {
            if let Some(bundle_root) = find_app_bundle_root(&executable) {
                let resources_dir = bundle_root.join("Contents/Resources");
                append(resources_dir.join("Web/code-server/lib/node"));
                append(resources_dir.join("code-server/lib/node"));
            }
        }
        if let Ok(cwd) = env::current_dir() {
            append(cwd.join("gpui/runtime/macos/Web/code-server/lib/node"));
        }
        let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        if let Some(repo_root) = manifest_dir.parent() {
            append(repo_root.join("gpui/runtime/macos/Web/code-server/lib/node"));
        }
    }
    // Non-macOS staged layouts keep bundled payloads beside the executable;
    // the staged gxserver package also carries a matching Node runtime.
    #[cfg(not(target_os = "macos"))]
    if let Ok(executable) = env::current_exe() {
        if let Some(exe_dir) = executable.parent() {
            append(exe_dir.join("code-server/lib/node"));
            append(exe_dir.join("gxserver/code-server/lib/node"));
        }
    }
    candidates
}

fn source_code_server_system_node_candidates(required_major: u64) -> Vec<PathBuf> {
    let home = home_dir();
    let mut candidates = Vec::new();
    for directory in [
        home.join(".local/node"),
        home.join(".local/share/mise/installs/node"),
        home.join(".asdf/installs/nodejs"),
        home.join(".nvm/versions/node"),
    ] {
        candidates.extend(source_code_server_node_install_candidates(
            &directory,
            required_major,
        ));
    }
    #[cfg(target_os = "macos")]
    {
        candidates.push(PathBuf::from(format!(
            "/opt/homebrew/opt/node@{required_major}/bin/node"
        )));
        candidates.push(PathBuf::from(format!(
            "/usr/local/opt/node@{required_major}/bin/node"
        )));
    }
    if let Some(path_node) = source_code_server_resolve_command_path("node") {
        candidates.push(path_node);
    }
    let mut seen = HashSet::new();
    candidates
        .into_iter()
        .filter(|candidate| seen.insert(candidate.clone()))
        .collect()
}

fn source_code_server_node_install_candidates(
    directory: &Path,
    required_major: u64,
) -> Vec<PathBuf> {
    let Ok(entries) = fs::read_dir(directory) else {
        return Vec::new();
    };
    let mut candidates = entries
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|entry| entry.is_dir())
        .filter(|entry| {
            let name = entry
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or_default();
            name.starts_with(&format!("node-v{required_major}."))
                || name.starts_with(&format!("v{required_major}."))
                || name.starts_with(&format!("{required_major}."))
        })
        .map(|entry| entry.join("bin/node"))
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| right.cmp(left));
    candidates
}

fn source_code_server_node_major(node_path: &Path) -> Option<u64> {
    if !node_path.is_file() {
        return None;
    }
    let output = Command::new(node_path)
        .arg("-v")
        .stdin(Stdio::null())
        .stderr(Stdio::null())
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let version = String::from_utf8(output.stdout).ok()?;
    source_code_server_first_integer(version.trim())
}

fn source_code_server_first_integer(value: &str) -> Option<u64> {
    let mut digits = String::new();
    for character in value.chars() {
        if character.is_ascii_digit() {
            digits.push(character);
            continue;
        }
        if !digits.is_empty() {
            break;
        }
    }
    digits.parse().ok()
}

#[cfg(target_os = "macos")]
fn source_code_server_resolve_command_path(command: &str) -> Option<PathBuf> {
    // macOS GUI apps inherit a minimal PATH, so consult the user's login
    // shell for the real one.
    let output = Command::new("/bin/zsh")
        .arg("-lc")
        .arg(format!("command -v {}", gpui_shell_quote(command)))
        .stdin(Stdio::null())
        .stderr(Stdio::null())
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let stdout = String::from_utf8(output.stdout).ok()?;
    stdout
        .lines()
        .next()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
}

#[cfg(not(target_os = "macos"))]
fn source_code_server_resolve_command_path(command: &str) -> Option<PathBuf> {
    // Outside macOS the process PATH is the session PATH; scan it directly
    // instead of assuming a specific login shell exists.
    let path = env::var_os("PATH")?;
    env::split_paths(&path)
        .map(|directory| directory.join(command))
        .find(|candidate| candidate.is_file())
}

#[cfg(target_os = "macos")]
fn source_code_server_is_bundled_repo_root(repo_root: &Path) -> bool {
    let Ok(executable) = env::current_exe() else {
        return false;
    };
    let Some(bundle_root) = find_app_bundle_root(&executable) else {
        return false;
    };
    let resources_dir = bundle_root.join("Contents/Resources");
    let repo_root = repo_root
        .canonicalize()
        .unwrap_or_else(|_| repo_root.to_path_buf());
    for bundled in [
        resources_dir.join("Web/code-server"),
        resources_dir.join("code-server"),
    ] {
        let bundled = bundled.canonicalize().unwrap_or(bundled);
        if repo_root == bundled || repo_root.starts_with(&bundled) {
            return true;
        }
    }
    false
}

#[cfg(not(target_os = "macos"))]
fn source_code_server_is_bundled_repo_root(repo_root: &Path) -> bool {
    // Flat staged layouts bundle code-server beside the executable.
    let Ok(executable) = env::current_exe() else {
        return false;
    };
    let Some(exe_dir) = executable.parent() else {
        return false;
    };
    let repo_root = repo_root
        .canonicalize()
        .unwrap_or_else(|_| repo_root.to_path_buf());
    let bundled = exe_dir.join("code-server");
    let bundled = bundled.canonicalize().unwrap_or(bundled);
    repo_root == bundled || repo_root.starts_with(&bundled)
}

fn source_code_server_runtime_environment(repo_root: &Path) -> HashMap<String, String> {
    let mut environment: HashMap<String, String> = env::vars().collect();
    environment.insert("VSCODE_IPC_HOOK_CLI".to_string(), String::new());
    environment.remove("CODE_SERVER_PARENT_PID");
    if source_code_server_is_bundled_runtime(repo_root) {
        environment.remove("VSCODE_DEV");
        environment.insert("NODE_ENV".to_string(), "production".to_string());
    } else {
        environment.insert("VSCODE_DEV".to_string(), "1".to_string());
        environment.insert("NODE_ENV".to_string(), "development".to_string());
        let mut path_entries = vec![repo_root.join("node_modules/.bin")];
        match environment.get("PATH") {
            Some(path) => path_entries.extend(env::split_paths(path)),
            None => path_entries.extend(env::split_paths(
                "/usr/local/bin:/opt/homebrew/bin:/usr/bin:/bin:/usr/sbin:/sbin",
            )),
        }
        if let Ok(path) = env::join_paths(path_entries) {
            environment.insert("PATH".to_string(), path.to_string_lossy().to_string());
        }
    }
    environment
}

fn source_code_server_is_bundled_runtime(repo_root: &Path) -> bool {
    repo_root.join("lib/node").is_file()
}

#[derive(Clone, Copy, Default)]
struct SourceCodeServerReadiness {
    http_runtime_ready: bool,
    prompt_editor_ipc_ready: bool,
}

impl SourceCodeServerReadiness {
    fn is_ready(self) -> bool {
        self.http_runtime_ready && self.prompt_editor_ipc_ready
    }
}

fn source_code_server_readiness_at(port: u16) -> SourceCodeServerReadiness {
    let Ok(address) =
        format!("{}:{}", SOURCE_CODE_SERVER_EDITOR_HOST, port).parse::<std::net::SocketAddr>()
    else {
        return SourceCodeServerReadiness::default();
    };
    let Ok(mut stream) = TcpStream::connect_timeout(&address, Duration::from_secs(1)) else {
        return SourceCodeServerReadiness::default();
    };
    let _ = stream.set_read_timeout(Some(Duration::from_secs(1)));
    let _ = stream.set_write_timeout(Some(Duration::from_secs(1)));
    let request = format!(
        "GET /healthz HTTP/1.1\r\nHost: {}:{}\r\nConnection: close\r\n\r\n",
        SOURCE_CODE_SERVER_EDITOR_HOST, port
    );
    if stream.write_all(request.as_bytes()).is_err() {
        return SourceCodeServerReadiness::default();
    }
    let mut response = String::new();
    if stream.read_to_string(&mut response).is_err() {
        return SourceCodeServerReadiness::default();
    }
    let http_runtime_ready =
        response.starts_with("HTTP/1.1 200") || response.starts_with("HTTP/1.0 200");
    if !http_runtime_ready {
        return SourceCodeServerReadiness::default();
    }
    let prompt_editor_ipc_ready = response
        .split_once("\r\n\r\n")
        .and_then(|(_, body)| serde_json::from_str::<serde_json::Value>(body).ok())
        .and_then(|body| {
            body.get("promptEditorIpcReady")
                .and_then(serde_json::Value::as_bool)
        })
        .unwrap_or(false);
    SourceCodeServerReadiness {
        http_runtime_ready,
        prompt_editor_ipc_ready,
    }
}

fn source_code_server_health_check_at(port: u16) -> bool {
    source_code_server_readiness_at(port).http_runtime_ready
}

fn source_code_server_health_check() -> bool {
    source_code_server_health_check_at(SOURCE_CODE_SERVER_EDITOR_PORT)
}

fn source_code_server_wait_until_responsive_at(
    port: u16,
    timeout: Duration,
) -> SourceCodeServerReadiness {
    let deadline = Instant::now() + timeout;
    while Instant::now() < deadline {
        let readiness = source_code_server_readiness_at(port);
        if readiness.is_ready() {
            return readiness;
        }
        thread::sleep(SOURCE_CODE_SERVER_HEALTH_POLL_INTERVAL);
    }
    source_code_server_readiness_at(port)
}

fn source_code_server_wait_until_responsive(timeout: Duration) -> SourceCodeServerReadiness {
    source_code_server_wait_until_responsive_at(SOURCE_CODE_SERVER_EDITOR_PORT, timeout)
}

fn source_code_server_wait_until_not_responsive(timeout: Duration) -> bool {
    let deadline = Instant::now() + timeout;
    while Instant::now() < deadline {
        if !source_code_server_health_check() {
            return true;
        }
        thread::sleep(SOURCE_CODE_SERVER_HEALTH_POLL_INTERVAL);
    }
    !source_code_server_health_check()
}

#[cfg(not(target_os = "windows"))]
fn source_code_server_open_file_in_existing_instance(file_path: &Path) -> Result<(), String> {
    /*
    Use the bundled code-server CLI's reviewed session-socket protocol to open
    the validated file in the already-owned Source workbench. The Source CEF
    surface may need a moment to register its VS Code socket after creation, so
    retry only during the normal startup grace window; never launch a second
    editor server or fall back to an external application.
    */
    let repo_root = source_code_server_resolve_repo_root()?;
    let node_path = source_code_server_resolve_node_path(&repo_root)?;
    let entrypoint_path = repo_root.join("out/node/entry.js");
    let (user_data_dir, _) = source_code_server_runtime_storage()?;
    let session_socket = user_data_dir.join("code-server-ipc.sock");
    let deadline = Instant::now() + SOURCE_CODE_SERVER_STARTUP_GRACE_INTERVAL;

    while Instant::now() < deadline {
        let mut command = Command::new(&node_path);
        command
            .arg(&entrypoint_path)
            .arg("--user-data-dir")
            .arg(&user_data_dir)
            .arg("--session-socket")
            .arg(&session_socket)
            .arg("--reuse-window")
            .arg(file_path)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .envs(source_code_server_runtime_environment(&repo_root));
        if let Some(parent) = file_path.parent() {
            command.current_dir(parent);
        }
        if command.status().is_ok_and(|status| status.success()) {
            return Ok(());
        }
        thread::sleep(SOURCE_CODE_SERVER_HEALTH_POLL_INTERVAL);
    }

    Err("Ghostex Source did not become ready to open that file.".to_string())
}

#[cfg(target_os = "windows")]
fn source_code_server_open_file_in_existing_instance(file_path: &Path) -> Result<(), String> {
    let deadline = Instant::now() + SOURCE_CODE_SERVER_STARTUP_GRACE_INTERVAL;
    while Instant::now() < deadline {
        let mut command = windows_terminal_backend::source_code_server_open_file_command(
            file_path,
            SOURCE_CODE_SERVER_DEFAULT_NODE_MAJOR,
        )?;
        command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        if command.status().is_ok_and(|status| status.success()) {
            return Ok(());
        }
        thread::sleep(SOURCE_CODE_SERVER_HEALTH_POLL_INTERVAL);
    }
    Err("Ghostex Source did not become ready to open that file.".to_string())
}

fn kanban_workarea_runtime_url_from_project_snapshot(
    snapshot: &GpuiProjectSnapshot,
) -> Option<ProjectWorkareaRealRuntimeUrl> {
    /*
    CDXC:GPUIProjectWorkareaRuntimeCefBundles 2026-06-24-11:03:
    Kanban runtime URL authority is the bundled first-party CEF page plus the explicit live sidebar project identity. The URL is passed directly to CefSurface creation and is not stored in shell state, logged, derived from .git/folders, or backed by WKWebView/WebKit.
    */
    if !snapshot.feature_availability.kanban || snapshot.is_quick_projectless {
        return None;
    }
    let active_project_id = snapshot.active_project_id.as_ref()?.0.clone();
    let remote_reference = gpui_remote_project_reference_from_project_id(&active_project_id);
    let request_project_id = remote_reference
        .as_ref()
        .map(|reference| reference.project_id.clone())
        .unwrap_or(active_project_id);
    let project_path = snapshot
        .in_memory_project_path
        .as_ref()?
        .to_string_lossy()
        .to_string();
    let surface_id = snapshot.surface_ids.kanban_board_id.as_ref()?.clone();
    let base_url = gpui_cef_html_entry_url("GHOSTEX_GPUI_KANBAN_URL", "kanban.html").ok()?;
    let mut params = vec![
        ("projectName", snapshot.display_name.clone()),
        ("projectPath", project_path),
        ("projectId", request_project_id),
        ("projectEditorId", surface_id),
        ("beadsDisplayKey", snapshot.display_name.clone()),
    ];
    if let Some(reference) = remote_reference {
        params.push(("remoteMachineId", reference.remote_machine_id));
    }
    ProjectWorkareaRealRuntimeUrl::from_authorized_runtime_url(append_url_query_params(
        base_url, &params,
    ))
}

fn automate_workarea_runtime_url_from_project_snapshot(
    snapshot: &GpuiProjectSnapshot,
    runtime_settings: &cef::SidebarRuntimeSettingsSnapshot,
) -> Option<ProjectWorkareaRealRuntimeUrl> {
    /*
    CDXC:GPUIAutomateWorkarea 2026-07-04-23:18:
    Automate mirrors macOS `createProjectAutomateEditorUrl`: use the bundled Kanban/tasks CEF page, the explicit project identity params, the automate-mode project editor id, and `surface=automations`. Projectless contexts, missing project path, or missing automateBoardId must stay on the placeholder instead of synthesizing an Automate URL.

    CDXC:GPUIAutomateStable 2026-07-26:
    Project-scoped Automate is no longer an experimental GPUI feature. Mark that first-party workarea explicitly so the shared page does not apply the Show Beta Features content gate or experimental label. Quick Automations Overview keeps its existing experimental startup seed.
    */
    if !snapshot.feature_availability.automate {
        return None;
    }
    let active_project_id = snapshot.active_project_id.as_ref()?.0.clone();
    if active_project_id == GPUI_QUICK_AUTOMATIONS_PROJECT_ID {
        /*
        CDXC:GPUIQuickAutomationsOverview 2026-07-08:
        Mirror macOS `createQuickAutomationsProjectEditorUrl` in `native/sidebar/native-sidebar.tsx`: the quick-automations project is a real Automate overview surface with empty `projectPath`, all-project scope, and the same Show Beta Features seed. Its identity is the project id, so it must not require an in-memory project path or be rejected by the projectless guard.
        */
        let surface_id = snapshot.surface_ids.automate_board_id.as_ref()?.clone();
        let base_url = gpui_cef_html_entry_url("GHOSTEX_GPUI_KANBAN_URL", "kanban.html").ok()?;
        return ProjectWorkareaRealRuntimeUrl::from_authorized_runtime_url(
            append_url_query_params_with_percent_encoded_spaces(
                base_url,
                &[
                    (
                        "projectName",
                        GPUI_QUICK_AUTOMATIONS_DISPLAY_TITLE.to_string(),
                    ),
                    ("projectPath", String::new()),
                    ("projectId", GPUI_QUICK_AUTOMATIONS_PROJECT_ID.to_string()),
                    ("projectEditorId", surface_id),
                    ("surface", "automations".to_string()),
                    ("scope", "all".to_string()),
                    (
                        "beadsDisplayKey",
                        GPUI_QUICK_AUTOMATIONS_DISPLAY_TITLE.to_string(),
                    ),
                    (
                        "showBetaFeatures",
                        if runtime_settings.show_beta_features {
                            "true"
                        } else {
                            "false"
                        }
                        .to_string(),
                    ),
                ],
            ),
        );
    }
    if snapshot.is_quick_projectless {
        return None;
    }
    let project_path = snapshot
        .in_memory_project_path
        .as_ref()?
        .to_string_lossy()
        .to_string();
    let surface_id = snapshot.surface_ids.automate_board_id.as_ref()?.clone();
    let base_url = gpui_cef_html_entry_url("GHOSTEX_GPUI_KANBAN_URL", "kanban.html").ok()?;
    ProjectWorkareaRealRuntimeUrl::from_authorized_runtime_url(append_url_query_params(
        base_url,
        &[
            ("projectName", snapshot.display_name.clone()),
            ("projectPath", project_path),
            ("projectId", active_project_id),
            ("projectEditorId", surface_id),
            ("beadsDisplayKey", snapshot.display_name.clone()),
            ("surface", "automations".to_string()),
            ("automationExperimental", "false".to_string()),
            (
                "showBetaFeatures",
                if runtime_settings.show_beta_features {
                    "true"
                } else {
                    "false"
                }
                .to_string(),
            ),
        ],
    ))
}

fn manage_workarea_runtime_url_from_project_snapshot(
    snapshot: &GpuiProjectSnapshot,
) -> Option<ProjectWorkareaRealRuntimeUrl> {
    /*
    CDXC:GPUIProjectWorkareaRuntimeCefBundles 2026-06-24-11:03:
    Manage runtime URL authority is the bundled first-party CEF page plus explicit project/manage identity only. The project root stays in the Rust bridge from the in-memory sidebar snapshot, so the Manage page URL remains pathless while CEF replaces the old WKWebView runtime surface.
    */
    if !snapshot.feature_availability.manage || snapshot.is_quick_projectless {
        return None;
    }
    let active_project_id = snapshot.active_project_id.as_ref()?.0.clone();
    let surface_id = snapshot.surface_ids.manage_workspace_id.as_ref()?.clone();
    snapshot.in_memory_project_path.as_ref()?;
    let base_url = gpui_cef_html_entry_url("GHOSTEX_GPUI_MANAGE_URL", "manage.html").ok()?;
    ProjectWorkareaRealRuntimeUrl::from_authorized_runtime_url(append_url_query_params(
        base_url,
        &[
            ("projectId", active_project_id),
            ("projectEditorId", surface_id),
        ],
    ))
}

