enum ManageFilesBridgeSideEffect {
    AddToSessionContext(String),
    CopyFullPath(String),
    RevealInFinder(PathBuf),
}

struct ManageFilesBridgeOutcome {
    action: String,
    request_id: String,
    response: serde_json::Value,
    side_effect: Option<ManageFilesBridgeSideEffect>,
}

fn manage_files_bridge_outcome(
    action: String,
    request_id: String,
    result: Result<serde_json::Value, String>,
) -> ManageFilesBridgeOutcome {
    let mut response = match result {
        Ok(response) => response,
        Err(error) => manage_files_bridge_error_response(&action, &request_id, &error),
    };
    let side_effect = if response.get("error").is_some() {
        None
    } else {
        let object = response.as_object_mut();
        match action.as_str() {
            "addToSessionContext" => object
                .and_then(|object| object.remove("contextPrompt"))
                .and_then(|value| value.as_str().map(str::to_string))
                .map(ManageFilesBridgeSideEffect::AddToSessionContext),
            "copyFullPath" => object
                .and_then(|object| object.remove("fullPath"))
                .and_then(|value| value.as_str().map(str::to_string))
                .map(ManageFilesBridgeSideEffect::CopyFullPath),
            "revealInFinder" => object
                .and_then(|object| object.remove("revealPath"))
                .and_then(|value| value.as_str().map(PathBuf::from))
                .map(ManageFilesBridgeSideEffect::RevealInFinder),
            _ => None,
        }
    };
    ManageFilesBridgeOutcome {
        action,
        request_id,
        response,
        side_effect,
    }
}

fn run_manage_files_bridge_request_for_project_snapshot(
    payload: &str,
    snapshot: Option<&GpuiProjectSnapshot>,
    additional_docs_folders_text: &str,
    global_docs_directory_text: &str,
) -> ManageFilesBridgeOutcome {
    let request = serde_json::from_str::<serde_json::Value>(payload).unwrap_or_default();
    let action = request
        .get("action")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("")
        .to_string();
    let request_id = request
        .get("requestId")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("")
        .to_string();

    manage_files_bridge_outcome(
        action,
        request_id,
        manage_files_bridge_result(
            &request,
            snapshot,
            additional_docs_folders_text,
            global_docs_directory_text,
        ),
    )
}

fn run_remote_manage_files_bridge_request_for_project_snapshot(
    payload: &str,
    snapshot: Option<&GpuiProjectSnapshot>,
    additional_docs_folders_text: &str,
    reference: &GpuiRemoteProjectReference,
    target: Option<&GpuiRemoteGxserverRequestTarget>,
) -> ManageFilesBridgeOutcome {
    /*
    CDXC:RemoteProjectDocs 2026-08-06:
    Remote Docs uses the owning gxserver as the filesystem boundary. The CEF
    request must still match the active machine-scoped project/editor snapshot,
    then Rust replaces that scoped presentation id with the daemon's raw
    project id and forwards only the fixed Docs action fields through the live
    authenticated tunnel. No remote path, host, token, or generic endpoint
    authority crosses the renderer bridge; a disconnected machine fails
    directly instead of probing the same path on the local Mac.
    */
    let request = serde_json::from_str::<serde_json::Value>(payload).unwrap_or_default();
    let action = manage_request_string(&request, "action").unwrap_or_default();
    let request_id = manage_request_string(&request, "requestId").unwrap_or_default();
    let result = (|| {
        let snapshot =
            snapshot.ok_or_else(|| "No active Docs project is available.".to_string())?;
        manage_validate_request_identity(&request, snapshot)?;
        if !matches!(
            action.as_str(),
            "list"
                | "read"
                | "stat"
                | "save"
                | "rename"
                | "delete"
                | "duplicate"
                | "createFolder"
                | "move"
                | "copyFullPath"
                | "addToSessionContext"
        ) {
            return if action == "revealInFinder" {
                Err("Reveal in Finder is unavailable for remote Docs items.".to_string())
            } else {
                Err("Unsupported Docs file action.".to_string())
            };
        }
        let target =
            target.ok_or_else(|| "Reconnect the remote machine to use Docs.".to_string())?;
        let mut params = serde_json::Map::new();
        params.insert(
            "action".to_string(),
            serde_json::Value::String(action.clone()),
        );
        params.insert(
            "requestId".to_string(),
            serde_json::Value::String(request_id.clone()),
        );
        params.insert(
            "projectId".to_string(),
            serde_json::Value::String(reference.project_id.clone()),
        );
        params.insert(
            "additionalDocsFolders".to_string(),
            serde_json::Value::String(additional_docs_folders_text.to_string()),
        );
        for key in ["path", "newPath", "content"] {
            if let Some(value) = manage_request_string(&request, key) {
                params.insert(key.to_string(), serde_json::Value::String(value));
            }
        }
        let response = gpui_remote_gxserver_rpc_result(
            target,
            "/api/runProjectDocsAction",
            &serde_json::Value::Object(params),
            Duration::from_secs(30),
        )?;
        if !response.is_object()
            || response.get("action").and_then(serde_json::Value::as_str) != Some(action.as_str())
            || response
                .get("requestId")
                .and_then(serde_json::Value::as_str)
                != Some(request_id.as_str())
        {
            return Err("The remote Docs service returned an invalid response.".to_string());
        }
        Ok(response)
    })();
    manage_files_bridge_outcome(action, request_id, result)
}

fn read_remote_manage_docs_resource(
    target: Option<&GpuiRemoteGxserverRequestTarget>,
    project_id: &str,
    relative_path: &str,
    additional_docs_folders_text: &str,
) -> Option<Vec<u8>> {
    let target = target?;
    let request_id = format!(
        "docs-resource-{}",
        MANAGE_REMOTE_RESOURCE_REQUEST_SEQUENCE.fetch_add(1, Ordering::Relaxed)
    );
    let response = gpui_remote_gxserver_rpc_result(
        target,
        "/api/runProjectDocsAction",
        &serde_json::json!({
            "action": "readResource",
            "additionalDocsFolders": additional_docs_folders_text,
            "path": relative_path,
            "projectId": project_id,
            "requestId": request_id,
        }),
        Duration::from_secs(30),
    )
    .ok()?;
    if !response.is_object()
        || response.get("action").and_then(serde_json::Value::as_str) != Some("readResource")
        || response
            .get("requestId")
            .and_then(serde_json::Value::as_str)
            != Some(request_id.as_str())
    {
        return None;
    }
    let encoded = response
        .get("dataBase64")
        .and_then(serde_json::Value::as_str)?;
    let data = BASE64_STANDARD.decode(encoded).ok()?;
    (data.len() <= MANAGE_REMOTE_RESOURCE_MAX_BYTES).then_some(data)
}

fn manage_files_bridge_result(
    request: &serde_json::Value,
    snapshot: Option<&GpuiProjectSnapshot>,
    additional_docs_folders_text: &str,
    global_docs_directory_text: &str,
) -> Result<serde_json::Value, String> {
    /*
    macOS `runManageFilesBridgeRequest` parity: the bridge is DOCS-scoped, not
    a general project browser. The project root's listing walks the docs/
    folder, configured additional Docs folders, and root
    Markdown/HTML/Excalidraw artifacts; a configured Docs directory is mounted
    ALONGSIDE it and walks its whole tree (CDXC:DocsRootAdditive,
    CDXC:DocsRootRecursive). Either way
    read/stat/save/rename/duplicate/delete/createFolder/move all validate against
    the allowlist of the root the path was routed to, and text previews carry the
    Git HEAD baseline for meo's gutter. Every response's rootName is the fixed
    docs scope name.
    */
    let action = manage_request_string(request, "action").unwrap_or_default();
    let request_id = manage_request_string(request, "requestId").unwrap_or_default();
    let snapshot = snapshot.ok_or_else(|| "No active project root is available.".to_string())?;
    let roots = manage_docs_root(
        snapshot.active_project_id.as_ref().map(|id| id.0.as_str()),
        snapshot.in_memory_project_path.as_deref(),
        global_docs_directory_text,
    )?;
    manage_validate_request_identity(request, snapshot)?;
    let context = ManageDocsContext {
        additional_docs_folders_text,
        roots: &roots,
    };

    match action.as_str() {
        "list" => Ok(serde_json::json!({
            "action": action,
            "entries": manage_project_file_entries(context)?,
            "requestId": request_id,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        "read" => Ok(serde_json::json!({
            "action": action,
            "file": manage_project_file_preview(
                context,
                manage_request_string(request, "path").as_deref(),
            )?,
            "requestId": request_id,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        "stat" => Ok(serde_json::json!({
            "action": action,
            "file": manage_project_file_metadata(
                context,
                manage_request_string(request, "path").as_deref(),
            )?,
            "requestId": request_id,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        "save" => Ok(serde_json::json!({
            "action": action,
            "file": manage_save_project_file(
                context,
                manage_request_string(request, "path").as_deref(),
                manage_request_string(request, "content").as_deref(),
            )?,
            "requestId": request_id,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        "rename" => Ok(serde_json::json!({
            "action": action,
            "file": manage_rename_project_file(
                context,
                manage_request_string(request, "path").as_deref(),
                manage_request_string(request, "newPath").as_deref(),
            )?,
            "requestId": request_id,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        "duplicate" => Ok(serde_json::json!({
            "action": action,
            "file": manage_duplicate_project_file(
                context,
                manage_request_string(request, "path").as_deref(),
                manage_request_string(request, "newPath").as_deref(),
            )?,
            "requestId": request_id,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        "delete" => {
            manage_delete_project_file(context, manage_request_string(request, "path").as_deref())?;
            Ok(serde_json::json!({
                "action": action,
                "requestId": request_id,
                "rootName": MANAGE_DOCS_RELATIVE_PATH,
            }))
        }
        "createFolder" => {
            manage_create_project_folder(
                context,
                manage_request_string(request, "path").as_deref(),
            )?;
            Ok(serde_json::json!({
                "action": action,
                "requestId": request_id,
                "rootName": MANAGE_DOCS_RELATIVE_PATH,
            }))
        }
        "move" => Ok(serde_json::json!({
            "action": action,
            "file": manage_move_project_item(
                context,
                manage_request_string(request, "path").as_deref(),
                manage_request_string(request, "newPath").as_deref(),
            )?,
            "requestId": request_id,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        "revealInFinder" => Ok(serde_json::json!({
            "action": action,
            "requestId": request_id,
            "revealPath": manage_docs_action_item_path(
                context,
                manage_request_string(request, "path").as_deref(),
                "Select an item to reveal.",
            )?,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        "copyFullPath" => Ok(serde_json::json!({
            "action": action,
            "fullPath": manage_docs_action_item_path(
                context,
                manage_request_string(request, "path").as_deref(),
                "Select an item to copy its full path.",
            )?,
            "requestId": request_id,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        "addToSessionContext" => Ok(serde_json::json!({
            "action": action,
            "contextPrompt": manage_session_context_prompt(
                context,
                manage_request_string(request, "path").as_deref(),
            )?,
            "requestId": request_id,
            "rootName": MANAGE_DOCS_RELATIVE_PATH,
        })),
        _ => Err("Unsupported Docs file action.".to_string()),
    }
}

fn manage_docs_action_item<'a>(
    context: ManageDocsContext<'a>,
    path: Option<&str>,
    unavailable_message: &str,
) -> Result<(PathBuf, ManageDocsPath<'a>, fs::Metadata), String> {
    let path = manage_docs_path(context, path)?;
    if path.inner.is_empty() {
        return Err(unavailable_message.to_string());
    }
    let target = manage_operation_url(&path)?;
    manage_validate_docs_action_relative_path(&path, context)?;
    let metadata = fs::metadata(&target).map_err(|_| unavailable_message.to_string())?;
    Ok((target, path, metadata))
}

fn manage_docs_action_item_path(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
    unavailable_message: &str,
) -> Result<String, String> {
    let (target, _, _) = manage_docs_action_item(context, path, unavailable_message)?;
    Ok(target.to_string_lossy().into_owned())
}

fn manage_session_context_prompt(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
) -> Result<String, String> {
    /*
    CDXC:ManageFileActions 2026-08-08:
    Session-context staging reads only a validated Docs file, caps it before
    and after the read, rejects binary/non-UTF-8 content, and formats a fenced
    relative-path block. The CEF response strips this private prompt before
    dispatch; only the selected live agent terminal receives it.
    */
    let unavailable = "Select a file to add to session context.";
    let (target, path, metadata) = manage_docs_action_item(context, path, unavailable)?;
    /*
    CDXC:DocsRootAdditive 2026-08-09:
    The prompt names the file the way the Docs tree does — the mount's own name,
    not the reserved routing segment — because this text is read by a human and
    by the agent in the terminal it is pasted into.
    */
    let relative_path = path.display(context);
    if !metadata.is_file() {
        return Err(unavailable.to_string());
    }
    if metadata.len() > MANAGE_SESSION_CONTEXT_MAX_BYTES as u64 {
        return Err("File is too large to add to session context.".to_string());
    }
    let data = fs::read(&target).map_err(|_| unavailable.to_string())?;
    if data.len() > MANAGE_SESSION_CONTEXT_MAX_BYTES {
        return Err("File is too large to add to session context.".to_string());
    }
    if data.contains(&0) {
        return Err("Only UTF-8 text files can be added to session context.".to_string());
    }
    let text = String::from_utf8(data)
        .map_err(|_| "Only UTF-8 text files can be added to session context.".to_string())?;
    let fence = manage_session_context_fence(&text);
    let language = manage_session_context_language(&relative_path);
    let fence_header = if language.is_empty() {
        fence.clone()
    } else {
        format!("{fence}{language}")
    };
    Ok(format!(
        "\nFile context: {relative_path}\n\n{fence_header}\n{text}\n{fence}\n"
    ))
}

fn manage_session_context_fence(text: &str) -> String {
    let mut length = 3;
    while text.contains(&"`".repeat(length)) {
        length += 1;
    }
    "`".repeat(length)
}

fn manage_session_context_language(relative_path: &str) -> &'static str {
    match Path::new(relative_path)
        .extension()
        .and_then(std::ffi::OsStr::to_str)
        .map(str::to_ascii_lowercase)
        .as_deref()
    {
        Some("css") => "css",
        Some("excalidraw" | "json") => "json",
        Some("htm" | "html") => "html",
        Some("js" | "mjs") => "javascript",
        Some("md" | "markdown" | "mdown" | "mkdn") => "markdown",
        Some("sh" | "zsh") => "shell",
        Some("swift") => "swift",
        Some("ts" | "tsx") => "typescript",
        _ => "",
    }
}

/// Mirrors `gxserver-rs/src/project_docs.rs` `DocsContext`: both mounted roots
/// plus the project's configured Docs folders, carried as one value so no
/// operation can resolve against one root while validating against the other.
#[derive(Clone, Copy)]
struct ManageDocsContext<'a> {
    additional_docs_folders_text: &'a str,
    roots: &'a ManageDocsRoots,
}

/// Mirrors `DocsPath`: a Docs path routed to its root. `outer` is what the Docs
/// page addresses, `inner` is what the filesystem under `root` sees.
struct ManageDocsPath<'a> {
    extra: bool,
    inner: String,
    outer: String,
    root: &'a Path,
}

impl ManageDocsPath<'_> {
    /// What a human is shown: the mount's own name, never the reserved segment.
    fn display(&self, context: ManageDocsContext<'_>) -> String {
        let Some(mount) = context.roots.extra.as_ref().filter(|_| self.extra) else {
            return self.outer.clone();
        };
        if self.inner.is_empty() {
            mount.name.clone()
        } else {
            format!("{}/{}", mount.name, self.inner)
        }
    }
}

/*
CDXC:DocsRootAdditive 2026-08-09:
Mirrors `docs_path` in `gxserver-rs/src/project_docs.rs`. The reserved mount
segment is the whole routing vocabulary: a path that starts with it belongs to
the mounted Docs directory, anything else is project-relative. One relative path
can therefore only ever mean one root.
*/
fn manage_docs_path<'a>(
    context: ManageDocsContext<'a>,
    path: Option<&str>,
) -> Result<ManageDocsPath<'a>, String> {
    let outer = manage_normalized_relative_path(path)?;
    let Some(inner) = manage_extra_root_relative_path(&outer) else {
        return Ok(ManageDocsPath {
            extra: false,
            inner: outer.clone(),
            outer,
            root: context.roots.project.as_path(),
        });
    };
    let mount = context
        .roots
        .extra
        .as_ref()
        .ok_or_else(|| "No Docs directory is configured.".to_string())?;
    let root = mount.location.as_deref().map_err(|error| error.clone())?;
    Ok(ManageDocsPath {
        extra: true,
        inner,
        outer,
        root,
    })
}

/// `Some(inner path)` when the path addresses the mounted Docs directory.
fn manage_extra_root_relative_path(outer: &str) -> Option<String> {
    if outer == MANAGE_DOCS_EXTRA_ROOT_MOUNT_SEGMENT {
        return Some(String::new());
    }
    outer
        .strip_prefix(&format!("{MANAGE_DOCS_EXTRA_ROOT_MOUNT_SEGMENT}/"))
        .map(str::to_string)
}

fn manage_additional_docs_folder_relative_paths(
    additional_docs_folders_text: &str,
    docs_is_implicit_root: bool,
) -> Vec<String> {
    let mut folders = Vec::new();
    let mut seen = HashSet::new();
    for raw_folder in additional_docs_folders_text.split(',') {
        let trimmed = raw_folder.trim();
        let normalized_separators = trimmed.replace('\\', "/");
        let parts = normalized_separators
            .split('/')
            .filter(|part| !part.is_empty())
            .collect::<Vec<_>>();
        if parts.is_empty()
            || normalized_separators.contains('\0')
            || normalized_separators.starts_with('~')
            || normalized_separators.starts_with('/')
            || parts.iter().any(|part| *part == "." || *part == "..")
        {
            continue;
        }
        let folder = parts.join("/");
        let key = folder.to_lowercase();
        if (docs_is_implicit_root && MANAGE_BUILT_IN_DOCS_RELATIVE_PATHS.contains(&key.as_str()))
            || !seen.insert(key)
        {
            continue;
        }
        folders.push(folder);
    }
    folders
}

/*
CDXC:DocsRootAdditive 2026-08-09:
Mirrors `scan_roots` in `gxserver-rs/src/project_docs.rs`. Docs folders is
project-root-relative again, the meaning it had before a custom root existed:
`docs` plus each configured folder. Round 2 made it narrow the custom root
instead; with additive mounting that is no longer coherent, because the mounted
Docs directory always shows its whole tree.
*/
fn manage_docs_scan_root_relative_paths(additional_docs_folders_text: &str) -> Vec<String> {
    let mut roots = MANAGE_BUILT_IN_DOCS_RELATIVE_PATHS
        .iter()
        .map(|path| (*path).to_string())
        .collect::<Vec<_>>();
    roots.extend(manage_additional_docs_folder_relative_paths(
        additional_docs_folders_text,
        true,
    ));
    roots
}

fn manage_path_is_in_docs_scan_root(
    relative_path: &str,
    additional_docs_folders_text: &str,
) -> bool {
    manage_docs_scan_root_relative_paths(additional_docs_folders_text)
        .iter()
        .any(|root| relative_path == root || relative_path.starts_with(&format!("{root}/")))
}

fn manage_path_is_docs_scan_root(relative_path: &str, additional_docs_folders_text: &str) -> bool {
    manage_docs_scan_root_relative_paths(additional_docs_folders_text)
        .iter()
        .any(|root| relative_path == root)
}

/// The nodes no operation may rename, move, or delete: the project root's scan
/// roots, and the mounted Docs directory itself.
fn manage_path_is_docs_root_node(
    path: &ManageDocsPath<'_>,
    context: ManageDocsContext<'_>,
) -> bool {
    if path.extra {
        return path.inner.is_empty();
    }
    manage_path_is_docs_scan_root(&path.inner, context.additional_docs_folders_text)
}

/// The extensions the Docs surface renders. One list for root artifacts and for
/// custom-root tree discovery, so the two can never drift apart.
fn manage_has_docs_artifact_extension(name: &str) -> bool {
    name.rsplit_once('.').is_some_and(|(_, extension)| {
        MANAGE_ROOT_ARTIFACT_FILE_EXTENSIONS.contains(&extension.to_ascii_lowercase().as_str())
    })
}

fn manage_is_root_artifact_file_relative_path(relative_path: &str) -> bool {
    if relative_path.is_empty() || relative_path.contains('/') {
        return false;
    }
    manage_has_docs_artifact_extension(relative_path)
}

/*
CDXC:GPUISessionChatLinks 2026-08-03:
Docs can only show what its own bridge will read: a Markdown/HTML/Excalidraw
artifact that is either a direct repo-root artifact or inside a configured Docs
folder. A chat file link that fails this test is not a Docs file, so it opens in
Code instead of bouncing off the Docs allowlist with an error.
*/
fn session_chat_file_opens_in_docs(
    relative_path: &str,
    additional_docs_folders_text: &str,
) -> bool {
    if !manage_has_docs_artifact_extension(relative_path) {
        return false;
    }
    // A chat link is a path inside the project, so it is tested against the
    // project root's own allowlist, never the mounted Docs directory's.
    manage_path_is_in_docs_scan_root(relative_path, additional_docs_folders_text)
        || manage_is_root_artifact_file_relative_path(relative_path)
}

/*
CDXC:DocsRootAdditive 2026-08-09:
The mounted Docs directory serves its whole tree, so a path that routed there
needs no further allowlist: canonicalization already confined it to that root.
Project-root paths keep exactly the allowlist they have always had.
*/
fn manage_validate_accessible_relative_path(
    path: &ManageDocsPath<'_>,
    context: ManageDocsContext<'_>,
) -> Result<(), String> {
    if path.extra
        || path.inner == MANAGE_ANNOTATIONS_SIDECAR_RELATIVE_PATH
        || manage_path_is_in_docs_scan_root(&path.inner, context.additional_docs_folders_text)
        || manage_is_root_artifact_file_relative_path(&path.inner)
    {
        return Ok(());
    }
    Err(
        "Docs files must be inside configured Docs folders or be root Markdown, HTML, or Excalidraw files."
            .to_string(),
    )
}

fn manage_validate_docs_tree_relative_path(
    path: &ManageDocsPath<'_>,
    context: ManageDocsContext<'_>,
) -> Result<(), String> {
    if path.extra
        || manage_path_is_in_docs_scan_root(&path.inner, context.additional_docs_folders_text)
    {
        return Ok(());
    }
    Err("Docs items must be inside configured Docs folders.".to_string())
}

fn manage_validate_docs_action_relative_path(
    path: &ManageDocsPath<'_>,
    context: ManageDocsContext<'_>,
) -> Result<(), String> {
    if path.extra
        || manage_path_is_in_docs_scan_root(&path.inner, context.additional_docs_folders_text)
        || manage_is_root_artifact_file_relative_path(&path.inner)
    {
        return Ok(());
    }
    Err(
        "Docs items must be inside configured Docs folders or be root Markdown, HTML, or Excalidraw files."
            .to_string(),
    )
}

/// Two operations must never straddle the mount: a rename, duplicate, or move
/// that crosses roots is refused rather than silently rewriting one root's file
/// into the other.
fn manage_require_same_docs_root(
    source: &ManageDocsPath<'_>,
    destination: &ManageDocsPath<'_>,
) -> Result<(), String> {
    if source.extra == destination.extra {
        return Ok(());
    }
    Err("Docs cannot move items between the project and the Docs directory.".to_string())
}

fn manage_parent_relative_path(relative_path: &str) -> String {
    let components = relative_path
        .split('/')
        .filter(|component| !component.is_empty())
        .collect::<Vec<_>>();
    if components.len() <= 1 {
        return String::new();
    }
    components[..components.len() - 1].join("/")
}

fn manage_request_string(request: &serde_json::Value, key: &str) -> Option<String> {
    request
        .get(key)
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
}

fn manage_validate_request_identity(
    request: &serde_json::Value,
    snapshot: &GpuiProjectSnapshot,
) -> Result<(), String> {
    let active_project_id = snapshot
        .active_project_id
        .as_ref()
        .map(|id| id.0.as_str())
        .unwrap_or("");
    let manage_surface_id = snapshot
        .surface_ids
        .manage_workspace_id
        .as_deref()
        .unwrap_or("");
    for key in ["projectId", "projectEditorId"] {
        let Some(value) = request
            .get(key)
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            continue;
        };
        if value != active_project_id && value != manage_surface_id {
            return Err("Manage request was not sent by this project editor.".to_string());
        }
    }
    Ok(())
}

/*
CDXC:DocsRootDirectory 2026-08-09:
The ONE place the local Docs roots are resolved: the project's own Docs
directory, then the Docs directory Global Default. Every local Docs caller (the
CEF files bridge and the Docs resource scope) goes through here, so the cascade
exists once.

CDXC:DocsRootAdditive 2026-08-09:
The project root is ALWAYS mounted; a configured Docs directory is mounted in
addition to it, never instead of it. Blank is the only value that inherits, and
a configured path that is missing, is not a folder, or is not absolute is
carried as an unavailable mount rather than failing the panel: the project's own
docs keep listing and the mount node names the path that failed. That is still
not a silent fallback — a silent revert reads exactly like "my vault is empty"
and hides the typo that caused it.
*/
fn manage_docs_root(
    project_id: Option<&str>,
    in_memory_project_path: Option<&Path>,
    global_docs_directory: &str,
) -> Result<ManageDocsRoots, String> {
    let configured = match manage_project_docs_directory(project_id)? {
        Some(directory) => directory,
        None => global_docs_directory.trim().to_string(),
    };
    let project = manage_in_memory_project_root(in_memory_project_path)?;
    if configured.is_empty() {
        return Ok(ManageDocsRoots {
            project,
            extra: None,
        });
    }
    Ok(ManageDocsRoots {
        project,
        extra: Some(ManageDocsExtraMount {
            location: manage_configured_docs_root(&configured),
            name: manage_docs_extra_root_name(&configured),
        }),
    })
}

/// The mount's label: the configured folder's own basename, so a vault at
/// `/Users/sven/vault` shows up as a top-level `vault` folder.
fn manage_docs_extra_root_name(configured: &str) -> String {
    let path = manage_expanded_docs_directory_path(configured);
    path.file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| path.to_string_lossy().into_owned())
}

/*
CDXC:DocsRootAdditive 2026-08-09:
Mirrors `DocsRoots` in `gxserver-rs/src/project_docs.rs`: the two roots one Docs
request sees, canonicalized. The mount carries either where its folder is or why
it could not be opened, because that failure belongs on one tree node instead of
on the whole listing.
*/
struct ManageDocsRoots {
    extra: Option<ManageDocsExtraMount>,
    project: PathBuf,
}

struct ManageDocsExtraMount {
    location: Result<PathBuf, String>,
    name: String,
}

/// The project's own Docs directory, or `None` when it stores none. An
/// unreadable project row is an error, never "no override": answering "no
/// override" would silently point Docs at the wrong folder.
fn manage_project_docs_directory(project_id: Option<&str>) -> Result<Option<String>, String> {
    let Some(project_id) = gpui_trimmed_nonempty_str(project_id) else {
        return Ok(None);
    };
    let project = gpui_find_gxserver_project_by_id(project_id)
        .map_err(|_| "Ghostex could not read this project's Docs directory setting.".to_string())?;
    Ok(project
        .get("projectBoardConfig")
        .and_then(serde_json::Value::as_object)
        .and_then(|config| gpui_trimmed_json_string_field(config, "docsDirectory"))
        .map(str::to_string))
}

/// Validate a configured Docs directory: absolute (after expanding a leading
/// `~`) and an existing folder.
fn manage_configured_docs_root(configured: &str) -> Result<PathBuf, String> {
    let path = manage_expanded_docs_directory_path(configured);
    if !path.is_absolute() {
        return Err(format!(
            "Docs directory must be an absolute path: {configured}"
        ));
    }
    let metadata = fs::metadata(&path)
        .map_err(|_| format!("Docs directory does not exist: {}", path.display()))?;
    if !metadata.is_dir() {
        return Err(format!(
            "Docs directory is not a folder: {}",
            path.display()
        ));
    }
    fs::canonicalize(&path)
        .map_err(|_| format!("Docs directory is unavailable: {}", path.display()))
}

fn manage_expanded_docs_directory_path(configured: &str) -> PathBuf {
    let Some(rest) = configured.strip_prefix('~') else {
        return PathBuf::from(configured);
    };
    let home = shared_settings::ghostex_storage_paths().home_dir.clone();
    let rest = rest.trim_start_matches(['/', '\\']);
    if rest.is_empty() {
        home
    } else {
        home.join(rest)
    }
}

fn manage_in_memory_project_root(path: Option<&Path>) -> Result<PathBuf, String> {
    let path = path.ok_or_else(|| "No active project root is available.".to_string())?;
    #[cfg(target_os = "windows")]
    let path = windows_terminal_backend::windows_path_for_wsl_path(path)
        .map_err(|_| "The active project root is unavailable.".to_string())?;
    #[cfg(not(target_os = "windows"))]
    let path = path.to_path_buf();
    let metadata =
        fs::metadata(&path).map_err(|_| "The active project root is unavailable.".to_string())?;
    if !metadata.is_dir() {
        return Err("The active project root is unavailable.".to_string());
    }
    fs::canonicalize(&path).map_err(|_| "The active project root is unavailable.".to_string())
}

fn manage_files_bridge_error_response(
    action: &str,
    request_id: &str,
    error: &str,
) -> serde_json::Value {
    serde_json::json!({
        "action": action,
        "error": error,
        "requestId": request_id,
    })
}

/*
CDXC:DocsRootAdditive 2026-08-09:
The project's own entries come first and are discovered exactly as they have
always been, so setting a Docs directory can never take the repo's README.md,
CLAUDE.md, or docs/ away. The mounted Docs directory is appended after them.
*/
fn manage_project_file_entries(
    context: ManageDocsContext<'_>,
) -> Result<Vec<serde_json::Value>, String> {
    let mut entries = manage_project_root_file_entries(context.roots.project.as_path(), context)?;
    if let Some(mount) = context.roots.extra.as_ref() {
        manage_append_docs_extra_root_entries(&mut entries, mount);
    }
    Ok(entries)
}

fn manage_project_root_file_entries(
    root: &Path,
    context: ManageDocsContext<'_>,
) -> Result<Vec<serde_json::Value>, String> {
    /*
    macOS `manageProjectFileEntries` parity: docs/ and each configured Docs
    folder render as their own top-level directory entries, direct repo-root
    Markdown/HTML/Excalidraw artifacts join them, and only the scan roots are
    walked (bounded), so the Docs sidebar never becomes a broad repo browser.
    */
    let mut entries = Vec::new();
    let scan_roots = manage_docs_scan_root_relative_paths(context.additional_docs_folders_text);
    for relative_path in &scan_roots {
        let Some(directory) = manage_project_directory(root, relative_path) else {
            continue;
        };
        let modified_at = fs::metadata(&directory)
            .ok()
            .and_then(|metadata| metadata.modified().ok())
            .map(gpui_iso8601_utc);
        entries.push(serde_json::json!({
            "depth": 0,
            "kind": "directory",
            "modifiedAt": modified_at,
            "name": relative_path,
            "path": relative_path,
            "size": serde_json::Value::Null,
        }));
    }
    manage_append_project_root_artifact_file_entries(&mut entries, root)?;
    for relative_path in &scan_roots {
        if entries.len() >= MANAGE_FILE_LIST_MAX_ENTRIES {
            break;
        }
        let Some(directory) = manage_project_directory(root, relative_path) else {
            continue;
        };
        manage_append_project_file_entries(&mut entries, root, &directory, relative_path, 1)?;
    }
    Ok(entries)
}

fn manage_project_directory(root: &Path, relative_path: &str) -> Option<PathBuf> {
    let directory = root.join(PathBuf::from(relative_path));
    let metadata = fs::metadata(&directory).ok()?;
    if !metadata.is_dir() {
        return None;
    }
    let resolved = fs::canonicalize(&directory).ok()?;
    path_is_inside_or_equal(&resolved, root).then_some(resolved)
}

/*
CDXC:DocsRootRecursive 2026-08-09:
Mirrors `append_extra_root_entries` in `gxserver-rs/src/project_docs.rs`, so the
local Docs pane and a remote project's Docs pane list the same tree. The mounted
Docs directory is walked to the bottom and files are narrowed to the extensions
Docs renders.

CDXC:DocsRootAdditive 2026-08-09: every failure lands on the mount node's label
instead of on the listing — an unopenable directory, and the entry and depth caps
alike. Losing the whole panel, including the project's own README.md, because a
vault is too deep is the one thing this must not do, and a tree that silently
stopped at 20,000 entries reads exactly like a vault that only has that many.
*/
fn manage_append_docs_extra_root_entries(
    entries: &mut Vec<serde_json::Value>,
    mount: &ManageDocsExtraMount,
) {
    let root = match mount.location.as_deref() {
        Ok(root) => root,
        Err(error) => {
            entries.push(manage_unavailable_docs_extra_root_entry(&mount.name, error));
            return;
        }
    };
    let mut tree = Vec::new();
    let mut scanned_directory_entries = 0;
    if let Err(error) = manage_append_docs_tree_entries(
        &mut tree,
        root,
        root,
        MANAGE_DOCS_EXTRA_ROOT_MOUNT_SEGMENT,
        1,
        &mut scanned_directory_entries,
    ) {
        entries.push(manage_unavailable_docs_extra_root_entry(
            &mount.name,
            &error,
        ));
        return;
    }
    let modified_at = fs::metadata(root)
        .ok()
        .and_then(|metadata| metadata.modified().ok())
        .map(gpui_iso8601_utc);
    entries.push(serde_json::json!({
        "depth": 0,
        "displayPath": mount.name,
        "kind": "directory",
        "modifiedAt": modified_at,
        "name": mount.name,
        "path": MANAGE_DOCS_EXTRA_ROOT_MOUNT_SEGMENT,
        "size": serde_json::Value::Null,
    }));
    manage_name_docs_extra_root_tree_entries(&mut tree, &mount.name);
    entries.append(&mut tree);
}

/*
CDXC:DocsRootAdditive 2026-08-10:
Mirrors `name_extra_root_tree_entries` in gxserver-rs/src/project_docs.rs: every
mounted entry carries the name the tree shows it under beside the routing
address it answers to, so the reserved segment never reaches Copy Path or text
pasted into a terminal.
*/
fn manage_name_docs_extra_root_tree_entries(tree: &mut [serde_json::Value], mount_name: &str) {
    for entry in tree {
        let Some(relative_path) = entry
            .get("path")
            .and_then(serde_json::Value::as_str)
            .and_then(|path| path.strip_prefix(MANAGE_DOCS_EXTRA_ROOT_MOUNT_SEGMENT))
        else {
            continue;
        };
        let display_path = format!("{mount_name}{relative_path}");
        if let Some(entry) = entry.as_object_mut() {
            entry.insert(
                "displayPath".to_string(),
                serde_json::Value::String(display_path),
            );
        }
    }
}

/// The mount still shows when its folder does not, carrying the reason in the
/// only field the Docs tree renders. A missing vault must look missing, not
/// look empty.
fn manage_unavailable_docs_extra_root_entry(name: &str, error: &str) -> serde_json::Value {
    serde_json::json!({
        "depth": 0,
        "kind": "directory",
        "displayPath": name,
        "modifiedAt": serde_json::Value::Null,
        "name": format!("{name} — {error}"),
        "path": MANAGE_DOCS_EXTRA_ROOT_MOUNT_SEGMENT,
        "size": serde_json::Value::Null,
    })
}

/// The scan budget the gxserver walk enforces, so a folder full of files Docs
/// does not render costs the same on both sides instead of being free here.
fn manage_bounded_docs_tree_children(
    directory: &Path,
    scanned_directory_entries: &mut usize,
) -> Result<Vec<fs::DirEntry>, String> {
    let mut children = Vec::new();
    for child in fs::read_dir(directory).map_err(|_| "Could not list project files.".to_string())? {
        if *scanned_directory_entries >= MANAGE_DOCS_TREE_MAX_ENTRIES {
            return Err(manage_docs_tree_entry_cap_error());
        }
        *scanned_directory_entries += 1;
        if let Ok(child) = child {
            children.push(child);
        }
    }
    Ok(children)
}

fn manage_append_docs_tree_entries(
    entries: &mut Vec<serde_json::Value>,
    root: &Path,
    directory: &Path,
    relative_directory_path: &str,
    depth: usize,
    scanned_directory_entries: &mut usize,
) -> Result<(), String> {
    if depth > MANAGE_DOCS_TREE_MAX_DEPTH {
        return Err(manage_docs_tree_depth_cap_error());
    }
    let mut children = manage_bounded_docs_tree_children(directory, scanned_directory_entries)?;
    children.sort_by(|left, right| {
        let left_is_dir = left
            .metadata()
            .map(|metadata| metadata.is_dir())
            .unwrap_or(false);
        let right_is_dir = right
            .metadata()
            .map(|metadata| metadata.is_dir())
            .unwrap_or(false);
        right_is_dir
            .cmp(&left_is_dir)
            .then_with(|| left.file_name().cmp(&right.file_name()))
    });

    let mut directories = Vec::new();
    for child in children {
        if entries.len() >= MANAGE_DOCS_TREE_MAX_ENTRIES {
            return Err(manage_docs_tree_entry_cap_error());
        }
        let name = child.file_name().to_string_lossy().to_string();
        let metadata = match child.metadata() {
            Ok(metadata) => metadata,
            Err(_) => continue,
        };
        let is_directory = metadata.is_dir();
        if is_directory {
            if name.starts_with('.') || MANAGE_IGNORED_DIRECTORY_NAMES.contains(&name.as_str()) {
                continue;
            }
        } else if !manage_has_docs_artifact_extension(&name) {
            continue;
        }
        // Confinement, and the reason an outward symlink never joins the tree.
        let resolved = match fs::canonicalize(child.path()) {
            Ok(resolved) => resolved,
            Err(_) => continue,
        };
        if !path_is_inside_or_equal(&resolved, root) {
            continue;
        }
        let relative_path = format!("{relative_directory_path}/{name}");
        entries.push(serde_json::json!({
            "depth": depth,
            "kind": if is_directory { "directory" } else { "file" },
            "modifiedAt": metadata.modified().ok().map(gpui_iso8601_utc),
            "name": name,
            "path": relative_path,
            "size": if is_directory { None } else { Some(metadata.len()) },
        }));
        if is_directory
            && !child
                .file_type()
                .map(|file_type| file_type.is_symlink())
                .unwrap_or(false)
        {
            directories.push((child.path(), relative_path));
        }
    }

    for (directory, relative_path) in directories {
        manage_append_docs_tree_entries(
            entries,
            root,
            &directory,
            &relative_path,
            depth + 1,
            scanned_directory_entries,
        )?;
    }
    Ok(())
}

fn manage_docs_tree_entry_cap_error() -> String {
    format!(
        "Docs directory holds more than {MANAGE_DOCS_TREE_MAX_ENTRIES} files and folders. Point it at a smaller folder in Settings > Projects."
    )
}

fn manage_docs_tree_depth_cap_error() -> String {
    format!(
        "Docs directory nests deeper than {MANAGE_DOCS_TREE_MAX_DEPTH} folders. Point it at a smaller folder in Settings > Projects."
    )
}

fn manage_append_project_root_artifact_file_entries(
    entries: &mut Vec<serde_json::Value>,
    root: &Path,
) -> Result<(), String> {
    if entries.len() >= MANAGE_FILE_LIST_MAX_ENTRIES {
        return Ok(());
    }
    let mut children = fs::read_dir(root)
        .map_err(|_| "Could not list project files.".to_string())?
        .filter_map(Result::ok)
        .collect::<Vec<_>>();
    children.sort_by_key(|child| child.file_name());
    for child in children {
        if entries.len() >= MANAGE_FILE_LIST_MAX_ENTRIES {
            return Ok(());
        }
        let name = child.file_name().to_string_lossy().to_string();
        if name == ".DS_Store" || !manage_is_root_artifact_file_relative_path(&name) {
            continue;
        }
        let Ok(metadata) = child.metadata() else {
            continue;
        };
        if metadata.is_dir() {
            continue;
        }
        let Ok(resolved) = fs::canonicalize(child.path()) else {
            continue;
        };
        if !path_is_inside_or_equal(&resolved, root) {
            continue;
        }
        entries.push(serde_json::json!({
            "depth": 0,
            "kind": "file",
            "modifiedAt": metadata.modified().ok().map(gpui_iso8601_utc),
            "name": name,
            "path": name,
            "size": metadata.len(),
        }));
    }
    Ok(())
}

fn manage_append_project_file_entries(
    entries: &mut Vec<serde_json::Value>,
    root: &Path,
    directory: &Path,
    relative_directory_path: &str,
    depth: usize,
) -> Result<(), String> {
    if entries.len() >= MANAGE_FILE_LIST_MAX_ENTRIES || depth > MANAGE_FILE_LIST_MAX_DEPTH {
        return Ok(());
    }
    let mut children = fs::read_dir(directory)
        .map_err(|_| "Could not list project files.".to_string())?
        .filter_map(Result::ok)
        .collect::<Vec<_>>();
    children.sort_by(|left, right| {
        let left_is_dir = left
            .metadata()
            .map(|metadata| metadata.is_dir())
            .unwrap_or(false);
        let right_is_dir = right
            .metadata()
            .map(|metadata| metadata.is_dir())
            .unwrap_or(false);
        right_is_dir
            .cmp(&left_is_dir)
            .then_with(|| left.file_name().cmp(&right.file_name()))
    });

    let mut directories = Vec::new();
    for child in children {
        if entries.len() >= MANAGE_FILE_LIST_MAX_ENTRIES {
            return Ok(());
        }
        let name = child.file_name().to_string_lossy().to_string();
        if name == ".DS_Store" {
            continue;
        }
        let metadata = match child.metadata() {
            Ok(metadata) => metadata,
            Err(_) => continue,
        };
        let is_directory = metadata.is_dir();
        if is_directory && MANAGE_IGNORED_DIRECTORY_NAMES.contains(&name.as_str()) {
            continue;
        }
        let resolved = match fs::canonicalize(child.path()) {
            Ok(resolved) => resolved,
            Err(_) => continue,
        };
        if !path_is_inside_or_equal(&resolved, root) {
            continue;
        }
        let relative_path = if relative_directory_path.is_empty() {
            name.clone()
        } else {
            format!("{relative_directory_path}/{name}")
        };
        entries.push(serde_json::json!({
            "depth": depth,
            "kind": if is_directory { "directory" } else { "file" },
            "modifiedAt": metadata.modified().ok().map(gpui_iso8601_utc),
            "name": name,
            "path": relative_path,
            "size": if is_directory { None } else { Some(metadata.len()) },
        }));
        if is_directory
            && !child
                .file_type()
                .map(|file_type| file_type.is_symlink())
                .unwrap_or(false)
            && depth < MANAGE_FILE_LIST_MAX_DEPTH
        {
            directories.push((child.path(), relative_path));
        }
    }

    for (directory, relative_path) in directories {
        manage_append_project_file_entries(entries, root, &directory, &relative_path, depth + 1)?;
    }
    Ok(())
}

/*
CDXC:DocsRootAdditive 2026-08-09:
Every response carries the path the Docs page addressed, mount segment included,
never the path relative to whichever root answered. A preview that answered with
a bare inner path would hand the page an address that means the project root
next time it is used.
*/
fn manage_project_file_preview(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
) -> Result<serde_json::Value, String> {
    let path = manage_docs_path(context, path)?;
    if path.inner.is_empty() {
        return Err("Select a project file to preview.".to_string());
    }
    let target = manage_existing_url(&path)?;
    manage_validate_accessible_relative_path(&path, context)?;
    let metadata = fs::metadata(&target).map_err(|_| "Select a file to preview.".to_string())?;
    if metadata.is_dir() {
        return Err("Select a file to preview.".to_string());
    }
    let size = metadata.len();
    let name = target
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("")
        .to_string();
    if size > MANAGE_FILE_PREVIEW_MAX_BYTES {
        return Ok(manage_unsupported_file_preview(
            "File is too large to preview.",
            &name,
            &path.outer,
            &path.display(context),
            size,
            &metadata,
        ));
    }
    let data = fs::read(&target).map_err(|_| "Could not read project file.".to_string())?;
    if data.contains(&0) {
        return Ok(manage_unsupported_file_preview(
            "Binary files are not previewed.",
            &name,
            &path.outer,
            &path.display(context),
            size,
            &metadata,
        ));
    }
    let Ok(content) = String::from_utf8(data) else {
        return Ok(manage_unsupported_file_preview(
            "This file is not valid UTF-8 text.",
            &name,
            &path.outer,
            &path.display(context),
            size,
            &metadata,
        ));
    };
    Ok(serde_json::json!({
        "content": content,
        /*
        CDXC:DocsRootAdditive 2026-08-09:
        `path` stays the routing address the page must send back; `displayPath`
        is the same file named the way the tree names it, so the header never
        shows the reserved mount segment.
        */
        "displayPath": path.display(context),
        "gitBaseline": manage_git_baseline_payload(path.root, &target, &path.inner),
        "kind": "text",
        "modifiedAt": metadata.modified().ok().map(gpui_iso8601_utc),
        "name": name,
        "path": path.outer,
        "size": size,
    }))
}

fn manage_project_file_metadata(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
) -> Result<serde_json::Value, String> {
    let path = manage_docs_path(context, path)?;
    if path.inner.is_empty() {
        return Err("Select a project file to inspect.".to_string());
    }
    let target = manage_existing_url(&path)?;
    manage_validate_accessible_relative_path(&path, context)?;
    let metadata = fs::metadata(&target).map_err(|_| "Select a file to inspect.".to_string())?;
    if metadata.is_dir() {
        return Err("Select a file to inspect.".to_string());
    }
    let name = target
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("")
        .to_string();
    Ok(serde_json::json!({
        "kind": "text",
        "modifiedAt": metadata.modified().ok().map(gpui_iso8601_utc),
        "name": name,
        "path": path.outer,
        "size": metadata.len(),
    }))
}

fn manage_unsupported_file_preview(
    error: &str,
    name: &str,
    relative_path: &str,
    display_path: &str,
    size: u64,
    metadata: &fs::Metadata,
) -> serde_json::Value {
    serde_json::json!({
        "displayPath": display_path,
        "error": error,
        "kind": "unsupported",
        "modifiedAt": metadata.modified().ok().map(gpui_iso8601_utc),
        "name": name,
        "path": relative_path,
        "size": size,
    })
}

fn manage_save_project_file(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
    content: Option<&str>,
) -> Result<serde_json::Value, String> {
    let content = content.ok_or_else(|| "No file content was provided.".to_string())?;
    if content.len() > MANAGE_FILE_SAVE_MAX_BYTES {
        return Err("File is too large to save from Docs.".to_string());
    }
    let path = manage_docs_path(context, path)?;
    if path.inner.is_empty() {
        return Err("Select a project file to save.".to_string());
    }
    let target = manage_writable_url(&path)?;
    manage_validate_accessible_relative_path(&path, context)?;
    if fs::metadata(&target)
        .map(|metadata| metadata.is_dir())
        .unwrap_or(false)
    {
        return Err("Select a file to save.".to_string());
    }
    let parent = target
        .parent()
        .ok_or_else(|| "Select a file to save.".to_string())?;
    fs::create_dir_all(parent).map_err(|_| "Could not save project file.".to_string())?;
    let temp = parent.join(format!(
        ".ghostex-gpui-manage-save-{}.tmp",
        system_time_epoch_millis_string(std::time::SystemTime::now())
    ));
    fs::write(&temp, content).map_err(|_| "Could not save project file.".to_string())?;
    fs::rename(&temp, &target).map_err(|_| "Could not save project file.".to_string())?;
    manage_project_file_preview(context, Some(&path.outer))
}

fn manage_rename_project_file(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
    new_path: Option<&str>,
) -> Result<serde_json::Value, String> {
    /*
    macOS `manageRenameProjectFile` parity: same-parent rename of a Docs file
    or folder (or a root artifact file), never a move API, never an overwrite,
    with sanitized errors only.
    */
    let source_path = manage_docs_path(context, path)?;
    let destination_path = manage_docs_path(context, new_path)?;
    manage_require_same_docs_root(&source_path, &destination_path)?;
    if source_path.inner.is_empty()
        || destination_path.inner.is_empty()
        || manage_path_is_docs_root_node(&source_path, context)
        || manage_path_is_docs_root_node(&destination_path, context)
    {
        return Err("Select an item to rename.".to_string());
    }
    let source = manage_operation_url(&source_path)?;
    let destination = manage_operation_url(&destination_path)?;
    manage_validate_docs_action_relative_path(&source_path, context)?;
    manage_validate_docs_action_relative_path(&destination_path, context)?;
    if manage_parent_relative_path(&source_path.inner)
        != manage_parent_relative_path(&destination_path.inner)
    {
        return Err("Docs rename cannot move items.".to_string());
    }
    let source_metadata =
        fs::metadata(&source).map_err(|_| "Select an item to rename.".to_string())?;
    let source_is_directory = source_metadata.is_dir();
    if !source_path.extra
        && manage_is_root_artifact_file_relative_path(&source_path.inner)
        && source_is_directory
    {
        return Err("Select a file to rename.".to_string());
    }
    if source_path.outer == destination_path.outer {
        if !source_is_directory {
            return manage_project_file_preview(context, Some(&source_path.outer));
        }
        return Ok(serde_json::Value::Null);
    }
    manage_require_existing_destination_parent(source_path.root, &destination)
        .map_err(|_| "Docs rename target is unavailable.".to_string())?;
    if destination.exists() {
        return Err("A file or folder with that name already exists.".to_string());
    }
    fs::rename(&source, &destination).map_err(|_| "Could not rename item.".to_string())?;
    if source_is_directory {
        return Ok(serde_json::Value::Null);
    }
    manage_project_file_preview(context, Some(&destination_path.outer))
}

fn manage_delete_project_file(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
) -> Result<(), String> {
    /*
    macOS `manageDeleteProjectFile` parity: files or folders inside Docs scan
    roots (recursive for folders) plus root artifact files; the scan roots
    themselves, and the mounted Docs directory, are never deletable through
    this path.
    */
    let path = manage_docs_path(context, path)?;
    if path.inner.is_empty() || manage_path_is_docs_root_node(&path, context) {
        return Err("Select an item to delete.".to_string());
    }
    let target = manage_operation_url(&path)?;
    manage_validate_docs_action_relative_path(&path, context)?;
    let metadata = fs::metadata(&target).map_err(|_| "Select an item to delete.".to_string())?;
    let is_directory = metadata.is_dir();
    if !path.extra && manage_is_root_artifact_file_relative_path(&path.inner) && is_directory {
        return Err("Select a file to delete.".to_string());
    }
    let removed = if is_directory {
        fs::remove_dir_all(&target)
    } else {
        fs::remove_file(&target)
    };
    removed.map_err(|_| "Could not delete item.".to_string())
}

fn manage_duplicate_project_file(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
    new_path: Option<&str>,
) -> Result<serde_json::Value, String> {
    // macOS `manageDuplicateProjectFile` parity: file-only same-folder copy;
    // the page chooses the " (n)" suffix, native rejects overwrites.
    let source_path = manage_docs_path(context, path)?;
    let destination_path = manage_docs_path(context, new_path)?;
    manage_require_same_docs_root(&source_path, &destination_path)?;
    if source_path.inner.is_empty()
        || destination_path.inner.is_empty()
        || manage_path_is_docs_root_node(&source_path, context)
        || manage_path_is_docs_root_node(&destination_path, context)
    {
        return Err("Select a file to duplicate.".to_string());
    }
    let source = manage_operation_url(&source_path)?;
    let destination = manage_operation_url(&destination_path)?;
    manage_validate_docs_action_relative_path(&source_path, context)?;
    manage_validate_docs_action_relative_path(&destination_path, context)?;
    if manage_parent_relative_path(&source_path.inner)
        != manage_parent_relative_path(&destination_path.inner)
    {
        return Err("Docs duplicate cannot move files.".to_string());
    }
    let source_metadata =
        fs::metadata(&source).map_err(|_| "Select a file to duplicate.".to_string())?;
    if source_metadata.is_dir() {
        return Err("Select a file to duplicate.".to_string());
    }
    manage_require_existing_destination_parent(source_path.root, &destination)
        .map_err(|_| "Duplicate target is unavailable.".to_string())?;
    if destination.exists() {
        return Err("A file with that name already exists.".to_string());
    }
    fs::copy(&source, &destination).map_err(|_| "Could not duplicate file.".to_string())?;
    manage_project_file_preview(context, Some(&destination_path.outer))
}

fn manage_create_project_folder(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
) -> Result<(), String> {
    // macOS `manageCreateProjectFolder` parity: docs-scoped folder creation;
    // the docs/ root is created on demand, overwrites are rejected.
    let path = manage_docs_path(context, path)?;
    if path.inner.is_empty() || manage_path_is_docs_root_node(&path, context) {
        return Err("Select a folder to create.".to_string());
    }
    let target = manage_operation_url(&path)?;
    manage_validate_docs_tree_relative_path(&path, context)?;
    if !path.extra
        && path
            .inner
            .starts_with(&format!("{MANAGE_DOCS_RELATIVE_PATH}/"))
    {
        let docs = path.root.join(MANAGE_DOCS_RELATIVE_PATH);
        fs::create_dir_all(&docs).map_err(|_| "Could not create folder.".to_string())?;
    }
    manage_require_existing_destination_parent(path.root, &target)
        .map_err(|_| "Folder parent is unavailable.".to_string())?;
    if target.exists() {
        return Err("A file or folder with that name already exists.".to_string());
    }
    fs::create_dir(&target).map_err(|_| "Could not create folder.".to_string())
}

fn manage_move_project_item(
    context: ManageDocsContext<'_>,
    path: Option<&str>,
    new_path: Option<&str>,
) -> Result<serde_json::Value, String> {
    /*
    macOS `manageMoveProjectItem` parity: drag/drop moves Docs items (and root
    artifact files) into docs-scoped destinations only, rejecting overwrites
    and directory self-nesting.
    */
    let source_path = manage_docs_path(context, path)?;
    let destination_path = manage_docs_path(context, new_path)?;
    manage_require_same_docs_root(&source_path, &destination_path)?;
    if source_path.inner.is_empty()
        || destination_path.inner.is_empty()
        || manage_path_is_docs_root_node(&source_path, context)
        || manage_path_is_docs_root_node(&destination_path, context)
    {
        return Err("Select an item to move.".to_string());
    }
    let source = manage_operation_url(&source_path)?;
    let destination = manage_operation_url(&destination_path)?;
    manage_validate_docs_action_relative_path(&source_path, context)?;
    manage_validate_docs_tree_relative_path(&destination_path, context)?;
    if source_path.outer == destination_path.outer {
        let is_file = fs::metadata(&source)
            .map(|metadata| !metadata.is_dir())
            .unwrap_or(false);
        if is_file {
            return manage_project_file_preview(context, Some(&source_path.outer));
        }
        return Ok(serde_json::Value::Null);
    }
    let source_metadata =
        fs::metadata(&source).map_err(|_| "Select an item to move.".to_string())?;
    let source_is_directory = source_metadata.is_dir();
    if !source_path.extra
        && manage_is_root_artifact_file_relative_path(&source_path.inner)
        && source_is_directory
    {
        return Err("Select a file to move.".to_string());
    }
    if source_is_directory
        && destination_path
            .inner
            .starts_with(&format!("{}/", source_path.inner))
    {
        return Err("Folders cannot be moved inside themselves.".to_string());
    }
    manage_require_existing_destination_parent(source_path.root, &destination)
        .map_err(|_| "Move target is unavailable.".to_string())?;
    if destination.exists() {
        return Err("A file or folder with that name already exists.".to_string());
    }
    fs::rename(&source, &destination).map_err(|_| "Could not move item.".to_string())?;
    if source_is_directory {
        return Ok(serde_json::Value::Null);
    }
    manage_project_file_preview(context, Some(&destination_path.outer))
}

/// macOS `manageFileOperationURL` parity: resolve symlinks for the escape
/// check, but return the UNRESOLVED path so a listed symlink entry is operated
/// on as the entry itself.
fn manage_operation_url(path: &ManageDocsPath<'_>) -> Result<PathBuf, String> {
    let target = if path.inner.is_empty() {
        path.root.to_path_buf()
    } else {
        path.root.join(PathBuf::from(&path.inner))
    };
    if let Ok(resolved) = fs::canonicalize(&target) {
        if !path_is_inside_or_equal(&resolved, path.root) {
            return Err("Docs paths must stay inside the project.".to_string());
        }
    } else {
        let parent = target
            .parent()
            .ok_or_else(|| "Docs paths must stay inside the project.".to_string())?;
        let nearest_existing_parent = nearest_existing_ancestor(parent)
            .ok_or_else(|| "Docs paths must stay inside the project.".to_string())?;
        let resolved_parent = fs::canonicalize(nearest_existing_parent)
            .map_err(|_| "Docs paths must stay inside the project.".to_string())?;
        if !path_is_inside_or_equal(&resolved_parent, path.root) {
            return Err("Docs paths must stay inside the project.".to_string());
        }
    }
    Ok(target)
}

fn manage_require_existing_destination_parent(
    root: &Path,
    destination: &Path,
) -> Result<(), String> {
    let parent = destination
        .parent()
        .ok_or_else(|| "unavailable".to_string())?;
    let resolved_parent = fs::canonicalize(parent).map_err(|_| "unavailable".to_string())?;
    let metadata = fs::metadata(&resolved_parent).map_err(|_| "unavailable".to_string())?;
    if !metadata.is_dir() || !path_is_inside_or_equal(&resolved_parent, root) {
        return Err("unavailable".to_string());
    }
    Ok(())
}

fn manage_run_git(arguments: &[&str], cwd: &Path) -> Option<(i32, Vec<u8>)> {
    let output = std::process::Command::new("/usr/bin/git")
        .args(arguments)
        .current_dir(cwd)
        .stdin(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .output()
        .ok()?;
    Some((output.status.code().unwrap_or(-1), output.stdout))
}

fn manage_git_trimmed_output(stdout: &[u8]) -> String {
    String::from_utf8_lossy(stdout).trim().to_string()
}

fn manage_unavailable_git_baseline(reason: &str) -> serde_json::Value {
    serde_json::json!({
        "available": false,
        "baseText": serde_json::Value::Null,
        "headOid": serde_json::Value::Null,
        "maxBytesExceeded": serde_json::Value::Null,
        "reason": reason,
        "tracked": false,
    })
}

fn manage_renderable_git_baseline(
    base_text: Option<String>,
    head_oid: Option<&str>,
    max_bytes_exceeded: Option<bool>,
    reason: Option<&str>,
    tracked: bool,
) -> serde_json::Value {
    serde_json::json!({
        "available": true,
        "baseText": base_text,
        "headOid": head_oid,
        "maxBytesExceeded": max_bytes_exceeded,
        "reason": reason,
        "tracked": tracked,
    })
}

fn manage_git_baseline_payload(root: &Path, file: &Path, relative_path: &str) -> serde_json::Value {
    /*
    macOS `manageGitBaselinePayload` parity for meo's CodeMirror Git gutter:
    resolve the repo from the file's parent, reject repos outside the active
    project root, cap baseline text at 1 MB, and return sanitized enum-like
    reasons instead of stderr or filesystem paths.
    */
    if relative_path.is_empty() {
        return manage_unavailable_git_baseline("not-file");
    }
    let Some(parent) = file.parent() else {
        return manage_unavailable_git_baseline("not-repo");
    };
    let Some((exit_code, stdout)) = manage_run_git(&["rev-parse", "--show-toplevel"], parent)
    else {
        return manage_unavailable_git_baseline("git-unavailable");
    };
    if exit_code != 0 {
        return manage_unavailable_git_baseline("not-repo");
    }
    let repo_root_path = manage_git_trimmed_output(&stdout);
    if repo_root_path.is_empty() {
        return manage_unavailable_git_baseline("not-repo");
    }
    let Ok(repo_root) = fs::canonicalize(PathBuf::from(&repo_root_path)) else {
        return manage_unavailable_git_baseline("not-repo");
    };
    if !path_is_inside_or_equal(&repo_root, root) {
        return manage_unavailable_git_baseline("not-repo");
    }
    let Ok(git_path) = file.strip_prefix(&repo_root) else {
        return manage_unavailable_git_baseline("not-repo");
    };
    let git_path = git_path.to_string_lossy().to_string();
    if git_path.is_empty() {
        return manage_unavailable_git_baseline("not-repo");
    }

    let Some((ignore_exit, _)) =
        manage_run_git(&["check-ignore", "-q", "--", &git_path], &repo_root)
    else {
        return manage_unavailable_git_baseline("git-unavailable");
    };
    match ignore_exit {
        0 => return manage_unavailable_git_baseline("ignored"),
        1 => {}
        _ => return manage_unavailable_git_baseline("error"),
    }

    let Some((tracked_exit, _)) = manage_run_git(
        &["ls-files", "--error-unmatch", "--", &git_path],
        &repo_root,
    ) else {
        return manage_unavailable_git_baseline("git-unavailable");
    };
    let tracked = tracked_exit == 0;

    let head_oid = manage_run_git(&["rev-parse", "--verify", "HEAD"], &repo_root)
        .filter(|(exit_code, _)| *exit_code == 0)
        .map(|(_, stdout)| manage_git_trimmed_output(&stdout))
        .filter(|head_oid| !head_oid.is_empty());

    if !tracked || head_oid.is_none() {
        return manage_renderable_git_baseline(None, head_oid.as_deref(), None, None, tracked);
    }
    let head_oid = head_oid.unwrap();
    let head_spec = format!("HEAD:{git_path}");

    let Some((size_exit, size_stdout)) =
        manage_run_git(&["cat-file", "-s", &head_spec], &repo_root)
    else {
        return manage_renderable_git_baseline(None, Some(&head_oid), None, Some("error"), tracked);
    };
    if size_exit != 0 {
        return manage_renderable_git_baseline(None, Some(&head_oid), None, Some("error"), tracked);
    }
    if manage_git_trimmed_output(&size_stdout)
        .parse::<u64>()
        .is_ok_and(|size| size > MANAGE_GIT_BASELINE_MAX_BYTES as u64)
    {
        return manage_renderable_git_baseline(
            None,
            Some(&head_oid),
            Some(true),
            Some("too-large"),
            tracked,
        );
    }
    let Some((baseline_exit, baseline_stdout)) =
        manage_run_git(&["cat-file", "-p", &head_spec], &repo_root)
    else {
        return manage_renderable_git_baseline(None, Some(&head_oid), None, Some("error"), tracked);
    };
    if baseline_exit != 0 {
        return manage_renderable_git_baseline(None, Some(&head_oid), None, Some("error"), tracked);
    }
    if baseline_stdout.len() > MANAGE_GIT_BASELINE_MAX_BYTES {
        return manage_renderable_git_baseline(
            None,
            Some(&head_oid),
            Some(true),
            Some("too-large"),
            tracked,
        );
    }
    if baseline_stdout.contains(&0) {
        return manage_renderable_git_baseline(
            None,
            Some(&head_oid),
            None,
            Some("binary"),
            tracked,
        );
    }
    manage_renderable_git_baseline(
        Some(String::from_utf8_lossy(&baseline_stdout).to_string()),
        Some(&head_oid),
        None,
        None,
        tracked,
    )
}

/*
CDXC:DocsRootAdditive 2026-08-09:
Confinement is per root, and it is the root the path was ROUTED to, so a `..`
chain or an outward symlink under one mount can never surface inside the other.
*/
fn manage_existing_url(path: &ManageDocsPath<'_>) -> Result<PathBuf, String> {
    let target = if path.inner.is_empty() {
        path.root.to_path_buf()
    } else {
        path.root.join(PathBuf::from(&path.inner))
    };
    let resolved = fs::canonicalize(&target)
        .map_err(|_| "Manage paths must stay inside the project.".to_string())?;
    if !path_is_inside_or_equal(&resolved, path.root) {
        return Err("Manage paths must stay inside the project.".to_string());
    }
    Ok(resolved)
}

fn manage_writable_url(path: &ManageDocsPath<'_>) -> Result<PathBuf, String> {
    let target = path.root.join(PathBuf::from(&path.inner));
    let parent = target
        .parent()
        .ok_or_else(|| "Select a project file to save.".to_string())?;
    let nearest_existing_parent = nearest_existing_ancestor(parent)
        .ok_or_else(|| "Manage paths must stay inside the project.".to_string())?;
    let resolved_parent = fs::canonicalize(nearest_existing_parent)
        .map_err(|_| "Manage paths must stay inside the project.".to_string())?;
    if !path_is_inside_or_equal(&resolved_parent, path.root) {
        return Err("Manage paths must stay inside the project.".to_string());
    }
    Ok(target)
}

fn manage_normalized_relative_path(path: Option<&str>) -> Result<String, String> {
    let trimmed = path.unwrap_or("").trim();
    if trimmed.is_empty() {
        return Ok(String::new());
    }
    if trimmed.contains('\0') || trimmed.starts_with('/') {
        return Err("Manage paths must be project-relative.".to_string());
    }
    let components = trimmed
        .split('/')
        .filter(|component| !component.is_empty())
        .collect::<Vec<_>>();
    if components
        .iter()
        .any(|component| *component == "." || *component == "..")
    {
        return Err("Manage paths must stay inside the project.".to_string());
    }
    Ok(components.join("/"))
}

fn nearest_existing_ancestor(path: &Path) -> Option<&Path> {
    path.ancestors().find(|candidate| candidate.exists())
}

fn path_is_inside_or_equal(candidate: &Path, root: &Path) -> bool {
    candidate == root || candidate.starts_with(root)
}

fn system_time_epoch_millis_string(time: std::time::SystemTime) -> String {
    time.duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis().to_string())
        .unwrap_or_else(|_| "0".to_string())
}

#[derive(Clone)]
struct ProjectBoardBridgeRuntimeContext {
    project_id: Option<String>,
    project_path: String,
    remote_machine_id: Option<String>,
    remote_target: Option<GpuiRemoteGxserverRequestTarget>,
}

fn project_board_bridge_runtime_context_from_snapshot(
    snapshot: Option<&GpuiProjectSnapshot>,
) -> Option<ProjectBoardBridgeRuntimeContext> {
    /*
    CDXC:GPUIProjectWorkareaCefBridge 2026-06-24-11:03:
    Kanban and Automate CEF bridge execution may carry only explicit active-project identity from the live sidebar snapshot. The bridge sends gxserver the current project id/path pair for scoped Beads and automation operations, never derives projects from .git/folders/URLs, never launches bd directly, and never logs or persists the private path.
    */
    let snapshot = snapshot?;
    if snapshot.is_quick_projectless
        || (!snapshot.feature_availability.kanban && !snapshot.feature_availability.automate)
    {
        return None;
    }
    let project_path = snapshot
        .in_memory_project_path
        .as_ref()?
        .to_string_lossy()
        .trim()
        .to_string();
    if project_path.is_empty() {
        return None;
    }
    let active_project_id = snapshot
        .active_project_id
        .as_ref()
        .map(|project_id| project_id.0.clone());
    let remote_reference = active_project_id
        .as_deref()
        .and_then(gpui_remote_project_reference_from_project_id);
    Some(ProjectBoardBridgeRuntimeContext {
        project_id: remote_reference
            .as_ref()
            .map(|reference| reference.project_id.clone())
            .or(active_project_id),
        project_path,
        remote_machine_id: remote_reference.map(|reference| reference.remote_machine_id),
        remote_target: None,
    })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GpuiProjectBoardCommandIntent {
    InitializeBeads,
    InstallOrUpdateBeads,
    MigrateBeads,
    AdoptBeads,
    AdoptBeadsFastForward,
    ReconcileBeadsFork,
}

impl GpuiProjectBoardCommandIntent {
    fn command_id(self) -> &'static str {
        match self {
            Self::InitializeBeads => GPUI_PROJECT_BOARD_INITIALIZE_BEADS_COMMAND_ID,
            Self::InstallOrUpdateBeads => GPUI_PROJECT_BOARD_INSTALL_OR_UPDATE_BEADS_COMMAND_ID,
            Self::MigrateBeads => GPUI_PROJECT_BOARD_MIGRATE_BEADS_COMMAND_ID,
            Self::AdoptBeads => GPUI_PROJECT_BOARD_ADOPT_BEADS_COMMAND_ID,
            Self::AdoptBeadsFastForward => GPUI_PROJECT_BOARD_ADOPT_BEADS_FAST_FORWARD_COMMAND_ID,
            Self::ReconcileBeadsFork => GPUI_PROJECT_BOARD_RECONCILE_BEADS_FORK_COMMAND_ID,
        }
    }

    fn title(self) -> &'static str {
        match self {
            Self::InitializeBeads => "Initialize Beads",
            Self::InstallOrUpdateBeads => "Install or Update Beads",
            Self::MigrateBeads => "Migrate Beads",
            Self::AdoptBeads | Self::AdoptBeadsFastForward => "Adopt Beads Remote",
            Self::ReconcileBeadsFork => "Back Up and Adopt Beads Remote",
        }
    }

    fn command(self) -> &'static str {
        match self {
            Self::InitializeBeads => "bd init",
            Self::InstallOrUpdateBeads => {
                "curl -fsSL https://raw.githubusercontent.com/gastownhall/beads/main/scripts/install.sh | bash"
            }
            Self::MigrateBeads => "bd migrate --force && bd dolt push",
            Self::AdoptBeads | Self::AdoptBeadsFastForward => "bd bootstrap",
            Self::ReconcileBeadsFork => "bd export --all -o backup.jsonl && bd bootstrap",
        }
    }
}

fn gpui_project_board_action_for_command_id(command_id: &str) -> Option<&'static str> {
    match command_id {
        GPUI_PROJECT_BOARD_INITIALIZE_BEADS_COMMAND_ID => {
            Some(GPUI_PROJECT_BOARD_INITIALIZE_BEADS_ACTION)
        }
        GPUI_PROJECT_BOARD_INSTALL_OR_UPDATE_BEADS_COMMAND_ID => {
            Some(GPUI_PROJECT_BOARD_INSTALL_OR_UPDATE_BEADS_ACTION)
        }
        GPUI_PROJECT_BOARD_MIGRATE_BEADS_COMMAND_ID
        | GPUI_PROJECT_BOARD_ADOPT_BEADS_COMMAND_ID
        | GPUI_PROJECT_BOARD_ADOPT_BEADS_FAST_FORWARD_COMMAND_ID
        | GPUI_PROJECT_BOARD_RECONCILE_BEADS_FORK_COMMAND_ID => {
            Some(GPUI_PROJECT_BOARD_RUN_BEADS_MIGRATION_ACTION)
        }
        _ => None,
    }
}

fn gpui_project_board_command_request(
    request: &serde_json::Value,
    context: Option<&ProjectBoardBridgeRuntimeContext>,
) -> Result<GpuiProjectBoardCommandIntent, String> {
    let object = request
        .as_object()
        .ok_or_else(|| "The Beads command request is invalid.".to_string())?;
    if object
        .keys()
        .any(|key| !["action", "migrationOption", "projectId", "requestId"].contains(&key.as_str()))
    {
        return Err("The Beads command request is invalid.".to_string());
    }
    let _request_id = object
        .get("requestId")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| {
            !value.is_empty()
                && value.chars().count() <= GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS
                && !value.chars().any(char::is_control)
        })
        .ok_or_else(|| "The Beads command request is invalid.".to_string())?;
    let action = object
        .get("action")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| "The Beads command request is invalid.".to_string())?;
    let migration_option = object
        .get("migrationOption")
        .and_then(serde_json::Value::as_str);
    let intent = match (action, migration_option) {
        (GPUI_PROJECT_BOARD_INITIALIZE_BEADS_ACTION, None) => {
            GpuiProjectBoardCommandIntent::InitializeBeads
        }
        (GPUI_PROJECT_BOARD_INSTALL_OR_UPDATE_BEADS_ACTION, None) => {
            GpuiProjectBoardCommandIntent::InstallOrUpdateBeads
        }
        (GPUI_PROJECT_BOARD_RUN_BEADS_MIGRATION_ACTION, Some("migrate")) => {
            GpuiProjectBoardCommandIntent::MigrateBeads
        }
        (GPUI_PROJECT_BOARD_RUN_BEADS_MIGRATION_ACTION, Some("adopt")) => {
            GpuiProjectBoardCommandIntent::AdoptBeads
        }
        (GPUI_PROJECT_BOARD_RUN_BEADS_MIGRATION_ACTION, Some("adopt-fast-forward")) => {
            GpuiProjectBoardCommandIntent::AdoptBeadsFastForward
        }
        (GPUI_PROJECT_BOARD_RUN_BEADS_MIGRATION_ACTION, Some("reconcile-fork")) => {
            GpuiProjectBoardCommandIntent::ReconcileBeadsFork
        }
        _ => return Err("The Beads command request is invalid.".to_string()),
    };
    let context = context.ok_or_else(|| "No active Kanban project is available.".to_string())?;
    if context.remote_machine_id.is_some() {
        return Err(
            "Run this Beads command from a terminal on the remote machine, then refresh the board."
                .to_string(),
        );
    }
    let request_project_id = object
        .get("projectId")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if request_project_id.is_some_and(|project_id| {
        project_id.chars().count() > GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS
            || project_id.chars().any(char::is_control)
            || context.project_id.as_deref() != Some(project_id)
    }) {
        return Err("The Beads command request is not for this active project.".to_string());
    }
    Ok(intent)
}

fn project_board_bridge_response_for_request_payload(
    payload: &str,
    snapshot: Option<&GpuiProjectSnapshot>,
) -> serde_json::Value {
    let request = serde_json::from_str::<serde_json::Value>(payload).unwrap_or_default();
    let request_id = manage_request_string(&request, "requestId").unwrap_or_default();
    let action = manage_request_string(&request, "action").unwrap_or_default();
    if action == "getState" || action == "projectEditorFocusOwnerChanged" {
        let project_id = snapshot
            .and_then(|snapshot| snapshot.active_project_id.as_ref())
            .map(|id| id.0.clone());
        return serde_json::json!({
            "ok": true,
            "payload": {
                "agents": [],
                "links": [],
                "projectId": project_id,
                "sessions": [],
            },
            "requestId": request_id,
        });
    }
    serde_json::json!({
        "error": "Project board conversation action is not handled by this GPUI runtime surface.",
        "ok": false,
        "requestId": request_id,
    })
}

fn run_project_beads_bridge_request_for_context(
    payload: &str,
    context: Option<&ProjectBoardBridgeRuntimeContext>,
) -> serde_json::Value {
    let request = serde_json::from_str::<serde_json::Value>(payload).unwrap_or_default();
    let request_id = manage_request_string(&request, "requestId").unwrap_or_default();
    match project_beads_bridge_result_for_request(&request, context) {
        Ok(response) => response,
        Err(error) => project_beads_bridge_error_response(&request_id, &error),
    }
}

fn project_beads_bridge_result_for_request(
    request: &serde_json::Value,
    context: Option<&ProjectBoardBridgeRuntimeContext>,
) -> Result<serde_json::Value, String> {
    let context = context.ok_or_else(|| "No active Kanban project is available.".to_string())?;
    let request_id = manage_request_string(request, "requestId").unwrap_or_default();
    let action = manage_request_string(request, "action").unwrap_or_default();
    if action == "generateTitle" {
        return gpui_project_beads_generate_title(request, context, &request_id);
    }

    let gxserver_action = project_beads_gxserver_action_for_board_action(&action)?;
    let mut params = serde_json::Map::new();
    params.insert(
        "action".to_string(),
        serde_json::Value::String(gxserver_action.to_string()),
    );
    params.insert(
        "projectBoardScope".to_string(),
        serde_json::Value::Bool(true),
    );
    params.insert(
        "projectPath".to_string(),
        serde_json::Value::String(context.project_path.clone()),
    );
    let request_project_id = manage_request_string(request, "projectId")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    if let (Some(request_project_id), Some(active_project_id)) =
        (request_project_id.as_ref(), context.project_id.as_ref())
    {
        if request_project_id != active_project_id {
            return Err("Project board request was not sent by this active project.".to_string());
        }
    }
    if let Some(project_id) = request_project_id.or_else(|| context.project_id.clone()) {
        params.insert(
            "projectId".to_string(),
            serde_json::Value::String(project_id),
        );
    }

    for key in [
        "comment",
        "dependsOnId",
        "depType",
        "description",
        "issueId",
        "label",
        "priority",
        "query",
        "status",
        "title",
        "value",
    ] {
        if let Some(value) = manage_request_string(request, key) {
            params.insert(key.to_string(), serde_json::Value::String(value));
        }
    }
    if let Some(estimate) = request.get("estimate").filter(|value| value.is_number()) {
        params.insert("estimate".to_string(), estimate.clone());
    }
    if let Some(labels) = request.get("labels").and_then(serde_json::Value::as_array) {
        let labels = labels
            .iter()
            .filter_map(serde_json::Value::as_str)
            .map(|label| serde_json::Value::String(label.to_string()))
            .collect::<Vec<_>>();
        params.insert("labels".to_string(), serde_json::Value::Array(labels));
    }

    let params = serde_json::Value::Object(params);
    if context.remote_machine_id.is_some() {
        let target = context
            .remote_target
            .as_ref()
            .ok_or_else(|| "The remote gxserver is not connected.".to_string())?;
        let result = gpui_remote_gxserver_rpc_result(
            target,
            "/api/runBeadsAction",
            &params,
            Duration::from_secs(60),
        )?;
        return Ok(project_beads_bridge_response_from_result(
            &result,
            &request_id,
        ));
    }
    let (status_code, body) =
        gxserver_post_typed_operation("/api/runBeadsAction", &params, Duration::from_secs(60))?;
    project_beads_bridge_response_from_gxserver(status_code, &body, &request_id)
}

fn project_beads_gxserver_action_for_board_action(action: &str) -> Result<&'static str, String> {
    match action {
        "addComment" => Ok("comment"),
        "addLabel" => Ok("addLabel"),
        "configGet" => Ok("configGet"),
        "configGetIssuePrefix" => Ok("configGetIssuePrefix"),
        "configSet" => Ok("configSet"),
        "create" => Ok("create"),
        "delete" => Ok("delete"),
        "depAdd" => Ok("depAdd"),
        "depRemove" => Ok("depRemove"),
        "list" => Ok("list"),
        "listIssues" => Ok("board"),
        "listAllLabels" => Ok("listAllLabels"),
        "renamePrefix" => Ok("renamePrefix"),
        "removeLabel" => Ok("removeLabel"),
        "search" => Ok("search"),
        "setLabels" => Ok("setLabels"),
        "show" => Ok("show"),
        "updateDescription" => Ok("updateDescription"),
        "updateEstimate" => Ok("updateEstimate"),
        "updatePriority" => Ok("updatePriority"),
        "updateStatus" => Ok("updateStatus"),
        "updateTitle" => Ok("updateTitle"),
        _ => Err(format!("Unsupported Beads action: {action}")),
    }
}

fn project_beads_bridge_response_from_gxserver(
    status_code: u16,
    body: &str,
    request_id: &str,
) -> Result<serde_json::Value, String> {
    if !(200..300).contains(&status_code) {
        let error = project_beads_gxserver_error_message(body, Some(status_code));
        return Ok(project_beads_bridge_error_response(request_id, &error));
    }
    let response = serde_json::from_str::<serde_json::Value>(body)
        .map_err(|_| "gxserver returned an invalid Beads response.".to_string())?;
    let result = response
        .get("result")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "gxserver did not return a Beads result.".to_string())?;
    Ok(project_beads_bridge_response_from_result(
        &serde_json::Value::Object(result.clone()),
        request_id,
    ))
}

fn project_beads_bridge_response_from_result(
    result: &serde_json::Value,
    request_id: &str,
) -> serde_json::Value {
    let exit_code = result
        .get("exitCode")
        .and_then(serde_json::Value::as_i64)
        .unwrap_or(1);
    serde_json::json!({
        "error": null,
        "exitCode": exit_code,
        "requestId": request_id,
        "stderr": result.get("stderr").and_then(serde_json::Value::as_str).unwrap_or(""),
        "stdout": result.get("stdout").and_then(serde_json::Value::as_str).unwrap_or(""),
    })
}

fn project_beads_gxserver_error_message(body: &str, status_code: Option<u16>) -> String {
    if let Ok(value) = serde_json::from_str::<serde_json::Value>(body) {
        if let Some(message) = value
            .get("error")
            .and_then(|error| error.get("message"))
            .and_then(serde_json::Value::as_str)
            .or_else(|| value.get("message").and_then(serde_json::Value::as_str))
        {
            return message.to_string();
        }
    }
    match status_code {
        Some(status_code) => format!("gxserver Beads request failed with HTTP {status_code}."),
        None => "gxserver Beads request failed.".to_string(),
    }
}

fn project_beads_bridge_error_response(request_id: &str, error: &str) -> serde_json::Value {
    serde_json::json!({
        "error": error,
        "exitCode": 127,
        "requestId": request_id,
        "stderr": error,
        "stdout": "",
    })
}

fn gpui_project_beads_generate_title(
    request: &serde_json::Value,
    context: &ProjectBoardBridgeRuntimeContext,
    request_id: &str,
) -> Result<serde_json::Value, String> {
    // Scenario-gated (native.project.board) title-generation diagnostics:
    // agent id, prompt size, duration, and outcome only — never prompt text,
    // generated titles, paths, or process output.
    let agent_id = manage_request_string(request, "agentId").unwrap_or_default();
    let prompt_chars = manage_request_string(request, "prompt")
        .map(|prompt| prompt.chars().count())
        .unwrap_or(0);
    let started_at = Instant::now();
    support_logs::append(
        support_logs::GpuiSupportLog::ProjectBoard,
        "gpui.projectBoard.generateTitleStarted",
        serde_json::json!({ "agentId": agent_id, "promptChars": prompt_chars }),
    );
    let result = gpui_project_beads_generate_title_inner(request, context, request_id);
    support_logs::append(
        support_logs::GpuiSupportLog::ProjectBoard,
        if result.is_ok() {
            "gpui.projectBoard.generateTitleFinished"
        } else {
            "gpui.projectBoard.generateTitleFailed"
        },
        serde_json::json!({
            "durationMs": started_at.elapsed().as_millis() as u64,
            "ok": result.is_ok(),
        }),
    );
    result
}

fn gpui_project_beads_generate_title_inner(
    request: &serde_json::Value,
    context: &ProjectBoardBridgeRuntimeContext,
    request_id: &str,
) -> Result<serde_json::Value, String> {
    /*
    macOS `projectBeadsGenerateTitle` parity (TerminalWorkspaceView.swift):
    board ticket title generation is a local prompt-agent subprocess, not a
    gxserver endpoint. The selected/default prompt agent runs once through a
    login zsh with the title prompt fed as a heredoc, and the first non-empty
    stdout line becomes the sanitized 39-char board title.
    */
    let prompt = manage_request_string(request, "prompt")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "Missing required Beads field: prompt".to_string())?;
    let agent_command = manage_request_string(request, "agentCommand");
    let agent_id = manage_request_string(request, "agentId");
    let cwd = std::path::PathBuf::from(&context.project_path);
    if !cwd.is_dir() {
        return Err(format!(
            "Project path does not exist: {}",
            context.project_path
        ));
    }
    let generation_command = gpui_project_beads_prompt_generation_command(
        agent_command.as_deref(),
        agent_id.as_deref(),
    )?;
    let source_text: String = prompt.chars().take(4_000).collect();
    let generation_prompt = format!(
        "Write a concise session title that summarizes the user's text.\n\
         Return plain text only.\n\
         Rules:\n\
         - keep it specific and scannable\n\
         - must be fewer than 60 characters\n\
         - do not use quotes, markdown, or commentary\n\
         - do not end with punctuation\n\
         - focus on the task, bug, feature, or topic\n\
         \n\
         User text:\n\
         {source_text}\n\
         \n\
         Output handling:\n\
         - Produce only the final session title.\n\
         - Do not wrap the result in backticks.\n\
         - Print only the final result to stdout."
    );
    let delimiter = format!(
        "ghostex_SESSION_TITLE_{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|elapsed| elapsed.as_secs())
            .unwrap_or(0)
    );
    let command =
        format!("{generation_command} <<'{delimiter}'\n{generation_prompt}\n{delimiter}\n");
    let mut process = std::process::Command::new("/bin/zsh");
    process
        .arg("-lc")
        .arg(&command)
        .current_dir(&cwd)
        .env("GHOSTEX_INTERNAL_PROMPT_GENERATION", "1")
        .env("GHOSTEX_INTERNAL_TITLE_GENERATION", "1")
        .env(
            "PATH",
            gpui_project_beads_title_generation_path(std::env::var("PATH").ok().as_deref()),
        );
    for key in GPUI_PROJECT_BEADS_TITLE_GENERATION_STRIPPED_ENV_KEYS {
        process.env_remove(key);
    }
    // macOS waits on the process with no deadline (the page's own 60s bridge
    // timeout owns UI responsiveness); the beads bridge already runs on the
    // background executor.
    let output = process
        .output()
        .map_err(|_| "Could not launch the prompt-agent title generation process.".to_string())?;
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);
    if !output.status.success() {
        let stderr = stderr.trim();
        return Err(if stderr.is_empty() {
            "Prompt-agent title generation failed.".to_string()
        } else {
            stderr.to_string()
        });
    }
    let line = stdout
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .ok_or_else(|| "Prompt-agent title generation returned an empty title.".to_string())?;
    let sanitized = gpui_project_beads_sanitize_generated_title(line);
    if sanitized.is_empty() {
        return Err("Prompt-agent title generation returned an empty title.".to_string());
    }
    let title: String = sanitized.chars().take(39).collect();
    Ok(serde_json::json!({
        "error": null,
        "exitCode": 0,
        "requestId": request_id,
        "stderr": "",
        "stdout": serde_json::json!({ "title": title }).to_string(),
    }))
}

const GPUI_PROJECT_BEADS_TITLE_GENERATION_STRIPPED_ENV_KEYS: [&str; 22] = [
    // macOS `projectBoardInternalPromptGenerationEnvironmentKeys`: internal
    // prompt-agent work must not inherit Ghostex session-binding environment,
    // so hooks cannot turn the background job into a restorable user session.
    "GHOSTEX_AGENT",
    "GHOSTEX_GLOBAL_SESSION_REF",
    "GHOSTEX_GXSERVER_AUTH_TOKEN_FILE",
    "GHOSTEX_GXSERVER_BASE_URL",
    "GHOSTEX_GXSERVER_PROTOCOL_VERSION",
    "GHOSTEX_NATIVE_SESSION_ID",
    "GHOSTEX_SESSION_ID",
    "GHOSTEX_SESSION_STATE_FILE",
    "GHOSTEX_WORKSPACE_ID",
    "GHOSTEX_WORKSPACE_ROOT",
    "VSMUX_AGENT",
    "VSMUX_SESSION_ID",
    "VSMUX_SESSION_STATE_FILE",
    "VSMUX_WORKSPACE_ID",
    "VSMUX_WORKSPACE_ROOT",
    "ZMX_SESSION",
    "ZMX_SESSION_PREFIX",
    "ghostex_AGENT",
    "ghostex_SESSION_ID",
    "ghostex_SESSION_STATE_FILE",
    "ghostex_WORKSPACE_ID",
    "ghostex_WORKSPACE_ROOT",
];

fn gpui_project_beads_prompt_generation_command(
    agent_command: Option<&str>,
    agent_id: Option<&str>,
) -> Result<String, String> {
    // macOS `projectBeadsPromptGenerationCommand` parity, including the
    // ephemeral Codex exec profile so a title prompt can never become a
    // restorable Codex transcript.
    const CODEX_EXEC_ARGS: &str = "exec --ephemeral --skip-git-repo-check -m gpt-5.6-luna -c 'model_reasoning_effort=\"low\"'";
    let normalized_agent_id = agent_id
        .map(|value| value.trim().to_lowercase())
        .unwrap_or_default();
    let command = agent_command
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if normalized_agent_id.is_empty() {
        return Ok(format!("codex {CODEX_EXEC_ARGS}"));
    }
    if let Some(command) = command {
        return Ok(match normalized_agent_id.as_str() {
            "codex" => format!("{command} {CODEX_EXEC_ARGS}"),
            "cursor" => format!(
                "{command} --print --mode ask --trust --model cursor-grok-4.5-low --output-format text"
            ),
            "claude" => format!("{command} -p --model haiku --effort low"),
            "gemini" => format!("{command} -p"),
            _ => command.to_string(),
        });
    }
    match normalized_agent_id.as_str() {
        "codex" => Ok(format!("codex {CODEX_EXEC_ARGS}")),
        "claude" => Ok("claude -p --model haiku --effort low".to_string()),
        "cursor" => Ok(
            "cursor-agent --print --mode ask --trust --model cursor-grok-4.5-low --output-format text"
                .to_string(),
        ),
        "gemini" => Ok("gemini -p".to_string()),
        _ => Err(format!(
            "{normalized_agent_id} does not support background title generation."
        )),
    }
}

fn gpui_project_beads_title_generation_path(existing: Option<&str>) -> String {
    // macOS `projectBoardNativeProcessPath`: common tool directories lead so
    // agent CLIs resolve even under minimal login-shell PATH files.
    let home = std::env::var("HOME").unwrap_or_default();
    let default_entries = [
        format!("{home}/.local/share/mise/shims"),
        format!("{home}/.local/bin"),
        format!("{home}/.asdf/shims"),
        "/opt/homebrew/bin".to_string(),
        "/opt/homebrew/sbin".to_string(),
        "/usr/local/bin".to_string(),
        "/usr/local/sbin".to_string(),
        "/usr/bin".to_string(),
        "/bin".to_string(),
        "/usr/sbin".to_string(),
        "/sbin".to_string(),
    ];
    let mut seen = std::collections::HashSet::new();
    default_entries
        .into_iter()
        .chain(existing.unwrap_or_default().split(':').map(str::to_string))
        .filter(|entry| {
            let normalized = entry.trim().to_string();
            !normalized.is_empty() && seen.insert(normalized)
        })
        .collect::<Vec<_>>()
        .join(":")
}

fn gpui_project_beads_sanitize_generated_title(line: &str) -> String {
    let stripped = line
        .trim()
        .trim_matches(|character| matches!(character, '"' | '\'' | '`'));
    let collapsed = stripped.split_whitespace().collect::<Vec<_>>().join(" ");
    collapsed
        .trim_end_matches(|character| matches!(character, '.' | '…'))
        .trim()
        .to_string()
}

enum GpuiAutomationBoardNavigation {
    FocusSession(String),
    FocusProject(String),
    RevealWorktreePath(String),
}

const GPUI_QUICK_AUTOMATIONS_PROJECT_ID: &str = "quick-automations";
const GPUI_QUICK_AUTOMATIONS_DISPLAY_TITLE: &str = "Automations Overview";

fn gpui_automation_gxserver_endpoint_for_board_action(action: &str) -> Option<&'static str> {
    // macOS `gxserverAutomationEndpointForProjectBoardAction` parity.
    match action {
        "automationGetState" => Some("/api/readAutomationState"),
        "automationSave" => Some("/api/saveAutomation"),
        "automationDelete" => Some("/api/deleteAutomation"),
        "automationRunNow" => Some("/api/runAutomationNow"),
        "automationSetEnabled" => Some("/api/setAutomationEnabled"),
        "automationArchiveRun" => Some("/api/archiveAutomationRun"),
        "automationMarkRunRead" => Some("/api/markAutomationRunRead"),
        _ => None,
    }
}

fn gpui_automation_board_ok_response(
    request_id: &str,
    automation_state: serde_json::Value,
) -> serde_json::Value {
    serde_json::json!({
        "ok": true,
        "payload": automation_state,
        "requestId": request_id,
    })
}

fn gpui_project_board_error_response(request_id: &str, error: &str) -> serde_json::Value {
    serde_json::json!({
        "error": error,
        "ok": false,
        "requestId": request_id,
    })
}

fn gpui_project_board_conversation_action_forwarded(action: &str) -> bool {
    // The board conversation surface owned by the sidebar runtime — the same
    // action set macOS `handleProjectBoardRequest` serves in native-sidebar.tsx
    // (minus the automation family, which Rust forwards to gxserver directly,
    // and `projectEditorFocusOwnerChanged`, which stays Rust-answered).
    matches!(
        action,
        "getState"
            | "startWork"
            | "associateFocusedSession"
            | "jumpToConversation"
            | "unlinkConversation"
            | "showToast"
            | "appendDebugLog"
    )
}

fn gpui_automation_rpc_automation_state(
    endpoint: &str,
    params: &serde_json::Value,
) -> Result<serde_json::Value, String> {
    let (status_code, body) =
        gxserver_post_typed_operation(endpoint, params, Duration::from_secs(60))?;
    if !(200..300).contains(&status_code) {
        return Err(gpui_automation_gxserver_error_message(&body, status_code));
    }
    parse_gpui_gxserver_rpc_result(&body)?
        .get("automationState")
        .cloned()
        .ok_or_else(|| "gxserver did not return an automation state.".to_string())
}

fn gpui_automation_gxserver_error_message(body: &str, status_code: u16) -> String {
    if let Ok(value) = serde_json::from_str::<serde_json::Value>(body) {
        if let Some(message) = value
            .get("error")
            .and_then(|error| error.get("message"))
            .and_then(serde_json::Value::as_str)
            .or_else(|| value.get("message").and_then(serde_json::Value::as_str))
        {
            return message.to_string();
        }
    }
    format!("gxserver automation request failed with HTTP {status_code}.")
}

fn gpui_list_gxserver_domain_projects() -> Result<Vec<serde_json::Value>, String> {
    let result = gpui_gxserver_rpc_result(
        "/api/listProjects",
        &serde_json::json!({}),
        Duration::from_secs(30),
    )?;
    Ok(result
        .get("projects")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default())
}

fn gpui_normalized_project_path_for_comparison(path: &str) -> String {
    path.trim().trim_end_matches('/').to_string()
}

fn gpui_find_gxserver_project_id_by_path(path: &str) -> Result<Option<String>, String> {
    let normalized = gpui_normalized_project_path_for_comparison(path);
    Ok(gpui_list_gxserver_domain_projects()?
        .iter()
        .find(|project| {
            project
                .get("path")
                .and_then(serde_json::Value::as_str)
                .map(gpui_normalized_project_path_for_comparison)
                .is_some_and(|candidate| candidate == normalized)
        })
        .and_then(|project| project.get("projectId").and_then(serde_json::Value::as_str))
        .map(str::to_string))
}

struct GpuiAutomationBoardScope {
    project_id: Option<String>,
    project_path: Option<String>,
}

fn gpui_automation_board_scope(
    request: &serde_json::Value,
    context: Option<&ProjectBoardBridgeRuntimeContext>,
) -> GpuiAutomationBoardScope {
    // macOS `createGxserverAutomationParams` scope resolution: the request's
    // ids win (the overview page targets other projects), the active board
    // project is the fallback.
    let request_project_id = manage_request_string(request, "projectId")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let request_project_path = manage_request_string(request, "projectPath")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    GpuiAutomationBoardScope {
        project_id: request_project_id
            .or_else(|| context.and_then(|context| context.project_id.clone())),
        project_path: request_project_path
            .or_else(|| context.map(|context| context.project_path.clone())),
    }
}

fn gpui_automation_scope_params(
    scope: &GpuiAutomationBoardScope,
) -> serde_json::Map<String, serde_json::Value> {
    let mut params = serde_json::Map::new();
    if let Some(project_id) = &scope.project_id {
        params.insert(
            "projectId".to_string(),
            serde_json::Value::String(project_id.clone()),
        );
    }
    if let Some(project_path) = &scope.project_path {
        params.insert(
            "projectPath".to_string(),
            serde_json::Value::String(project_path.clone()),
        );
    }
    params
}

fn gpui_automation_payload_json(request: &serde_json::Value) -> Result<serde_json::Value, String> {
    let payload_json = manage_request_string(request, "payloadJson")
        .ok_or_else(|| "No automation payload was supplied.".to_string())?;
    serde_json::from_str::<serde_json::Value>(&payload_json)
        .map_err(|_| "Automation payload is not valid JSON.".to_string())
}

fn gpui_automation_enabled_from_payload(request: &serde_json::Value) -> Result<bool, String> {
    let payload = gpui_automation_payload_json(request)
        .map_err(|_| "No automation enabled payload was supplied.".to_string())?;
    payload
        .get("enabled")
        .and_then(serde_json::Value::as_bool)
        .ok_or_else(|| "Automation enabled payload is incomplete.".to_string())
}

fn gpui_automation_remove_worktree_from_payload(request: &serde_json::Value) -> bool {
    gpui_automation_payload_json(request)
        .ok()
        .and_then(|payload| {
            payload
                .get("removeWorktree")
                .and_then(serde_json::Value::as_bool)
        })
        == Some(true)
}

fn run_gpui_project_board_automation_request(
    request: &serde_json::Value,
    context: Option<&ProjectBoardBridgeRuntimeContext>,
) -> (serde_json::Value, Option<GpuiAutomationBoardNavigation>) {
    let request_id = manage_request_string(request, "requestId").unwrap_or_default();
    match gpui_project_board_automation_result(request, context) {
        Ok((automation_state, navigation)) => (
            gpui_automation_board_ok_response(&request_id, automation_state),
            navigation,
        ),
        Err(error) => (gpui_project_board_error_response(&request_id, &error), None),
    }
}

fn gpui_project_board_automation_result(
    request: &serde_json::Value,
    context: Option<&ProjectBoardBridgeRuntimeContext>,
) -> Result<(serde_json::Value, Option<GpuiAutomationBoardNavigation>), String> {
    let action = manage_request_string(request, "action").unwrap_or_default();
    let scope = gpui_automation_board_scope(request, context);
    if action == "automationGetAllState" {
        return Ok((gpui_automation_all_projects_state(&scope)?, None));
    }
    if action == "automationOpenRunSession" || action == "automationOpenWorktree" {
        return gpui_automation_open_run_target(&action, request, &scope);
    }
    let endpoint = gpui_automation_gxserver_endpoint_for_board_action(&action)
        .ok_or_else(|| format!("Unsupported automation action: {action}"))?;
    let mut params = gpui_automation_scope_params(&scope);
    match action.as_str() {
        "automationSave" => {
            params.insert(
                "definition".to_string(),
                gpui_automation_payload_json(request)?,
            );
        }
        "automationDelete" | "automationRunNow" | "automationSetEnabled" => {
            let automation_id = manage_request_string(request, "sessionId")
                .map(|value| value.trim().to_string())
                .filter(|value| !value.is_empty())
                .ok_or_else(|| "No automation id was supplied.".to_string())?;
            params.insert(
                "automationId".to_string(),
                serde_json::Value::String(automation_id),
            );
        }
        "automationArchiveRun" | "automationMarkRunRead" => {
            let run_id = manage_request_string(request, "sessionId")
                .map(|value| value.trim().to_string())
                .filter(|value| !value.is_empty())
                .ok_or_else(|| "No automation run id was supplied.".to_string())?;
            params.insert("runId".to_string(), serde_json::Value::String(run_id));
        }
        _ => {}
    }
    if action == "automationSetEnabled" {
        params.insert(
            "enabled".to_string(),
            serde_json::Value::Bool(gpui_automation_enabled_from_payload(request)?),
        );
    }
    if action == "automationArchiveRun" {
        params.insert(
            "removeWorktree".to_string(),
            serde_json::Value::Bool(gpui_automation_remove_worktree_from_payload(request)),
        );
    }
    let state = gpui_automation_rpc_automation_state(endpoint, &serde_json::Value::Object(params))?;
    Ok((state, None))
}

fn gpui_automation_all_projects_state(
    scope: &GpuiAutomationBoardScope,
) -> Result<serde_json::Value, String> {
    /*
    macOS `createAllProjectGxserverAutomationsBridgeState` parity for a client
    with no native project registry: aggregate per-project gxserver automation
    states across the daemon's registered target projects. Agents come from the
    per-project states (the daemon builds them from the same HUD source macOS
    seeds from), and per-project read failures skip that project like the
    macOS `Promise.allSettled` walk.
    */
    let target_projects: Vec<(String, String)> = gpui_list_gxserver_domain_projects()?
        .iter()
        .filter(|project| {
            let project_id = project
                .get("projectId")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let path = project
                .get("path")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            project_id != GPUI_QUICK_AUTOMATIONS_PROJECT_ID
                && !path.trim().is_empty()
                && project
                    .get("isRecentProject")
                    .and_then(serde_json::Value::as_bool)
                    != Some(true)
                && project
                    .get("visibility")
                    .and_then(serde_json::Value::as_str)
                    != Some("hidden")
                && project
                    .get("systemKind")
                    .and_then(serde_json::Value::as_str)
                    != Some("remoteAttachCarrier")
        })
        .filter_map(|project| {
            let project_id = project
                .get("projectId")
                .and_then(serde_json::Value::as_str)?;
            let path = project.get("path").and_then(serde_json::Value::as_str)?;
            Some((project_id.to_string(), path.to_string()))
        })
        .collect();
    let states: Vec<serde_json::Value> = target_projects
        .iter()
        .filter_map(|(project_id, path)| {
            gpui_automation_rpc_automation_state(
                "/api/readAutomationState",
                &serde_json::json!({ "projectId": project_id, "projectPath": path }),
            )
            .ok()
        })
        .collect();
    let mut agents: Vec<serde_json::Value> = Vec::new();
    let mut seen_agent_ids: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut automations: Vec<serde_json::Value> = Vec::new();
    let mut runs: Vec<serde_json::Value> = Vec::new();
    for state in &states {
        for agent in state
            .get("agents")
            .and_then(serde_json::Value::as_array)
            .into_iter()
            .flatten()
        {
            let agent_id = agent
                .get("agentId")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default()
                .to_string();
            if !agent_id.is_empty() && seen_agent_ids.insert(agent_id) {
                agents.push(agent.clone());
            }
        }
        automations.extend(
            state
                .get("automations")
                .and_then(serde_json::Value::as_array)
                .cloned()
                .unwrap_or_default(),
        );
        runs.extend(
            state
                .get("runs")
                .and_then(serde_json::Value::as_array)
                .cloned()
                .unwrap_or_default(),
        );
    }
    let first_state = states.first();
    let projects = first_state
        .and_then(|state| state.get("projects").cloned())
        .unwrap_or_else(|| {
            serde_json::Value::Array(
                target_projects
                    .iter()
                    .map(|(project_id, path)| {
                        serde_json::json!({
                            "canUseWorktrees": false,
                            "label": path.rsplit('/').next().unwrap_or(project_id),
                            "path": path,
                            "projectId": project_id,
                            "worktreeUnavailableReason":
                                "Open the project Automate view to use worktree mode.",
                        })
                    })
                    .collect(),
            )
        });
    Ok(serde_json::json!({
        "agents": agents,
        "automations": automations,
        "defaultAgentId": first_state
            .and_then(|state| state.get("defaultAgentId").cloned())
            .unwrap_or(serde_json::Value::String("codex".to_string())),
        "projectCanUseWorktrees": false,
        "projectId": scope
            .project_id
            .clone()
            .unwrap_or_else(|| GPUI_QUICK_AUTOMATIONS_PROJECT_ID.to_string()),
        "projectName": GPUI_QUICK_AUTOMATIONS_DISPLAY_TITLE,
        "projectPath": "",
        "projects": projects,
        "runs": runs,
        "worktreeUnavailableReason": "Choose a project before using worktree mode.",
    }))
}

fn gpui_automation_open_run_target(
    action: &str,
    request: &serde_json::Value,
    scope: &GpuiAutomationBoardScope,
) -> Result<(serde_json::Value, Option<GpuiAutomationBoardNavigation>), String> {
    let run_id = manage_request_string(request, "sessionId")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "No automation run id was supplied.".to_string())?;
    let state = gpui_automation_rpc_automation_state(
        "/api/readAutomationState",
        &serde_json::Value::Object(gpui_automation_scope_params(scope)),
    )?;
    let run = state
        .get("runs")
        .and_then(serde_json::Value::as_array)
        .into_iter()
        .flatten()
        .find(|run| run.get("id").and_then(serde_json::Value::as_str) == Some(run_id.as_str()))
        .cloned()
        .ok_or_else(|| "Automation run not found.".to_string())?;
    let run_project_id = run
        .get("projectId")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .or_else(|| scope.project_id.clone())
        .ok_or_else(|| "Automation run has no project.".to_string())?;
    let worktree_path = run
        .get("worktree")
        .and_then(|worktree| worktree.get("path"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|path| !path.is_empty())
        .map(str::to_string);
    let navigation = if action == "automationOpenWorktree" {
        let worktree_path =
            worktree_path.ok_or_else(|| "Automation run has no linked worktree.".to_string())?;
        match gpui_find_gxserver_project_id_by_path(&worktree_path)? {
            // macOS parity: focus the registered worktree project when it
            // exists, otherwise reveal the checkout in Finder.
            Some(project_id) => Some(GpuiAutomationBoardNavigation::FocusProject(project_id)),
            None => Some(GpuiAutomationBoardNavigation::RevealWorktreePath(
                worktree_path,
            )),
        }
    } else {
        let session_id = run
            .get("sessionId")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|session_id| !session_id.is_empty())
            .map(str::to_string)
            .ok_or_else(|| "Automation run has no linked session.".to_string())?;
        // Worktree/thread runs live in another project than the automation;
        // resolve the session's owning project like gxserver's own
        // `find_run_session_project_id` (worktree path match, else run project).
        let session_project_id = match &worktree_path {
            Some(path) => {
                gpui_find_gxserver_project_id_by_path(path)?.unwrap_or(run_project_id.clone())
            }
            None => run_project_id.clone(),
        };
        gpui_combined_presentation_session_focus_id(&session_project_id, &session_id)
            .map(GpuiAutomationBoardNavigation::FocusSession)
    };
    let mut mark_read_params = gpui_automation_scope_params(scope);
    mark_read_params.insert("runId".to_string(), serde_json::Value::String(run_id));
    let refreshed = gpui_automation_rpc_automation_state(
        "/api/markAutomationRunRead",
        &serde_json::Value::Object(mark_read_params),
    )?;
    Ok((refreshed, navigation))
}

fn parse_gpui_gxserver_rpc_result(body: &str) -> Result<serde_json::Value, String> {
    let value = serde_json::from_str::<serde_json::Value>(body)
        .map_err(|_| "gxserver returned an invalid RPC response.".to_string())?;
    if value.get("ok").and_then(serde_json::Value::as_bool) != Some(true)
        || value.get("product").and_then(serde_json::Value::as_str) != Some(GPUI_GXSERVER_PRODUCT)
        || value
            .get("protocolVersion")
            .and_then(serde_json::Value::as_u64)
            != Some(GPUI_GXSERVER_PROTOCOL_VERSION)
    {
        return Err("gxserver returned an invalid RPC response.".to_string());
    }
    value
        .get("result")
        .and_then(serde_json::Value::as_object)
        .cloned()
        .map(serde_json::Value::Object)
        .ok_or_else(|| "gxserver returned an invalid RPC result.".to_string())
}

fn gxserver_post_typed_operation(
    path: &str,
    params: &serde_json::Value,
    timeout: Duration,
) -> Result<(u16, String), String> {
    /*
    CDXC:GPUIProjectBoardGxserverBridge 2026-06-24-11:03:
    GPUI Kanban CEF parity must use the existing gxserver typed-operation boundary for Beads work. Send the same protocol-version envelope and bearer token as the native bridge to localhost only, with no bd subprocess execution, remote fallback, raw request logging, response logging, URL/title inspection, or persisted board payloads.

    CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-11:39:
    Settings fan-out also uses this narrow local gxserver RPC helper so agent-policy saves share the existing bearer-token path and response-body parser. Keep callers endpoint-specific and privacy-safe; this helper must not log tokens, URLs, settings payloads, project paths, command text, stdout/stderr, or daemon responses.

    CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-12:14:
    Startup/open-time agent-policy hydration also uses this helper for `/api/readAgentSettings` so GPUI does not invent a second daemon client or bypass the same token, localhost, timeout, protocol-header, and response-sanitization boundary.

    CDXC:GPUISettingsStatusBridge 2026-06-24-11:40:
    Settings status/action parity reuses this helper for hook status/install/uninstall and Portless state updates. Keep the helper transport-only: callers own endpoint allowlists, result validation, explicit UI error messages, and no persistent logging.
    */
    if !path.starts_with("/api/") {
        return Err("Invalid gxserver API path.".to_string());
    }
    let token = read_gpui_gxserver_auth_token()?;
    let address = format!("{GPUI_GXSERVER_LOCAL_API_HOST}:{GPUI_GXSERVER_LOCAL_API_PORT}");
    let mut stream = TcpStream::connect(&address)
        .map_err(|_| "gxserver is not reachable on 127.0.0.1:58744.".to_string())?;
    stream
        .set_read_timeout(Some(timeout))
        .map_err(|_| "Could not configure gxserver read timeout.".to_string())?;
    stream
        .set_write_timeout(Some(timeout))
        .map_err(|_| "Could not configure gxserver write timeout.".to_string())?;

    let body = serde_json::json!({
        "protocolVersion": GPUI_GXSERVER_PROTOCOL_VERSION,
        "params": params,
    })
    .to_string();
    let request = format!(
        "POST {path} HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\nAuthorization: Bearer {token}\r\nContent-Type: application/json\r\n{GPUI_GXSERVER_PROTOCOL_HEADER}: {GPUI_GXSERVER_PROTOCOL_VERSION}\r\nContent-Length: {}\r\n\r\n{body}",
        body.len()
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "Could not send gxserver request.".to_string())?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|_| "Could not read gxserver response.".to_string())?;
    let (headers, body) = response
        .split_once("\r\n\r\n")
        .ok_or_else(|| "gxserver returned an invalid HTTP response.".to_string())?;
    let status_code = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .ok_or_else(|| "gxserver returned an invalid HTTP status.".to_string())?;
    Ok((status_code, gxserver_http_response_body(headers, body)?))
}

fn gpui_remote_gxserver_rpc_result(
    target: &GpuiRemoteGxserverRequestTarget,
    path: &str,
    params: &serde_json::Value,
    timeout: Duration,
) -> Result<serde_json::Value, String> {
    let (status_code, body) =
        gpui_remote_gxserver_post_typed_operation(target, path, params, timeout)?;
    if !(200..300).contains(&status_code) {
        return Err("Remote gxserver request failed.".to_string());
    }
    parse_gpui_gxserver_rpc_result(&body)
}

/*
CDXC:AddProject 2026-07-30:
The add-project dialog is the one gxserver surface that shows the daemon's own
rejection text ("Workspace root is not a directory: …", "Destination path
already exists and is not empty.", a `gh` lookup failure). Generic errors made
the old remote add-project flow unusable: the user could not tell a bad path
from a dead tunnel. Only the daemon's structured `message` is forwarded, and
only for a rejected request — transport failures stay as fixed local copy so no
tunnel host, port, token, or raw response body can reach the renderer.
*/
fn gpui_add_project_dialog_rpc_result(
    target: Option<&GpuiRemoteGxserverRequestTarget>,
    path: &str,
    params: &serde_json::Value,
    timeout: Duration,
) -> Result<serde_json::Value, String> {
    let (status_code, body) = match target {
        Some(target) => gpui_remote_gxserver_post_typed_operation(target, path, params, timeout)
            .map_err(|_| "The remote machine did not answer.".to_string())?,
        None => gxserver_post_typed_operation(path, params, timeout)
            .map_err(|_| "gxserver is not reachable.".to_string())?,
    };
    if !(200..300).contains(&status_code) {
        return Err(gpui_add_project_dialog_error_message(&body));
    }
    parse_gpui_gxserver_rpc_result(&body)
        .map_err(|_| "gxserver returned an unexpected response.".to_string())
}

fn gpui_add_project_dialog_restore_recent_project(
    target: Option<&GpuiRemoteGxserverRequestTarget>,
    add_result: serde_json::Value,
    timeout: Duration,
) -> Result<serde_json::Value, String> {
    /*
    CDXC:AddProjectRestoreRecent 2026-08-12:
    `/api/addProjectPath` is intentionally idempotent and returns an existing
    path registration unchanged. When that registration is parked in Recent
    Projects, Add Project must perform the same authoritative restore mutation
    as clicking its Recent Projects row before reporting success. Otherwise the
    dialog closes around a still-hidden `isRecentProject: true` project and the
    user sees a silent no-op.
    */
    let Some(project) = add_result
        .get("project")
        .and_then(serde_json::Value::as_object)
    else {
        return Ok(add_result);
    };
    if !gpui_gxserver_project_row_is_explicit_recent_project(project) {
        return Ok(add_result);
    }
    let project_id = gpui_trimmed_json_string_field(project, "projectId")
        .filter(|project_id| gpui_remote_sidebar_project_id_allowed(project_id))
        .ok_or_else(|| "gxserver returned an unexpected response.".to_string())?;
    gpui_add_project_dialog_rpc_result(
        target,
        "/api/restoreRecentProject",
        &serde_json::json!({ "projectId": project_id }),
        timeout,
    )
}

fn gpui_add_project_dialog_error_message(body: &str) -> String {
    serde_json::from_str::<serde_json::Value>(body)
        .ok()
        .as_ref()
        .and_then(|value| value.get("message"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|message| !message.is_empty())
        .map(|message| {
            message
                .chars()
                .filter(|character| !character.is_control())
                .take(GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS)
                .collect::<String>()
        })
        .filter(|message| !message.is_empty())
        .unwrap_or_else(|| "gxserver rejected the request.".to_string())
}

fn gpui_repository_clone_rpc_result(
    target: Option<&GpuiRemoteGxserverRequestTarget>,
    path: &str,
    params: &serde_json::Value,
    timeout: Duration,
) -> Result<serde_json::Value, String> {
    match target {
        Some(target) => gpui_remote_gxserver_rpc_result(target, path, params, timeout),
        None => gpui_gxserver_rpc_result(path, params, timeout),
    }
}

fn gpui_remote_gxserver_presentation_stream_loop(
    target: GpuiRemoteGxserverRequestTarget,
    cancel: Arc<AtomicBool>,
    tx: mpsc::UnboundedSender<GpuiRemoteGxserverPresentationStreamMessage>,
    client_id: String,
    last_revision: Option<u64>,
) {
    let mut last_revision = last_revision;
    for attempt in 0..GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_ATTEMPTS {
        if cancel.load(Ordering::SeqCst) {
            return;
        }
        let _ = gpui_remote_gxserver_presentation_stream_once(
            &target,
            cancel.as_ref(),
            &tx,
            client_id.as_str(),
            &mut last_revision,
        );
        if cancel.load(Ordering::SeqCst) {
            return;
        }
        if attempt + 1 < GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_ATTEMPTS {
            thread::sleep(GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_RECONNECT_DELAY);
        }
    }
    if !cancel.load(Ordering::SeqCst) {
        let _ = tx.unbounded_send(GpuiRemoteGxserverPresentationStreamMessage::Failed);
    }
}

fn gpui_remote_gxserver_presentation_stream_once(
    target: &GpuiRemoteGxserverRequestTarget,
    cancel: &AtomicBool,
    tx: &mpsc::UnboundedSender<GpuiRemoteGxserverPresentationStreamMessage>,
    client_id: &str,
    last_revision: &mut Option<u64>,
) -> Result<(), String> {
    /*
    CDXC:GPUIRemotePresentationStreaming 2026-06-24-19:54:
    The remote presentation stream uses gxserver's existing WebSocket protocol through the authenticated localhost tunnel. The only renderer-bound products of this helper are presentation snapshots and deltas already consumed by SidebarApp; eventStreamReady, server ids, auth details, raw response bodies, and transport failures stay native-only.
    */
    let mut stream = gpui_remote_gxserver_open_presentation_websocket(target, cancel)?;
    stream
        .set_read_timeout(Some(GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_READ_TIMEOUT))
        .map_err(|_| "Could not configure remote gxserver event read timeout.".to_string())?;
    let subscribe = gpui_remote_gxserver_presentation_subscribe_message(client_id, *last_revision);
    gpui_websocket_write_text_frame(&mut stream, subscribe.as_bytes())?;
    let mut liveness = GpuiRemoteGxserverPresentationLiveness::new();
    loop {
        if cancel.load(Ordering::SeqCst) {
            return Ok(());
        }
        let Some(frame) = gpui_websocket_read_frame(&mut stream, target, &mut liveness, cancel)?
        else {
            return Ok(());
        };
        match frame {
            GpuiWebSocketFrame::Text(text) => {
                let Ok(event) = serde_json::from_str::<serde_json::Value>(text.trim()) else {
                    continue;
                };
                let Some((payload, revision)) =
                    gpui_remote_gxserver_presentation_event_payload(&event)
                else {
                    continue;
                };
                if let Some(revision) = revision {
                    *last_revision = Some(revision);
                }
                tx.unbounded_send(GpuiRemoteGxserverPresentationStreamMessage::Event(payload))
                    .map_err(|_| "Remote presentation receiver closed.".to_string())?;
            }
            GpuiWebSocketFrame::Ping(payload) => {
                gpui_websocket_write_control_frame(&mut stream, 0xA, &payload)?;
            }
            GpuiWebSocketFrame::Close => {
                return Err("Remote gxserver event stream closed.".to_string());
            }
            GpuiWebSocketFrame::Pong | GpuiWebSocketFrame::Other => {}
        }
    }
}

fn gpui_remote_gxserver_open_presentation_websocket(
    target: &GpuiRemoteGxserverRequestTarget,
    cancel: &AtomicBool,
) -> Result<TcpStream, String> {
    let address = format!("127.0.0.1:{}", target.local_port);
    let mut stream = TcpStream::connect(&address)
        .map_err(|_| "Remote gxserver event stream is not reachable.".to_string())?;
    stream
        .set_read_timeout(Some(GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_READ_TIMEOUT))
        .map_err(|_| "Could not configure remote gxserver event read timeout.".to_string())?;
    stream
        .set_write_timeout(Some(
            GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_HANDSHAKE_TIMEOUT,
        ))
        .map_err(|_| "Could not configure remote gxserver event write timeout.".to_string())?;
    let request = format!(
        "GET /api/events?protocolVersion={GPUI_GXSERVER_PROTOCOL_VERSION}&authToken={} HTTP/1.1\r\nHost: {address}\r\nConnection: Upgrade\r\nUpgrade: websocket\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n",
        target.token.as_str(),
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "Could not send remote gxserver event handshake.".to_string())?;
    let headers = gpui_read_websocket_handshake_headers(&mut stream, cancel)?;
    let status = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .ok_or_else(|| "Remote gxserver returned an invalid event stream status.".to_string())?;
    if status != 101 {
        return Err("Remote gxserver did not accept the event stream.".to_string());
    }
    Ok(stream)
}

fn gpui_read_websocket_handshake_headers(
    stream: &mut TcpStream,
    cancel: &AtomicBool,
) -> Result<String, String> {
    let deadline = Instant::now() + GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_HANDSHAKE_TIMEOUT;
    let mut bytes = Vec::new();
    let mut byte = [0u8; 1];
    while Instant::now() < deadline {
        if cancel.load(Ordering::SeqCst) {
            return Err("Remote gxserver event stream was cancelled.".to_string());
        }
        match stream.read(&mut byte) {
            Ok(0) => return Err("Remote gxserver closed the event handshake.".to_string()),
            Ok(_) => {
                bytes.push(byte[0]);
                if bytes.ends_with(b"\r\n\r\n") {
                    return String::from_utf8(bytes)
                        .map_err(|_| "Remote gxserver event handshake was invalid.".to_string());
                }
                if bytes.len() > 16 * 1024 {
                    return Err("Remote gxserver event handshake was too large.".to_string());
                }
            }
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) =>
            {
                continue;
            }
            Err(_) => return Err("Could not read remote gxserver event handshake.".to_string()),
        }
    }
    Err("Remote gxserver event handshake timed out.".to_string())
}

fn gpui_remote_gxserver_presentation_subscribe_message(
    client_id: &str,
    last_revision: Option<u64>,
) -> String {
    let mut payload = serde_json::Map::new();
    payload.insert("clientId".to_string(), serde_json::json!(client_id));
    if let Some(last_revision) = last_revision {
        payload.insert("lastRevision".to_string(), serde_json::json!(last_revision));
    }
    payload.insert(
        "type".to_string(),
        serde_json::json!("subscribePresentation"),
    );
    serde_json::Value::Object(payload).to_string()
}

enum GpuiWebSocketFrame {
    Close,
    Other,
    Ping(Vec<u8>),
    Pong,
    Text(String),
}

struct GpuiRemoteGxserverPresentationLiveness {
    next_health_check: Instant,
}

impl GpuiRemoteGxserverPresentationLiveness {
    fn new() -> Self {
        Self {
            next_health_check: Instant::now() + GPUI_REMOTE_GXSERVER_PRESENTATION_HEALTH_INTERVAL,
        }
    }

    fn confirm_after_read_timeout(
        &mut self,
        target: &GpuiRemoteGxserverRequestTarget,
    ) -> Result<(), String> {
        if Instant::now() < self.next_health_check {
            return Ok(());
        }
        self.next_health_check = Instant::now() + GPUI_REMOTE_GXSERVER_PRESENTATION_HEALTH_INTERVAL;
        if gpui_remote_authenticated_health(target.local_port, target.token.as_str()).is_some() {
            Ok(())
        } else {
            Err("Remote gxserver event stream failed its liveness check.".to_string())
        }
    }
}

fn gpui_websocket_read_frame(
    stream: &mut TcpStream,
    target: &GpuiRemoteGxserverRequestTarget,
    liveness: &mut GpuiRemoteGxserverPresentationLiveness,
    cancel: &AtomicBool,
) -> Result<Option<GpuiWebSocketFrame>, String> {
    let mut header = [0u8; 2];
    if !gpui_websocket_read_exact(stream, &mut header, target, liveness, cancel)? {
        return Ok(None);
    }
    let fin = header[0] & 0x80 != 0;
    let opcode = header[0] & 0x0F;
    if !fin {
        return Err("Remote gxserver sent a fragmented event frame.".to_string());
    }
    let masked = header[1] & 0x80 != 0;
    let mut payload_len = u64::from(header[1] & 0x7F);
    if payload_len == 126 {
        let mut extended = [0u8; 2];
        if !gpui_websocket_read_exact(stream, &mut extended, target, liveness, cancel)? {
            return Ok(None);
        }
        payload_len = u64::from(u16::from_be_bytes(extended));
    } else if payload_len == 127 {
        let mut extended = [0u8; 8];
        if !gpui_websocket_read_exact(stream, &mut extended, target, liveness, cancel)? {
            return Ok(None);
        }
        payload_len = u64::from_be_bytes(extended);
    }
    if payload_len as usize > GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_FRAME_MAX_BYTES {
        return Err("Remote gxserver event frame was too large.".to_string());
    }
    let mut mask = [0u8; 4];
    if masked && !gpui_websocket_read_exact(stream, &mut mask, target, liveness, cancel)? {
        return Ok(None);
    }
    let mut payload = vec![0u8; payload_len as usize];
    if !payload.is_empty()
        && !gpui_websocket_read_exact(stream, &mut payload, target, liveness, cancel)?
    {
        return Ok(None);
    }
    if masked {
        for (index, byte) in payload.iter_mut().enumerate() {
            *byte ^= mask[index % mask.len()];
        }
    }
    match opcode {
        0x1 => String::from_utf8(payload)
            .map(GpuiWebSocketFrame::Text)
            .map(Some)
            .map_err(|_| "Remote gxserver event frame was not UTF-8.".to_string()),
        0x8 => Ok(Some(GpuiWebSocketFrame::Close)),
        0x9 => Ok(Some(GpuiWebSocketFrame::Ping(payload))),
        0xA => Ok(Some(GpuiWebSocketFrame::Pong)),
        _ => Ok(Some(GpuiWebSocketFrame::Other)),
    }
}

fn gpui_websocket_read_exact(
    stream: &mut TcpStream,
    buffer: &mut [u8],
    target: &GpuiRemoteGxserverRequestTarget,
    liveness: &mut GpuiRemoteGxserverPresentationLiveness,
    cancel: &AtomicBool,
) -> Result<bool, String> {
    let mut offset = 0;
    while offset < buffer.len() {
        if cancel.load(Ordering::SeqCst) {
            return Ok(false);
        }
        match stream.read(&mut buffer[offset..]) {
            Ok(0) => return Err("Remote gxserver closed the event stream.".to_string()),
            Ok(read_count) => {
                offset += read_count;
            }
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) =>
            {
                liveness.confirm_after_read_timeout(target)?;
                continue;
            }
            Err(_) => return Err("Could not read remote gxserver event stream.".to_string()),
        }
    }
    Ok(true)
}

fn gpui_websocket_write_text_frame(stream: &mut TcpStream, payload: &[u8]) -> Result<(), String> {
    gpui_websocket_write_frame(stream, 0x1, payload)
}

fn gpui_websocket_write_control_frame(
    stream: &mut TcpStream,
    opcode: u8,
    payload: &[u8],
) -> Result<(), String> {
    if payload.len() > 125 {
        return Err("Remote gxserver control frame was too large.".to_string());
    }
    gpui_websocket_write_frame(stream, opcode, payload)
}

fn gpui_websocket_write_frame(
    stream: &mut TcpStream,
    opcode: u8,
    payload: &[u8],
) -> Result<(), String> {
    let mask = gpui_websocket_mask();
    let mut frame = Vec::with_capacity(payload.len() + 14);
    frame.push(0x80 | (opcode & 0x0F));
    if payload.len() <= 125 {
        frame.push(0x80 | payload.len() as u8);
    } else if payload.len() <= u16::MAX as usize {
        frame.push(0x80 | 126);
        frame.extend_from_slice(&(payload.len() as u16).to_be_bytes());
    } else {
        frame.push(0x80 | 127);
        frame.extend_from_slice(&(payload.len() as u64).to_be_bytes());
    }
    frame.extend_from_slice(&mask);
    for (index, byte) in payload.iter().enumerate() {
        frame.push(*byte ^ mask[index % mask.len()]);
    }
    stream
        .write_all(&frame)
        .map_err(|_| "Could not write remote gxserver event frame.".to_string())
}

fn gpui_websocket_mask() -> [u8; 4] {
    (SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u32)
        .wrapping_add(std::process::id())
        .to_be_bytes()
}

fn gpui_remote_gxserver_presentation_event_payload(
    event: &serde_json::Value,
) -> Option<(serde_json::Value, Option<u64>)> {
    let object = event.as_object()?;
    match object.get("type").and_then(serde_json::Value::as_str)? {
        "presentationSnapshot" => {
            let snapshot = object.get("snapshot")?;
            if !gpui_remote_gxserver_presentation_snapshot_allowed(snapshot) {
                return None;
            }
            let revision = gpui_json_revision(snapshot).or_else(|| gpui_json_revision(event));
            Some((
                serde_json::json!({
                    "snapshot": (*snapshot).clone(),
                    "type": "presentationSnapshot",
                }),
                revision,
            ))
        }
        "presentationDelta" => {
            let delta = object.get("delta")?;
            if !gpui_remote_gxserver_presentation_delta_allowed(delta) {
                return None;
            }
            let revision = gpui_json_revision(event)?;
            Some((
                serde_json::json!({
                    "delta": (*delta).clone(),
                    "revision": revision,
                    "type": "presentationDelta",
                }),
                Some(revision),
            ))
        }
        _ => None,
    }
}

fn gpui_remote_gxserver_presentation_snapshot_allowed(value: &serde_json::Value) -> bool {
    let Some(object) = value.as_object() else {
        return false;
    };
    object
        .get("groups")
        .and_then(serde_json::Value::as_array)
        .is_some()
        && object
            .get("projects")
            .and_then(serde_json::Value::as_array)
            .is_some()
        && object
            .get("sessions")
            .and_then(serde_json::Value::as_array)
            .is_some()
        && gpui_json_revision(value).is_some()
}

fn gpui_remote_gxserver_presentation_delta_allowed(value: &serde_json::Value) -> bool {
    value
        .as_object()
        .and_then(|object| object.get("type"))
        .and_then(serde_json::Value::as_str)
        .is_some()
}

fn gpui_json_revision(value: &serde_json::Value) -> Option<u64> {
    value.get("revision").and_then(|revision| {
        revision.as_u64().or_else(|| {
            revision
                .as_i64()
                .and_then(|value| u64::try_from(value).ok())
        })
    })
}

fn gpui_remote_gxserver_post_typed_operation(
    target: &GpuiRemoteGxserverRequestTarget,
    path: &str,
    params: &serde_json::Value,
    timeout: Duration,
) -> Result<(u16, String), String> {
    /*
    CDXC:GPUIRemoteMachines 2026-06-24-16:48:
    Remote gxserver RPCs use the live SSH tunnel target and in-memory token captured by Rust after Keychain storage. Keep this helper transport-only and response-unlogged: callers own endpoint allowlists and user-facing generic errors, while tokens, URLs, remote paths, params, stdout/stderr, and daemon bodies are never persisted or copied to renderer globals.
    */
    if !path.starts_with("/api/") {
        return Err("Invalid remote gxserver API path.".to_string());
    }
    let address = format!("127.0.0.1:{}", target.local_port);
    let mut stream = TcpStream::connect(&address)
        .map_err(|_| "Remote gxserver tunnel is not reachable.".to_string())?;
    stream
        .set_read_timeout(Some(timeout))
        .map_err(|_| "Could not configure remote gxserver read timeout.".to_string())?;
    stream
        .set_write_timeout(Some(timeout))
        .map_err(|_| "Could not configure remote gxserver write timeout.".to_string())?;

    let body = serde_json::json!({
        "protocolVersion": GPUI_GXSERVER_PROTOCOL_VERSION,
        "params": params,
    })
    .to_string();
    let request = format!(
        "POST {path} HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\n{GPUI_GXSERVER_PROTOCOL_HEADER}: {GPUI_GXSERVER_PROTOCOL_VERSION}\r\nContent-Length: {}\r\n\r\n{body}",
        target.token.as_str(),
        body.len()
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "Could not send remote gxserver request.".to_string())?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|_| "Could not read remote gxserver response.".to_string())?;
    let (headers, body) = response
        .split_once("\r\n\r\n")
        .ok_or_else(|| "Remote gxserver returned an invalid HTTP response.".to_string())?;
    let status_code = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .ok_or_else(|| "Remote gxserver returned an invalid HTTP status.".to_string())?;
    Ok((status_code, gxserver_http_response_body(headers, body)?))
}

fn gxserver_get_typed_operation(path: &str, timeout: Duration) -> Result<(u16, String), String> {
    /*
    CDXC:GPUISettingsStatusBridge 2026-06-24-11:40:
    GPUI Settings reads gxserver health through the same localhost/token/protocol boundary as typed POST operations. Health reads must stay GET-only, short-timeout, response-unlogged, and limited to `/api/` paths so Portless HUD hydration does not introduce a second daemon client.
    */
    if !path.starts_with("/api/") {
        return Err("Invalid gxserver API path.".to_string());
    }
    let token = read_gpui_gxserver_auth_token()?;
    let address = format!("{GPUI_GXSERVER_LOCAL_API_HOST}:{GPUI_GXSERVER_LOCAL_API_PORT}");
    let mut stream = TcpStream::connect(&address)
        .map_err(|_| "gxserver is not reachable on 127.0.0.1:58744.".to_string())?;
    stream
        .set_read_timeout(Some(timeout))
        .map_err(|_| "Could not configure gxserver read timeout.".to_string())?;
    stream
        .set_write_timeout(Some(timeout))
        .map_err(|_| "Could not configure gxserver write timeout.".to_string())?;

    let request = format!(
        "GET {path} HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\nAuthorization: Bearer {token}\r\n{GPUI_GXSERVER_PROTOCOL_HEADER}: {GPUI_GXSERVER_PROTOCOL_VERSION}\r\n\r\n",
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "Could not send gxserver health request.".to_string())?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|_| "Could not read gxserver health response.".to_string())?;
    let (headers, body) = response
        .split_once("\r\n\r\n")
        .ok_or_else(|| "gxserver returned an invalid HTTP response.".to_string())?;
    let status_code = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .ok_or_else(|| "gxserver returned an invalid HTTP status.".to_string())?;
    Ok((status_code, gxserver_http_response_body(headers, body)?))
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiGxserverReadAgentSettingsResult {
    is_persisted: bool,
    settings: shared_settings::SharedGxserverAgentSettings,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum GpuiGxserverAgentSettingsReconciliationAction {
    SeedLocal(shared_settings::SharedGxserverAgentSettings),
    ApplyCanonical(shared_settings::SharedGxserverAgentSettings),
    Noop,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiGxserverAgentSettingsHydrationResult {
    expected_local_settings: shared_settings::SharedGxserverAgentSettings,
    canonical_settings: shared_settings::SharedGxserverAgentSettings,
}

fn gpui_gxserver_agent_settings_reconciliation_action(
    local_settings: &shared_settings::SharedGxserverAgentSettings,
    daemon_result: &GpuiGxserverReadAgentSettingsResult,
) -> GpuiGxserverAgentSettingsReconciliationAction {
    if !daemon_result.is_persisted {
        return GpuiGxserverAgentSettingsReconciliationAction::SeedLocal(local_settings.clone());
    }
    if daemon_result.settings != *local_settings {
        return GpuiGxserverAgentSettingsReconciliationAction::ApplyCanonical(
            daemon_result.settings.clone(),
        );
    }
    GpuiGxserverAgentSettingsReconciliationAction::Noop
}

fn reconcile_gpui_gxserver_agent_settings_with_daemon()
-> Result<Option<GpuiGxserverAgentSettingsHydrationResult>, String> {
    let daemon_agent_settings = read_gpui_gxserver_agent_settings()?;
    let local_agent_settings =
        shared_settings::shared_sidebar_settings_snapshot().gxserver_agent_settings();
    match gpui_gxserver_agent_settings_reconciliation_action(
        &local_agent_settings,
        &daemon_agent_settings,
    ) {
        GpuiGxserverAgentSettingsReconciliationAction::SeedLocal(settings) => {
            let expected_local_settings = settings.clone();
            update_gpui_gxserver_agent_settings(&settings).map(|canonical_settings| {
                Some(GpuiGxserverAgentSettingsHydrationResult {
                    expected_local_settings,
                    canonical_settings,
                })
            })
        }
        GpuiGxserverAgentSettingsReconciliationAction::ApplyCanonical(settings) => {
            Ok(Some(GpuiGxserverAgentSettingsHydrationResult {
                expected_local_settings: local_agent_settings,
                canonical_settings: settings,
            }))
        }
        GpuiGxserverAgentSettingsReconciliationAction::Noop => Ok(None),
    }
}

fn read_gpui_gxserver_agent_settings() -> Result<GpuiGxserverReadAgentSettingsResult, String> {
    /*
    CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-12:14:
    Startup/open-time reconciliation reads the daemon's canonical agent-settings row through the same typed localhost RPC envelope as save-time sync. Parse only `isPersisted`, `agentAcceptAllEnabled`, and `defaultPromptAgentId`; failures remain local `Result` values and never create fallback daemon state or leak raw gxserver responses.
    */
    let (status_code, body) = gxserver_post_typed_operation(
        "/api/readAgentSettings",
        &serde_json::json!({}),
        Duration::from_secs(5),
    )?;
    if !(200..300).contains(&status_code) {
        return Err("gxserver agent settings read failed.".to_string());
    }
    parse_gpui_gxserver_read_agent_settings_response(&body)
}

fn update_gpui_gxserver_agent_settings(
    settings: &shared_settings::SharedGxserverAgentSettings,
) -> Result<shared_settings::SharedGxserverAgentSettings, String> {
    /*
    CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-11:39:
    GPUI Settings saves use the same local gxserver HTTP/token path as other GPUI gxserver calls. The request is the macOS-compatible `/api/updateAgentSettings` RPC envelope with only Accept All and Default Prompt Agent values; failures stay as local `Result` values so callers can silently preserve the render cache without private logs or fake daemon state.
    */
    let mut params = serde_json::Map::new();
    settings.write_to_settings_object(&mut params);
    let (status_code, body) = gxserver_post_typed_operation(
        "/api/updateAgentSettings",
        &serde_json::Value::Object(params),
        Duration::from_secs(5),
    )?;
    if !(200..300).contains(&status_code) {
        return Err("gxserver agent settings request failed.".to_string());
    }
    parse_gpui_gxserver_agent_settings_response(&body)
}

fn parse_gpui_gxserver_agent_settings_response(
    body: &str,
) -> Result<shared_settings::SharedGxserverAgentSettings, String> {
    let result = parse_gpui_gxserver_agent_settings_rpc_result(body)?;
    parse_gpui_gxserver_agent_settings_from_result(&result)
}

fn parse_gpui_gxserver_read_agent_settings_response(
    body: &str,
) -> Result<GpuiGxserverReadAgentSettingsResult, String> {
    let result = parse_gpui_gxserver_agent_settings_rpc_result(body)?;
    let is_persisted = result
        .get("isPersisted")
        .and_then(serde_json::Value::as_bool)
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())?;
    let settings = parse_gpui_gxserver_agent_settings_from_result(&result)?;
    Ok(GpuiGxserverReadAgentSettingsResult {
        is_persisted,
        settings,
    })
}

fn parse_gpui_gxserver_agent_settings_rpc_result(
    body: &str,
) -> Result<serde_json::Map<String, serde_json::Value>, String> {
    let value = serde_json::from_str::<serde_json::Value>(body)
        .map_err(|_| "gxserver returned an invalid agent settings response.".to_string())?;
    if value.get("ok").and_then(serde_json::Value::as_bool) != Some(true)
        || value.get("product").and_then(serde_json::Value::as_str) != Some(GPUI_GXSERVER_PRODUCT)
        || value
            .get("protocolVersion")
            .and_then(serde_json::Value::as_u64)
            != Some(GPUI_GXSERVER_PROTOCOL_VERSION)
    {
        return Err("gxserver returned an invalid agent settings response.".to_string());
    }
    value
        .get("result")
        .and_then(serde_json::Value::as_object)
        .cloned()
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())
}

fn parse_gpui_gxserver_agent_settings_from_result(
    result: &serde_json::Map<String, serde_json::Value>,
) -> Result<shared_settings::SharedGxserverAgentSettings, String> {
    let settings = result
        .get("settings")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())?;
    let agent_accept_all_enabled = settings
        .get("agentAcceptAllEnabled")
        .and_then(serde_json::Value::as_bool)
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())?;
    let default_prompt_agent_id = settings
        .get("defaultPromptAgentId")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())?;
    Ok(shared_settings::SharedGxserverAgentSettings::new(
        agent_accept_all_enabled,
        default_prompt_agent_id,
    ))
}

fn gpui_sidebar_gxserver_bootstrap(
    latest_snapshot: Option<&GpuiProjectSnapshot>,
    focus_state: &GpuiGxserverPresentationFocusState,
    local_focus_key: Option<&GpuiLocalWorkspaceSessionKey>,
) -> Option<cef::SidebarGxserverBootstrap> {
    /*
    CDXC:GPUISidebarGxserverBootstrap 2026-06-24-11:17:
    Build the GPUI sidebar bootstrap only from real local gxserver facts: the selected loopback API port, the existing auth-token helper, protocol version 1, a stable GPUI sidebar client id, and the explicit active project id already stored from the live sidebar snapshot. Do not infer optional session ids from project paths, titles, shell terminal ids, Browser tabs, fixtures, or fallback state.

    CDXC:GPUISidebarGxserverBootstrap 2026-06-24-13:34 (revised 2026-08-07):
    `initialActiveProjectId` may be supplied only from the validated latest sidebar active-project snapshot, the exact local workspace-focus key whose raw session matches `focusedSessionId`, or the contract-validated persisted focus state's own `activeProjectId` (cold-start replay of the last active workspace project). This helper must not query gxserver project lists or log project identity.

    CDXC:GPUISidebarGxserverFocusState 2026-06-24-21:07:
    `focusedSessionId` and `visibleSessionIds` may be supplied only from the separate GPUI focus state that has already accepted real gxserver presentation ids. Local ids remain raw daemon session ids; remote ids remain machine-scoped sidebar ids so bootstrap replay is collision-safe.

    CDXC:GPUIWorkspaceSessionFocus 2026-06-27-13:25:
    A GPUI sidebar local-session click carries the authoritative project/session pair through the fixed workspace-focus bridge. If that project matches the stored focused session exactly, prefer it over the latest active-project snapshot so a second click cannot bootstrap the current session under a stale project and render an empty selection.
    */
    let initial_active_project_id = local_focus_key
        .filter(|key| focus_state.focused_session_id.as_deref() == Some(key.session_id.as_str()))
        .map(|key| key.project_id.as_str())
        .or_else(|| gpui_active_project_id_from_snapshot(latest_snapshot))
        .or(focus_state.active_project_id.as_deref())
        .map(str::to_string);
    Some(cef::SidebarGxserverBootstrap {
        base_url: format!("http://{GPUI_GXSERVER_LOCAL_API_HOST}:{GPUI_GXSERVER_LOCAL_API_PORT}"),
        auth_token: read_gpui_gxserver_auth_token().ok()?,
        protocol_version: GPUI_GXSERVER_PROTOCOL_VERSION as i32,
        client_id: GPUI_SIDEBAR_GXSERVER_CLIENT_ID.to_string(),
        initial_active_project_id,
        focused_session_id: focus_state.focused_session_id.clone(),
        visible_session_ids: focus_state.visible_session_ids.clone(),
    })
}

fn read_gpui_gxserver_auth_token() -> Result<String, String> {
    #[cfg(target_os = "windows")]
    {
        return windows_terminal_backend::auth_token()
            .ok_or_else(|| "gxserver auth token is unavailable.".to_string());
    }
    #[cfg(not(target_os = "windows"))]
    {
        let token_path = shared_settings::ghostex_storage_paths()
            .gxserver_state_dir()
            .join("auth")
            .join("token");
        let token = fs::read_to_string(token_path)
            .map_err(|_| "gxserver auth token is unavailable.".to_string())?
            .trim()
            .to_string();
        if token.is_empty() {
            return Err("gxserver auth token is empty.".to_string());
        }
        Ok(token)
    }
}

fn gxserver_http_response_body(headers: &str, body: &str) -> Result<String, String> {
    if !headers.lines().any(|line| {
        let Some((name, value)) = line.split_once(':') else {
            return false;
        };
        name.trim().eq_ignore_ascii_case("transfer-encoding")
            && value
                .split(',')
                .any(|part| part.trim().eq_ignore_ascii_case("chunked"))
    }) {
        return Ok(body.to_string());
    }
    gxserver_decode_chunked_http_body(body)
}

fn gxserver_decode_chunked_http_body(body: &str) -> Result<String, String> {
    let bytes = body.as_bytes();
    let mut index = 0;
    let mut output = Vec::new();
    loop {
        let line_end = gxserver_find_crlf(bytes, index)
            .ok_or_else(|| "Invalid chunked gxserver response.".to_string())?;
        let size_text = std::str::from_utf8(&bytes[index..line_end])
            .unwrap_or("")
            .split(';')
            .next()
            .unwrap_or("")
            .trim();
        let size = usize::from_str_radix(size_text, 16)
            .map_err(|_| "Invalid chunked gxserver response size.".to_string())?;
        index = line_end + 2;
        if size == 0 {
            return String::from_utf8(output)
                .map_err(|_| "Invalid UTF-8 in gxserver response.".to_string());
        }
        let chunk_end = index
            .checked_add(size)
            .filter(|end| *end <= bytes.len())
            .ok_or_else(|| "Invalid chunked gxserver response.".to_string())?;
        output.extend_from_slice(&bytes[index..chunk_end]);
        index = chunk_end;
        if bytes.get(index..index + 2) != Some(b"\r\n") {
            return Err("Invalid chunked gxserver response.".to_string());
        }
        index += 2;
    }
}

fn gxserver_find_crlf(bytes: &[u8], start: usize) -> Option<usize> {
    bytes
        .get(start..)?
        .windows(2)
        .position(|window| window == b"\r\n")
        .map(|offset| start + offset)
}

fn project_board_image_request_needs_clipboard(payload: &str) -> bool {
    serde_json::from_str::<serde_json::Value>(payload)
        .ok()
        .and_then(|request| manage_request_string(&request, "action"))
        .as_deref()
        == Some("pasteImage")
}

fn project_board_image_bridge_response_for_payload(
    payload: &str,
    clipboard_item: Option<ClipboardItem>,
) -> serde_json::Value {
    let request = serde_json::from_str::<serde_json::Value>(payload).unwrap_or_default();
    let request_id = manage_request_string(&request, "requestId").unwrap_or_default();
    let action = manage_request_string(&request, "action").unwrap_or_default();
    let result = match action.as_str() {
        "pasteImage" => {
            project_board_clipboard_image_path(clipboard_item.as_ref()).map(|image_path| {
                let request_id = request_id.clone();
                serde_json::json!({
                    "dataUrl": null,
                    "error": null,
                    "imagePath": image_path,
                    "path": null,
                    "requestId": request_id,
                })
            })
        }
        "loadPreview" => {
            let path = manage_request_string(&request, "path").unwrap_or_default();
            project_board_image_preview_data_url(&path).map(|data_url| {
                let request_id = request_id.clone();
                serde_json::json!({
                    "dataUrl": data_url,
                    "error": null,
                    "imagePath": null,
                    "path": path,
                    "requestId": request_id,
                })
            })
        }
        _ => Err(format!("Unsupported Project Board image action: {action}")),
    };
    result.unwrap_or_else(|error| {
        serde_json::json!({
            "dataUrl": null,
            "error": error,
            "imagePath": null,
            "path": request.get("path").and_then(serde_json::Value::as_str),
            "requestId": request_id,
        })
    })
}

fn project_board_clipboard_image_path(
    clipboard_item: Option<&ClipboardItem>,
) -> Result<String, String> {
    /*
    CDXC:GPUIProjectBoardImagePaste 2026-06-24-11:03:
    Kanban image paste through CEF should preserve the native Project Board contract: return a durable path reference, not base64 Markdown. Existing image file references stay as paths; GPUI image clipboard bytes are saved under the resolved Ghostex image directory with their declared image format and returned as the same display path convention.
    */
    let item = clipboard_item
        .ok_or_else(|| "Clipboard does not contain an image path or image data.".to_string())?;
    for entry in &item.entries {
        if let ClipboardEntry::ExternalPaths(paths) = entry {
            for path in paths.paths() {
                if is_project_board_image_file_path(path) {
                    return Ok(project_board_display_image_path_for_existing_path(path));
                }
            }
        }
    }
    for entry in &item.entries {
        if let ClipboardEntry::String(clipboard_string) = entry {
            if let Some(path) = project_board_image_path_from_reference(clipboard_string.text()) {
                if is_project_board_image_file_path(&path) {
                    return Ok(project_board_display_image_path_for_existing_path(&path));
                }
            }
        }
    }
    for entry in &item.entries {
        if let ClipboardEntry::Image(image) = entry {
            let bytes = image.bytes();
            if bytes.is_empty() || bytes.len() > PROJECT_BOARD_CLIPBOARD_IMAGE_MAX_BYTES {
                return Err("Clipboard image is too large to save.".to_string());
            }
            let path =
                unique_project_board_image_path(project_board_image_extension(image.format()))?;
            fs::write(&path, bytes).map_err(|_| "Could not save clipboard image.".to_string())?;
            return Ok(project_board_display_image_path_for_saved_path(&path));
        }
    }
    Err("Clipboard does not contain an image path or image data.".to_string())
}

fn project_board_image_preview_data_url(path: &str) -> Result<String, String> {
    let path = project_board_image_path_from_reference(path)
        .ok_or_else(|| "Image preview path does not point to a local image.".to_string())?;
    if !is_project_board_image_file_path(&path) {
        return Err("Image preview path does not point to a local image.".to_string());
    }
    let metadata = fs::metadata(&path)
        .map_err(|_| "Image preview path does not point to a local image.".to_string())?;
    if !metadata.is_file() || metadata.len() as usize > PROJECT_BOARD_IMAGE_PREVIEW_MAX_BYTES {
        return Err("Image preview data could not be decoded.".to_string());
    }
    let extension = path
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    let mime_type = project_board_image_mime_type_for_extension(&extension)
        .ok_or_else(|| "Image preview format is not supported by this CEF runtime.".to_string())?;
    let data =
        fs::read(&path).map_err(|_| "Image preview data could not be decoded.".to_string())?;
    Ok(format!(
        "data:{mime_type};base64,{}",
        project_board_base64_encode(&data)
    ))
}

fn project_board_image_path_from_reference(value: &str) -> Option<PathBuf> {
    let trimmed = value.trim();
    if trimmed.is_empty() || trimmed.contains('\0') {
        return None;
    }
    if trimmed.starts_with("file://") {
        let parsed = gpui::http_client::Url::parse(trimmed).ok()?;
        if parsed.scheme() == "file" {
            return parsed.to_file_path().ok();
        }
        return None;
    }
    if let Some(relative_path) = trimmed.strip_prefix("~/.ghostex/") {
        return Some(
            shared_settings::ghostex_storage_paths()
                .data_dir
                .join(relative_path),
        );
    }
    if let Some(relative_path) = trimmed.strip_prefix("~/") {
        return Some(home_dir().join(relative_path));
    }
    if trimmed.starts_with('/') {
        return Some(PathBuf::from(trimmed));
    }
    None
}

fn is_project_board_image_file_path(path: &Path) -> bool {
    let extension = path
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    project_board_image_extension_is_allowed(&extension)
        && fs::metadata(path).map(|m| m.is_file()).unwrap_or(false)
}

fn project_board_image_extension_is_allowed(extension: &str) -> bool {
    matches!(
        extension,
        "avif"
            | "bmp"
            | "gif"
            | "heic"
            | "heif"
            | "ico"
            | "jpg"
            | "jpeg"
            | "png"
            | "svg"
            | "tif"
            | "tiff"
            | "webp"
    )
}

fn project_board_image_mime_type_for_extension(extension: &str) -> Option<&'static str> {
    match extension {
        "avif" => Some("image/avif"),
        "bmp" => Some("image/bmp"),
        "gif" => Some("image/gif"),
        "ico" => Some("image/x-icon"),
        "jpg" | "jpeg" => Some("image/jpeg"),
        "png" => Some("image/png"),
        "svg" => Some("image/svg+xml"),
        "webp" => Some("image/webp"),
        _ => None,
    }
}

fn project_board_image_extension(format: ImageFormat) -> &'static str {
    match format {
        ImageFormat::Png => "png",
        ImageFormat::Jpeg => "jpg",
        ImageFormat::Webp => "webp",
        ImageFormat::Gif => "gif",
        ImageFormat::Svg => "svg",
        ImageFormat::Bmp => "bmp",
        ImageFormat::Tiff => "tif",
        ImageFormat::Ico => "ico",
        ImageFormat::Pnm => "pnm",
    }
}

fn unique_project_board_image_path(extension: &str) -> Result<PathBuf, String> {
    let directory = shared_settings::ghostex_storage_paths().images_dir();
    fs::create_dir_all(&directory).map_err(|_| "Could not create image directory.".to_string())?;
    let base_name = system_time_epoch_millis_string(std::time::SystemTime::now());
    let first = directory.join(format!("{base_name}.{extension}"));
    if !first.exists() {
        return Ok(first);
    }
    for index in 2..100 {
        let candidate = directory.join(format!("{base_name}-{index}.{extension}"));
        if !candidate.exists() {
            return Ok(candidate);
        }
    }
    Ok(directory.join(format!(
        "{}-{}.{}",
        base_name,
        std::process::id(),
        extension
    )))
}

fn project_board_display_image_path_for_saved_path(path: &Path) -> String {
    project_board_display_image_path_for_existing_path(path)
}

fn project_board_display_image_path_for_existing_path(path: &Path) -> String {
    let user_home = home_dir();
    if let Ok(relative_path) = path.strip_prefix(&user_home) {
        return format!("~/{}", relative_path.to_string_lossy());
    }
    path.to_string_lossy().to_string()
}

fn home_dir() -> PathBuf {
    env::var_os("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."))
}

fn project_board_base64_encode(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut output = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let b0 = chunk[0];
        let b1 = *chunk.get(1).unwrap_or(&0);
        let b2 = *chunk.get(2).unwrap_or(&0);
        output.push(TABLE[(b0 >> 2) as usize] as char);
        output.push(TABLE[(((b0 & 0x03) << 4) | (b1 >> 4)) as usize] as char);
        if chunk.len() > 1 {
            output.push(TABLE[(((b1 & 0x0f) << 2) | (b2 >> 6)) as usize] as char);
        } else {
            output.push('=');
        }
        if chunk.len() > 2 {
            output.push(TABLE[(b2 & 0x3f) as usize] as char);
        } else {
            output.push('=');
        }
    }
    output
}

fn current_sidebar_max_width(window: &Window) -> f32 {
    let max_for_window =
        window.bounds().size.width.as_f32() - SIDEBAR_DIVIDER_WIDTH - WORKSPACE_MIN_WIDTH;
    SIDEBAR_MAX_WIDTH.min(max_for_window).max(SIDEBAR_MIN_WIDTH)
}

fn clamp_sidebar_width(width: f32, max_width: f32) -> f32 {
    /*
    CDXC:GPUISidebarDividerColor 2026-07-22:
    Sidebar and divider are separately painted normal-layout siblings. Keep
    their shared boundary on a whole logical point so 1x and Retina backing
    stores cannot expose a half-covered workspace-colored seam between them.
    */
    width
        .round()
        .clamp(SIDEBAR_MIN_WIDTH, max_width.floor().max(SIDEBAR_MIN_WIDTH))
}

fn read_sidebar_width_setting() -> Option<f32> {
    read_json_number_field(&native_chrome_settings_path(), "sidebarWidth")
}

fn read_sidebar_default_width_setting() -> Option<f32> {
    shared_settings::shared_sidebar_settings_snapshot()
        .sidebar_default_width_px()
        .map(|width| width.clamp(SIDEBAR_MIN_WIDTH, SIDEBAR_MAX_WIDTH))
}

fn gpui_sidebar_side_from_shared_settings(
    settings: &shared_settings::SharedSidebarSettingsSnapshot,
) -> GpuiSidebarSide {
    /*
    CDXC:GPUISidebarSide 2026-06-26-23:35:
    GPUI reads the typed shared `sidebarSide` snapshot as the startup placement source. Missing or malformed values are normalized by the shared settings boundary to native's left-side default without adding a second durable setting.
    */
    match settings.sidebar_side() {
        shared_settings::SharedSidebarSide::Left => GpuiSidebarSide::Left,
        shared_settings::SharedSidebarSide::Right => GpuiSidebarSide::Right,
    }
}

fn gpui_command_pane_side_from_shared_settings(
    settings: &shared_settings::SharedSidebarSettingsSnapshot,
) -> GpuiCommandPaneSide {
    match settings.command_pane_side() {
        shared_settings::SharedCommandPaneSide::Bottom => GpuiCommandPaneSide::Bottom,
        shared_settings::SharedCommandPaneSide::Right => GpuiCommandPaneSide::Right,
    }
}

fn write_gpui_sidebar_side_to_shared_settings(side: GpuiSidebarSide) {
    /*
    CDXC:GPUISidebarSide 2026-06-26-23:35:
    GPUI persists Move Sidebar through the typed shared settings writer so only `sidebarSide` changes and sidebar width, collapsed state, and unrelated settings remain untouched.
    */
    let shared_side = match side {
        GpuiSidebarSide::Left => shared_settings::SharedSidebarSide::Left,
        GpuiSidebarSide::Right => shared_settings::SharedSidebarSide::Right,
    };
    let _ = shared_settings::write_shared_sidebar_side(shared_side);
}

fn persist_sidebar_width_setting(width: f32) {
    /*
    CDXC:GPUIPrivacyAudit 2026-06-23-13:18:
    The GPUI settings write is limited to merging the finite numeric sidebarWidth into the existing native settings JSON object. Do not add project/session/browser/runtime fields here, and do not persist paths, names, command text, URLs, page titles, terminal content, tokens, cookies, secrets, stdout/stderr, or raw CEF/sidebar payloads from GPUI state.
    */
    let path = native_chrome_settings_path();
    let mut settings = read_json_object(&path).unwrap_or_default();
    settings.insert(
        "sidebarWidth".to_string(),
        serde_json::Value::Number(
            serde_json::Number::from_f64(width as f64)
                .expect("clamped sidebar width should be finite"),
        ),
    );

    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    if let Ok(data) = serde_json::to_vec_pretty(&serde_json::Value::Object(settings)) {
        let _ = fs::write(path, data);
    }
}

fn read_json_number_field(path: &Path, key: &str) -> Option<f32> {
    let object = read_json_object(path)?;
    json_value_to_f32(object.get(key)?)
}

fn read_json_object(path: &Path) -> Option<serde_json::Map<String, serde_json::Value>> {
    let text = fs::read_to_string(path).ok()?;
    match serde_json::from_str::<serde_json::Value>(&text).ok()? {
        serde_json::Value::Object(object) => Some(object),
        _ => None,
    }
}

fn json_value_to_f32(value: &serde_json::Value) -> Option<f32> {
    let number = match value {
        serde_json::Value::Number(number) => number.as_f64()?,
        serde_json::Value::String(text) => text.parse::<f64>().ok()?,
        _ => return None,
    };
    number.is_finite().then_some(number as f32)
}

fn titlebar_mode_switcher_items(
    availability: ProjectScopedWorkareaAvailability,
) -> Vec<TitlebarModeSwitcherItem> {
    /*
    CDXC:GPUTitlebarAvailability 2026-07-04-01:00:
    The GPUI titlebar mode list mirrors macOS Quick/projectless presentation: Agents and Source are always visible and selectable; Browser, Kanban, Automate, and Docs stay visible but disabled in Quick context. Activation, hotkeys, restored active mode, and persisted active mode delegate to the same context availability helper.

    CDXC:GPUIProjectScopedWorkareaAvailability 2026-06-22-18:00:
    Kanban, Automate, and Docs must be unavailable without a project, and GPUI currently shares Browser's Quick/projectless disablement through the same titlebar contract. Until a real GPUI project/sidebar snapshot exists, keep GHOSTEX_GPUI_PROJECT_IS_QUICK isolated behind GpuiProjectContext and pass a typed ProjectScopedWorkareaAvailability into mode lists and action guards instead of adding git/path heuristics or fallback project detection.

    CDXC:GPUIProjectScopedWorkareaAvailability 2026-06-22-19:44:
    Runtime App titlebar mode lists, activation guards, and active-mode coercion prefer the latest valid in-memory sidebar project snapshot when available. The fallback availability is supplied by the caller so app runtime code can choose its current strict source without persisting or logging raw snapshot details.

    CDXC:GPUIProjectSidebarBridge 2026-07-04-01:00:
    App-owned titlebar mode lists and active-mode fallback receive fallback availability from the current project context, but Docs/Manage titlebar visibility is unconditional and only project context can disable it.
    */
    availability.titlebar_mode_switcher_items()
}

fn titlebar_mode_view_tab_hidden_settings_key(mode: TitlebarMode) -> Option<&'static str> {
    match mode {
        TitlebarMode::Source => Some(SOURCE_CODE_VIEW_TAB_HIDDEN_SETTINGS_KEY),
        TitlebarMode::Browser => Some(BROWSER_VIEW_TAB_HIDDEN_SETTINGS_KEY),
        TitlebarMode::Kanban => Some(KANBAN_VIEW_TAB_HIDDEN_SETTINGS_KEY),
        TitlebarMode::Automate => Some(AUTOMATE_VIEW_TAB_HIDDEN_SETTINGS_KEY),
        TitlebarMode::Manage => Some(DOCS_VIEW_TAB_HIDDEN_SETTINGS_KEY),
        TitlebarMode::Agents => None,
    }
}

fn gpui_titlebar_mode_hidden_from_settings(mode: TitlebarMode) -> bool {
    let Some(settings_key) = titlebar_mode_view_tab_hidden_settings_key(mode) else {
        return false;
    };
    shared_settings::shared_sidebar_settings_snapshot()
        .object()
        .get(settings_key)
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
}

fn project_scoped_workarea_availability_from_latest_sidebar_snapshot(
    latest_snapshot: Option<&GpuiProjectSnapshot>,
    fallback_availability: ProjectScopedWorkareaAvailability,
) -> ProjectScopedWorkareaAvailability {
    latest_snapshot.map_or(fallback_availability, |snapshot| {
        snapshot.titlebar_availability()
    })
}

