fn gxserver_workspace_tab_session_title_field(
    object: &serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Result<String, GpuiGxserverPresentationFocusStateContractError> {
    let value = object
        .get(key)
        .ok_or(GpuiGxserverPresentationFocusStateContractError::MissingField)?
        .as_str()
        .ok_or(GpuiGxserverPresentationFocusStateContractError::MalformedField)?
        .trim();
    if value.is_empty()
        || value.chars().count() > GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS
        || value.contains('\0')
        || value.chars().any(char::is_control)
    {
        return Err(GpuiGxserverPresentationFocusStateContractError::MalformedField);
    }
    Ok(value.to_string())
}

fn gxserver_focus_session_id_string(
    value: &serde_json::Value,
) -> Result<String, GpuiGxserverPresentationFocusStateContractError> {
    let value = value
        .as_str()
        .ok_or(GpuiGxserverPresentationFocusStateContractError::MalformedField)?
        .trim();
    if !gpui_sidebar_gxserver_presentation_session_id_allowed(value) {
        return Err(GpuiGxserverPresentationFocusStateContractError::MalformedField);
    }
    Ok(value.to_string())
}

fn gpui_sidebar_gxserver_presentation_session_id_allowed(value: &str) -> bool {
    if gpui_remote_attach_session_reference_from_project_id(value).is_some() {
        return true;
    }
    !value.is_empty()
        && value.chars().count() <= GPUI_PROJECT_CONTRACT_STRING_MAX_CHARS
        && !value.contains('/')
        && !value.contains('\\')
        && !value.contains(':')
        && !value.contains('\0')
        && !value.chars().any(char::is_control)
}

fn gpui_sidebar_local_gxserver_session_id_allowed(value: &str) -> bool {
    gpui_remote_attach_session_reference_from_project_id(value).is_none()
        && gpui_sidebar_gxserver_presentation_session_id_allowed(value)
}

fn sidebar_runtime_settings_snapshot_from_shared_settings(
    settings: &shared_settings::SharedSidebarSettingsSnapshot,
) -> cef::SidebarRuntimeSettingsSnapshot {
    /*
    CDXC:GPUIProjectSidebarBridge 2026-06-23-06:36:
    The sidebar CEF runtime settings handoff must use the same shared sidebar settings file and strict boolean interpretation as SidebarApp. These booleans seed TS-side payload and workarea behavior only; Docs titlebar visibility stays governed by project context, not debuggingMode/showBetaFeatures.

    CDXC:GPUISettingsSidebarHandoff 2026-06-24-11:22:
    The GPUI sidebar runtime snapshot now also carries the saved shared Settings object as serialized first-party payload so the mounted SidebarApp can normalize real user preferences immediately on initial CEF install and after Settings saves. This is not a generic settings bus and must not write logs, persist another copy, or expose settings to Browser/workarea/modal CEF clients.
    */
    cef::SidebarRuntimeSettingsSnapshot {
        debugging_mode: settings.debugging_mode(),
        show_beta_features: settings.show_beta_features(),
        saved_settings_json: sidebar_runtime_saved_settings_json(settings),
    }
}

fn sidebar_runtime_saved_settings_json(
    settings: &shared_settings::SharedSidebarSettingsSnapshot,
) -> String {
    serde_json::to_string(&serde_json::Value::Object(settings.object().clone()))
        .unwrap_or_else(|_| "{}".to_string())
}

fn changed_sidebar_runtime_settings_snapshot(
    current: &cef::SidebarRuntimeSettingsSnapshot,
    next: cef::SidebarRuntimeSettingsSnapshot,
) -> Option<cef::SidebarRuntimeSettingsSnapshot> {
    (current != &next).then_some(next)
}

fn project_editor_auto_sleep_duration(
    mode: TitlebarMode,
    settings: &shared_settings::SharedSidebarSettingsSnapshot,
) -> Option<Duration> {
    let target = match mode {
        TitlebarMode::Source => shared_settings::SharedSettingsAutoSleepTarget::CodeEditor,
        TitlebarMode::Browser => shared_settings::SharedSettingsAutoSleepTarget::Browser,
        TitlebarMode::Kanban | TitlebarMode::Automate | TitlebarMode::Manage => {
            shared_settings::SharedSettingsAutoSleepTarget::ProjectEditor
        }
        TitlebarMode::Agents => return None,
    };
    settings.auto_sleep_duration(target)
}

fn native_chrome_settings_path() -> PathBuf {
    if let Ok(override_path) = env::var("ghostex_SETTINGS_PATH") {
        if !override_path.trim().is_empty() {
            return PathBuf::from(override_path);
        }
    }

    let Some(home) = env::var_os("HOME") else {
        return PathBuf::from("settings.json");
    };
    let app_support = PathBuf::from(home).join("Library/Application Support");
    let candidates = [
        app_support.join("com.madda.ghostex.host/state/settings.json"),
        app_support.join("dev.maddada.ghostex/dev/state/settings.json"),
        app_support.join("com.ghostex.host/state/settings.json"),
    ];
    candidates
        .iter()
        .find(|path| path.exists())
        .cloned()
        .unwrap_or_else(|| candidates[0].clone())
}

fn ghostex_state_root() -> PathBuf {
    shared_settings::ghostex_storage_paths().state_dir.clone()
}

fn gpui_workspace_shell_state_path() -> PathBuf {
    ghostex_state_root().join("gpui-workspace-shell-state.json")
}

fn gpui_gxserver_presentation_focus_state_path() -> PathBuf {
    ghostex_state_root().join("gpui-gxserver-presentation-focus-state.json")
}

/// Persists the sidebar-owned presentation focus state (focused + visible
/// gxserver session ids) so relaunch bootstraps can replay it and eagerly
/// re-materialize the previously focused session (Decision #3). The file
/// carries only the fixed focus-state contract shape — no titles, paths,
/// commands, or terminal content.
fn persist_gpui_gxserver_presentation_focus_state(state: &GpuiGxserverPresentationFocusState) {
    let path = gpui_gxserver_presentation_focus_state_path();
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    /*
    CDXC:GPUIWorkspaceSessionReattach 2026-08-07:
    `activeProjectId` persists alongside the focus ids so a cold start can
    replay the last active workspace project (local or machine-scoped remote)
    through the sidebar bootstrap instead of re-deriving it from the focused
    session alone — a derivation that fails whenever the focused session was
    remote or the focused id is stale. Tab sessions stay unpersisted: the
    sidebar's first hydrate is their only authority.
    */
    let payload = serde_json::json!({
        "version": GPUI_SIDEBAR_GXSERVER_FOCUS_STATE_MESSAGE_VERSION,
        "type": GPUI_SIDEBAR_GXSERVER_FOCUS_STATE_MESSAGE_TYPE,
        "activeProjectId": state.active_project_id,
        "focusedSessionId": state.focused_session_id,
        "visibleSessionIds": state.visible_session_ids,
    });
    let _ = fs::write(path, payload.to_string());
}

fn load_gpui_gxserver_presentation_focus_state() -> GpuiGxserverPresentationFocusState {
    fs::read_to_string(gpui_gxserver_presentation_focus_state_path())
        .ok()
        .and_then(|text| {
            gpui_gxserver_presentation_focus_state_from_sidebar_contract_json(&text).ok()
        })
        .unwrap_or_default()
}

// Revision markers mirror shared/first-launch-setup-settings.ts
// (FIRST_LAUNCH_SETUP_CURRENT_REVISION / HIGHLIGHTED_FEATURES_CURRENT_REVISION);
// keep them in sync when the shared revisions bump so both apps replay the
// refreshed onboarding exactly once.
const GPUI_FIRST_LAUNCH_SETUP_SEEN_REVISION: &str = "2026-06-18-short-first-launch";
const GPUI_HIGHLIGHTED_FEATURES_SEEN_REVISION: &str = "2026-06-16-highlighted-features-launch";

fn set_ghostex_gpui_main_menus(source_workarea_cef_owns_native_focus: bool, cx: &App) {
    cx.set_menus(ghostex_gpui_main_menus_for_source_focus(
        source_workarea_cef_owns_native_focus,
    ));
    #[cfg(target_os = "macos")]
    cef::refresh_application_menu_hooks();
}

fn register_ghostex_gpui_main_menu_actions(
    app: gpui::WeakEntity<GhostexGpuiApp>,
    main_window: gpui::AnyWindowHandle,
    cx: &mut App,
) {
    /*
    CDXC:GPUIMainMenuActions 2026-07-10:
    GPUI validates native menu items against the active window dispatch tree
    plus app-global action listeners. Menu validation can run without that
    GPUI dispatch tree while native CEF/Ghostty responders or child panels own
    AppKit focus, so application and window commands must be registered
    globally instead of existing only on the rendered shell root. Keep
    focus-sensitive File/Edit commands on their normal window/responder paths.
    */
    cx.on_action(|_: &AboutGhostexGpui, _cx| {
        #[cfg(target_os = "macos")]
        unsafe {
            GhostexGpuiShowStandardAboutPanel()
        };
    });
    cx.on_action({
        let app = app.clone();
        move |_: &CheckForGhostexGpuiUpdates, cx| {
            /*
            CDXC:GPUIMainMenuUpdater 2026-07-24:
            App-menu update checks dispatch while GPUI already owns the active
            window update. Defer the Sparkle handoff until that action cycle
            returns so the main window can be borrowed and Sparkle can present
            its standard user-initiated update or no-update UI.
            */
            let app = app.clone();
            cx.defer(move |cx| {
                let _ = main_window.update(cx, |_, window, cx| {
                    let _ = app.update(cx, |app, cx| app.check_for_gpui_updates(window, cx));
                });
            });
        }
    });
    cx.on_action({
        let app = app.clone();
        move |_: &OpenGpuiSettingsModal, cx| {
            /*
            CDXC:GPUIMainMenuSettings 2026-07-24:
            Native app-menu actions dispatch while GPUI already owns the active
            window update. Defer the Settings window mutation until that action
            cycle returns so the main window can be borrowed normally instead
            of silently rejecting a re-entrant update.
            */
            let app = app.clone();
            cx.defer(move |cx| {
                let _ = main_window.update(cx, |_, window, cx| {
                    let _ = app.update(cx, |app, cx| {
                        app.open_gpui_app_modal_from_titlebar(
                            GpuiAppModalKind::Settings,
                            window,
                            cx,
                        );
                    });
                });
            });
        }
    });
    cx.on_action({
        let app = app.clone();
        move |_: &OpenGpuiPluginsModal, cx| {
            let app = app.clone();
            cx.defer(move |cx| {
                let _ = main_window.update(cx, |_, window, cx| {
                    let _ = app.update(cx, |app, cx| {
                        app.open_gpui_settings_plugins_page(Some(window), cx);
                    });
                });
            });
        }
    });
    cx.on_action(|_: &HideGhostexGpui, cx| cx.hide());
    cx.on_action(|_: &HideGhostexGpuiOthers, cx| cx.hide_other_apps());
    cx.on_action(|_: &ShowAllGhostexGpuiApps, cx| cx.unhide_other_apps());
    cx.on_action(|_: &QuitGhostexGpui, cx| {
        GPUI_APP_QUIT_IN_PROGRESS.store(true, Ordering::Release);
        cx.quit();
    });
    cx.on_action(move |_: &MinimizeGhostexGpuiWindow, cx| {
        let _ = main_window.update(cx, |_, window, _cx| window.minimize_window());
    });
    cx.on_action(move |_: &ZoomGhostexGpuiWindow, cx| {
        let _ = main_window.update(cx, |_, window, _cx| window.zoom_window());
    });
}

/// Native app menu bar (macOS `installMainMenu` parity, AppDelegate.swift
/// :2533-2663): App (About/Check for Updates/Settings/Hide/Quit),
/// File → Close Pane ⌘W, the Edit clipboard set (first-responder OS actions so
/// CEF and Ghostty views handle them natively), and Window → Minimize/Zoom.
/// Undo/Redo are omitted from the GPUI-owned menu because gpui routes them
/// through app actions instead of first-responder selectors; the macOS CEF hook
/// installs them after each menu replacement.
fn ghostex_gpui_main_menus_for_source_focus(
    source_workarea_cef_owns_native_focus: bool,
) -> Vec<gpui::Menu> {
    use gpui::{Menu, MenuItem, OsAction};
    /*
    CDXC:GPUISourceViewHotkeyPassthrough 2026-07-05:
    GPUI macOS derives menu item key equivalents from the keymap when
    `cx.set_menus` builds NSMenuItems. While Source CEF owns native focus,
    replace File > Close Pane with a menu-only action that has no keybinding,
    so `[NSApp mainMenu] performKeyEquivalent:` cannot consume Cmd-W before
    AppKit offers it to embedded VSCode. The CEF menu-install hook similarly
    removes standard Edit key equivalents while Source owns focus, without
    removing their clickable actions. App-reserved quit/hide/minimize
    equivalents stay on their normal actions.
    */
    let close_pane_item = if source_workarea_cef_owns_native_focus {
        MenuItem::action("Close Pane", CloseFocusedSurfaceMenuOnly)
    } else {
        MenuItem::action("Close Pane", CloseFocusedSurface)
    };
    vec![
        Menu::new("Ghostex").items(vec![
            MenuItem::action("About Ghostex", AboutGhostexGpui),
            MenuItem::action("Check for Updates…", CheckForGhostexGpuiUpdates),
            MenuItem::separator(),
            MenuItem::action("Settings…", OpenGpuiSettingsModal),
            MenuItem::separator(),
            MenuItem::action("Hide Ghostex", HideGhostexGpui),
            MenuItem::action("Hide Others", HideGhostexGpuiOthers),
            MenuItem::action("Show All", ShowAllGhostexGpuiApps),
            MenuItem::separator(),
            MenuItem::action("Quit Ghostex", QuitGhostexGpui),
        ]),
        Menu::new("File").items(vec![close_pane_item]),
        Menu::new("Edit").items(vec![
            MenuItem::os_action("Cut", GpuiEditMenuCut, OsAction::Cut),
            MenuItem::os_action("Copy", GpuiEditMenuCopy, OsAction::Copy),
            MenuItem::os_action("Paste", GpuiEditMenuPaste, OsAction::Paste),
            MenuItem::separator(),
            MenuItem::os_action("Select All", GpuiEditMenuSelectAll, OsAction::SelectAll),
        ]),
        Menu::new("Window").items(vec![
            MenuItem::action("Minimize", MinimizeGhostexGpuiWindow),
            MenuItem::action("Zoom", ZoomGhostexGpuiWindow),
        ]),
    ]
}

const GPUI_WINDOW_FRAME_STATE_VERSION: u64 = 1;
const GPUI_WINDOW_FRAME_MIN_WIDTH: f32 = 800.0;
const GPUI_WINDOW_FRAME_MIN_HEIGHT: f32 = 600.0;

/// Window frame persistence (macOS `persistMainWindowChrome` /
/// `restoredInitialWindowFrame` parity): the frame is stored as a display
/// uuid plus a display-relative origin so a moved or removed monitor restores
/// onto an existing display instead of offscreen.
#[derive(Clone, PartialEq)]
struct GpuiWindowFrameState {
    state: String,
    display_uuid: String,
    relative_origin_x: f32,
    relative_origin_y: f32,
    width: f32,
    height: f32,
}

thread_local! {
    // The latest observed frame lives process-locally so quit and
    // last-window-close persistence never need the (possibly already
    // dropped) app entity.
    static GPUI_LATEST_WINDOW_FRAME_STATE: RefCell<Option<GpuiWindowFrameState>> =
        const { RefCell::new(None) };
}

fn gpui_window_frame_state_path() -> PathBuf {
    ghostex_state_root().join("gpui-window-frame-state.json")
}

fn gpui_window_frame_state_from_window(
    window: &Window,
    cx: &gpui::App,
) -> Option<GpuiWindowFrameState> {
    let display = window.display(cx)?;
    let display_origin = display.bounds().origin;
    let display_uuid = display.uuid().ok()?.to_string();
    let (state, bounds) = match window.window_bounds() {
        WindowBounds::Windowed(bounds) => ("windowed", bounds),
        WindowBounds::Maximized(bounds) => ("maximized", bounds),
        WindowBounds::Fullscreen(bounds) => ("fullscreen", bounds),
    };
    Some(GpuiWindowFrameState {
        state: state.to_string(),
        display_uuid,
        relative_origin_x: (bounds.origin.x - display_origin.x).as_f32(),
        relative_origin_y: (bounds.origin.y - display_origin.y).as_f32(),
        width: bounds.size.width.as_f32(),
        height: bounds.size.height.as_f32(),
    })
}

fn record_gpui_window_frame_state(window: &Window, cx: &gpui::App) {
    let Some(state) = gpui_window_frame_state_from_window(window, cx) else {
        return;
    };
    GPUI_LATEST_WINDOW_FRAME_STATE.with(|latest| {
        *latest.borrow_mut() = Some(state);
    });
}

fn persist_gpui_window_frame_state() {
    let Some(state) = GPUI_LATEST_WINDOW_FRAME_STATE.with(|latest| latest.borrow().clone()) else {
        return;
    };
    write_gpui_window_frame_state_file(&gpui_window_frame_state_path(), &state);
}

fn write_gpui_window_frame_state_file(path: &Path, state: &GpuiWindowFrameState) {
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let payload = serde_json::json!({
        "displayUuid": state.display_uuid,
        "height": state.height,
        "relativeOriginX": state.relative_origin_x,
        "relativeOriginY": state.relative_origin_y,
        "state": state.state,
        "version": GPUI_WINDOW_FRAME_STATE_VERSION,
        "width": state.width,
    });
    let _ = fs::write(path, payload.to_string());
}

fn load_gpui_window_frame_state() -> Option<GpuiWindowFrameState> {
    load_gpui_window_frame_state_file(&gpui_window_frame_state_path())
}

fn load_gpui_window_frame_state_file(path: &Path) -> Option<GpuiWindowFrameState> {
    let text = fs::read_to_string(path).ok()?;
    let value = serde_json::from_str::<serde_json::Value>(&text).ok()?;
    if value.get("version").and_then(serde_json::Value::as_u64)
        != Some(GPUI_WINDOW_FRAME_STATE_VERSION)
    {
        return None;
    }
    let number = |key: &str| -> Option<f32> {
        value
            .get(key)
            .and_then(serde_json::Value::as_f64)
            .filter(|number| number.is_finite())
            .map(|number| number as f32)
    };
    let state = value
        .get("state")
        .and_then(serde_json::Value::as_str)
        .filter(|state| matches!(*state, "windowed" | "maximized" | "fullscreen"))?
        .to_string();
    Some(GpuiWindowFrameState {
        state,
        display_uuid: value
            .get("displayUuid")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_string(),
        relative_origin_x: number("relativeOriginX")?,
        relative_origin_y: number("relativeOriginY")?,
        width: number("width")?,
        height: number("height")?,
    })
}

/// Restores the persisted frame with the macOS multi-monitor rules: prefer
/// the stored display by uuid, fall back to the primary display, clamp the
/// size to the display and a minimum, and keep the origin inside the display.
fn restored_gpui_window_bounds(cx: &gpui::App) -> Option<WindowBounds> {
    let state = load_gpui_window_frame_state()?;
    restored_gpui_window_bounds_from_state(
        state,
        GPUI_WINDOW_FRAME_MIN_WIDTH,
        GPUI_WINDOW_FRAME_MIN_HEIGHT,
        cx,
    )
}

fn restored_gpui_window_bounds_from_state(
    state: GpuiWindowFrameState,
    min_width: f32,
    min_height: f32,
    cx: &gpui::App,
) -> Option<WindowBounds> {
    let displays = cx.displays();
    let display = displays
        .iter()
        .find(|display| {
            display
                .uuid()
                .ok()
                .is_some_and(|uuid| uuid.to_string() == state.display_uuid)
        })
        .cloned()
        .or_else(|| cx.primary_display())
        .or_else(|| displays.first().cloned())?;
    let display_bounds = display.bounds();
    let width = px(state
        .width
        .max(min_width)
        .min(display_bounds.size.width.as_f32()));
    let height = px(state
        .height
        .max(min_height)
        .min(display_bounds.size.height.as_f32()));
    let max_x = (display_bounds.size.width - width).max(px(0.0));
    let max_y = (display_bounds.size.height - height).max(px(0.0));
    let origin = gpui::point(
        display_bounds.origin.x + px(state.relative_origin_x).clamp(px(0.0), max_x),
        display_bounds.origin.y + px(state.relative_origin_y).clamp(px(0.0), max_y),
    );
    let bounds = Bounds::new(origin, size(width, height));
    Some(match state.state.as_str() {
        "maximized" => WindowBounds::Maximized(bounds),
        "fullscreen" => WindowBounds::Fullscreen(bounds),
        _ => WindowBounds::Windowed(bounds),
    })
}

fn gpui_browser_media_permission_state_path() -> PathBuf {
    ghostex_state_root().join("gpui-browser-media-permissions.json")
}

/// Browser microphone/camera answers live in GPUI-owned state rather than a
/// CEF profile: Alloy-style CEF never persists media content settings, and the
/// shell (not Chromium) owns the prompt that produced them.
fn load_gpui_browser_media_permission_decisions() -> GpuiBrowserMediaPermissionDecisions {
    let Some(value) = fs::read_to_string(gpui_browser_media_permission_state_path())
        .ok()
        .and_then(|text| serde_json::from_str::<serde_json::Value>(&text).ok())
    else {
        return GpuiBrowserMediaPermissionDecisions::default();
    };
    let Some(origins) = value.get("origins").and_then(serde_json::Value::as_object) else {
        return GpuiBrowserMediaPermissionDecisions::default();
    };
    let read_decision = |value: &serde_json::Value, key: &str| match value
        .get(key)
        .and_then(serde_json::Value::as_str)
    {
        Some("allow") => Some(true),
        Some("block") => Some(false),
        _ => None,
    };
    GpuiBrowserMediaPermissionDecisions {
        origins: origins
            .iter()
            .filter_map(|(key, value)| {
                let decision = GpuiBrowserMediaPermissionDecision {
                    microphone: read_decision(value, "microphone"),
                    camera: read_decision(value, "camera"),
                };
                (!decision.is_empty()).then(|| (key.clone(), decision))
            })
            .collect(),
    }
}

fn persist_gpui_browser_media_permission_decisions(
    decisions: &GpuiBrowserMediaPermissionDecisions,
) {
    let path = gpui_browser_media_permission_state_path();
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let write_decision = |decision: Option<bool>| match decision {
        Some(true) => Some(serde_json::Value::from("allow")),
        Some(false) => Some(serde_json::Value::from("block")),
        None => None,
    };
    let mut origins = serde_json::Map::new();
    for (key, decision) in &decisions.origins {
        if decision.is_empty() {
            continue;
        }
        let mut entry = serde_json::Map::new();
        if let Some(value) = write_decision(decision.microphone) {
            entry.insert("microphone".to_string(), value);
        }
        if let Some(value) = write_decision(decision.camera) {
            entry.insert("camera".to_string(), value);
        }
        origins.insert(key.clone(), serde_json::Value::Object(entry));
    }
    let payload = serde_json::json!({ "origins": origins });
    let _ = fs::write(path, payload.to_string());
}

fn gpui_first_run_onboarding_state_path() -> PathBuf {
    ghostex_state_root().join("gpui-first-run-onboarding-state.json")
}

/// Keep first-run onboarding in GPUI-owned state rather than coupling native
/// onboarding lifecycle to any CEF profile or page-local storage.
#[derive(Clone, Default)]
struct GpuiFirstRunOnboardingState {
    tips_and_tricks_seen: bool,
    highlighted_features_seen_revision: Option<String>,
    first_launch_setup_seen_revision: Option<String>,
    os_integration_onboarding_seen: bool,
    first_launch_setup_complete: bool,
    windows_terminal_setup_complete: bool,
}

/// CDXC:GPUIFirstRunOnboardingOnce 2026-08-18: the markers whose surfaces are
/// user-visible, so they are written only after that surface is on screen.
#[derive(Clone, Copy, PartialEq, Eq)]
enum GpuiFirstRunOnboardingMarker {
    FirstLaunchSetupSeen,
    OsIntegrationOnboardingSeen,
}

fn load_gpui_first_run_onboarding_state() -> GpuiFirstRunOnboardingState {
    let Some(value) = fs::read_to_string(gpui_first_run_onboarding_state_path())
        .ok()
        .and_then(|text| serde_json::from_str::<serde_json::Value>(&text).ok())
    else {
        return GpuiFirstRunOnboardingState::default();
    };
    GpuiFirstRunOnboardingState {
        tips_and_tricks_seen: value
            .get("tipsAndTricksSeen")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false),
        highlighted_features_seen_revision: value
            .get("highlightedFeaturesSeenRevision")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string),
        first_launch_setup_seen_revision: value
            .get("firstLaunchSetupSeenRevision")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string),
        os_integration_onboarding_seen: value
            .get("osIntegrationOnboardingSeen")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false),
        first_launch_setup_complete: value
            .get("firstLaunchSetupComplete")
            // Written under the Windows-only name until 2026-08-19.
            .or_else(|| value.get("windowsFirstLaunchSetupComplete"))
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false),
        windows_terminal_setup_complete: value
            .get("windowsTerminalSetupComplete")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false),
    }
}

fn persist_gpui_first_run_onboarding_state(state: &GpuiFirstRunOnboardingState) {
    let path = gpui_first_run_onboarding_state_path();
    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let payload = serde_json::json!({
        "firstLaunchSetupSeenRevision": state.first_launch_setup_seen_revision,
        "highlightedFeaturesSeenRevision": state.highlighted_features_seen_revision,
        "osIntegrationOnboardingSeen": state.os_integration_onboarding_seen,
        "tipsAndTricksSeen": state.tips_and_tricks_seen,
        "firstLaunchSetupComplete": state.first_launch_setup_complete,
        "windowsTerminalSetupComplete": state.windows_terminal_setup_complete,
    });
    let _ = fs::write(path, payload.to_string());
}
